```typescript
/**
 * Groups the elements of an array into buckets keyed by a derived value.
 *
 * Iterates over `arr` once, calling `keyFn` on each element to compute its
 * group key. Elements that produce the same key are collected into the same
 * array, preserving their original relative order.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key. Must be usable as an object
 *               property key (string, number, or symbol).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that derives a grouping key from each element.
 *                Receives the element, its index, and the original array.
 *
 * @returns An object mapping each distinct key to an array of the elements
 *          that produced it. Keys appear in the order they were first
 *          encountered. Returns an empty object for an empty input array.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - **Time complexity:** O(n), where n is `arr.length`.
 * - **Space complexity:** O(n) for the output structure.
 * - **Stable:** Items within each group retain their original order.
 * - **Key coercion:** Because the result is a plain object, numeric keys are
 *   coerced to strings (e.g. `1` and `"1"` land in the same group). If you
 *   need to group by non-primitive keys (objects, dates) or need to
 *   distinguish `1` from `"1"`, use {@link groupByMap} instead.
 * - **Prototype safety:** The result is created with `Object.create(null)`,
 *   so keys like `"__proto__"` or `"constructor"` are handled safely.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? "even" : "odd"));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: "Alice", dept: "Engineering" },
 *   { name: "Bob",   dept: "Sales" },
 *   { name: "Carol", dept: "Engineering" },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: "Alice", ... }, { name: "Carol", ... }],
 * //   Sales:       [{ name: "Bob", ... }]
 * // }
 *
 * @example
 * // Group strings by length
 * groupBy(["one", "two", "three", "four"], s => s.length);
 * // => { 3: ["one", "two"], 4: ["four"], 5: ["three"] }
 *
 * @example
 * // Using the index argument: chunk into groups of 2
 * groupBy(["a", "b", "c", "d", "e"], (_, i) => Math.floor(i / 2));
 * // => { 0: ["a", "b"], 1: ["c", "d"], 2: ["e"] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupBy: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  // Null-prototype object avoids collisions with inherited keys like "toString".
  const result = Object.create(null) as Record<K, T[]>;

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (result[key] === undefined) {
      result[key] = [];
    }
    result[key].push(item);
  }

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map` instead of a plain object.
 *
 * Use this when keys are non-primitive values (objects, arrays, dates) or
 * when you need to distinguish keys that would collide after string
 * coercion (e.g. `1` vs `"1"`). Keys are compared using SameValueZero
 * semantics, so object keys are matched by reference, not structure.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key (any type).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that derives a grouping key from each element.
 *
 * @returns A `Map` from each distinct key to the array of elements that
 *          produced it, in first-encountered key order.
 *
 * @example
 * const alice = { id: 1 };
 * const bob = { id: 2 };
 * const tasks = [
 *   { title: "Write docs", owner: alice },
 *   { title: "Fix bug",    owner: bob },
 *   { title: "Review PR",  owner: alice },
 * ];
 * const byOwner = groupByMap(tasks, t => t.owner);
 * byOwner.get(alice); // => [{ title: "Write docs", ... }, { title: "Review PR", ... }]
 */
export function groupByMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByMap: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByMap: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    const group = result.get(key);
    if (group) {
      group.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}
```

### Plain JavaScript version

```javascript
/**
 * Groups array elements by a key derived from each element.
 *
 * @template T
 * @param {T[]} arr - The array to group. Not mutated.
 * @param {(item: T, index: number, array: T[]) => string | number | symbol} keyFn
 *   Function returning the group key for each element.
 * @returns {Record<string, T[]>} Object mapping each key to its elements,
 *   in original order. Null-prototype, so safe for any key name.
 * @throws {TypeError} If arguments are of the wrong type.
 *
 * @example
 * groupBy([1, 2, 3, 4], n => (n % 2 ? "odd" : "even"));
 * // => { odd: [1, 3], even: [2, 4] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) throw new TypeError("groupBy: expected an array");
  if (typeof keyFn !== "function") throw new TypeError("groupBy: expected keyFn to be a function");

  const result = Object.create(null);
  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    (result[key] ??= []).push(item);
  });
  return result;
}
```

### Design notes

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | A plain `{}` inherits from `Object.prototype`, so a key like `"constructor"` would find an existing function and `.push` would crash. A null-prototype object avoids this. |
| **Stable ordering** | Items keep their input order within each group, which callers usually expect. |
| **Index passed to `keyFn`** | Matches the `Array.prototype.map/filter` callback signature and enables positional grouping (e.g. chunking). |
| **Separate `groupByMap`** | Object keys are always strings or symbols. A `Map` variant covers object keys and avoids `1`/`"1"` collisions. |
| **No mutation** | The input array is only read, never modified. |

### Native alternative

Modern runtimes (ES2024: Node 21+, Chrome 117+, Safari 17.4+, Firefox 119+) include built-ins with the same semantics:

```javascript
Object.groupBy(arr, keyFn); // ≈ groupBy (null-prototype object)
Map.groupBy(arr, keyFn);    // ≈ groupByMap
```

If you can target those environments, prefer the built-ins. The utility above is useful for older targets or when you want the extra argument validation.

