```typescript
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * Iterates over `arr` once, calling `keyFn` on every element. Elements that
 * produce the same key are collected into the same group. Groups preserve the
 * original relative order of their elements, and the groups themselves appear
 * in the order their keys were first encountered.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key. Must be a valid object property key
 *               (string, number, or symbol).
 *
 * @param arr - The array to group. It is not mutated.
 * @param keyFn - A function that derives a grouping key from an element.
 *                Receives the element, its index, and the original array.
 *
 * @returns An object mapping each derived key to an array of elements that
 *          produced that key. The returned object has a `null` prototype, so
 *          keys like `"constructor"` or `"__proto__"` are safe to use.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - **Complexity:** O(n) time, O(n) additional space.
 * - **Key coercion:** Because the result is a plain object, numeric keys are
 *   coerced to strings (`1` and `"1"` land in the same group). If you need
 *   to keep keys distinct by type, or use objects as keys, use
 *   {@link groupByToMap} instead.
 * - **Native alternative:** Modern runtimes (ES2024+) provide
 *   `Object.groupBy` and `Map.groupBy`, which behave equivalently.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? "even" : "odd"));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: "Alice", dept: "Engineering" },
 *   { name: "Bob",   dept: "Sales" },
 *   { name: "Carol", dept: "Engineering" },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: "Alice", ... }, { name: "Carol", ... }],
 * //   Sales:       [{ name: "Bob", ... }]
 * // }
 *
 * @example
 * // Use the index argument to chunk items into groups of 3
 * groupBy(["a", "b", "c", "d", "e"], (_, i) => Math.floor(i / 3));
 * // => { 0: ["a", "b", "c"], 1: ["d", "e"] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupBy: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  // Null prototype avoids collisions with inherited properties
  // such as "toString", "constructor", or "__proto__".
  const groups = Object.create(null) as Record<K, T[]>;

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (key in groups) {
      groups[key].push(item);
    } else {
      groups[key] = [item];
    }
  }

  return groups;
}

/**
 * Like {@link groupBy}, but returns a `Map` instead of a plain object.
 *
 * Use this when keys are not strings, for example objects, or when you
 * need `1` and `"1"` to remain separate groups. Keys are compared using
 * SameValueZero semantics (like `===`, except `NaN` equals `NaN`).
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key (any type).
 *
 * @param arr - The array to group. It is not mutated.
 * @param keyFn - A function that derives a grouping key from an element.
 *
 * @returns A `Map` from each key to the array of elements that produced it,
 *          in first-encountered key order.
 *
 * @example
 * const alice = { id: 1 };
 * const bob = { id: 2 };
 * const tasks = [
 *   { title: "Write docs", owner: alice },
 *   { title: "Fix bug",    owner: bob },
 *   { title: "Review PR",  owner: alice },
 * ];
 * const byOwner = groupByToMap(tasks, t => t.owner);
 * byOwner.get(alice); // => [{ title: "Write docs", ... }, { title: "Review PR", ... }]
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  const groups = new Map<K, T[]>();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const group = groups.get(key);

    if (group) {
      group.push(item);
    } else {
      groups.set(key, [item]);
    }
  }

  return groups;
}
