```typescript
/**
 * Groups the elements of an array into buckets based on a derived key.
 *
 * Iterates over `arr` once, calling `keyFn` for each element, and collects
 * elements that produce the same key into the same array. The relative order
 * of elements within each group matches their order in the input array, and
 * groups appear in the order their keys were first encountered.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key. Must be a valid object property
 *               key (`string`, `number`, or `symbol`).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that derives a grouping key from each element.
 *                Receives the element and its index in the array.
 *
 * @returns An object mapping each distinct key to an array of the elements
 *          that produced it. Keys that never occur are absent, so every
 *          present group contains at least one element.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - **Key coercion:** Because the result is a plain object, numeric keys are
 *   coerced to strings (e.g. `1` and `"1"` land in the same group). If you need
 *   to preserve key identity (e.g. for object keys or to distinguish `1` from
 *   `"1"`), use {@link groupByToMap} instead.
 * - **Prototype safety:** The result is created with `Object.create(null)`, so
 *   keys like `"__proto__"` or `"constructor"` are handled safely and won't
 *   collide with inherited `Object.prototype` properties.
 * - **Complexity:** O(n) time and O(n) additional space.
 * - Modern runtimes provide a native `Object.groupBy` (ES2024) with similar
 *   semantics; this utility is useful for older environments or when you want
 *   the index passed to `keyFn`.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? "even" : "odd"));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: "Alice", dept: "Engineering" },
 *   { name: "Bob",   dept: "Sales" },
 *   { name: "Carol", dept: "Engineering" },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: "Alice", ... }, { name: "Carol", ... }],
 * //   Sales:       [{ name: "Bob", ... }],
 * // }
 *
 * @example
 * // Group strings by length
 * groupBy(["one", "two", "three"], s => s.length);
 * // => { 3: ["one", "two"], 5: ["three"] }
 *
 * @example
 * // Use the index to bucket into chunks of 2
 * groupBy(["a", "b", "c", "d", "e"], (_, i) => Math.floor(i / 2));
 * // => { 0: ["a", "b"], 1: ["c", "d"], 2: ["e"] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = Object.create(null) as Record<K, T[]>;

  arr.forEach((item, index) => {
    const key = keyFn(item, index);
    // Using `in` is safe here because `result` has no prototype.
    if (key in result) {
      result[key].push(item);
    } else {
      result[key] = [item];
    }
  });

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map`, preserving the exact identity
 * of keys (no string coercion). Use this when keys are objects, or when
 * you must distinguish between e.g. `1` and `"1"`.
 *
 * @example
 * const admin = { role: "admin" };
 * const guest = { role: "guest" };
 * const users = [
 *   { name: "Ann", role: admin },
 *   { name: "Ben", role: guest },
 *   { name: "Cat", role: admin },
 * ];
 * const byRole = groupByToMap(users, u => u.role);
 * byRole.get(admin); // => [{ name: "Ann", ... }, { name: "Cat", ... }]
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  arr.forEach((item, index) => {
    const key = keyFn(item, index);
    const group = result.get(key);
    if (group) {
      group.push(item);
    } else {
      result.set(key, [item]);
    }
  });

  return result;
}
