 *   { name: 'Cara',  dept: 'Engineering' },
 * ];
 * const byDept = groupBy(people, p => p.dept);
 * byDept.get('Engineering'); // [{ name: 'Alice', ... }, { name: 'Cara', ... }]
 *
 * @example
 * // Convert to a plain object if needed
 * const obj = Object.fromEntries(groupBy(['apple', 'avocado', 'banana'], s => s[0]));
 * // { a: ['apple', 'avocado'], b: ['banana'] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const groups = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const bucket = groups.get(key);

    if (bucket) {
      bucket.push(item);
    } else {
      groups.set(key, [item]);
    }
  }

  return groups;
}

/**
 * Like {@link groupBy}, but returns a plain object keyed by string.
 *
 * Convenient for JSON serialization or when keys are naturally strings.
 * Keys returned by `keyFn` are coerced to strings, so `1` and `"1"` will
 * land in the same group. The result has a `null` prototype, so keys like
 * `"__proto__"` or `"toString"` are safe.
 *
 * @template T
 * @param {readonly T[]} arr - The array of items to group.
 * @param {(item: T, index: number, array: readonly T[]) => PropertyKey} keyFn -
 *   Returns the group key for each item.
 * @returns {Record<string, T[]>} An object mapping each key to its items.
 *
 * @example
 * groupByToObject([1.2, 1.8, 2.5], Math.floor);
 * // { '1': [1.2, 1.8], '2': [2.5] }
 */
function groupByToObject(arr, keyFn) {
  const result = Object.create(null);
  for (const [key, items] of groupBy(arr, keyFn)) {
    result[key] = items;
  }
  return result;
}

module.exports = { groupBy, groupByToObject };
```

