/**
 * Groups the elements of an array by a key derived from each element.
 * See the JS version above for full documentation.
 */
export function groupBy<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  const groups = new Map<K, T[]>();
  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    const bucket = groups.get(key);
    if (bucket) bucket.push(item);
    else groups.set(key, [item]);
  });
  return groups;
}

export function groupByToObject<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  const result = Object.create(null) as Record<K, T[]>;
  for (const [key, items] of groupBy(arr, keyFn)) {
    result[key] = items;
  }
  return result;
