 * // => {
 * //   Engineering: [{ name: 'Alice', ... }, { name: 'Carol', ... }],
 * //   Sales:       [{ name: 'Bob', ... }]
 * // }
 *
 * @example
 * // Group by a computed value
 * groupBy([1, 2, 3, 4, 5, 6], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4, 6] }
 *
 * @example
 * // Group strings by length
 * groupBy(['one', 'two', 'three', 'four'], s => s.length);
 * // => { 3: ['one', 'two'], 4: ['four'], 5: ['three'] }
 *
 * @remarks
 * - **Key coercion:** Because the result is a plain object, non-symbol keys are
 *   coerced to strings (e.g. `1` and `"1"` land in the same group). If you need
 *   to group by objects or preserve key types exactly, use {@link groupByToMap}.
 * - **Empty input:** Returns an empty object.
 * - **Complexity:** O(n) time, O(n) additional space.
 * - **Native alternative:** Modern runtimes (ES2024+) provide `Object.groupBy`,
 *   which behaves equivalently.
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (result[key] === undefined) {
      result[key] = [];
    }
    result[key].push(item);
  }

  return result;
