## TypeScript Implementation

```typescript
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * Iterates over `arr` once, calling `keyFn` on each item to compute its group key.
 * Items that produce the same key are collected into the same array, preserving
 * their original relative order.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key. Must be a valid object property key
 *               (`string`, `number`, or `symbol`).
 *
 * @param arr   - The array of items to group. Not mutated.
 * @param keyFn - A function that receives each item (along with its index and the
 *                source array) and returns the key of the group it belongs to.
 *
 * @returns A plain object whose keys are the derived group keys and whose values
 *          are arrays of the items that produced that key. Returns an empty object
 *          if `arr` is empty.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - **Order:** Items within each group appear in the same order as in `arr`.
 *   Group keys are ordered by first appearance, except that integer-like keys
 *   (e.g. `"1"`, `"42"`) are enumerated first, in ascending numeric order. This is
 *   standard JavaScript object key ordering. Use {@link groupByToMap} if key order
 *   matters.
 * - **Key coercion:** Number keys are converted to strings by the object
 *   (`1` and `"1"` land in the same group).
 * - **Prototype safety:** The result is created with `Object.create(null)`, so keys
 *   like `"__proto__"` or `"constructor"` are safe to use.
 * - **Complexity:** O(n) time and O(n) additional space.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Sales' },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: 'Alice', ... }, { name: 'Carol', ... }],
 * //   Sales:       [{ name: 'Bob', ... }],
 * // }
 *
 * @example
 * // Group strings by length
 * groupBy(['one', 'two', 'three'], s => s.length);
 * // => { 3: ['one', 'two'], 5: ['three'] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  // Null-prototype object avoids collisions with inherited keys like "toString".
  const result = Object.create(null) as Record<K, T[]>;

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    // Use a guard rather than `??=` for broader runtime compatibility.
    if (result[key] === undefined) {
      result[key] = [];
    }
    result[key].push(item);
  }

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map` instead of a plain object.
 *
 * Prefer this variant when:
 * - keys are **not** strings/numbers/symbols (e.g. objects, `Date`s, tuples by reference),
 * - you need keys preserved **exactly** (no coercion of `1` → `"1"`),
 * - you need groups enumerated strictly in **first-seen order**.
 *
 * Keys are compared using SameValueZero semantics (the same as `Map`), so
 * `NaN` groups with `NaN`, and objects are compared by reference.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key (any type).
 *
 * @param arr   - The array of items to group. Not mutated.
 * @param keyFn - Function returning the group key for each item.
 *
 * @returns A `Map` from each distinct key to the array of items that produced it.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * const byLength = groupByToMap(['a', 'bb', 'cc', 'd'], s => s.length);
 * byLength.get(1); // => ['a', 'd']
 * byLength.get(2); // => ['bb', 'cc']
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const group = result.get(key);
    if (group) {
      group.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}
```

## Plain JavaScript Version

```javascript
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * @template T, K
 * @param {readonly T[]} arr - The array to group. Not mutated.
 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 *   Returns the group key for each item. Keys should be strings, numbers, or symbols.
 * @returns {Record<K, T[]>} An object mapping each key to the items that produced it,
 *   in their original order.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * groupBy([1, 2, 3, 4], n => (n % 2 ? 'odd' : 'even'));
 * // => { odd: [1, 3], even: [2, 4] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const key = keyFn(arr[i], i, arr);
    (result[key] || (result[key] = [])).push(arr[i]);
  }

  return result;
}

module.exports = { groupBy };
