    expect(result.get(teamA)?.map(p => p.name)).toEqual(['p1', 'p3']);
    expect(result.get(teamB)?.map(p => p.name)).toEqual(['p2']);
  });

  it('does not coerce keys', () => {
    const result = groupByToMap([1, '1'], x => x);
    expect(result.size).toBe(2);
  });
});
