 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    // Use `in` rather than truthiness so an existing empty bucket is reused.
    if (key in result) {
      result[key].push(item);
    } else {
      result[key] = [item];
    }
  }

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map`, preserving the exact identity
 * and type of each key (no string coercion).
 *
 * Use this when keys are objects, when you need to distinguish `1` from `"1"`,
 * or when you want guaranteed insertion-ordered iteration over groups.
 *
 * @template T, K
 * @param {readonly T[]} arr - The array to group. Not mutated.
 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 *   Function that returns the group key for an element. Keys are compared
 *   using SameValueZero (the same semantics as `Map`).
 * @returns {Map<K, T[]>} A Map from each key to its group, in order of first
 *   appearance.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * const m = groupByMap([1, '1', 2], x => x);
 * m.get(1);   // => [1]
 * m.get('1'); // => ['1']
 */
function groupByMap(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByMap: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupByMap: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const bucket = result.get(key);

    if (bucket) {
      bucket.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}

module.exports = { groupBy, groupByMap };
```

## TypeScript version

```typescript
/**
 * Groups array elements by a derived key into a plain object.
 *
 * @typeParam T - Element type of the input array.
 * @typeParam K - Key type returned by `keyFn` (string, number, or symbol).
 * @param arr - The array to group. Not mutated.
 * @param keyFn - Computes the group key for each element.
 * @returns A null-prototype object mapping each key to its elements,
 *   in original order. Keys are partial because not every possible `K`
 *   is guaranteed to appear.
 *
 * @example
 * groupBy([1, 2, 3], n => (n % 2 ? 'odd' : 'even'));
 * // => { odd: [1, 3], even: [2] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K,
): Partial<Record<K, T[]>> {
  const result = Object.create(null) as Partial<Record<K, T[]>>;

  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    (result[key] ??= []).push(item);
  });

  return result;
}

/**
 * Groups array elements by a derived key into a `Map`, preserving key
 * identity and type (no string coercion).
 *
 * @example
 * groupByMap(users, u => u.team); // Map<Team, User[]>
 */
export function groupByMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K,
): Map<K, T[]> {
  const result = new Map<K, T[]>();

  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    const bucket = result.get(key);
    if (bucket) bucket.push(item);
    else result.set(key, [item]);
  });

  return result;
}
```

## Design notes

| Decision | Rationale |
|---|---|
| **Null-prototype object** | Prevents bugs when a key is `"constructor"`, `"toString"`, or `"__proto__"`. |
| **Order preserved** | Items appear in each group in the same order as the input, so the output is predictable. |
| **`keyFn(item, index, array)`** | Matches the `map`/`filter` callback signature, so index-based grouping (e.g., chunking with `i => Math.floor(i / 3)`) works. |
| **Separate `groupByMap`** | Object keys are always strings, so `1` and `"1"` would merge. `Map` avoids that and supports object keys. |
| **Single pass, O(n)** | Each element is visited once; `keyFn` is called exactly once per element. |
| **Input not mutated** | Only new arrays are created. Elements themselves are not copied (shallow grouping). |
| **`Partial<Record<...>>` in TS** | Honest typing: accessing a key that never appeared yields `undefined`, and the type reflects that. |

## Native alternative

Modern runtimes (Node 21+, Chrome 117+, Safari 17.4+, Firefox 119+) ship this built in:

```javascript
Object.groupBy(arr, keyFn); // ≈ groupBy
Map.groupBy(arr, keyFn);    // ≈ groupByMap
```

If you can target those environments, prefer the native versions. The utilities above are useful as a polyfill or for older targets. Note that the native callback receives `(item, index)` without the array argument.

