## TypeScript Implementation

```typescript
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * Iterates over `arr` once, calling `keyFn` for every item, and collects
 * items that produce the same key into arrays. The relative order of items
 * within each group matches their order in the original array, and groups
 * appear in the order their keys were first encountered.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key. Must be usable as an object
 *               property key (`string`, `number`, or `symbol`).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that derives the grouping key for an item.
 *                Receives the item, its index, and the source array.
 *
 * @returns An object whose keys are the derived keys and whose values are
 *          arrays of the items that produced each key. Keys that never
 *          occur are absent (never present with an empty array).
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - The result is created with `Object.create(null)`, so it has no
 *   prototype. This prevents collisions with inherited properties such as
 *   `"constructor"` or `"__proto__"` when they are used as keys.
 * - Numeric keys are converted to strings, as with any object property.
 *   For example, keys `1` and `"1"` land in the same group. If you need to
 *   preserve key types (or use objects as keys), see {@link groupByToMap}.
 * - Runs in O(n) time and O(n) additional space.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? "even" : "odd"));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: "Ana",  dept: "eng" },
 *   { name: "Ben",  dept: "ops" },
 *   { name: "Cara", dept: "eng" },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   eng: [{ name: "Ana", dept: "eng" }, { name: "Cara", dept: "eng" }],
 * //   ops: [{ name: "Ben", dept: "ops" }],
 * // }
 *
 * @example
 * // Group strings by length
 * groupBy(["a", "bb", "cc", "d"], s => s.length);
 * // => { 1: ["a", "d"], 2: ["bb", "cc"] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = Object.create(null) as Record<K, T[]>;

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    // Look up the group once; create it on first sight of the key.
    const group = result[key];
    if (group) {
      group.push(item);
    } else {
      result[key] = [item];
    }
  }

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map` instead of a plain object.
 *
 * Use this when keys are not strings, for example objects, or when you
 * need to distinguish `1` from `"1"`. Keys are compared using SameValueZero
 * (the same semantics as `Map`), so object keys group by reference.
 *
 * @template T - The type of elements in the input array.
 * @template K - The type of the derived key (any value).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that derives the grouping key for an item.
 *
 * @returns A `Map` from each derived key to the array of matching items,
 *          in first-encountered key order.
 *
 * @example
 * const map = groupByToMap([1, "1", 2], x => x);
 * map.get(1);   // => [1]
 * map.get("1"); // => ["1"]
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    const group = result.get(key);
    if (group) {
      group.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}
