/**
 * Groups the elements of an array by a key derived from each element.
 *
 * Iterates over `arr` once, calling `keyFn` on every element. Elements that
 * produce the same key are collected into the same array, preserving their
 * original relative order.
 *
 * @typeParam T - The type of elements in the input array.
 * @typeParam K - The type of the derived key. Must be a valid object key
 *                (`string`, `number`, or `symbol`).
 *
 * @param arr   - The array to group. It is not mutated.
 * @param keyFn - A function that receives each element (plus its index and the
 *                source array) and returns the key to group it under.
 *
 * @returns A plain object whose keys are the derived keys and whose values are
 *          non-empty arrays of the elements that produced each key. Returns an
 *          empty object if `arr` is empty.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @remarks
 * - **Order:** Within each group, elements appear in the same order as in `arr`.
 *   Group keys are ordered by first appearance, except that integer-like keys
 *   (e.g. `"1"`, `"42"`) are listed first in ascending numeric order. This is
 *   standard JavaScript object key ordering.
 * - **Key coercion:** Numeric keys are converted to strings by the object,
 *   so `1` and `"1"` end up in the same group.
 * - **Prototype safety:** The result is created with `Object.create(null)`,
 *   so keys like `"__proto__"` or `"constructor"` are stored safely and do not
 *   collide with inherited properties.
 * - **References:** Elements are not cloned. Groups hold references to the
 *   original items.
 * - **Complexity:** O(n) time and O(n) additional space.
 *
 * @example
 * // Group by a property
 * const people = [
 *   { name: "Alice", dept: "Engineering" },
 *   { name: "Bob",   dept: "Sales" },
 *   { name: "Cara",  dept: "Engineering" },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: "Alice", ... }, { name: "Cara", ... }],
 * //   Sales:       [{ name: "Bob", ... }]
 * // }
 *
 * @example
 * // Group by a computed value
 * groupBy([1, 2, 3, 4, 5, 6], n => (n % 2 === 0 ? "even" : "odd"));
 * // => { odd: [1, 3, 5], even: [2, 4, 6] }
 *
 * @example
 * // Group strings by length (numeric keys)
 * groupBy(["one", "two", "three"], s => s.length);
 * // => { 3: ["one", "two"], 5: ["three"] }
 *
 * @see {@link groupByToMap} if you need non-primitive keys (objects, dates, etc.)
 *      or want to keep the key's original type.
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Record<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupBy: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  // Null-prototype object: avoids collisions with keys like "__proto__" or "toString".
  const result = Object.create(null) as Record<K, T[]>;

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    // Cast is needed for TypeScript to index with a generic key.
    const bucket = (result[key] as T[] | undefined);
    if (bucket) {
      bucket.push(item);
    } else {
      result[key] = [item];
    }
  }

  return result;
}

/**
 * Like {@link groupBy}, but returns a `Map` instead of a plain object.
 *
 * Use this variant when:
 * - Keys are not strings or numbers (e.g. objects, booleans, `null`).
 * - You need `1` and `"1"` to stay in **separate** groups.
 * - You want group order to strictly follow first appearance.
 *
 * Keys are compared with SameValueZero (the same rule `Map` uses), so object
 * keys are matched by **reference**, not by structure.
 *
 * @example
 * const byActive = groupByToMap(users, u => u.isActive);
 * byActive.get(true);  // active users
 * byActive.get(false); // inactive users
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, received ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, received ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const bucket = result.get(key);
    if (bucket) {
      bucket.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}
