    throw new TypeError(
      `groupBy: expected keyFn to be a function, received ${typeof keyFn}`
    );
  }

  // Null-prototype object avoids collisions with Object.prototype keys.
  const result = Object.create(null) as Record<K, T[]>;

  arr.forEach((item, index) => {
    const key = keyFn(item, index, arr);
    (result[key] ??= []).push(item);
  });

  return result;
