## Usage Examples

```typescript
// 1. Basic grouping
groupBy(["apple", "avocado", "banana", "blueberry", "cherry"], (s) => s[0]);
// => { a: ["apple", "avocado"], b: ["banana", "blueberry"], c: ["cherry"] }

// 2. Using the index argument (chunk into rows of 3)
groupBy([10, 20, 30, 40, 50], (_, i) => Math.floor(i / 3));
// => { 0: [10, 20, 30], 1: [40, 50] }

// 3. Bucketing by range
const scores = [55, 72, 88, 91, 64, 99];
groupBy(scores, (s) => (s >= 90 ? "A" : s >= 80 ? "B" : s >= 70 ? "C" : "F"));
// => { F: [55, 64], C: [72], B: [88], A: [91, 99] }

// 4. Non-string keys with the Map variant
const tasks = [
  { title: "Write docs", done: true },
  { title: "Fix bug",    done: false },
  { title: "Deploy",     done: true },
];
const byStatus = groupByToMap(tasks, (t) => t.done);
byStatus.get(true);  // => [{ title: "Write docs", ... }, { title: "Deploy", ... }]
byStatus.get(false); // => [{ title: "Fix bug", ... }]

// 5. Empty input
groupBy([], (x) => x); // => {}
