 * const byLength = groupByToMap(["a", "bb", "c"], s => s.length);
 * byLength.get(1); // => ["a", "c"]
 * byLength.get(2); // => ["bb"]
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByToMap: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== "function") {
    throw new TypeError(`groupByToMap: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  const result = new Map<K, T[]>();

  arr.forEach((item, index) => {
    const key = keyFn(item, index, arr);
    const group = result.get(key);
    if (group) {
      group.push(item);
    } else {
      result.set(key, [item]);
    }
  });

  return result;
}
