/**
 * Groups the elements of an array into buckets keyed by a derived value.
 *
 * Iterates over `arr` once, calling `keyFn` on each item to compute its key,
 * and collects items that share the same key into an array. The relative
 * order of items within each group matches their order in the input array,
 * and groups appear in the order their keys were first encountered.
 *
 * Returns a `Map` rather than a plain object so that:
 *   - Keys of any type (numbers, objects, booleans, `null`, etc.) are
 *     preserved exactly, with no coercion to strings.
 *   - There is no risk of collisions with `Object.prototype` properties
 *     (e.g. a key of `"constructor"` or `"__proto__"`).
 *   - Insertion order of groups is guaranteed.
 *
 * Keys are compared using SameValueZero semantics (the same as `Map`), so
 * `NaN` groups with `NaN`, and `0` / `-0` are treated as the same key.
 * Object keys are compared by reference, not by structure.
 *
 * @template T, K
 * @param {Iterable<T>} arr
 *   The collection to group. Any iterable is accepted (arrays, Sets,
 *   generators, etc.), though arrays are the common case.
 * @param {(item: T, index: number) => K} keyFn
 *   A function that derives the grouping key for each item. Receives the
 *   item and its zero-based index. Called exactly once per item.
 * @returns {Map<K, T[]>}
 *   A Map from each distinct key to the array of items that produced it.
 *   Returns an empty Map if the input is empty.
 * @throws {TypeError}
 *   If `arr` is not iterable or `keyFn` is not a function.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => Map { 'odd' => [1, 3, 5], 'even' => [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: 'Ana',  dept: 'eng' },
 *   { name: 'Ben',  dept: 'sales' },
 *   { name: 'Cleo', dept: 'eng' },
 * ];
 * groupBy(people, p => p.dept);
 * // => Map {
 * //   'eng'   => [{ name: 'Ana', dept: 'eng' }, { name: 'Cleo', dept: 'eng' }],
 * //   'sales' => [{ name: 'Ben', dept: 'sales' }]
 * // }
 *
 * @example
 * // Non-string keys are preserved
 * groupBy(['a', 'bb', 'cc', 'ddd'], s => s.length);
 * // => Map { 1 => ['a'], 2 => ['bb', 'cc'], 3 => ['ddd'] }
 *
 * @example
 * // Need a plain object instead? Convert the result:
 * Object.fromEntries(groupBy(people, p => p.dept));
 * // => { eng: [...], sales: [...] }
 */
function groupBy(arr, keyFn) {
  if (arr == null || typeof arr[Symbol.iterator] !== 'function') {
    throw new TypeError('groupBy: first argument must be iterable');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: keyFn must be a function');
  }

  const groups = new Map();
  let index = 0;

  for (const item of arr) {
    const key = keyFn(item, index++);
    const bucket = groups.get(key);
    if (bucket) {
      bucket.push(item);
    } else {
      groups.set(key, [item]);
    }
  }

  return groups;
}

module.exports = { groupBy };
```

### Design notes

| Decision | Rationale |
|---|---|
| **Returns a `Map`** | Preserves key types and order and avoids prototype-pollution pitfalls. Convert with `Object.fromEntries()` when you need a plain object. |
| **Single pass, O(n)** | Each item is visited once and `Map` lookups are O(1) on average. |
| **`keyFn` gets `(item, index)`** | Mirrors `Array.prototype.map` and enables index-based grouping, e.g. chunking with `(_, i) => Math.floor(i / 3)`. |
| **Accepts any iterable** | Works with Sets, generators, and `Map.values()` at no extra cost. |
| **Stable ordering** | Items keep their input order within each group, so results are predictable and testable. |
| **Input validation** | Fails fast with a clear message instead of an obscure error deep in the loop. |

