 * strings (or symbols). If you need non-string keys (e.g. objects, or to keep
 * `1` and `"1"` distinct), use {@link groupByToMap} instead.
 *
 * The returned object has a `null` prototype, so keys such as `"constructor"`
 * or `"__proto__"` are safe and won't collide with `Object.prototype`.
 *
 * @template T - The type of elements in the input array.
 * @template {PropertyKey} K - The type of key produced by `keyFn`.
 *
 * @param {readonly T[]} arr - The array to group. It is not mutated.
 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 *   A function that returns the group key for each element. It receives the
 *   current element, its index, and the full array (mirroring `Array#map`).
 *
 * @returns {Record<string, T[]>} An object mapping each key to an array of the
 *   elements that produced it. Groups preserve the input order of elements.
 *   Returns an empty object for an empty input array.
 *
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: 'Ana',  dept: 'eng' },
 *   { name: 'Ben',  dept: 'sales' },
 *   { name: 'Cara', dept: 'eng' },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   eng:   [{ name: 'Ana', dept: 'eng' }, { name: 'Cara', dept: 'eng' }],
 * //   sales: [{ name: 'Ben', dept: 'sales' }]
 * // }
 *
 * @example
 * // Group strings by length
 * groupBy(['one', 'two', 'three'], s => s.length);
 * // => { '3': ['one', 'two'], '5': ['three'] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected keyFn to be a function, got ${typeof keyFn}`);
  }

  // Null-prototype object avoids collisions with inherited properties
  // like "toString" or "__proto__".
  const groups = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (groups[key] === undefined) {
      groups[key] = [];
    }
    groups[key].push(item);
  }

  return groups;
