/**
 * Groups array elements into an object keyed by the result of `keyFn`.
 *
 * - Single pass, O(n) time.
 * - Input array is not mutated.
 * - Element order within each group matches input order.
 * - Result has a null prototype (safe for keys like "__proto__").
 *
 * @param arr   - The array to group.
 * @param keyFn - Derives a group key from each element (receives item, index, array).
 * @returns An object mapping each key to the elements that produced it.
 *
 * @example
 * groupBy([1.2, 1.8, 2.1], Math.floor); // { '1': [1.2, 1.8], '2': [2.1] }
 */
export function groupBy<T, K extends PropertyKey>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K,
): Partial<Record<K, T[]>> {
  const groups = Object.create(null) as Partial<Record<K, T[]>>;

  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    (groups[key] ??= []).push(item);
  });

  return groups;
}

/**
 * Like {@link groupBy}, but returns a `Map` so keys keep their type and
 * identity (no string coercion). Keys are compared with SameValueZero.
 *
 * @example
 * groupByToMap(users, u => u.team); // Map<Team, User[]>, keyed by object identity
 */
export function groupByToMap<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K,
): Map<K, T[]> {
  const groups = new Map<K, T[]>();

  arr.forEach((item, i) => {
    const key = keyFn(item, i, arr);
    const bucket = groups.get(key);
    if (bucket) bucket.push(item);
    else groups.set(key, [item]);
  });

  return groups;
}
```

> **Why `Partial<Record<K, T[]>>`?** Not every possible key is guaranteed to have a group. For example, if `K` is `'even' | 'odd'` but the input has only odd numbers, `result.even` is `undefined`. `Partial` makes TypeScript force you to handle that case.

## Design notes

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Prevents keys like `"constructor"` or `"__proto__"` from colliding with or polluting `Object.prototype`. |
| **`keyFn(item, index, array)`** | Mirrors the `Array#map`/`forEach` signature, so index-based grouping works (e.g. chunking by `i % 3`). |
| **Order preserved** | Elements appear in each group in their original order, which makes results predictable and easy to test. |
| **Separate Map variant** | Object keys are always strings, so `1` and `"1"` merge. `groupByToMap` keeps them distinct and supports object keys. |
| **Input validation** | Fails fast with a clear message instead of an obscure error deep in the loop. |

