```typescript
/**
 * A simple in-memory key/value cache.
 *
 * @typeParam K - The type of keys stored in the cache.
 * @typeParam V - The type of values stored in the cache.
 *
 * @example
 * ```ts
 * const cache = new Cache<string, number>();
 * cache.set("answer", 42);
 * cache.get("answer");    // 42
 * cache.has("answer");    // true
 * cache.delete("answer"); // true
 * cache.get("answer");    // undefined
 * ```
 */
export class Cache<K, V> {
  private readonly store = new Map<K, V>();

  /**
   * Retrieves the value associated with a key.
   *
   * @param key - The key to look up.
   * @returns The cached value, or `undefined` if the key is not present.
   *
   * @remarks
   * If `undefined` is a valid stored value, use {@link Cache.has} to
   * distinguish a missing key from a stored `undefined`.
   */
  get(key: K): V | undefined {
    return this.store.get(key);
  }

  /**
   * Stores a value under the given key, replacing any existing value.
   *
   * @param key - The key to store the value under.
   * @param value - The value to cache.
   * @returns The cache instance, allowing calls to be chained.
   *
   * @example
   * ```ts
   * cache.set("a", 1).set("b", 2);
   * ```
   */
  set(key: K, value: V): this {
    this.store.set(key, value);
    return this;
  }

  /**
   * Checks whether a key exists in the cache.
   *
   * @param key - The key to check.
   * @returns `true` if the key is present, otherwise `false`.
   */
  has(key: K): boolean {
    return this.store.has(key);
  }

  /**
   * Removes a key and its associated value from the cache.
   *
   * @param key - The key to remove.
   * @returns `true` if the key existed and was removed, `false` if it was not present.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }
}
```

**Design notes:**
- **Generic types** (`K`, `V`) give type safety for both keys and values.
- **`Map` storage** supports any key type (including objects) and keeps insertion order, unlike a plain object.
- **`set` returns `this`** so calls can be chained, matching `Map`'s behavior.
- **`delete` returns a boolean** so callers can tell whether anything was actually removed.
- The internal `store` is `private`, so the four documented methods are the only public API.

If you need more, natural extensions would be a `clear()` method, a `size` getter, per-entry TTL expiration, or a max-size limit with LRU eviction.

