/**
 * A simple in-memory key-value cache.
 *
 * Entries can optionally expire after a time-to-live (TTL), specified in
 * milliseconds. Expired entries are removed lazily, when they are next accessed.
 *
 * @typeParam K - The type of keys stored in the cache.
 * @typeParam V - The type of values stored in the cache.
 *
 * @example
 * ```ts
 * const cache = new Cache<string, number>();
 * cache.set("answer", 42);
 * cache.get("answer"); // 42
 *
 * cache.set("temp", 1, 1000); // expires in 1 second
 * ```
 */
export class Cache<K, V> {
  private readonly store = new Map<K, { value: V; expiresAt: number | null }>();

  /**
   * Retrieves the value associated with `key`.
   *
