I'll write this in TypeScript, with JSDoc comments on the public API. The class wraps a `Map`, with optional time-to-live (TTL) expiration and an optional size limit that evicts the least-recently-used entry.

```typescript
/**
 * Options for configuring a {@link Cache} instance.
 */
export interface CacheOptions {
  /**
   * Default time-to-live for entries, in milliseconds.
   * If omitted, entries never expire unless a TTL is given to {@link Cache.set}.
   */
  defaultTtl?: number;

  /**
   * Maximum number of entries to hold. When the limit is exceeded,
   * the least recently used entry is evicted.
   * If omitted, the cache size is unbounded.
   */
  maxSize?: number;
}

interface Entry<V> {
  value: V;
  expiresAt: number | null;
}

/**
 * A simple in-memory key/value cache with optional TTL expiration
 * and least-recently-used (LRU) eviction.
 *
 * @typeParam K - The type of keys.
 * @typeParam V - The type of cached values.
 *
 * @example
 * ```ts
 * const cache = new Cache<string, number>({ defaultTtl: 60_000, maxSize: 100 });
 *
 * cache.set("answer", 42);
 * cache.get("answer");    // 42
 * cache.has("answer");    // true
 * cache.delete("answer"); // true
 * cache.get("answer");    // undefined
 * ```
 */
export class Cache<K, V> {
  private readonly store = new Map<K, Entry<V>>();
  private readonly defaultTtl?: number;
  private readonly maxSize?: number;

  /**
   * Creates a new cache.
   *
   * @param options - Optional configuration. See {@link CacheOptions}.
   * @throws {RangeError} If `defaultTtl` is not a positive finite number,
   *   or `maxSize` is not a positive integer.
   */
  constructor(options: CacheOptions = {}) {
    const { defaultTtl, maxSize } = options;

    if (defaultTtl !== undefined) assertValidTtl(defaultTtl);
    if (maxSize !== undefined && (!Number.isInteger(maxSize) || maxSize <= 0)) {
      throw new RangeError(`maxSize must be a positive integer, got ${maxSize}`);
    }

    this.defaultTtl = defaultTtl;
    this.maxSize = maxSize;
  }

  /**
   * Retrieves the value stored under `key`.
   *
   * Reading an entry marks it as most recently used. Expired entries are
   * removed and treated as missing.
   *
   * @param key - The key to look up.
   * @returns The cached value, or `undefined` if the key is missing or expired.
   *
   * @remarks If `undefined` is a legitimate stored value, use {@link Cache.has}
   *   to distinguish "stored undefined" from "missing".
   */
  get(key: K): V | undefined {
    const entry = this.getLiveEntry(key);
    if (!entry) return undefined;

    // Re-insert to mark as most recently used (Map preserves insertion order).
    this.store.delete(key);
    this.store.set(key, entry);
    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any existing entry.
   *
   * If the cache is at `maxSize`, the least recently used entry is evicted.
   *
   * @param key - The key to store the value under.
   * @param value - The value to cache.
   * @param ttl - Optional time-to-live in milliseconds for this entry.
   *   Overrides the cache's `defaultTtl`. Omit to use the default.
   * @returns The cache instance, allowing calls to be chained.
   * @throws {RangeError} If `ttl` is not a positive finite number.
   */
  set(key: K, value: V, ttl: number | undefined = this.defaultTtl): this {
    if (ttl !== undefined) assertValidTtl(ttl);

    const expiresAt = ttl === undefined ? null : Date.now() + ttl;

    // Delete first so an overwrite moves the key to the most-recent position.
    this.store.delete(key);
    this.store.set(key, { value, expiresAt });

    if (this.maxSize !== undefined && this.store.size > this.maxSize) {
      // The first key in iteration order is the least recently used.
      const oldestKey = this.store.keys().next().value as K;
      this.store.delete(oldestKey);
    }

    return this;
  }

  /**
   * Checks whether a live (non-expired) entry exists for `key`.
   *
   * Unlike {@link Cache.get}, this does **not** affect LRU ordering.
   * Expired entries found during the check are removed.
   *
   * @param key - The key to check.
   * @returns `true` if the key exists and has not expired, otherwise `false`.
   */
  has(key: K): boolean {
    return this.getLiveEntry(key) !== undefined;
  }

  /**
   * Removes the entry for `key`, if present.
   *
   * @param key - The key to remove.
   * @returns `true` if a live entry was removed, or `false` if the key was
   *   missing or had already expired.
   */
  delete(key: K): boolean {
    const existed = this.getLiveEntry(key) !== undefined;
    this.store.delete(key);
    return existed;
  }

  /** Returns the entry for `key` if it exists and hasn't expired; purges it if expired. */
  private getLiveEntry(key: K): Entry<V> | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;

    if (entry.expiresAt !== null && Date.now() >= entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return entry;
  }
}

function assertValidTtl(ttl: number): void {
  if (!Number.isFinite(ttl) || ttl <= 0) {
    throw new RangeError(`ttl must be a positive finite number, got ${ttl}`);
  }
}
```

