 * const cache = new Cache<string, number>();
 * cache.set("answer", 42);
 * cache.get("answer");    // 42
 * cache.has("answer");    // true
 * cache.delete("answer"); // true
 * cache.get("answer");    // undefined
 */
export class Cache<K, V> {
  /** Internal storage: value plus optional absolute expiry timestamp (ms). */
  private readonly store = new Map<K, { value: V; expiresAt?: number }>();

  /**
   * Retrieves the value stored under `key`.
   *
   * Expired entries are removed lazily when accessed.
   *
   * @param key - The key to look up.
   * @returns The cached value, or `undefined` if the key is missing or expired.
   */
  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;

    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any existing entry.
   *
   * @param key - The key to store the value under.
   * @param value - The value to cache.
   * @param ttlMs - Optional time-to-live in milliseconds. If omitted,
   *   the entry never expires. Must be a positive finite number.
   * @returns The cache instance, allowing calls to be chained.
   * @throws {RangeError} If `ttlMs` is provided but is not a positive finite number.
   */
  set(key: K, value: V, ttlMs?: number): this {
    if (ttlMs !== undefined && (!Number.isFinite(ttlMs) || ttlMs <= 0)) {
      throw new RangeError(`ttlMs must be a positive finite number, got ${ttlMs}`);
    }
    const expiresAt = ttlMs !== undefined ? Date.now() + ttlMs : undefined;
    this.store.set(key, { value, expiresAt });
    return this;
  }

  /**
   * Checks whether a non-expired entry exists for `key`.
   *
   * Note: a key explicitly set to `undefined` still counts as present.
   *
   * @param key - The key to check.
   * @returns `true` if the key exists and has not expired, otherwise `false`.
   */
  has(key: K): boolean {
    const entry = this.store.get(key);
    if (!entry) return false;

    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry stored under `key`.
   *
   * @param key - The key to remove.
   * @returns `true` if a non-expired entry was removed, `false` if the key
   *   was not present or had already expired.
   */
  delete(key: K): boolean {
    const entry = this.store.get(key);
    if (!entry) return false;

    this.store.delete(key);
    return !this.isExpired(entry);
  }

  /** Returns `true` if the entry has an expiry time that has passed. */
  private isExpired(entry: { expiresAt?: number }): boolean {
    return entry.expiresAt !== undefined && Date.now() >= entry.expiresAt;
  }
}
```

## API Reference

| Method | Signature | Returns | Description |
|---|---|---|---|
| `get` | `get(key: K)` | `V \| undefined` | Returns the cached value, or `undefined` if the key is missing or expired. |
| `set` | `set(key: K, value: V, ttlMs?: number)` | `this` | Stores a value, overwriting any existing one. The optional `ttlMs` sets an expiry. The method is chainable. |
| `has` | `has(key: K)` | `boolean` | Returns `true` if a live (non-expired) entry exists. |
| `delete` | `delete(key: K)` | `boolean` | Removes an entry. Returns `true` if a live entry was removed. |

## Usage

```ts
const cache = new Cache<string, { name: string }>();

cache
  .set("user:1", { name: "Ada" })            // never expires
  .set("user:2", { name: "Linus" }, 5_000);  // expires in 5 seconds

cache.get("user:1");    // { name: "Ada" }
cache.has("user:2");    // true (for the next 5 seconds)
cache.delete("user:1"); // true
cache.has("user:1");    // false
```

## Notes

- **Lazy expiration:** Expired entries are only removed when they are accessed through `get`, `has`, or `delete`. If you store many short-lived keys that are never read again, consider adding a periodic cleanup step or a maximum size.
- **`undefined` values:** If you store `undefined` as a value, `get` cannot tell it apart from a missing key. Use `has` to distinguish the two cases.
- **Key equality:** Keys are compared with `Map` semantics (SameValueZero). Object keys therefore match by reference, not by structure.

