 * If `options.signal` (an `AbortSignal`) is aborted, the function stops
 * immediately, including during a backoff wait, and rejects with the
 * abort reason. Aborts are never retried.
 *
 * ## Caveats
 * - Retrying non-idempotent requests (e.g. `POST`) can cause duplicate side
 *   effects. Only retry them if your API supports idempotency keys.
 * - Request bodies that are streams (`ReadableStream`) can only be consumed
 *   once and therefore cannot be safely retried. Use strings, `Blob`s,
 *   `FormData`, or `URLSearchParams` instead.
 *
 * @param {string | URL | Request} url
 *        The resource to fetch.
 * @param {RequestInit} [options={}]
 *        Standard `fetch` options (method, headers, body, signal, ...).
 * @param {number} [retries=3]
 *        Maximum number of *retries* after the initial attempt.
 *        Total attempts = `retries + 1`.
 * @param {RetryConfig} [retryConfig={}]
 *        Optional tuning for backoff behavior.
 *
 * @returns {Promise<Response>}
 *          Resolves with the first successful or non-retryable `Response`.
 *          If retries are exhausted on a retryable status, resolves with the
 *          last `Response` so the caller can inspect it.
 *
 * @throws {Error}
 *         Rejects with the last error if every attempt failed due to a
 *         network error or timeout, or with the abort reason if cancelled.
 *
 * @example
 * // Basic usage: up to 3 retries with default backoff
 * const res = await fetchWithRetry('https://api.example.com/data');
 * const data = await res.json();
 *
 * @example
 * // Custom configuration with logging and a per-attempt timeout
 * const res = await fetchWithRetry(
 *   'https://api.example.com/items',
 *   { headers: { Accept: 'application/json' } },
 *   5,
 *   {
 *     baseDelay: 1000,
 *     timeout: 8000,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(
 *         `Retry #${attempt} in ${delay}ms`,
 *         error?.message ?? `HTTP ${response.status}`
 *       ),
 *   }
 * );
 *
 * @example
 * // Cancelling from the outside
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 10_000);
 * await fetchWithRetry(url, { signal: controller.signal });
 */
async function fetchWithRetry(url, options = {}, retries = 3, retryConfig = {}) {
  const {
    baseDelay = 500,
    maxDelay = 30_000,
    factor = 2,
    jitter = true,
    timeout,
    retryOn = [408, 425, 429, 500, 502, 503, 504],
    onRetry,
  } = retryConfig;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`"retries" must be a non-negative integer, got: ${retries}`);
  }

  const userSignal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Respect cancellation before every attempt.
    throwIfAborted(userSignal);

    // Combine the caller's signal with an optional per-attempt timeout.
    const { signal, cleanup } = createAttemptSignal(userSignal, timeout);

    try {
      const response = await fetch(url, { ...options, signal });
      cleanup();

      const isLastAttempt = attempt === retries;
      if (response.ok || !retryOn.includes(response.status) || isLastAttempt) {
        return response;
      }

      // Retryable status: compute delay, preferring the server's Retry-After.
      const delay =
        parseRetryAfter(response.headers.get('Retry-After'), maxDelay) ??
        computeBackoff(attempt, baseDelay, factor, maxDelay, jitter);

      // Discard the body so the underlying connection can be reused.
      response.body?.cancel().catch(() => {});

      onRetry?.({ attempt: attempt + 1, delay, response });
      await sleep(delay, userSignal);
    } catch (error) {
      cleanup();

      // Never retry a user-initiated abort.
      if (userSignal?.aborted) throw userSignal.reason ?? error;

      lastError = error;
      if (attempt === retries) break;

      const delay = computeBackoff(attempt, baseDelay, factor, maxDelay, jitter);
      onRetry?.({ attempt: attempt + 1, delay, error });
      await sleep(delay, userSignal);
    }
  }

  throw lastError;
}

/* ------------------------------------------------------------------------ */
/* Helpers                                                                  */
/* ------------------------------------------------------------------------ */

/**
 * Computes the exponential backoff delay for a given attempt.
 * @param {number} attempt   Zero-based attempt index.
 * @param {number} base      Base delay in ms.
 * @param {number} factor    Growth multiplier.
 * @param {number} max       Maximum delay in ms.
 * @param {boolean} jitter   Whether to apply full jitter.
 * @returns {number} Delay in milliseconds.
 */
function computeBackoff(attempt, base, factor, max, jitter) {
  const exp = Math.min(max, base * factor ** attempt);
  return Math.round(jitter ? Math.random() * exp : exp);
}

/**
 * Parses an HTTP `Retry-After` header (either delta-seconds or an HTTP date).
 * @param {string | null} header
 * @param {number} max  Cap for the returned delay.
 * @returns {number | undefined} Delay in ms, or `undefined` if absent/invalid.
 */
function parseRetryAfter(header, max) {
  if (!header) return undefined;

  const seconds = Number(header);
  if (Number.isFinite(seconds) && seconds >= 0) {
    return Math.min(max, seconds * 1000);
  }

  const date = Date.parse(header);
  if (!Number.isNaN(date)) {
    return Math.min(max, Math.max(0, date - Date.now()));
  }

  return undefined;
}

/**
 * Creates an AbortSignal for a single attempt that fires when either the
 * caller's signal aborts or the per-attempt timeout elapses.
 * @param {AbortSignal | undefined} userSignal
 * @param {number | undefined} timeout
 * @returns {{ signal: AbortSignal | undefined, cleanup: () => void }}
 */
function createAttemptSignal(userSignal, timeout) {
  if (timeout == null) return { signal: userSignal, cleanup: () => {} };

  const controller = new AbortController();
  const timer = setTimeout(
    () => controller.abort(new Error(`Request timed out after ${timeout}ms`)),
    timeout
  );
  const onAbort = () => controller.abort(userSignal.reason);
  userSignal?.addEventListener('abort', onAbort, { once: true });

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timer);
      userSignal?.removeEventListener('abort', onAbort);
    },
  };
}

/**
 * Waits for `ms` milliseconds, rejecting early if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason);
    }
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Throws the signal's abort reason if it has already been aborted.
 * @param {AbortSignal} [signal]
 */
function throwIfAborted(signal) {
  if (signal?.aborted) {
    throw signal.reason ?? new DOMException('Aborted', 'AbortError');
  }
}

export { fetchWithRetry };
```

## Key design decisions

| Decision | Rationale |
|---|---|
| **Retries only transient failures** | Network errors, timeouts, and 408/425/429/5xx statuses are usually temporary. A 404 or 401 won't fix itself. |
| **Full jitter** | Randomizing the delay prevents a "thundering herd" where many clients retry at the same moment. This is the approach recommended by AWS's architecture guidance. |
| **Honors `Retry-After`** | Servers that rate-limit you often say exactly when to come back. Respecting that is both polite and effective. |
| **Returns the last response instead of throwing on HTTP errors** | This matches native `fetch` semantics: HTTP errors resolve, network errors reject. Callers can still check `res.ok`. |
| **Abort-aware** | A cancelled request stops immediately, even mid-backoff, so it never leaves dangling timers. |
| **Drains discarded bodies** | Unconsumed response bodies can keep connections open, especially in Node. |

## Example backoff timeline (defaults, jitter disabled)

| Attempt | Delay before it |
|---|---|
| 1 (initial) | — |
| 2 | 500 ms |
| 3 | 1000 ms |
| 4 | 2000 ms |

With jitter enabled, each delay is a random value between 0 and the number shown.

Here's a robust, well-documented implementation in JavaScript (works in modern browsers and Node.js 18+, which have a global `fetch`):

```javascript
/**
 * Error thrown when all retry attempts have been exhausted.
 * Preserves the last underlying error/response for inspection.
 */
class FetchRetryError extends Error {
  /**
   * @param {string} message - Human-readable description.
   * @param {object} details
   * @param {number} details.attempts - Total number of attempts made.
   * @param {Error} [details.cause] - The last error thrown (network error, timeout, etc.).
   * @param {Response} [details.response] - The last HTTP response received, if any.
   */
  constructor(message, { attempts, cause, response } = {}) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause;
    this.response = response;
  }
}

/**
 * HTTP status codes that are generally safe and sensible to retry.
 * - 408 Request Timeout
 * - 429 Too Many Requests
 * - 500, 502, 503, 504 Server/gateway errors
 */
const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504]);

/**
 * Sleep for a given number of milliseconds, aborting early if the signal fires.
 *
 * @param {number} ms - Duration to wait in milliseconds.
 * @param {AbortSignal} [signal] - Optional signal to cancel the wait.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason);
    }

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Parse a `Retry-After` header into milliseconds.
 * Supports both delta-seconds ("120") and HTTP-date formats.
 *
 * @param {string|null} header - Raw header value.
 * @returns {number|null} Delay in ms, or null if absent/invalid.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Fetch a resource, retrying on failure with exponential backoff and jitter.
 *
 * ## What counts as a failure?
 * - **Network errors** (fetch rejects, e.g. DNS failure, connection reset).
 * - **Retryable HTTP statuses**: 408, 429, 500, 502, 503, 504.
 *
 * Non-retryable responses (e.g. 400, 401, 404) are returned immediately —
 * retrying them would not change the outcome. Successful responses (2xx)
 * are returned as-is.
 *
 * ## Backoff strategy
 * The delay before retry attempt `n` (0-indexed) is:
 *
 *     delay = min(maxDelay, baseDelay * 2^n)
 *
 * with "full jitter" applied (a random value between 0 and `delay`) to avoid
 * many clients retrying in lockstep (the "thundering herd" problem).
 * If the server sends a `Retry-After` header (common with 429/503), that
 * value is honored instead (still capped at `maxDelay`).
 *
 * ## Cancellation
 * If `options.signal` is provided and aborted, the function stops immediately
 * — whether mid-request or mid-backoff — and rejects with the abort reason.
 *
 * ## Caution: idempotency
 * Retrying non-idempotent requests (e.g. `POST` that creates a resource) can
 * cause duplicate side effects. Only retry such requests if the server
 * supports idempotency keys or duplicates are harmless.
 *
 * @param {string|URL|Request} url - The resource to fetch.
 * @param {RequestInit} [options={}] - Standard fetch options (method, headers, body, signal...).
 *   Note: if `body` is a one-shot stream, it cannot be re-sent on retry; use a
 *   string, Blob, FormData, or ArrayBuffer instead.
 * @param {number} [retries=3] - Maximum number of *retries* after the first attempt.
 *   Total attempts = retries + 1. Use 0 to disable retrying.
 * @param {object} [config={}] - Optional tuning parameters.
 * @param {number} [config.baseDelay=500] - Initial backoff delay in ms.
 * @param {number} [config.maxDelay=30000] - Upper bound on any single delay in ms.
 * @param {(info: {attempt: number, delay: number, error?: Error, response?: Response}) => void} [config.onRetry]
 *   Optional callback invoked before each retry (useful for logging/metrics).
 *
 * @returns {Promise<Response>} Resolves with the first successful or
 *   non-retryable Response.
 *
 * @throws {FetchRetryError} When all attempts fail. Inspect `.cause` for the
 *   last thrown error or `.response` for the last retryable HTTP response.
 * @throws {DOMException} The abort reason, if `options.signal` is aborted.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry("https://api.example.com/data");
 * const data = await res.json();
 *
 * @example
 * // Custom retries, timeout per attempt, and logging
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Accept: "application/json" } },
 *   5,
 *   {
 *     baseDelay: 200,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(
 *         `Retry #${attempt} in ${Math.round(delay)}ms`,
 *         error?.message ?? `HTTP ${response.status}`
 *       ),
 *   }
 * );
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const { baseDelay = 500, maxDelay = 30_000, onRetry } = config;
  const { signal } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError(`retries must be a non-negative integer, got ${retries}`);
  }

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Reset per-attempt state so a stale value can't leak into the next decision.
    lastError = undefined;
    lastResponse = undefined;

    try {
      const response = await fetch(url, options);

      // Success, or a client error that retrying won't fix: return immediately.
      if (!RETRYABLE_STATUS_CODES.has(response.status)) {
        return response;
      }

      lastResponse = response;
    } catch (error) {
      // Never retry a deliberate cancellation.
      if (signal?.aborted) throw signal.reason ?? error;
      lastError = error;
    }

    // Out of attempts: stop looping and report failure below.
    if (attempt === retries) break;

    // Compute delay: honor Retry-After if present, else exponential backoff w/ full jitter.
    const retryAfter = parseRetryAfter(lastResponse?.headers.get("Retry-After"));
    const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay = retryAfter != null
      ? Math.min(maxDelay, retryAfter)
      : Math.random() * exponential;

    onRetry?.({ attempt: attempt + 1, delay, error: lastError, response: lastResponse });

    // Free the connection held by the discarded response body.
    await lastResponse?.body?.cancel().catch(() => {});

    await sleep(delay, signal);
  }

  const reason = lastError
    ? `network error: ${lastError.message}`
    : `HTTP ${lastResponse.status} ${lastResponse.statusText}`;

  throw new FetchRetryError(
    `Request to ${url} failed after ${retries + 1} attempt(s) (${reason})`,
    { attempts: retries + 1, cause: lastError, response: lastResponse }
  );
}

export { fetchWithRetry, FetchRetryError };
```

## Key design decisions

| Decision | Rationale |
|---|---|
| **Only retry specific statuses** | A 404 or 401 won't fix itself; retrying wastes time and load. |
| **Full jitter** | Prevents synchronized retry storms when many clients fail at once (per AWS's backoff research). |
| **Honor `Retry-After`** | Servers often specify exactly when to come back on 429/503. |
| **Cap at `maxDelay`** | Exponential growth gets huge fast (`500 * 2^10` ≈ 8.5 min). |
| **Respect `AbortSignal`** | Callers can cancel during a request *or* a backoff wait. |
| **Cancel discarded bodies** | Unconsumed response bodies can hold connections open, especially in Node. |
| **Rich error object** | `FetchRetryError` exposes the attempt count, last error, and last response for debugging. |

## Per-attempt timeouts

`fetch` has no built-in timeout. To bound each attempt, combine signals:

```javascript
const userController = new AbortController();

const res = await fetchWithRetry(url, {
  signal: AbortSignal.any([userController.signal, AbortSignal.timeout(5000)]),
});
```

Note that this timeout applies to the whole operation, and a timeout abort is treated as a cancellation and is not retried. For a true per-attempt timeout that *is* retried, you'd create a fresh `AbortSignal.timeout()` inside the loop for each attempt. That's an easy extension if you need it.

Here's a robust implementation in JavaScript (works in modern browsers and Node.js 18+, which have a native `fetch`):

```javascript
/**
 * Error thrown when all retry attempts are exhausted.
 * Exposes the final failure cause and the number of attempts made.
 */
class FetchRetryError extends Error {
  /**
   * @param {string} message - Human-readable description.
   * @param {object} details
   * @param {number} details.attempts - Total number of attempts made.
   * @param {Error} [details.cause] - The last underlying error (network error, timeout, etc.).
   * @param {Response} [details.response] - The last HTTP response, if the failure was a bad status.
   */
  constructor(message, { attempts, cause, response } = {}) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause;
    this.response = response;
  }
}

/** HTTP status codes that are generally safe and useful to retry. */
const DEFAULT_RETRY_STATUSES = new Set([408, 425, 429, 500, 502, 503, 504]);

/**
 * Pause execution for a given duration, aborting early if the signal fires.
 *
 * @param {number} ms - Milliseconds to wait.
 * @param {AbortSignal} [signal] - Optional signal to cancel the wait.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason);
    }
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Parse a `Retry-After` header into milliseconds.
 * Supports both delta-seconds ("120") and HTTP-date formats.
 *
 * @param {string|null} header - Raw header value.
 * @returns {number|null} Delay in ms, or null if absent/unparseable.
 */
function parseRetryAfter(header) {
  if (!header) return null;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());
  return null;
}

/**
 * Perform a `fetch` request, retrying on failure with exponential backoff and jitter.
 *
 * ## What counts as a failure?
 * - Network errors (DNS failure, connection reset, offline, etc.).
 * - HTTP responses whose status is in `retryOn` (default: 408, 425, 429, 500, 502, 503, 504).
 *
 * Other non-2xx responses (e.g. 400, 401, 404) are **not** retried, because
 * repeating them will almost never change the outcome. They are returned as-is,
 * matching native `fetch` semantics, so callers can inspect `response.ok`.
 *
 * ## Backoff strategy
 * The delay before retry *n* (0-indexed) is:
 *
 *     delay = min(maxDelay, baseDelay * 2^n)
 *
 * Then "full jitter" is applied: the actual wait is a random value in `[0, delay]`.
 * Jitter prevents many clients from retrying in lockstep ("thundering herd").
 * If the server sends a `Retry-After` header (common with 429/503), that value
 * is honored instead (still capped at `maxDelay`).
 *
 * With the defaults (baseDelay = 300ms, retries = 3), the maximum waits are
 * roughly 300ms, 600ms, 1200ms.
 *
 * ## Cancellation
 * If `options.signal` is aborted, the function stops immediately (including
 * during a backoff wait) and rejects with the abort reason. Aborts are never retried.
 *
 * ## Idempotency warning
 * Retrying non-idempotent requests (e.g. `POST` that creates a resource) can
 * cause duplicate side effects. Only retry such requests if the server supports
 * idempotency keys or you know duplicates are harmless.
 *
 * ## Request bodies
 * Bodies that are streams (`ReadableStream`) can only be consumed once and
 * therefore cannot be safely retried. Use strings, `Blob`, `FormData`,
 * `URLSearchParams`, or `ArrayBuffer` bodies when retries are needed.
 *
 * @param {string|URL|Request} url - The resource to fetch.
 * @param {RequestInit & {
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   timeout?: number,
 *   retryOn?: Iterable<number> | ((response: Response) => boolean),
 *   onRetry?: (info: { attempt: number, delay: number, error?: Error, response?: Response }) => void
 * }} [options={}] - Standard `fetch` options, plus these retry settings:
 *   - `baseDelay` (ms, default 300): initial backoff delay.
 *   - `maxDelay` (ms, default 10000): upper bound for any single wait.
 *   - `timeout` (ms, optional): per-attempt timeout; a timed-out attempt is retried.
 *   - `retryOn`: status codes to retry, or a predicate receiving the Response.
 *   - `onRetry`: callback invoked before each retry (useful for logging/metrics).
 * @param {number} [retries=3] - Maximum number of *retries* after the first
 *   attempt. Total attempts = `retries + 1`. Use 0 to disable retrying.
 * @returns {Promise<Response>} Resolves with the first successful (or
 *   non-retryable) response.
 * @throws {FetchRetryError} When all attempts fail. Inspect `.cause` for the
 *   last error or `.response` for the last bad response.
 * @throws {DOMException} With name `"AbortError"` (or the custom reason) if the
 *   caller's signal is aborted.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry("https://api.example.com/data");
 * const data = await res.json();
 *
 * @example
 * // Custom settings with logging and a per-attempt timeout
 * const res = await fetchWithRetry(
 *   "https://api.example.com/items",
 *   {
 *     method: "GET",
 *     headers: { Accept: "application/json" },
 *     baseDelay: 500,
 *     maxDelay: 5000,
 *     timeout: 8000,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(`Retry #${attempt} in ${delay}ms`, error ?? response?.status),
 *   },
 *   5
 * );
 *
 * @example
 * // Cancel all attempts after 20 seconds total
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 20_000);
 * await fetchWithRetry(url, { signal: controller.signal });
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    timeout,
    retryOn = DEFAULT_RETRY_STATUSES,
    onRetry,
    signal: userSignal,
    ...fetchOptions
  } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError(`retries must be a non-negative integer, got ${retries}`);
  }

  // Normalize retryOn into a predicate.
  const shouldRetryResponse =
    typeof retryOn === "function"
      ? retryOn
      : ((set) => (res) => set.has(res.status))(new Set(retryOn));

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Combine the caller's signal with an optional per-attempt timeout.
    const signals = [userSignal, timeout ? AbortSignal.timeout(timeout) : null].filter(Boolean);
    const signal = signals.length > 1 ? AbortSignal.any(signals) : signals[0];

    try {
      const response = await fetch(url, { ...fetchOptions, signal });

      // Success or a non-retryable status: hand it back to the caller.
      if (!shouldRetryResponse(response)) return response;

      lastResponse = response;
      lastError = undefined;
    } catch (err) {
      // The caller cancelled: stop immediately, never retry.
      if (userSignal?.aborted) throw userSignal.reason ?? err;
      // Otherwise it's a network error or a per-attempt timeout: retryable.
      lastError = err;
      lastResponse = undefined;
    }

    // No retries left; fall through to the final error.
    if (attempt === retries) break;

    // Compute the backoff: honor Retry-After if present, else exponential + full jitter.
    const retryAfter = parseRetryAfter(lastResponse?.headers.get("Retry-After"));
    const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay = Math.round(
      retryAfter !== null ? Math.min(maxDelay, retryAfter) : Math.random() * exponential
    );

    // Release the unused response body so the connection can be reused.
    await lastResponse?.body?.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, error: lastError, response: lastResponse });

    await sleep(delay, userSignal);
  }

  const reason = lastResponse
    ? `HTTP ${lastResponse.status} ${lastResponse.statusText}`.trim()
    : lastError?.message ?? "unknown error";

  throw new FetchRetryError(
    `Request to ${String(url)} failed after ${retries + 1} attempt(s): ${reason}`,
    { attempts: retries + 1, cause: lastError, response: lastResponse }
  );
}

