```javascript
/**
 * @typedef {Object} RetryOptions
 * @property {number}   [baseDelay=500]      Initial delay in milliseconds before the first retry.
 * @property {number}   [maxDelay=30000]     Upper bound (ms) for any single backoff delay.
 * @property {number}   [factor=2]           Multiplier applied to the delay after each attempt.
 * @property {boolean}  [jitter=true]        If true, applies "full jitter" (random delay between 0
 *                                           and the computed backoff) to avoid thundering herds.
 * @property {number[]} [retryOn]            HTTP status codes that should trigger a retry.
 *                                           Defaults to [408, 425, 429, 500, 502, 503, 504].
 * @property {number}   [timeout]            Optional per-attempt timeout in ms. Each attempt is
 *                                           aborted if it takes longer than this.
 * @property {(info: {attempt: number, delay: number, error?: Error, response?: Response}) => void} [onRetry]
 *                                           Optional callback invoked before each retry; useful
 *                                           for logging or metrics.
 */

/**
 * Default HTTP status codes considered transient and therefore retryable.
 *  - 408 Request Timeout
 *  - 425 Too Early
 *  - 429 Too Many Requests
 *  - 500, 502, 503, 504 Server / gateway errors
 * @type {number[]}
 */
const DEFAULT_RETRY_STATUSES = [408, 425, 429, 500, 502, 503, 504];

/**
 * Performs a `fetch` request, automatically retrying on transient failures
 * using exponential backoff.
 *
 * ## What counts as a failure?
 * 1. **Network errors**: `fetch` rejects (DNS failure, connection reset, offline, etc.).
 * 2. **Per-attempt timeouts**: if `retryOptions.timeout` is set and an attempt exceeds it.
 * 3. **Retryable HTTP statuses**: responses whose status is listed in `retryOn`
 *    (by default 408, 425, 429, and 5xx gateway/server errors).
 *
 * Non-retryable responses (e.g. 400, 401, 404) are returned immediately.
 * As with native `fetch`, this function does **not** throw for HTTP error
 * statuses; check `response.ok` yourself.
 *
 * ## Backoff strategy
 * The delay before retry *n* (0-indexed) is:
 *
 *     delay = min(maxDelay, baseDelay * factor^n)
 *
 * With `jitter` enabled (default), the actual wait is a random value in
 * `[0, delay]` ("full jitter"), which spreads out retries from many clients.
 *
 * If the server sends a `Retry-After` header (common with 429/503), that
 * value is honored instead, capped at `maxDelay`.
 *
 * ## Cancellation
 * If `options.signal` (an `AbortSignal`) is aborted, the current attempt is
 * cancelled, no further retries occur, and the returned promise rejects with
 * the abort reason.
 *
 * ## Caveats
 * - Retrying non-idempotent requests (e.g. `POST`) may cause duplicate side
 *   effects. Only retry these if the server supports idempotency keys.
 * - Request bodies that are streams (`ReadableStream`) can only be consumed
 *   once and therefore cannot be safely retried. Use strings, `Blob`,
 *   `FormData`, `URLSearchParams`, or `ArrayBuffer` bodies instead.
 *
 * @param {string | URL | Request} url
 *        The resource to fetch.
 * @param {RequestInit} [options={}]
 *        Standard `fetch` options (method, headers, body, signal, ...).
 * @param {number} [retries=3]
 *        Maximum number of *retries* after the initial attempt.
 *        Total attempts = `retries + 1`. Must be a non-negative integer.
 * @param {RetryOptions} [retryOptions={}]
 *        Optional tuning for backoff behavior.
 *
 * @returns {Promise<Response>}
 *          Resolves with the first successful or non-retryable `Response`,
 *          or with the last retryable `Response` once retries are exhausted.
 *
 * @throws {TypeError}  If `retries` is not a non-negative integer.
 * @throws {Error}      The last network/timeout error if every attempt failed
 *                      without producing a response.
 * @throws {DOMException} An `AbortError` if `options.signal` is aborted.
 *
 * @example
 * // Basic usage: up to 3 retries with default backoff (≈500ms, 1s, 2s)
 * const res = await fetchWithRetry('https://api.example.com/data');
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 *
 * @example
 * // Custom backoff, per-attempt timeout, and logging
 * const res = await fetchWithRetry(
 *   'https://api.example.com/items',
 *   { headers: { Accept: 'application/json' } },
 *   5,
 *   {
 *     baseDelay: 200,
 *     maxDelay: 5000,
 *     timeout: 3000,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(
 *         `Retry #${attempt} in ${Math.round(delay)}ms`,
 *         error?.message ?? `status ${response?.status}`
 *       ),
 *   }
 * );
 *
 * @example
 * // Cancelling from the outside
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 10_000);
 * await fetchWithRetry(url, { signal: controller.signal }, 4);
 */
async function fetchWithRetry(url, options = {}, retries = 3, retryOptions = {}) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`"retries" must be a non-negative integer, got ${retries}`);
  }

  const {
    baseDelay = 500,
    maxDelay = 30_000,
    factor = 2,
    jitter = true,
    retryOn = DEFAULT_RETRY_STATUSES,
    timeout,
    onRetry,
  } = retryOptions;

  const userSignal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Respect external cancellation before starting each attempt.
    throwIfAborted(userSignal);

    // Combine the caller's signal with an optional per-attempt timeout.
    const { signal, cleanup } = createAttemptSignal(userSignal, timeout);

    let response;
    try {
      response = await fetch(url, { ...options, signal });
    } catch (error) {
      cleanup();

      // Caller aborted: stop immediately, never retry.
      if (userSignal?.aborted) throw userSignal.reason ?? error;

      lastError = error;
      if (attempt === retries) break;

      const delay = computeDelay(attempt, { baseDelay, maxDelay, factor, jitter });
      onRetry?.({ attempt: attempt + 1, delay, error });
      await sleep(delay, userSignal);
      continue;
    }
    cleanup();

    // Success or non-retryable status: hand it back to the caller.
    if (!retryOn.includes(response.status) || attempt === retries) {
      return response;
    }

    // Retryable status: prefer the server's Retry-After hint if present.
    const retryAfter = parseRetryAfter(response.headers.get('Retry-After'));
    const delay =
      retryAfter !== null
        ? Math.min(retryAfter, maxDelay)
        : computeDelay(attempt, { baseDelay, maxDelay, factor, jitter });

    // Drain the body so the underlying connection can be reused.
    response.body?.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, response });
    await sleep(delay, userSignal);
  }

  // Every attempt failed with a network/timeout error.
  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

/**
 * Computes the exponential backoff delay for a given attempt.
 * @param {number} attempt Zero-based index of the attempt that just failed.
 * @param {{baseDelay: number, maxDelay: number, factor: number, jitter: boolean}} cfg
 * @returns {number} Delay in milliseconds.
 */
function computeDelay(attempt, { baseDelay, maxDelay, factor, jitter }) {
  const exp = Math.min(maxDelay, baseDelay * factor ** attempt);
  return jitter ? Math.random() * exp : exp;
}

/**
 * Parses an HTTP `Retry-After` header, which may be either a number of
 * seconds or an HTTP date.
 * @param {string | null} value
 * @returns {number | null} Delay in milliseconds, or null if absent/invalid.
 */
function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

/**
 * Resolves after `ms` milliseconds, or rejects early if `signal` aborts.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Creates an AbortSignal for a single attempt that fires when either the
 * caller's signal aborts or the per-attempt timeout elapses.
 * @param {AbortSignal} [userSignal]
 * @param {number} [timeout]
 * @returns {{ signal: AbortSignal | undefined, cleanup: () => void }}
 */
function createAttemptSignal(userSignal, timeout) {
  if (!timeout) return { signal: userSignal, cleanup: () => {} };

  const controller = new AbortController();
  const timer = setTimeout(
    () => controller.abort(new DOMException('Request timed out', 'TimeoutError')),
    timeout
  );
  const onAbort = () => controller.abort(userSignal.reason);
  userSignal?.addEventListener('abort', onAbort, { once: true });

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timer);
      userSignal?.removeEventListener('abort', onAbort);
    },
  };
}

/**
 * Throws the signal's abort reason if it has already been aborted.
 * @param {AbortSignal} [signal]
 */
function throwIfAborted(signal) {
  if (signal?.aborted) {
    throw signal.reason ?? new DOMException('Aborted', 'AbortError');
  }
}

