**Requirements:** Node.js 18+ (native `fetch`) or any modern browser.

Here's a robust, well-documented implementation in JavaScript, compatible with modern browsers and Node.js 18+ (both have a native `fetch`):

```javascript
/**
 * Error thrown when all retry attempts have been exhausted.
 * Preserves the last error/response so callers can inspect what went wrong.
 */
class FetchRetryError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {object} details
   * @param {number} details.attempts - Total number of attempts made.
   * @param {Error} [details.cause] - The last underlying error (network failure, timeout, etc.).
   * @param {Response} [details.response] - The last HTTP response received, if any.
   */
  constructor(message, { attempts, cause, response } = {}) {
    super(message);
    this.name = 'FetchRetryError';
    this.attempts = attempts;
    this.cause = cause;
    this.response = response;
  }
}

/**
 * HTTP status codes that are generally safe and sensible to retry.
 *  - 408 Request Timeout
 *  - 425 Too Early
 *  - 429 Too Many Requests (rate limited)
 *  - 500, 502, 503, 504 (transient server/gateway errors)
 *
 * Other 4xx errors (400, 401, 403, 404, ...) indicate a client problem that
 * retrying will not fix, so they are returned immediately.
 */
const DEFAULT_RETRY_STATUSES = new Set([408, 425, 429, 500, 502, 503, 504]);

/**
 * Sleep for a given number of milliseconds, aborting early if the signal fires.
 *
 * @param {number} ms - Duration to wait.
 * @param {AbortSignal} [signal] - Optional signal to cancel the wait.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Parse a `Retry-After` header into milliseconds.
 * The header may be either a number of seconds or an HTTP date.
 *
 * @param {string|null} header - Raw header value.
 * @returns {number|null} Delay in ms, or null if absent/unparseable.
 */
function parseRetryAfter(header) {
  if (!header) return null;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());
  return null;
}

/**
 * Fetch a resource, automatically retrying on transient failures using
 * exponential backoff with "full jitter".
 *
 * ## What gets retried
 * - Network errors (DNS failure, connection reset, offline, etc.)
 * - Per-attempt timeouts (see `options.timeout`)
 * - Responses whose status is in `options.retryOn` (default: 408, 425, 429, 5xx gateway/server errors)
 *
 * ## What does NOT get retried
 * - Successful responses (2xx/3xx) — returned immediately.
 * - Non-retryable client errors (e.g. 400, 401, 404) — returned immediately
 *   so the caller can handle them like a normal `fetch` response.
 * - Aborts triggered by the caller's own `options.signal`.
 *
 * ## Backoff strategy
 * The delay before retry attempt `n` (0-indexed) is a random value in:
 *
 *     [0, min(maxDelay, baseDelay * 2^n)]
 *
 * This "full jitter" approach (recommended by AWS) prevents many clients
 * from retrying in lockstep and overwhelming a recovering server.
 * If the server sends a `Retry-After` header, it takes precedence
 * (capped at `maxDelay`).
 *
 * ## ⚠️ Idempotency warning
 * Retrying non-idempotent requests (e.g. `POST` that creates a resource or
 * charges a card) can cause duplicate side effects. Only retry such requests
 * if the server supports idempotency keys or you are certain it is safe.
 *
 * ## ⚠️ Request bodies
 * Streaming bodies (`ReadableStream`) can only be consumed once and will fail
 * on retry. Use strings, `Blob`, `FormData`, `URLSearchParams`, or `ArrayBuffer`.
 *
 * @param {string|URL|Request} url - The resource to fetch.
 * @param {RequestInit & {
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   timeout?: number,
 *   retryOn?: Iterable<number> | ((response: Response) => boolean),
 *   onRetry?: (info: { attempt: number, delay: number, error?: Error, response?: Response }) => void
 * }} [options={}] - Standard `fetch` options plus retry configuration:
 *   - `baseDelay` (ms, default `500`): Initial backoff delay.
 *   - `maxDelay` (ms, default `30000`): Upper bound on any single delay.
 *   - `timeout` (ms, default `0` = none): Per-attempt timeout.
 *   - `retryOn`: Status codes to retry, or a predicate `(response) => boolean`.
 *   - `onRetry`: Callback invoked before each retry (useful for logging/metrics).
 *   - `signal`: An `AbortSignal` that cancels the whole operation, including waits.
 * @param {number} [retries=3] - Maximum number of retries *after* the first
 *   attempt. Total attempts = `retries + 1`. Use `0` to disable retrying.
 *
 * @returns {Promise<Response>} Resolves with the first successful or
 *   non-retryable `Response`.
 *
 * @throws {FetchRetryError} When every attempt fails. Inspect `.cause`
 *   (last error) and `.response` (last retryable response, if any).
 * @throws {DOMException} `AbortError` if the caller's `signal` is aborted.
 * @throws {TypeError} If arguments are invalid.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 * const data = await res.json();
 *
 * @example
 * // With configuration, timeout, logging, and cancellation
 * const controller = new AbortController();
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   {
 *     method: 'GET',
 *     headers: { Accept: 'application/json' },
 *     baseDelay: 250,
 *     maxDelay: 10_000,
 *     timeout: 5_000,
 *     signal: controller.signal,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(`Retry #${attempt} in ${delay}ms`, error?.message ?? response?.status),
 *   },
 *   5
 * );
 *
 * @example
 * // Handling exhaustion
 * try {
 *   await fetchWithRetry(url, {}, 2);
 * } catch (err) {
 *   if (err instanceof FetchRetryError) {
 *     console.error(`Gave up after ${err.attempts} attempts`, err.cause ?? err.response?.status);
 *   }
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`retries must be a non-negative integer, got: ${retries}`);
  }

  // Separate our retry-specific options from standard fetch options.
  const {
    baseDelay = 500,
    maxDelay = 30_000,
    timeout = 0,
    retryOn = DEFAULT_RETRY_STATUSES,
    onRetry,
    signal: userSignal,
    ...fetchOptions
  } = options;

  // Normalize `retryOn` into a predicate.
  const shouldRetryResponse =
    typeof retryOn === 'function'
      ? retryOn
      : ((set) => (res) => set.has(res.status))(new Set(retryOn));

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // If the caller already cancelled, stop immediately — never retry user aborts.
    if (userSignal?.aborted) {
      throw userSignal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    // Build a per-attempt signal that fires on user abort OR per-attempt timeout.
    const signals = [];
    if (userSignal) signals.push(userSignal);
    if (timeout > 0) signals.push(AbortSignal.timeout(timeout));
    const attemptSignal =
      signals.length > 1 ? AbortSignal.any(signals) : signals[0];

    // Clone Request objects so each attempt has a fresh, unconsumed body.
    const input = url instanceof Request ? url.clone() : url;

    try {
      const response = await fetch(input, { ...fetchOptions, signal: attemptSignal });

      // Success or non-retryable failure: hand it back to the caller as-is.
      if (!shouldRetryResponse(response)) {
        return response;
      }

      lastResponse = response;
      lastError = undefined;
    } catch (error) {
      // A user-initiated abort is intentional — propagate, don't retry.
      if (userSignal?.aborted) throw error;

      // Otherwise it's a network error or our per-attempt timeout: retryable.
      lastError = error;
      lastResponse = undefined;
    }

    // Out of attempts — exit loop and throw below.
    if (attempt === retries) break;

    // Compute delay: honor Retry-After if present, else exponential backoff + full jitter.
    const retryAfter = parseRetryAfter(lastResponse?.headers.get('Retry-After'));
    const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay =
      retryAfter !== null
        ? Math.min(maxDelay, retryAfter)
        : Math.floor(Math.random() * exponential);

    // Free the connection held by the unused response body before waiting.
    await lastResponse?.body?.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, error: lastError, response: lastResponse });

    await sleep(delay, userSignal);
  }

  throw new FetchRetryError(
    `Request to ${url instanceof Request ? url.url : url} failed after ${retries + 1} attempt(s)` +
      (lastResponse ? ` (last status: ${lastResponse.status})` : '') +
      (lastError ? `: ${lastError.message}` : ''),
    { attempts: retries + 1, cause: lastError, response: lastResponse }
  );
}

export { fetchWithRetry, FetchRetryError, DEFAULT_RETRY_STATUSES };
```

## Key design decisions

| Decision | Rationale |
|---|---|
| **Full jitter** (`random(0, base·2ⁿ)`) | Avoids a "thundering herd" where many clients retry at the same instant. |
| **Retry only transient statuses** | Retrying a `404` or `401` wastes time; it will never succeed. |
| **Return non-retryable responses** instead of throwing | Matches native `fetch` semantics: the caller checks `res.ok`. |
| **Honor `Retry-After`** | Respects server rate-limit guidance (common with `429`/`503`). |
| **Never retry user aborts** | Cancellation is intentional; retrying would defeat it. |
| **Abortable sleep** | Cancelling mid-backoff takes effect immediately instead of after the delay. |
| **Cancel unused response bodies** | Prevents leaked connections, especially in Node.js. |
| **Clone `Request` inputs** | A request body can only be read once. |

