 *   with a non-retryable error response (e.g. 404), so callers should still
 *   check `response.ok`.
 *
 * @throws {FetchRetryError} If every attempt fails. Inspect `.response` for the
 *   last HTTP response and `.cause` for the last network error.
 * @throws {DOMException} With name `"AbortError"` if the caller's signal aborts.
 * @throws {RangeError} If `retries` is not a non-negative integer.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry("https://api.example.com/data");
 * const data = await res.json();
 *
 * @example
 * // Custom configuration with logging and cancellation
 * const controller = new AbortController();
 * const res = await fetchWithRetry(
 *   "https://api.example.com/items",
 *   {
 *     method: "GET",
 *     headers: { Accept: "application/json" },
 *     signal: controller.signal,
 *     baseDelay: 250,
 *     maxDelay: 5000,
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(
 *         `Retry #${attempt} in ${Math.round(delay)}ms`,
 *         response ? `(status ${response.status})` : `(${error?.message})`
 *       ),
 *   },
 *   5
 * );
 *
 * @example
 * // Handling final failure
 * try {
 *   await fetchWithRetry("https://flaky.example.com", {}, 2);
 * } catch (err) {
 *   if (err instanceof FetchRetryError) {
 *     console.error(`Gave up after ${err.attempts} attempts`, err.response?.status);
 *   }
 * }
