async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError(`retries must be a non-negative integer, got ${retries}`);
  }

  // Separate retry-specific options from those passed through to fetch.
  const {
    baseDelay = 500,
    maxDelay = 10_000,
    retryOn = DEFAULT_RETRY_STATUSES,
    onRetry,
    ...fetchOptions
  } = options;

  const signal = fetchOptions.signal;

  const shouldRetryResponse =
    typeof retryOn === "function" ? retryOn : (res) => retryOn.has(res.status);

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      // Clone Request objects so each attempt has an unconsumed body.
      const input = url instanceof Request ? url.clone() : url;
      const response = await fetch(input, fetchOptions);

      // Success, or a non-retryable error the caller should handle.
      if (response.ok || !shouldRetryResponse(response)) {
        return response;
      }

      lastResponse = response;
      lastError = undefined;
    } catch (error) {
      // Never retry deliberate cancellation by the caller.
      if (signal?.aborted) throw error;

      lastError = error;
      lastResponse = undefined;
    }

    // Out of attempts: stop looping and report failure below.
    if (attempt === retries) break;

    // Compute the delay: honor Retry-After if present, else exponential backoff with full jitter.
    const retryAfter = parseRetryAfter(lastResponse?.headers.get("Retry-After"));
    const delay =
      retryAfter !== null
        ? Math.min(retryAfter, maxDelay)
        : Math.random() * Math.min(maxDelay, baseDelay * 2 ** attempt);

    onRetry?.({
      attempt: attempt + 1,
      delay,
      error: lastError,
      response: lastResponse,
    });

    // Release the connection held by the failed response before waiting.
    await lastResponse?.body?.cancel().catch(() => {});

    await sleep(delay, signal);
  }

  const attempts = retries + 1;
  const reason = lastResponse
    ? `HTTP ${lastResponse.status} ${lastResponse.statusText}`.trim()
    : lastError?.message ?? "unknown error";

  throw new FetchRetryError(
    `Request to ${String(url instanceof Request ? url.url : url)} failed after ${attempts} attempt(s): ${reason}`,
    { attempts, response: lastResponse, cause: lastError }
  );
}

