 *   retries were exhausted on a retryable status).
 * @throws {Error}
 *   The last network/timeout error if all attempts fail without any response,
 *   or an `AbortError` if the caller's signal is aborted.
 *
 * @example
 * // Basic usage: up to 3 retries with default backoff
 * const res = await fetchWithRetry('https://api.example.com/data');
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 *
 * @example
 * // Custom backoff, timeout, and logging
 * const res = await fetchWithRetry(
 *   'https://api.example.com/items',
 *   {
 *     headers: { Accept: 'application/json' },
 *     retry: {
 *       baseDelay: 250,
 *       maxDelay: 5000,
 *       timeout: 10_000,
 *       onRetry: ({ attempt, delay, error, response }) =>
 *         console.warn(
 *           `Retry #${attempt} in ${delay}ms`,
 *           error?.message ?? `status ${response?.status}`
 *         ),
 *     },
 *   },
 *   5
 * );
 *
 * @example
 * // Cancelling all attempts
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 15_000);
 * await fetchWithRetry(url, { signal: controller.signal });
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const { retry: retryConfig = {}, ...fetchOptions } = options;
  const {
    baseDelay = 500,
    maxDelay = 30_000,
    factor = 2,
    jitter = true,
    retryOnStatus = [408, 425, 429, 500, 502, 503, 504],
    timeout,
    onRetry,
