    // Respect caller cancellation before each attempt.
    throwIfAborted(userSignal);

    // Per-attempt AbortController so a timeout cancels only this attempt.
    const attemptController = new AbortController();
    const onUserAbort = () => attemptController.abort(userSignal.reason);
    userSignal?.addEventListener('abort', onUserAbort, { once: true });

    let timeoutId;
    if (timeout != null) {
      timeoutId = setTimeout(
        () => attemptController.abort(new TimeoutError(timeout)),
        timeout
