      const shouldRetry =
        retryOnStatus.includes(response.status) && attempt < retries;

      if (!shouldRetry) return response;

      const delay = computeDelay(attempt, response);
      onRetry?.({ attempt: attempt + 1, delay, response });

      // Discard the body so the connection can be reused.
      response.body?.cancel().catch(() => {});
      await sleep(delay, userSignal);
    } catch (error) {
      // Caller aborted: stop immediately, never retry.
      if (userSignal?.aborted) throw userSignal.reason ?? error;

      lastError = error;
      if (attempt >= retries) break;

      const delay = computeDelay(attempt);
      onRetry?.({ attempt: attempt + 1, delay, error });
      await sleep(delay, userSignal);
    } finally {
      clearTimeout(timeoutId);
      userSignal?.removeEventListener('abort', onUserAbort);
    }
