      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Parse a `Retry-After` header into a delay in milliseconds.
 * Supports both delta-seconds ("120") and HTTP-date formats.
 *
 * @param {string | null} header - The raw Retry-After header value.
 * @returns {number | null} Delay in ms, or null if absent/unparseable.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds) && seconds >= 0) {
    return seconds * 1000;
  }

  const date = Date.parse(header);
  if (!Number.isNaN(date)) {
    return Math.max(0, date - Date.now());
  }

  return null;
}

/**
 * Fetch a resource, automatically retrying on transient failures using
 * exponential backoff with "full jitter".
 *
 * ## What gets retried
 * - **Network errors** (DNS failure, connection reset, offline, etc.).
 * - **Retryable HTTP statuses**: 408, 425, 429, 500, 502, 503, 504.
 *
 * ## What does NOT get retried
 * - Other 4xx responses (e.g. 400, 401, 403, 404). These indicate a problem
 *   with the request itself, so repeating it won't help. The response is
 *   returned to the caller as-is, matching normal `fetch` semantics.
 * - Requests aborted by the caller via `options.signal`.
 *
 * ## Backoff strategy
 * The delay before retry attempt `n` (0-indexed) is a random value in:
 *
 *     [0, min(maxDelay, baseDelay * 2^n)]
 *
 * This is "full jitter", which prevents many clients from retrying in
 * lockstep and overwhelming a recovering server (the "thundering herd").
 * If the server sends a `Retry-After` header (common with 429/503), that
 * value takes precedence, still capped at `maxDelay`.
 *
 * ## Safety note on non-idempotent requests
 * Retrying POST/PATCH requests can cause duplicate side effects (e.g. double
 * charges) if the server processed the first request but the response was
 * lost. Only retry such requests if your API supports idempotency keys or you
 * know duplicates are harmless.
 *
 * ## Request bodies
 * A `ReadableStream` body can only be consumed once and will fail on retry.
 * Use strings, `Blob`, `FormData`, `URLSearchParams`, or `ArrayBuffer`
 * bodies, which can be safely resent.
 *
 * @param {string | URL | Request} url - The resource to fetch.
 * @param {RequestInit & {
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   onRetry?: (info: {
 *     attempt: number,
 *     delay: number,
 *     error?: Error,
 *     response?: Response
 *   }) => void
 * }} [options={}] - Standard `fetch` options, plus these retry settings:
 *   - `baseDelay` (default `500`): Initial backoff in ms.
 *   - `maxDelay` (default `30000`): Upper bound on any single delay in ms.
 *   - `onRetry`: Callback invoked before each retry. Useful for logging/metrics.
 * @param {number} [retries=3] - Maximum number of *retries* after the initial
 *   attempt. `retries = 3` means up to 4 total requests. Use `0` to disable.
 *
 * @returns {Promise<Response>} Resolves with the first successful response,
 *   or with a non-retryable error response (e.g. 404), just like `fetch`.
 *
 * @throws {FetchRetryError} If every attempt fails with a network error or
 *   retryable status. Inspect `.response` / `.cause` for details.
 * @throws {DOMException} An `AbortError` if `options.signal` is aborted,
 *   either mid-request or during a backoff delay.
 * @throws {RangeError} If `retries` is not a non-negative integer.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry('https://api.example.com/data');
 * const data = await res.json();
 *
 * @example
 * // Custom backoff, logging, and a 10-second overall timeout
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   {
 *     headers: { Accept: 'application/json' },
 *     baseDelay: 1000,
 *     maxDelay: 10000,
 *     signal: AbortSignal.timeout(10000),
 *     onRetry: ({ attempt, delay, error, response }) =>
 *       console.warn(
 *         `Retry #${attempt} in ${Math.round(delay)}ms`,
 *         error?.message ?? `HTTP ${response.status}`
 *       ),
 *   },
 *   5
 * );
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError(`retries must be a non-negative integer, got ${retries}`);
  }

  // Separate our retry-specific options from standard fetch options
  // so we don't pass unknown keys through to fetch().
  const {
    baseDelay = 500,
    maxDelay = 30_000,
    onRetry,
    ...fetchOptions
  } = options;
  const { signal } = fetchOptions;

  let lastResponse;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    lastResponse = undefined;
    lastError = undefined;

    try {
      // Clone Request objects so each attempt gets a fresh, unconsumed body.
      const input = url instanceof Request ? url.clone() : url;
      const response = await fetch(input, fetchOptions);

      // Success, or a client error that retrying won't fix: hand it back.
      if (response.ok || !RETRYABLE_STATUS_CODES.has(response.status)) {
        return response;
      }

      lastResponse = response;
    } catch (error) {
      // Never retry a caller-initiated abort; propagate it immediately.
      if (signal?.aborted) throw error;
      lastError = error;
    }

    // Out of attempts: stop and report.
    if (attempt === retries) break;

    // Compute the delay: honor Retry-After if present, else exponential + jitter.
    const retryAfter = parseRetryAfter(lastResponse?.headers.get('Retry-After'));
    const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay = retryAfter !== null
      ? Math.min(maxDelay, retryAfter)
      : Math.random() * exponential;

    // Free the connection held by the failed response's unread body.
    await lastResponse?.body?.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, error: lastError, response: lastResponse });

    await sleep(delay, signal);
  }

  const reason = lastResponse
    ? `HTTP ${lastResponse.status} ${lastResponse.statusText}`
    : lastError?.message ?? 'unknown error';

  throw new FetchRetryError(
    `Request to ${url} failed after ${retries + 1} attempt(s): ${reason}`,
    { attempts: retries + 1, response: lastResponse, cause: lastError }
  );
}

export { fetchWithRetry, FetchRetryError };
```

## Key design decisions

| Decision | Why |
|---|---|
| **Only retry transient failures** | A 404 or 401 won't fix itself, so retrying just wastes time and load. 5xx, 429, and network errors often do resolve. |
| **Full jitter** (`random * 2^n`) | Plain exponential backoff makes clients that failed together retry together. Randomizing spreads the load. |
| **Respect `Retry-After`** | Servers that rate-limit you often say exactly when to come back. Ignoring that can get you blocked. |
| **Cap with `maxDelay`** | Without a cap, attempt 10 at a 500ms base would wait about 8.5 minutes. |
| **Abort-aware sleep** | Cancelling via `AbortSignal` stops the operation immediately, even mid-backoff. |
| **Cancel discarded bodies** | Unread response bodies can hold connections open and leak resources. |
| **Return non-retryable responses** | This keeps normal `fetch` semantics: callers still check `res.ok` for 4xx. |
| **Custom error type** | `FetchRetryError` exposes the last response or cause for debugging and logging. |

