/**
 * Groups the items of an array by a key derived from each item.
 *
 * Items are placed into buckets according to the value returned by `keyFn`.
 * The relative order of items within each group matches their order in the
 * original array, and groups appear in the order their keys were first seen.
 *
 * @template T, K
 * @param {Iterable<T>} arr
 *   The collection to group. Any iterable works (arrays, Sets, generators).
 * @param {(item: T, index: number) => K} keyFn
 *   Function that returns the grouping key for an item. It receives the item
 *   and its zero-based index. Keys are compared using SameValueZero (as in
 *   `Map`), so objects are compared by reference and `NaN` equals `NaN`.
 * @returns {Map<K, T[]>}
 *   A Map from each key to the array of items that produced it. A Map is
 *   returned (rather than a plain object) so that keys of any type are
 *   supported, insertion order is preserved, and keys like `"__proto__"`
 *   can't cause prototype pollution.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // Group numbers by parity
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? "even" : "odd"));
 * // Map { "odd" => [1, 3, 5], "even" => [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: "Ana", city: "Lima" },
 *   { name: "Ben", city: "Oslo" },
 *   { name: "Caro", city: "Lima" },
 * ];
 * groupBy(people, p => p.city);
 * // Map {
 * //   "Lima" => [{ name: "Ana", ... }, { name: "Caro", ... }],
 * //   "Oslo" => [{ name: "Ben", ... }]
 * // }
 *
 * @example
 * // Convert to a plain object if you need one (keys become strings)
 * Object.fromEntries(groupBy(["apple", "avocado", "banana"], s => s[0]));
 * // { a: ["apple", "avocado"], b: ["banana"] }
 */
function groupBy(arr, keyFn) {
  if (typeof keyFn !== "function") {
    throw new TypeError("groupBy: keyFn must be a function");
  }

  const groups = new Map();
  let index = 0;

  for (const item of arr) {
    const key = keyFn(item, index++);
    const bucket = groups.get(key);
    if (bucket) {
      bucket.push(item);
    } else {
      groups.set(key, [item]);
    }
  }

  return groups;
}
