export function groupBy<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K
): Map<K, T[]> {
  if (!Array.isArray(arr)) {
    throw new TypeError("groupBy: first argument must be an array");
  }
