Here's a small, dependency-free `Cache` class in TypeScript. It supports optional per-entry TTL (time-to-live) and an optional max size with least-recently-used (LRU) eviction, since those are the things people usually want from a cache. Both are opt-in.

```typescript
/**
 * Options for configuring a Cache instance.
 */
export interface CacheOptions {
  /**
   * Maximum number of entries to hold. When exceeded, the least recently
   * used entry is evicted. Defaults to unlimited (`Infinity`).
   */
  maxSize?: number;

  /**
   * Default time-to-live for entries, in milliseconds. Entries expire
   * after this duration unless overridden in `set`. Defaults to no expiry.
   */
  defaultTtlMs?: number;
}

interface Entry<V> {
  value: V;
  expiresAt: number; // Infinity means "never expires"
}

/**
 * A small in-memory key/value cache with optional TTL and LRU eviction.
 *
 * @typeParam K - Key type. Keys are compared using Map semantics (SameValueZero).
 * @typeParam V - Value type.
 *
 * @example
 * const cache = new Cache<string, number>({ maxSize: 100, defaultTtlMs: 60_000 });
 * cache.set("answer", 42);
 * cache.get("answer");   // 42
 * cache.has("missing");  // false
 * cache.delete("answer"); // true
 */
export class Cache<K, V> {
  private readonly store = new Map<K, Entry<V>>();
  private readonly maxSize: number;
  private readonly defaultTtlMs: number;

  /**
   * Creates a new cache.
   * @param options - Optional configuration. See {@link CacheOptions}.
   * @throws {RangeError} If `maxSize` is less than 1 or `defaultTtlMs` is not positive.
   */
  constructor(options: CacheOptions = {}) {
    const { maxSize = Infinity, defaultTtlMs = Infinity } = options;
    if (!(maxSize >= 1)) throw new RangeError("maxSize must be >= 1");
    if (!(defaultTtlMs > 0)) throw new RangeError("defaultTtlMs must be > 0");
    this.maxSize = maxSize;
    this.defaultTtlMs = defaultTtlMs;
  }

  /**
   * Retrieves the value for a key and marks it as most recently used.
   *
   * @param key - The key to look up.
   * @returns The stored value, or `undefined` if the key is absent or expired.
   */
  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    // Re-insert to mark as most recently used (Map preserves insertion order).
    this.store.delete(key);
    this.store.set(key, entry);
    return entry.value;
  }

  /**
   * Stores a value under a key, replacing any existing value. The entry
   * becomes the most recently used. If the cache exceeds `maxSize`, the
   * least recently used entry is evicted.
   *
   * @param key - The key to store under.
