   * Retrieves the value stored for a key.
   *
   * @param key - The key to look up.
   * @returns The stored value, or `undefined` if the key is missing or expired.
   *          Expired entries are removed when encountered.
   */
  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Stores a value under a key, replacing any existing value.
   * Re-setting a key refreshes its expiry and its insertion order.
   *
   * @param key - The key to store under.
   * @param value - The value to store.
   * @param ttlMs - Optional TTL in milliseconds for this entry, overriding
   *                the default. Use `Infinity` for no expiry.
   * @returns The cache instance, to allow chaining.
   */
  set(key: K, value: V, ttlMs: number | undefined = this.defaultTtlMs): this {
    // Delete first so a re-set key moves to the "newest" position.
    this.store.delete(key);

    this.store.set(key, {
      value,
      expiresAt: ttlMs === undefined ? Infinity : Date.now() + ttlMs,
    });

    if (this.maxSize !== undefined && this.store.size > this.maxSize) {
      const oldest = this.store.keys().next();
      if (!oldest.done) this.store.delete(oldest.value);
    }
    return this;
  }

