   * Checks whether a non-expired entry exists for a key.
   * Unlike `get`, this works correctly for keys whose value is `undefined`.
   *
   * @param key - The key to check.
   * @returns `true` if the key exists and has not expired.
   */
  has(key: K): boolean {
    const entry = this.store.get(key);
    if (!entry) return false;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry for a key.
   *
   * @param key - The key to remove.
   * @returns `true` if an entry was removed, `false` if none existed
   *          (or it had already expired).
   */
  delete(key: K): boolean {
    const entry = this.store.get(key);
    if (!entry) return false;
    this.store.delete(key);
    return !this.isExpired(entry);
  }

  private isExpired(entry: Entry<V>): boolean {
    return Date.now() >= entry.expiresAt;
  }
}
```

**Design notes**

- **Expiry is lazy:** expired entries are removed when accessed via `get`, `has`, or `delete`, so there are no timers keeping the process alive.
