    const expiresAt = effectiveTtl === null ? null : Date.now() + effectiveTtl;

    this.store.delete(key); // Refresh position if the key already exists.
    this.store.set(key, { value, expiresAt });

    if (this.store.size > this.maxSize) {
      const oldest = this.store.keys().next().value as K;
      this.store.delete(oldest);
    }
    return this;
  }

  /**
   * Checks whether a non-expired entry exists for a key. Does not affect
   * the entry's recency.
   *
   * @param key - The key to check.
   * @returns `true` if the key exists and has not expired.
   */
  has(key: K): boolean {
    const entry = this.store.get(key);
    if (!entry) return false;

    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes an entry by key.
   *
   * @param key - The key to remove.
   * @returns `true` if an entry was removed, `false` if the key was not present.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }

  private isExpired(entry: Entry<V>): boolean {
    return entry.expiresAt !== null && Date.now() >= entry.expiresAt;
  }
}
```

**Design notes**

- **LRU via `Map`:** JavaScript's `Map` iterates in insertion order, so the first key is always the least recently used. Re-inserting on `get` and `set` keeps the order correct without extra data structures.
- **Lazy expiry:** Expired entries are removed when accessed rather than by timers, so there are no background handles to clean up. The tradeoff is that expired entries that are never accessed again remain in memory until evicted by size pressure or overwritten.
- **`has` doesn't refresh recency**, while `get` does. This lets you check for existence without altering eviction order.
- **`delete` on an expired but not-yet-purged entry** returns `true`, since an entry was physically removed. If you need stricter semantics, check expiry first.
- **Storing `undefined`:** `get` returns `undefined` for both missing keys and stored `undefined` values, so use `has` if you need to distinguish them.

