/**
 * Fetches a resource, retrying on network errors and retryable HTTP statuses
 * using exponential backoff with jitter.
 *
 * Retries occur when:
 *  - fetch() rejects (network failure, DNS error, etc.), except for aborts
 *  - the response status is 408, 429, or any 5xx
 *
 * Other 4xx responses are returned immediately, since retrying won't help.
 * If the server sends a `Retry-After` header (seconds or HTTP date), it is
 * honored in place of the computed backoff delay.
 *
 * @param {string | URL | Request} url - The resource to fetch.
 * @param {RequestInit & RetryOptions} [options={}] - Standard fetch options,
 *   plus the optional retry settings below.
 * @param {number} [options.baseDelay=500] - Initial delay in ms. The delay
 *   doubles each attempt: baseDelay * 2^attempt.
 * @param {number} [options.maxDelay=30000] - Upper bound for any single delay (ms).
 * @param {(info: {attempt: number, delay: number, error?: Error, response?: Response}) => void} [options.onRetry]
 *   - Called before each retry wait. Useful for logging.
 * @param {number} [retries=3] - Maximum number of retries after the first
 *   attempt (so up to retries + 1 total requests).
 *
 * @returns {Promise<Response>} The first successful (or non-retryable) response.
 *   If retries are exhausted on a retryable HTTP status, the last response is
 *   returned so the caller can inspect it.
 *
 * @throws {Error} The last network error if all attempts fail with a rejection,
 *   or an AbortError immediately if the request is aborted via `signal`.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { method: "GET", baseDelay: 300, onRetry: ({ attempt, delay }) =>
 *       console.warn(`Retry #${attempt} in ${delay}ms`) },
 *   4
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 *
 * @note Only use with idempotent requests (GET, PUT, DELETE) unless the server
 *   supports idempotency keys; retrying POSTs may cause duplicate side effects.
 *   Request bodies that are streams cannot be re-sent on retry.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    maxDelay = 30000,
    onRetry,
    ...fetchOptions
  } = options;

  const retryableStatus = (status) =>
    status === 408 || status === 429 || (status >= 500 && status <= 599);

  const parseRetryAfter = (response) => {
    const header = response.headers.get("Retry-After");
    if (!header) return null;
    const seconds = Number(header);
    if (!Number.isNaN(seconds)) return seconds * 1000;
    const date = Date.parse(header);
    return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
  };

  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason);
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
      if (!retryableStatus(response.status)) return response;
    } catch (err) {
      if (err?.name === "AbortError" || fetchOptions.signal?.aborted) throw err;
      error = err;
    }

    // Out of retries: return last response or throw last error.
    if (attempt >= retries) {
      if (response) return response;
      throw error;
    }

    // Exponential backoff with full jitter, capped at maxDelay.
    const backoff = Math.min(maxDelay, baseDelay * 2 ** attempt);
    let delay = Math.random() * backoff;
    if (response) {
      const retryAfter = parseRetryAfter(response);
      if (retryAfter !== null) delay = Math.min(maxDelay, retryAfter);
    }

    onRetry?.({ attempt: attempt + 1, delay, error, response });
    await response?.body?.cancel?.(); // free the connection before retrying
    await sleep(delay, fetchOptions.signal);
  }
}
```

**Design notes**

- **Full jitter**: the delay is random in `[0, baseDelay * 2^attempt]`, which prevents many clients from retrying in lockstep.
- **Retry-After**: respected for 429/503-style responses, still capped by `maxDelay`.
- **Abort-aware**: aborting through an `AbortSignal` stops both the request and any backoff wait immediately.
- **Fetch's quirk**: `fetch` doesn't reject on HTTP errors, so status codes are checked explicitly.

