    baseDelay = 500,
    maxDelay = 30000,
    retryOn,
    ...fetchOptions
  } = options;

  const RETRYABLE_STATUS = new Set([408, 425, 429, 500, 502, 503, 504]);

  const shouldRetry = (info) =>
    retryOn
      ? retryOn(info)
      : info.error
        ? true
        : RETRYABLE_STATUS.has(info.response.status);

  const parseRetryAfter = (response) => {
    const header = response.headers.get("Retry-After");
    if (!header) return null;
    const seconds = Number(header);
    if (!Number.isNaN(seconds)) return seconds * 1000;
    const date = Date.parse(header);
    return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
  };

  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason);
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  const signal = fetchOptions.signal;

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
    } catch (err) {
      // Never retry deliberate aborts.
      if (signal?.aborted || err.name === "AbortError") throw err;
      error = err;
    }

    const isLastAttempt = attempt >= retries;

    if (!error && !shouldRetry({ response, attempt })) return response;
    if (error && !shouldRetry({ error, attempt })) throw error;

    if (isLastAttempt) {
      if (error) throw error;
      return response;
    }

    // Compute backoff with full jitter, honoring Retry-After if present.
    const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
    const retryAfter = response ? parseRetryAfter(response) : null;
