  const {
    baseDelay = 500,
    maxDelay = 30000,
    jitter = true,
    retryOn,
    onRetry,
    ...fetchOptions
  } = options;

  const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);

  const shouldRetry = retryOn ??
    (({ response, error }) =>
      error ? true : RETRYABLE_STATUSES.has(response.status));

  /** Parses a Retry-After header into milliseconds, or null if absent/invalid. */
  const parseRetryAfter = (response) => {
    const header = response?.headers.get("Retry-After");
    if (!header) return null;
    const seconds = Number(header);
    if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
    const date = Date.parse(header);
    return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
  };

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
    } catch (err) {
      // Never retry deliberate cancellation.
      if (fetchOptions.signal?.aborted || err?.name === "AbortError") throw err;
      error = err;
