    const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
    let delay = jitter ? Math.random() * exponential : exponential;

    const retryAfter = parseRetryAfter(response);
    if (retryAfter !== null) delay = Math.min(retryAfter, maxDelay);

    // Free the connection before retrying; the body is no longer needed.
    if (response) response.body?.cancel().catch(() => {});

    onRetry?.({ attempt, delay, response, error });
    await sleep(delay, fetchOptions.signal);
  }
