      retryAfterMs(response, maxDelay) ??
      backoffDelay(attempt, baseDelay, factor, maxDelay, jitter);

    // Discard the unread body so the connection can be reused/freed.
    if (response) response.body?.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, error, response });
    await sleep(delay, signal);
  }
}

const RETRYABLE_STATUSES = new Set([408, 425, 429, 500, 502, 503, 504]);

/** Computes exponential backoff delay in ms, optionally with full jitter. */
function backoffDelay(attempt, baseDelay, factor, maxDelay, jitter) {
  const cap = Math.min(maxDelay, baseDelay * factor ** attempt);
  return jitter ? Math.random() * cap : cap;
}

/** Parses a Retry-After header (seconds or HTTP date) into ms, or null. */
function retryAfterMs(response, maxDelay) {
  const header = response?.headers.get("Retry-After");
  if (!header) return null;

  const seconds = Number(header);
  const ms = Number.isFinite(seconds)
    ? seconds * 1000
    : Date.parse(header) - Date.now();

  return Number.isFinite(ms) ? Math.min(Math.max(ms, 0), maxDelay) : null;
}

/** Resolves after `ms`, rejecting early if the signal aborts. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

**Design notes**

- **Retry-safe by default:** non-transient errors (4xx other than 408/425/429) return immediately, since retrying won't help.
- **Jitter:** prevents many clients from retrying in lockstep after an outage.
- **Retry-After:** respects server guidance on rate limiting and overload.
- **Abort support:** cancelling the signal stops both in-flight requests and backoff waits.
- **Exhausted retries:** returns the final response rather than throwing, matching `fetch` semantics where HTTP errors aren't exceptions. Throw on `!res.ok` yourself if you prefer.

```javascript
/**
 * Resolves after the given number of milliseconds, or rejects early if the
 * provided AbortSignal is aborted.
 *
 * @param {number} ms - Time to wait in milliseconds.
 * @param {AbortSignal} [signal] - Optional signal to cancel the wait.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    }

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Parses a Retry-After header value (seconds or HTTP date) into milliseconds.
 *
 * @param {string|null} value - The raw header value.
 * @returns {number|null} Delay in ms, or null if missing or unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

