 *   onRetry?: (info: {attempt: number, delay: number, response?: Response, error?: Error}) => void
 * }} [options={}] - Standard fetch options, plus these retry settings:
 *   - baseDelay {number}  Initial delay in ms (default 500).
 *   - maxDelay  {number}  Upper bound for any delay in ms (default 30000).
 *   - factor    {number}  Backoff multiplier (default 2).
 *   - jitter    {boolean} Apply full jitter (default true).
 *   - retryOn   {Function} Custom predicate overriding the default retry
 *                          rules. Return true to retry.
 *   - onRetry   {Function} Callback invoked before each wait (for logging).
 * @param {number} [retries=3] - Maximum number of retries after the first
 *   attempt (so up to retries + 1 total requests).
 * @returns {Promise<Response>} The first non-retryable response, or the last
 *   response if retries are exhausted on a retryable status.
 * @throws {Error} The last network error if all attempts fail with errors,
 *   or an AbortError if the request is aborted.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Accept: "application/json" }, baseDelay: 200 },
 *   5
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    maxDelay = 30000,
    factor = 2,
    jitter = true,
    retryOn,
    onRetry,
    ...fetchOptions
  } = options;

  const RETRYABLE_STATUSES = new Set([408, 425, 429, 500, 502, 503, 504]);

  const shouldRetry = ({ response, error, attempt }) => {
    if (retryOn) return retryOn({ response, error, attempt });
    if (error) return error.name !== "AbortError";
    return RETRYABLE_STATUSES.has(response.status);
  };

  const parseRetryAfter = (response) => {
    const header = response?.headers?.get("Retry-After");
    if (!header) return null;
    const seconds = Number(header);
    if (!Number.isNaN(seconds)) return seconds * 1000;
    const date = Date.parse(header);
    return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
  };

  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  for (let attempt = 0; ; attempt++) {
    let response, error;

    try {
      response = await fetch(url, fetchOptions);
    } catch (err) {
      error = err;
    }

    const canRetry = attempt < retries && shouldRetry({ response, error, attempt });

    if (!canRetry) {
      if (error) throw error;
      return response;
    }

    // Compute backoff delay, honoring Retry-After if present.
    const exponential = Math.min(maxDelay, baseDelay * Math.pow(factor, attempt));
    const retryAfter = parseRetryAfter(response);
    const delay =
      retryAfter !== null
        ? Math.min(maxDelay, retryAfter)
        : jitter
          ? Math.random() * exponential
          : exponential;

    // Free the connection for the discarded response.
    if (response?.body) response.body.cancel().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, response, error });
    await sleep(delay, fetchOptions.signal);
  }
}
```

**Notes on design choices**

- **Full jitter** spreads out retries from many clients so they don't all hit a recovering server at once.
- **Request bodies:** string, JSON, or `FormData` bodies are safe to resend. A `ReadableStream` body can only be consumed once, so don't use streams with retries.
- **Idempotency:** retrying `POST` requests can cause duplicate side effects. Consider only retrying them if the API supports idempotency keys, or supply a custom `retryOn`.
- **Exhausted retries on a bad status** returns the final `Response` rather than throwing, consistent with how `fetch` treats HTTP errors. Check `res.ok` as usual.

```javascript
