 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    maxDelay = 30000,
    factor = 2,
    onRetry,
    ...fetchOptions
  } = options;
  const signal = fetchOptions.signal;

  const isRetryableStatus = (s) => s === 408 || s === 429 || s >= 500;

  const parseRetryAfter = (res) => {
    const h = res.headers.get("Retry-After");
    if (!h) return null;
    const secs = Number(h);
    if (!Number.isNaN(secs)) return secs * 1000;
    const date = Date.parse(h);
    return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
  };

  const sleep = (ms) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason);
      };
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
      if (!isRetryableStatus(response.status)) return response;
    } catch (err) {
      // Never retry a deliberate abort.
      if (err.name === "AbortError" || signal?.aborted) throw err;
      error = err;
    }

    // Out of retries: return the last response or throw the last error.
    if (attempt >= retries) {
      if (response) return response;
      throw error;
    }

    // Exponential backoff with full jitter: random value in [0, capped delay].
    const backoff = Math.min(maxDelay, baseDelay * factor ** attempt);
    const retryAfter = response ? parseRetryAfter(response) : null;
    const delay =
      retryAfter !== null
        ? Math.min(retryAfter, maxDelay)
        : Math.random() * backoff;

    onRetry?.({ attempt: attempt + 1, error, response, delay });

    // Release the connection of the discarded response.
    if (response?.body) response.body.cancel().catch(() => {});

    await sleep(delay);
  }
}
```

**Design notes**

- **Full jitter** (random delay between 0 and the exponential cap) prevents many clients from retrying in lockstep and overwhelming a recovering server.
- **Returning the last response** when retries are exhausted on a 5xx lets callers read the error body or status rather than getting a generic exception.
- **Abort support**: an `AbortSignal` cancels both in-flight requests and backoff waits.
- **Not retried**: most 4xx errors (400, 401, 403, 404, etc.), since repeating them won't change the outcome.

```javascript
/**
 * Pauses execution for a given number of milliseconds.
 * @param {number} ms - Milliseconds to wait.
 * @returns {Promise<void>}
