 *     body: JSON.stringify({ hello: "world" }),
 *     signal: AbortSignal.timeout(10000),
 *     baseDelay: 200,
 *     onRetry: ({ attempt, delay }) =>
 *       console.warn(`Retry #${attempt} in ${Math.round(delay)}ms`),
 *   },
 *   5
 * );
