  const {
    baseDelay = 500,
    maxDelay = 30000,
    retryOn = [408, 429, 500, 502, 503, 504],
    onRetry,
    ...fetchOptions
  } = options;

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
      if (!retryOn.includes(response.status)) return response;
    } catch (err) {
      // Never retry deliberate aborts.
      if (err.name === "AbortError" || fetchOptions.signal?.aborted) throw err;
      error = err;
    }

    // Out of retries: return last response or throw last error.
    if (attempt >= retries) {
      if (response) return response;
      throw error;
    }

    const delay =
      parseRetryAfter(response?.headers.get("Retry-After"), maxDelay) ??
      Math.random() * Math.min(maxDelay, baseDelay * 2 ** attempt);

    onRetry?.({ attempt: attempt + 1, delay, error, response });

    // Release the connection held by the unused response body.
    if (response) response.body?.cancel().catch(() => {});

    await sleep(delay);
  }
}

/**
 * Parses a Retry-After header value into milliseconds.
 * @param {string|null|undefined} value - Seconds or an HTTP date.
 * @param {number} maxDelay - Cap in ms.
 * @returns {number|null} Delay in ms, or null if absent/invalid.
 */
function parseRetryAfter(value, maxDelay) {
  if (!value) return null;
  const seconds = Number(value);
  let ms = Number.isNaN(seconds) ? Date.parse(value) - Date.now() : seconds * 1000;
  if (Number.isNaN(ms)) return null;
  return Math.min(Math.max(ms, 0), maxDelay);
}
```

**Design notes**

- **Jitter**: Full jitter prevents the "thundering herd" problem when many clients fail simultaneously.
- **Abort handling**: If the caller's `AbortSignal` fires, the error propagates immediately. Note that the signal also applies during the sleep only indirectly, so a long backoff won't be interrupted. If you need that, race `sleep` against the signal.
- **Exhausted retries**: On a retryable HTTP status, the final response is returned rather than thrown, so callers handle HTTP errors the same way as with plain `fetch`.
- **Body reuse**: String, JSON, and `URLSearchParams` bodies are safe to resend. `ReadableStream` bodies are not.

