  const {
    baseDelay = 500,
    maxDelay = 30000,
    retryOn,
    onRetry,
    ...fetchOptions
  } = options;
  const signal = fetchOptions.signal;

  const defaultShouldRetry = ({ response, error }) => {
    if (error) return error.name !== "AbortError";
    const s = response.status;
    return s === 408 || s === 429 || (s >= 500 && s <= 599);
