 *   - `retryOn`: HTTP status codes to retry (default [408, 429, 500, 502, 503, 504]).
 *   - `onRetry`: Callback invoked before each wait, useful for logging.
 *   - `signal`: An AbortSignal; aborting cancels the request and any pending wait.
 * @param {number} [retries=3] - Maximum number of retries after the first attempt
 *   (so up to `retries + 1` total requests).
 * @returns {Promise<Response>} Resolves with the first non-retryable response, or
 *   the last response if retries are exhausted on a retryable status.
 * @throws {Error} The last network error if all attempts fail with exceptions, or
 *   an AbortError if the signal is aborted.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { method: "GET", baseDelay: 300, onRetry: ({attempt, delay}) =>
 *       console.warn(`Retry ${attempt} in ${Math.round(delay)}ms`) },
 *   5
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    maxDelay = 30000,
    retryOn = [408, 429, 500, 502, 503, 504],
    onRetry,
    ...fetchOptions
  } = options;
  const signal = fetchOptions.signal;

  for (let attempt = 0; ; attempt++) {
    let response;
    let error;

    try {
      response = await fetch(url, fetchOptions);
      if (!retryOn.includes(response.status)) return response;
    } catch (err) {
      if (err.name === "AbortError" || signal?.aborted) throw err;
      error = err;
    }

    // Out of retries: return the last response or throw the last error.
    if (attempt >= retries) {
      if (response) return response;
      throw error;
    }

    let delay = Math.random() * Math.min(maxDelay, baseDelay * 2 ** attempt);
    const retryAfter = response && parseRetryAfter(response.headers.get("Retry-After"));
    if (retryAfter !== null && retryAfter !== undefined) {
      delay = Math.min(retryAfter, maxDelay);
    }

    // Free the connection before retrying.
    if (response) response.body?.cancel?.().catch(() => {});

    onRetry?.({ attempt: attempt + 1, delay, error, response });
    await sleep(delay, signal);
  }
}

/** Parses a Retry-After header into milliseconds, or null if absent/invalid. */
function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

/** Resolves after `ms`, or rejects early if the signal aborts. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

**Design notes**
- **Full jitter** spreads out retries from many clients so they don't hammer a recovering server simultaneously.
- **Returns the final response** on exhausted retries rather than throwing, so callers handle HTTP errors in one place (`response.ok`).
- **Abort support** works both during the request and during backoff waits.
- Works in browsers and Node 18+ (where `fetch` is built in).

