V = TypeVar("V")


class Cache(Generic[K, V]):
    """An in-memory cache with hashable keys and no automatic eviction."""

    def __init__(self) -> None:
        """Create an empty cache."""
        self._entries: dict[K, V] = {}

    def get(self, key: K) -> V:
        """Return the value for key. Raise KeyError if it is absent."""
        return self._entries[key]

    def set(self, key: K, value: V) -> None:
        """Store value under key, replacing any existing value."""
        self._entries[key] = value

    def has(self, key: K) -> bool:
        """Return True if key is present, even if its value is None."""
        return key in self._entries

    def delete(self, key: K) -> bool:
        """Remove key and return True, or return False if it was absent."""
        try:
            del self._entries[key]
        except KeyError:
            return False
        return True
