/**
 * Fetch a URL, retrying network failures and transient HTTP errors.
 *
 * Retries HTTP 408, 429, 500, 502, 503, and 504. All other HTTP responses
 * are returned immediately, so callers should still check `response.ok`.
 * If all attempts fail, returns the last attempt's HTTP response or
 * throws the last attempt's network error.
 *
 * Backoff starts at 250 ms and doubles after each retry, up to 8 seconds.
 * An AbortSignal in `options.signal` cancels both fetches and retry delays.
 *
 * Only retry requests that are safe to repeat. A network failure does not
 * guarantee the server didn't process the request. Request bodies must be
 * reusable; a ReadableStream body cannot be replayed by this function.
 *
 * @param {string | URL} url - URL to fetch.
 * @param {RequestInit} [options={}] - Options passed to fetch.
 * @param {number} [retries=3] - Extra attempts after the initial request.
 * @returns {Promise<Response>}
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isSafeInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a non-negative safe integer");
  }

  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
  const { signal } = options;
  let delay = 250;

  for (let attempt = 0; ; attempt++) {
    signal?.throwIfAborted();

    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      if (signal?.aborted || error.name === "AbortError" || attempt >= retries) {
        throw error;
      }
    }

    if (response) {
      if (!retryableStatuses.has(response.status) || attempt >= retries) {
        return response;
      }

      // Release the response body before retrying.
      await response.body?.cancel().catch(() => {});
    }

    await wait(delay, signal);
    delay = Math.min(delay * 2, 8_000);
  }
}

/** Wait for `ms` milliseconds, or reject immediately if aborted. */
function wait(ms, signal) {
  return new Promise((resolve, reject) => {
    signal?.throwIfAborted();

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason);
    }

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

With the default `retries = 3`, the function makes at most **four attempts**, with waits of 250 ms, 500 ms, and 1,000 ms between them.

