/**
 * Fetch a URL, retrying network errors and transient HTTP failures.
 *
 * Retries HTTP 408, 429, and 5xx responses. Other HTTP responses are
 * returned immediately. If retries are exhausted, returns the last HTTP
 * response or throws the last network error, just like fetch().
 *
 * The first retry waits 250 ms; each subsequent delay doubles, up to 10 s.
 * An AbortSignal in options cancels both the request and any backoff wait.
 *
 * Only retry requests that are safe to repeat. A network error does not
 * prove the server did nothing. If options.body is set, it must be reusable
 * (for example, a string rather than a ReadableStream).
 *
 * @param {string | URL} url - The URL to fetch.
 * @param {RequestInit} [options={}] - Options passed to fetch().
 * @param {number} [retries=3] - Additional attempts after the first.
 * @returns {Promise<Response>}
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isSafeInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a non-negative safe integer");
  }

  const { signal } = options;
  let delayMs = 250;

  for (let attempt = 0; ; attempt++) {
    signal?.throwIfAborted();

    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      if (signal?.aborted || error?.name === "AbortError" || attempt >= retries) {
        throw error;
      }
    }

    if (response) {
      const { status } = response;
      const retryable = status === 408 || status === 429 ||
        (status >= 500 && status < 600);

      if (!retryable || attempt >= retries) return response;

      // Release the body of the response we won't return.
      await response.body?.cancel().catch(() => {});
    }

    await wait(delayMs, signal);
    delayMs = Math.min(delayMs * 2, 10_000);
  }

  function wait(ms, signal) {
    return new Promise((resolve, reject) => {
      signal?.throwIfAborted();

      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);

      function onAbort() {
        clearTimeout(timer);
        reject(signal.reason);
      }

      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }
}
```

`retries = 3` allows up to four attempts. Check `response.ok` before reading the body: like `fetch()`, this function does not throw merely because the server returned an HTTP error.

```js
/**
 * Fetches a URL, retrying network errors and transient HTTP failures.
 *
 * Retries HTTP 408, 429, 500, 502, 503, and 504. Other HTTP responses
 * are returned immediately, just as with native fetch().
 *
 * The first retry waits 250 ms, then the delay doubles after each failure,
 * up to 8 seconds. An AbortSignal can cancel both the request and the wait.
 *
 * Only use retries when repeating the request is safe. For example, a POST
 * may need a server-supported idempotency key. Request bodies must be
 * reusable; this helper does not support retrying a consumed stream.
 *
 * @param {string | URL} url - The URL to fetch.
 * @param {RequestInit} [options={}] - Standard fetch options.
 * @param {number} [retries=3] - Additional attempts after the first.
 * @returns {Promise<Response>} The final HTTP response, even if not OK.
 * @throws {RangeError} If retries is not a nonnegative safe integer.
 * @throws If the last attempt fails without an HTTP response, or if aborted.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isSafeInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a nonnegative safe integer");
  }

  const { signal } = options;
  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
  let delay = 250;

  for (let attempt = 0; ; attempt++) {
    signal?.throwIfAborted();

    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      // Fetch usually reports network failures as TypeError. It can also
      // use TypeError for invalid URLs or options, which retries won't fix.
      if (signal?.aborted || !(error instanceof TypeError) || attempt >= retries) {
        throw error;
      }
    }

    if (response) {
      if (!retryableStatuses.has(response.status) || attempt >= retries) {
        return response;
      }
      // Release the discarded response body before retrying.
      await response.body?.cancel().catch(() => {});
    }

    await wait(delay, signal);
    delay = Math.min(delay * 2, 8_000);
  }

  function wait(ms, signal) {
    return new Promise((resolve, reject) => {
      signal?.throwIfAborted();

      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);

      function onAbort() {
        clearTimeout(timer);
        reject(signal.reason);
      }

      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }
}
