```javascript
/**
 * Fetches a resource with automatic retries and exponential backoff on failure.
 *
 * Retries are triggered on network errors, 5xx server errors, and 429 (Too Many Requests)
 * responses. Other 4xx client errors (like 400 or 404) are returned immediately without
 * retrying, and aborted requests are immediately thrown.
 *
 * @param {string | URL | Request} url - The resource URL or Request object to fetch.
 * @param {RequestInit} [options={}] - Optional fetch configuration (method, headers, body, signal, etc.).
 * @param {number} [retries=3] - The maximum number of retry attempts after the initial request fails.
 * @param {number} [initialDelay=300] - The base delay in milliseconds before the first retry.
 * @returns {Promise<Response>} A Promise that resolves to the Fetch API Response object.
 * @throws {Error} Throws the last encountered error if all retry attempts fail, or if the request is aborted.
 *
 * @example
 * try {
 *   const response = await fetchWithRetry('https://api.example.com/data', { method: 'GET' }, 3);
 *   const data = await response.json();
 *   console.log(data);
 * } catch (error) {
 *   console.error('Request failed after retries:', error);
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3, initialDelay = 300) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Return immediately if the request succeeded or failed with a non-retryable 4xx error
      const isRetryableStatus = response.status >= 500 || response.status === 429;
      if (response.ok || !isRetryableStatus) {
        return response;
      }

      // Throw an error to enter the catch block and trigger a retry
      throw new Error(`HTTP error! Status: ${response.status}`);
    } catch (error) {
      const isLastAttempt = attempt === retries;

      // Do not retry if the request was manually aborted or if we're out of retries
      if (error.name === 'AbortError' || isLastAttempt) {
        throw error;
      }

      // Calculate exponential backoff: initialDelay * 2^attempt (e.g., 300ms, 600ms, 1200ms)
      const backoff = initialDelay * Math.pow(2, attempt);
      // Add random jitter (0–100ms) to prevent thundering herd problems
      const jitter = Math.random() * 100;

      await new Promise((resolve) => setTimeout(resolve, backoff + jitter));
    }
  }
}
```

### Key Features
* **Smart Retry Logic:** Only retries on network failures, `5xx` server errors, and `429` rate-limit responses. Standard `4xx` errors (like `404 Not Found` or `401 Unauthorized`) are returned immediately since retrying them usually won't succeed.
* **Exponential Backoff with Jitter:** Doubles the wait time after each failed attempt (`300ms` → `600ms` → `1200ms`) and adds a small random delay (*jitter*) to prevent multiple clients from retrying at the exact same millisecond.
* **`AbortController` Support:** If the caller cancels the request via `options.signal`, the `AbortError` is immediately rethrown without wasting retry attempts.

