 * and manually aborted requests are not retried.
 *
 * @param {string | URL} url - The resource URL to fetch.
 * @param {RequestInit} [options={}] - Standard `fetch` options (e.g., method, headers, body, signal).
 * @param {number} [retries=3] - Maximum number of retry attempts after the initial request fails.
 * @param {number} [backoff=300] - Base delay in milliseconds before the first retry. Doubles on each subsequent attempt.
 * @returns {Promise<Response>} A Promise that resolves to the `Response` object.
 * @throws {Error} Throws the last encountered error if all retry attempts are exhausted, or immediately if aborted.
 *
 * @example
 * try {
 *   const response = await fetchWithRetry(
 *     'https://api.example.com/data',
 *     { headers: { Authorization: 'Bearer token' } },
 *     3
 *   );
 *   const data = await response.json();
 *   console.log(data);
 * } catch (error) {
 *   console.error('Request failed after retries:', error);
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3, backoff = 300) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Return immediately on success, or on 4xx client errors (except 429 Too Many Requests)
      if (
        response.ok ||
        (response.status >= 400 && response.status < 500 && response.status !== 429)
      ) {
        return response;
      }

      // Trigger a retry for 5xx server errors and 429 rate limits
      throw new Error(`HTTP error! Status: ${response.status}`);
    } catch (error) {
      const isLastAttempt = attempt === retries;

      // Do not retry if we've exhausted all attempts or if the user aborted the request
      if (isLastAttempt || error.name === 'AbortError') {
        throw error;
      }

      // Calculate exponential backoff delay: backoff * 2^attempt (e.g., 300ms, 600ms, 1200ms)
      const delay = backoff * Math.pow(2, attempt);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
