      throw new Error(`HTTP error! Status: ${response.status} ${response.statusText}`);
    } catch (error) {
      // Do not retry if the request was manually aborted or if retries are exhausted
      if (options.signal?.aborted || attempt === retries) {
        throw error;
      }

      // Calculate exponential backoff (e.g., 300ms, 600ms, 1200ms) + random jitter (0-100ms)
      const exponentialDelay = baseDelay * Math.pow(2, attempt);
      const jitter = Math.random() * 100;
      const delay = exponentialDelay + jitter;

      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}
```

### Key Features
* **Exponential Backoff with Jitter:** Doubles the wait time after each failed attempt (`baseDelay * 2^attempt`) and adds a small random jitter (`0–100ms`) to prevent the "thundering herd" problem when many clients retry simultaneously.
* **Smart Status Handling:** Automatically retries on transient failures (network errors, `5xx`, and `429`), while returning immediately on permanent client errors like `404 Not Found` or `401 Unauthorized`.
* **`AbortSignal` Support:** Respects `AbortController` signals passed in `options.signal` and stops retrying immediately if the request is aborted.

Here is a well-documented implementation of `fetchWithRetry` using `async/await` and exponential backoff with jitter:

```javascript
/**
 * Fetches a resource with automatic retries and exponential backoff.
 *
 * Retries on network errors, HTTP 429 (Too Many Requests), and 5xx server errors.
 * Does not retry on 4xx client errors (except 429) or when the request is aborted.
 * If all retries are exhausted on a retryable HTTP status, the final `Response`
 * object is returned (matching standard `fetch` behavior).
 *
 * @param {string | URL} url - The URL of the resource to fetch.
 * @param {RequestInit} [options={}] - Optional `fetch` configuration object (headers, method, signal, etc.).
 * @param {number} [retries=3] - Maximum number of retry attempts after the initial request fails.
 * @param {number} [backoff=300] - Base delay in milliseconds for exponential backoff.
 * @returns {Promise<Response>} A Promise that resolves to the `Response` object.
 * @throws {Error} Throws the last encountered network error if all retries are exhausted,
 *                 or immediately if the request is aborted via `AbortSignal`.
 *
 * @example
 * try {
 *   const response = await fetchWithRetry('https://api.example.com/data', {
 *     method: 'GET',
 *     headers: { 'Accept': 'application/json' }
 *   }, 3);
 *
 *   if (!response.ok) {
 *     throw new Error(`Request failed with status ${response.status}`);
 *   }
 *
 *   const data = await response.json();
 *   console.log(data);
 * } catch (error) {
 *   console.error('Fetch failed after retries:', error);
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3, backoff = 300) {
  let attempt = 0;

  while (true) {
    try {
      const response = await fetch(url, options);

      // Identify transient HTTP errors that are safe to retry
      const isRetryableStatus =
        response.status === 429 || (response.status >= 500 && response.status < 600);

      if (!response.ok && isRetryableStatus && attempt < retries) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      return response;
    } catch (error) {
      // Do not retry if the request was intentionally aborted
      if (error.name === 'AbortError' || options.signal?.aborted) {
        throw error;
      }

      // Rethrow the error if we have exhausted all retry attempts
      if (attempt >= retries) {
        throw error;
      }

      // Exponential backoff with jitter: (backoff * 2^attempt) + random jitter (0-100ms)
      const delay = backoff * Math.pow(2, attempt) + Math.random() * 100;
      attempt++;

      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}
```

### Key Features
* **Exponential Backoff with Jitter**: Delays double on each attempt (`300ms`, `600ms`, `1200ms`, etc.) plus a small random jitter (`0–100ms`) to prevent the "thundering herd" problem when many clients retry simultaneously.
* **Smart Error Handling**: Retries on network failures, `429 Too Many Requests`, and `5xx` server errors, while immediately returning client errors like `400` or `404` where retrying won't help.
* **Abort Support**: Respects `AbortController` / `AbortSignal` and stops retrying immediately if the request is cancelled.

