 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 *   Called once for each item to determine its group key.
 * @returns {Map<K, T[]>} A map from each derived key to its items, in their
 *   original relative order.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * const words = ["ant", "bee", "cat", "dog"];
 * const byLength = groupBy(words, word => word.length);
 *
 * console.log(byLength.get(3)); // ["ant", "bee", "cat", "dog"]
 *
 * @example
 * const people = [
 *   { name: "Ada", role: "engineer" },
 *   { name: "Grace", role: "engineer" },
 *   { name: "Alan", role: "researcher" }
 * ];
 *
 * const byRole = groupBy(people, person => person.role);
 * // Map {
 * //   "engineer"   => [{ name: "Ada", ... }, { name: "Grace", ... }],
 * //   "researcher" => [{ name: "Alan", ... }]
 * // }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError("groupBy: arr must be an array");
  }
  if (typeof keyFn !== "function") {
    throw new TypeError("groupBy: keyFn must be a function");
  }

  const groups = new Map();

  arr.forEach((item, index) => {
    const key = keyFn(item, index, arr);
    const group = groups.get(key);

    if (group) {
      group.push(item);
    } else {
      groups.set(key, [item]);
    }
  });

  return groups;
}
