/**
 * Groups array items by a key derived from each item.
 *
 * Items with the same key are placed in the same array, preserving their
 * original relative order. The input array is not modified.
 *
 * A `Map` is returned so keys can be strings, numbers, symbols, or other
 * values without issues such as prototype-key collisions.
 *
 * @typeParam T - The type of items in the input array.
 * @typeParam K - The type of key returned by `keyFn`.
 * @param arr - The array to group.
 * @param keyFn - Called with each item, its index, and the original array
 *                to determine the item's group key.
 * @returns A map from each derived key to its corresponding items.
 *          An empty input array produces an empty map.
 *
 * @example
 * const people = [
 *   { name: "Ada", role: "engineer" },
 *   { name: "Grace", role: "engineer" },
 *   { name: "Alan", role: "researcher" },
 * ];
 *
 * const byRole = groupBy(people, person => person.role);
 *
 * byRole.get("engineer");
 * // [
 * //   { name: "Ada", role: "engineer" },
 * //   { name: "Grace", role: "engineer" }
 * // ]
 *
 * @remarks
 * Time complexity: O(n), where n is the number of items.
 * Space complexity: O(n).
 */
export function groupBy<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number, array: readonly T[]) => K,
): Map<K, T[]> {
  const groups = new Map<K, T[]>();

  arr.forEach((item, index) => {
    const key = keyFn(item, index, arr);
    const group = groups.get(key);

    if (group) {
      group.push(item);
    } else {
      groups.set(key, [item]);
    }
  });

  return groups;
}
```

