const RETRYABLE_STATUSES = new Set([
  408, // Request Timeout
  425, // Too Early
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

const INITIAL_DELAY_MS = 250;
const MAX_DELAY_MS = 5_000;

/**
 * Fetches a resource, retrying transient failures with exponential backoff.
 *
 * Retry behavior:
 * - Retries network errors and the HTTP statuses listed in RETRYABLE_STATUSES.
 * - Does not retry caller-initiated aborts or non-retryable responses such as
 *   400, 401, 403, or 404.
 * - Returns the final Response when HTTP retries are exhausted. As with fetch(),
 *   callers should check response.ok.
 * - Throws the final error when network retries are exhausted.
 *
 * Backoff starts at 250 ms, doubles after each failed attempt, and is capped at
 * 5 seconds. Full jitter is applied: each delay is randomly selected between
 * zero and the current backoff cap, helping prevent synchronized retries.
 *
 * @param {string | URL} url - The resource to fetch.
 * @param {RequestInit} [options={}] - Standard fetch options, including an
 *   optional AbortSignal. The same options are used for every attempt.
 * @param {number} [retries=3] - Number of retries after the initial request.
 *   For example, 3 permits up to 4 total attempts; 0 performs only one attempt.
 * @returns {Promise<Response>} The first non-retryable response, or the final
 *   response after all permitted attempts.
 * @throws {RangeError} If retries is not a non-negative integer.
 * @throws {*} The final fetch error, or immediately rethrows an abort error.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a non-negative integer");
  }

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

