 *   For example, 3 permits up to 4 total attempts; 0 disables retrying.
 * @returns {Promise<Response>} The successful, non-retryable, or final response.
 * @throws {RangeError} If retries is not a non-negative integer.
 * @throws {Error} The final fetch error, or the abort reason, when applicable.
 *
 * @example
 * const response = await fetchWithRetry("/api/items", {
 *   headers: { Accept: "application/json" }
 * }, 4);
 *
 * if (!response.ok) {
 *   throw new Error(`Request failed: ${response.status}`);
 * }
 *
 * const items = await response.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError("retries must be a non-negative integer");
  }

  const BASE_DELAY_MS = 250;
  const MAX_DELAY_MS = 8_000;
  const { signal } = options;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);
      const isRetryable =
        response.status === 408 ||
        response.status === 429 ||
        (response.status >= 500 && response.status <= 599);

      // Return successful responses, non-retryable errors, and the final
      // response after all retries have been exhausted.
      if (!isRetryable || attempt === retries) {
        return response;
      }

      // This response will not be consumed. Cancel its body so the connection
      // can be released instead of remaining occupied until garbage collection.
      if (response.body) {
        response.body.cancel().catch(() => {});
      }
    } catch (error) {
      const isAbort =
        signal?.aborted || (error instanceof Error && error.name === "AbortError");

      if (isAbort || attempt === retries) {
        throw error;
      }
    }

    const backoffCap = Math.min(
      MAX_DELAY_MS,
      BASE_DELAY_MS * 2 ** attempt
    );

    // Full jitter: choose a delay between 0 and the current backoff cap.
    const delay = Math.floor(Math.random() * (backoffCap + 1));
    await wait(delay, signal);
  }
