 *     { name: "Alan", dept: "math" },
 *     { name: "Grace", dept: "eng" },
 *   ];
 *   groupBy(people, (p) => p.dept);
 *   // => Map {
 *   //      "eng"  => [{ name: "Ada" }, { name: "Grace" }],
 *   //      "math" => [{ name: "Alan" }]
 *   //    }
 */
