    return this;
  }

  /**
   * Check whether a key exists.
   * @param {string} key
   * @returns {boolean}
   */
  has(key) {
    return this.#store.has(key);
  }

  /**
   * Remove a key.
   * @param {string} key
   * @returns {boolean} true if the key existed and was removed
   */
  delete(key) {
    return this.#store.delete(key);
  }
}
```

## Example

