# fetchWithRetry

A robust fetch wrapper with exponential backoff and jitter.

```js
/**
 * Fetch with automatic retries using exponential backoff.
 *
 * Retries on network errors and 5xx server errors (and 429 rate limiting).
 * The delay between attempts grows exponentially, with random jitter to
 * avoid "thundering herd" problems when many clients retry at once.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options] - Standard fetch options (method, headers, body, etc.).
 * @param {AbortSignal} [options.signal] - Abort signal; aborting rejects immediately.
 * @param {number} [retries=3] - Maximum number of retry attempts after the
 *   initial request (total attempts = retries + 1).
 * @param {Object} [backoffOptions] - Optional tuning of backoff behavior.
 * @param {number} [backoffOptions.baseDelay=300] - Delay (ms) for the first retry.
 * @param {number} [backoffOptions.maxDelay=30000] - Cap on any single delay (ms).
 *
 * @returns {Promise<Response>} The successful fetch Response.
 * @throws {Error} If all attempts fail, or the request is aborted.
 */
async function fetchWithRetry(url, options = {}, retries = 3, backoffOptions = {}) {
  const { baseDelay = 300, maxDelay = 30000 } = backoffOptions;
  const maxAttempts = retries + 1;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Retry on server errors and rate limiting; otherwise return.
      if (response.ok || (response.status < 500 && response.status !== 429)) {
        return response;
      }

      // Last attempt: don't retry, just fail with the bad response.
      if (attempt === maxAttempts - 1) {
        throw new Error(`Request failed with status ${response.status}`);
      }

      // Honor Retry-After header if the server provides one.
      const retryAfter = Number(response.headers.get("Retry-After"));
      const delay = Number.isFinite(retryAfter) && retryAfter > 0
        ? retryAfter * 1000
        : backoffDelay(attempt, baseDelay, maxDelay);

      await sleep(delay, options.signal);
    } catch (err) {
      // Abort errors should never be retried — rethrow immediately.
      if (err.name === "AbortError") throw err;

      if (attempt === maxAttempts - 1) throw err;

      await sleep(backoffDelay(attempt, baseDelay, maxDelay), options.signal);
    }
  }
}

/** Compute delay: base * 2^attempt, capped, with ±25% jitter. */
function backoffDelay(attempt, baseDelay, maxDelay) {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  const jitter = exponential * (0.75 + Math.random() * 0.5);
  return Math.round(jitter);
}

/** Promise-based sleep that rejects early if the abort signal fires. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    }

    if (signal) {
      if (signal.aborted) return onAbort();
      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}
```

## Usage

```js
// Basic usage
const res = await fetchWithRetry("https://api.example.com/data");
const data = await res.json();

// With options and custom retry count
const res2 = await fetchWithRetry(
  "https://api.example.com/items",
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: "widget" }),
    signal: AbortSignal.timeout(10000),
  },
  5 // up to 5 retries
);
```

## Key design decisions

- **What gets retried:** Network errors, 5xx responses, and 429 (rate limited). 4xx errors (other than 429) are treated as non-retryable since retrying a bad request won't help.
- **Jitter:** Randomizes each delay ±25% so many concurrent clients don't retry in lockstep.
- **Retry-After:** Honors the server's `Retry-After` header when present.
- **Abort safety:** An `AbortSignal` in `options.signal` works both for the fetch itself and for canceling the backoff wait between attempts.

