async function fetchWithRetry(url, options = {}, retries = 3, retryOptions = {}) {
  const {
    baseDelayMs = 300,
    maxDelayMs = 10_000,
    retryOnStatus = [408, 429],
  } = retryOptions;

  const isRetryableStatus = (status) =>
    status >= 500 || retryOnStatus.includes(status);

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (response.ok || !isRetryableStatus(response.status)) {
        return response; // Success, or a non-retryable error (e.g., 404)
      }

      // Retryable HTTP status — treat as a failure but keep the response info
      lastError = new Error(`HTTP ${response.status} for ${url}`);
    } catch (err) {
      // Network error / request aborted
      lastError = err;
    }

    // Don't sleep after the final attempt
    if (attempt < retries) {
      const exponential = baseDelayMs * 2 ** attempt;
      const jitter = Math.random() * exponential * 0.3; // 0–30% jitter
      const delay = Math.min(exponential + jitter, maxDelayMs);

      console.warn(
        `fetchWithRetry: attempt ${attempt + 1}/${retries + 1} failed ` +
        `(${lastError.message}). Retrying in ${Math.round(delay)}ms...`
      );

      await sleep(delay);
    }
  }

  throw lastError;
}
