 * Fetch a URL with automatic retries and exponential backoff.
 *
 * On failure (network error, 5xx, or 429 response), the request is retried
 * up to `retries` times. The delay between attempts grows exponentially:
 *
 *     delay = baseDelay * 2^attempt  (+ random jitter)
 *
 * e.g. with baseDelay = 500ms:  ~500ms, ~1000ms, ~2000ms, ...
 *
 * Jitter (randomness) is added to prevent "thundering herd" issues when
 * many clients retry simultaneously.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options={}] - Standard fetch options (method, headers,
 *   body, signal, etc.). Passed through to `fetch` unchanged.
 * @param {number} [retries=3] - Maximum number of retry attempts after the
 *   initial request. 0 means no retries (a single attempt).
 *
 * @returns {Promise<Response>} The resolved fetch Response on success.
 * @throws {Error} If all attempts fail, throws the last error encountered.
 *   If the final failure was an HTTP error response, the thrown Error has
 *   a `response` property attached.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const BASE_DELAY_MS = 500;
  const MAX_DELAY_MS = 30_000;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Retry on server errors and rate limiting; other 4xx errors
      // (e.g. 404, 401) are unlikely to succeed on retry, so throw.
      if (response.ok || (response.status < 500 && response.status !== 429)) {
        return response;
      }

      const error = new Error(`Request failed with status ${response.status}`);
      error.response = response;
      throw error;
    } catch (err) {
      lastError = err;

      // Don't retry if the caller aborted the request.
      if (err.name === 'AbortError') throw err;

      if (attempt < retries) {
        const backoff = Math.min(BASE_DELAY_MS * 2 ** attempt, MAX_DELAY_MS);
        const jitter = Math.random() * backoff * 0.3; // up to 30% jitter
        await new Promise((resolve) => setTimeout(resolve, backoff + jitter));
      }
    }
  }

  throw lastError;
}
```

