 *   const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 *   const data = await res.json();
 * } catch (err) {
 *   console.error('Request failed after retries:', err.message);
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const BASE_DELAY_MS = 500;
  const MAX_ATTEMPTS = retries + 1; // initial attempt + retries

  let lastError;

  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    try {
      const response = await fetch(url, options);

      // Treat HTTP error statuses as failures worth retrying
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return response;
    } catch (err) {
      lastError = err;

      // Don't wait if this was the final attempt
      if (attempt === MAX_ATTEMPTS - 1) break;

      // Exponential backoff with jitter:
      // delay = base * 2^attempt, randomized ±25%
      const delay = BASE_DELAY_MS * 2 ** attempt;
      const jitter = delay * 0.25 * (Math.random() * 2 - 1);
      await new Promise((resolve) => setTimeout(resolve, delay + jitter));
    }
  }

  throw lastError;
}

module.exports = { fetchWithRetry };
```

## Notes

- **Exponential backoff:** waits ~500ms, 1000ms, 2000ms (for 3 retries) — growing delay gives transient failures time to recover.
- **Jitter:** randomizes the wait so many concurrent clients don't retry in lockstep.
- **Status handling:** `response.ok` is checked, since `fetch` only rejects on *network* errors, not HTTP 4xx/5xx.
- **Caveat:** if `options.body` is a stream, it can only be consumed once — pass a string or `Blob`, or clone the body per attempt, if you need to retry requests with streaming bodies.
