# `fetchWithRetry`

A robust wrapper around the native `fetch` API that automatically retries failed requests using **exponential backoff** (with jitter) to avoid hammering a struggling server.

```javascript
/**
 * Fetch a resource with automatic retries and exponential backoff.
 *
 * Retries are attempted when:
 *   - The request throws a network/`TypeError` error (connection refused,
 *     DNS failure, offline, CORS, etc.)
 *   - The response has a retryable status code (default: 408, 429, 500,
 *     502, 503, 504)
 *
 * The delay between attempts grows exponentially:
 *
 *   delay(n) = baseDelay * 2^(n-1) + random jitter
 *
 * e.g. with baseDelay = 300ms:
 *   attempt 1 → ~300ms, attempt 2 → ~600ms, attempt 3 → ~1200ms ...
 *
 * Jitter (randomness) is added so that many clients retrying at once
 * don't synchronize into a "thundering herd".
 *
 * @param {string} url          - The URL to fetch.
 * @param {Object} [options]    - Standard `fetch` options (method, headers,
 *                                body, signal, etc.), plus the retry-specific
 *                                options below.
 * @param {number} [options.retryDelay=300]     - Base delay in ms for the
 *                                                first retry.
 * @param {number} [options.maxDelay=30000]    - Upper cap on any single
 *                                                backoff delay in ms.
 * @param {number[]} [options.retryOn=[408,429,500,502,503,504]]
 *                                              - HTTP status codes that
 *                                                trigger a retry.
 * @param {number} [retries=3]  - Maximum number of retry attempts
 *                                (so up to `retries + 1` total requests).
 *
 * @returns {Promise<Response>} The final `fetch` Response object.
 *
 * @throws {Error}  If all attempts fail, the last error is re-thrown.
 *                  For HTTP failures, an `Error` with a `response`
 *                  property is thrown.
 * @throws {AbortError} If the request is aborted via `options.signal`.
 *                      Aborted requests are never retried.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    retryDelay = 300, // Base backoff delay (ms)
    maxDelay = 30_000, // Cap on backoff delay (ms)
    retryOn = [408, 429, 500, 502, 503, 504], // Retryable status codes
    ...fetchOptions, // Everything else goes to native fetch
  } = options;

  /** Sleep helper that respects an AbortSignal. */
  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      signal?.addEventListener("abort", () => {
        clearTimeout(timer);
        reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      }, { once: true });
    });

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      // Success or a non-retryable status — hand it back to the caller.
      if (!retryOn.includes(response.status) || attempt === retries) {
        return response;
      }

      // Retryable HTTP status — treat as a failure and back off.
      lastError = new Error(`Request failed with status ${response.status}`);
      lastError.response = response;
    } catch (error) {
      // Never retry aborts — the caller intentionally cancelled.
      if (error.name === "AbortError") throw error;
      lastError = error;
    }

    // Don't sleep after the final attempt.
    if (attempt < retries) {
      const backoff = Math.min(retryDelay * 2 ** attempt, maxDelay);
      const jitter = Math.random() * backoff * 0.3; // up to 30% jitter
      await sleep(backoff + jitter, fetchOptions.signal);
    }
  }

  throw lastError;
}
```

