/**
 * Fetches a resource with automatic retries on failure using
 * exponential backoff.
 *
 * Retries occur when:
 *   - The network request throws (e.g., connection error, timeout)
 *   - The response status is >= 400 (configurable via shouldRetry)
 *
 * The delay before each retry doubles each attempt, starting at
 * `initialDelay` ms, with optional random "jitter" to avoid thundering
 * herds when many clients retry simultaneously.
 *
 * @param {string}    url             - The URL to fetch.
 * @param {Object}    [options]       - Standard fetch options (method,
 *                                      headers, body, etc.).
 * @param {Object}    [retryOptions]  - Retry configuration.
 * @param {number}    [retryOptions.retries=3]
 *                                      Maximum number of retry attempts.
 * @param {number}    [retryOptions.initialDelay=500]
 *                                      Delay (ms) before the first retry.
 * @param {number}    [retryOptions.backoffFactor=2]
 *                                      Multiplier applied to the delay
 *                                      after each failed attempt.
 * @param {number}    [retryOptions.maxDelay=30000]
 *                                      Cap on any single delay (ms).
 * @param {number}    [retryOptions.jitter=0.1]
 *                                      Fraction of randomization added
 *                                      to each delay (0 = none).
 * @param {Function}  [retryOptions.shouldRetry]
 *                                      Custom predicate `(response) => boolean`
 *                                      deciding whether a received response
 *                                      should trigger a retry. Defaults to
 *                                      retrying on any status >= 400.
 * @param {Function}  [retryOptions.onRetry]
 *                                      Callback `(attempt, delay, reason)`
 *                                      invoked before each retry — useful
 *                                      for logging/metrics.
 *
 * @returns {Promise<Response>} Resolves with the final fetch Response.
 *   Rejects with the last error if all attempts fail, or with an
 *   `Error` noting the final non-retryable status code.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { method: "GET", headers: { Authorization: "Bearer ..." } },
 *   { retries: 5, initialDelay: 1000, onRetry: (a, d) => console.log(a, d) }
 * );
 */
async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    initialDelay = 500,
    backoffFactor = 2,
    maxDelay = 30_000,
    jitter = 0.1,
    shouldRetry = (res) => res.status >= 400,
    onRetry = () => {},
  } = retryOptions;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (!shouldRetry(response) || attempt === retries) {
        if (response.status >= 400 && attempt === retries) {
          // Final attempt failed with a bad status — let the caller
          // decide what to do with the response.
          return response;
        }
        return response;
      }

      // Response was retryable (e.g., 5xx) — fall through to backoff.
      lastError = new Error(`HTTP ${response.status}`);
      scheduleRetry(attempt, lastError);
      await sleep(computeDelay(attempt));
      continue;
    } catch (err) {
      // Network-level failure.
      lastError = err;
      if (attempt === retries) break;
      scheduleRetry(attempt, err);
      await sleep(computeDelay(attempt));
    }
  }

  throw lastError;

  // --- helpers -------------------------------------------------------

  function computeDelay(attempt) {
    const base = Math.min(initialDelay * backoffFactor ** attempt, maxDelay);
    const spread = base * jitter;
    return base + (Math.random() * 2 - 1) * spread;
  }

  function scheduleRetry(attempt, reason) {
    const delay = computeDelay(attempt);
    onRetry(attempt + 1, delay, reason);
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
```

