 * avoid "thundering herd" problems when many clients retry at once.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options] - Standard fetch options (method, headers, body, etc.).
 * @param {AbortSignal} [options.signal] - Abort signal; aborting rejects immediately.
 * @param {number} [retries=3] - Maximum number of retry attempts after the
 *   initial request (total attempts = retries + 1).
 * @param {Object} [backoffOptions] - Optional tuning of backoff behavior.
 * @param {number} [backoffOptions.baseDelay=300] - Delay (ms) for the first retry.
 * @param {number} [backoffOptions.maxDelay=30000] - Cap on any single delay (ms).
 *
 * @returns {Promise<Response>} The successful fetch Response.
 * @throws {Error} If all attempts fail, or the request is aborted.
 */
async function fetchWithRetry(url, options = {}, retries = 3, backoffOptions = {}) {
  const { baseDelay = 300, maxDelay = 30000 } = backoffOptions;
  const maxAttempts = retries + 1;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Retry on server errors and rate limiting; otherwise return.
      if (response.ok || (response.status < 500 && response.status !== 429)) {
        return response;
      }

      // Last attempt: don't retry, just fail with the bad response.
      if (attempt === maxAttempts - 1) {
        throw new Error(`Request failed with status ${response.status}`);
      }

      // Honor Retry-After header if the server provides one.
      const retryAfter = Number(response.headers.get("Retry-After"));
      const delay = Number.isFinite(retryAfter) && retryAfter > 0
        ? retryAfter * 1000
        : backoffDelay(attempt, baseDelay, maxDelay);

