```javascript
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * On failure (network error, 5xx status, or 429 status), the request is
 * retried up to `retries` times. The delay between attempts grows
 * exponentially: delay = baseDelay * 2^attempt, capped at `maxDelay`.
 * Random jitter is added to prevent "thundering herd" issues when many
 * clients retry simultaneously.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options={}] - Standard fetch options (method, headers,
 *   body, signal, etc.).
 * @param {Object} [options.retryConfig] - Optional retry tuning:
 *   @param {number} [retryConfig.retries=3] - Max retry attempts after the
 *     initial request (so up to `retries + 1` total requests).
 *   @param {number} [retryConfig.baseDelay=300] - Delay (ms) before the
 *     first retry.
 *   @param {number} [retryConfig.maxDelay=5000] - Upper bound (ms) on any
 *     single backoff delay.
 *   @param {number[]} [retryConfig.retryOn=[429, 500, 502, 503, 504]] -
 *     HTTP status codes that should trigger a retry.
 * @param {number} [retries=3] - Legacy positional form: max retry attempts.
 *   Ignored if `options.retryConfig.retries` is set.
 *
 * @returns {Promise<Response>} The successful fetch Response object.
 *
 * @throws {Error} If all attempts fail. The error includes the last
 *   response status (if any) and the underlying cause.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    retryConfig: {
      retries: retryCount = retries,
      baseDelay = 300,
      maxDelay = 5000,
      retryOn = [429, 500, 502, 503, 504],
    } = {},
    ...fetchOptions
  } = options;

  let lastError;

  for (let attempt = 0; attempt <= retryCount; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      // Success or non-retryable status — return immediately.
      if (response.ok || !retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status.
      lastError = new Error(
        `Request failed with status ${response.status} (attempt ${attempt + 1})`
      );
      lastError.status = response.status;
    } catch (err) {
      // Network error or aborted request.
      if (err.name === 'AbortError') throw err; // Never retry user aborts.
      lastError = err;
    }

    // No more attempts left.
    if (attempt === retryCount) break;

    // Exponential backoff with jitter: 300ms, 600ms, 1200ms, ... capped.
    const backoff = Math.min(baseDelay * 2 ** attempt, maxDelay);
    const jitter = Math.random() * backoff * 0.3; // up to 30% jitter
    await new Promise((resolve) => setTimeout(resolve, backoff + jitter));
  }

  lastError.message = `fetchWithRetry failed after ${retryCount + 1} attempt(s): ${lastError.message}`;
  throw lastError;
}
