# fetchWithRetry

A utility that retries a failed `fetch` request with exponential backoff (with jitter) to avoid hammering a struggling server.

```js
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * On failure (network error or a retriable HTTP status), the request is
 * retried up to `retries` times. The delay before each retry grows
 * exponentially: baseDelay * 2^attempt, capped at `maxDelay`, with
 * random jitter to prevent "thundering herd" behavior.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options={}] - Standard fetch options (method, headers,
 *   body, signal, etc.). Passed through unchanged on every attempt.
 * @param {Object} [retryOptions={}] - Retry behavior settings.
 * @param {number} [retryOptions.retries=3] - Number of retry attempts
 *   after the initial failure (so up to `retries + 1` total requests).
 * @param {number} [retryOptions.baseDelay=300] - Base delay in
 *   milliseconds. First retry waits ~baseDelay, then doubles each time.
 * @param {number} [retryOptions.maxDelay=10000] - Upper bound (ms) on
 *   any single backoff delay.
 * @param {number[]} [retryOptions.retriableStatuses=[429, 500, 502, 503, 504]]
 *   - HTTP status codes that trigger a retry. Non-retriable statuses
 *   (e.g. 404) reject immediately.
 * @param {(error: Error, attempt: number) => boolean} [retryOptions.shouldRetry]
 *   - Custom predicate; return false to stop retrying early.
 * @param {AbortSignal} [options.signal] - Aborting the signal cancels
 *   retries immediately with the abort reason.
 *
 * @returns {Promise<Response>} The successful fetch Response.
 *   Note: a 4xx/5xx response that is NOT retriable resolves normally —
 *   callers should still check `response.ok`.
 *
 * @throws {Error} The last error, if all attempts fail or a status is
 *   non-retriable. Includes `error.attempt`, and for HTTP errors,
 *   `error.response` and `error.status`.
 */
async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10000,
    retriableStatuses = [429, 500, 502, 503, 504],
    shouldRetry,
  } = retryOptions;

  /** Pause for `ms` milliseconds, unless the signal aborts first. */
  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      // If the caller aborts during the backoff, stop waiting immediately.
      signal?.addEventListener("abort", () => {
        clearTimeout(timer);
        reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      }, { once: true });
    });

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (retriableStatuses.includes(response.status)) {
        const err = new Error(`HTTP ${response.status} from ${url}`);
        err.response = response;
        err.status = response.status;
        throw err;
      }

      return response; // Success or non-retriable status — caller decides.
    } catch (error) {
      lastError = error;

      // Aborts are never retried.
      if (error.name === "AbortError") throw error;

      // Out of attempts, or caller opted out via custom predicate.
      const outOfAttempts = attempt === retries;
      if (outOfAttempts || (shouldRetry && !shouldRetry(error, attempt))) {
        break;
      }

      // Exponential backoff: base * 2^n, capped, with ±25% jitter.
      const delay = Math.min(maxDelay, baseDelay * 2 ** attempt);
      const jittered = delay * (0.75 + Math.random() * 0.5);

      console.warn(
        `fetchWithRetry: attempt ${attempt + 1} failed ` +
        `(${error.message}). Retrying in ${Math.round(jittered)}ms...`
      );

      await sleep(jittered, options.signal);
    }
  }

  lastError.attempt = retries;
  throw lastError;
}
```

