# `fetchWithRetry`

A robust wrapper around `fetch` that retries failed requests using **exponential backoff** with jitter.

```javascript
/**
 * Fetches a resource, retrying with exponential backoff on failure.
 *
 * Retries occur on network errors and on HTTP responses that indicate
 * a retryable condition (408, 429, and any 5xx status).
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options] - Standard fetch options (method, headers, body, etc.).
 * @param {number} [options.timeoutMs=10000] - Per-attempt timeout in milliseconds.
 * @param {number} [retries=3] - Maximum number of retry attempts after the
 *   initial request (so up to `retries + 1` total requests).
 * @param {number} [baseDelayMs=500] - Delay before the first retry. Each
 *   subsequent retry doubles the delay (500 → 1000 → 2000 ...).
 * @returns {Promise<Response>} The successful fetch Response.
 * @throws {Error} If all attempts fail. The error includes the last failure
 *   reason and the total number of attempts made.
 */
async function fetchWithRetry(url, options = {}, retries = 3, baseDelayMs = 500) {
  const { timeoutMs = 10000, ...fetchOptions } = options;

  /** HTTP status codes worth retrying. */
  const isRetryableStatus = (status) =>
    status === 408 || status === 429 || status >= 500;

  /** Sleep helper. */
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Combine caller-supplied signal (if any) with a per-attempt timeout.
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    const onExternalAbort = () => controller.abort();
    fetchOptions.signal?.addEventListener("abort", onExternalAbort);

    try {
      const response = await fetch(url, {
        ...fetchOptions,
        signal: controller.signal,
      });

      if (response.ok || !isRetryableStatus(response.status)) {
        return response; // Success, or a non-retryable error (e.g., 404) — return it.
      }

      // Retryable HTTP status — treat as failure and retry.
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
    } catch (err) {
      lastError = err.name === "AbortError"
        ? new Error(`Attempt ${attempt + 1} timed out after ${timeoutMs}ms`)
        : err;
    } finally {
      clearTimeout(timeoutId);
      fetchOptions.signal?.removeEventListener("abort", onExternalAbort);
    }

    // Don't sleep after the final attempt.
    if (attempt < retries) {
      const delay = baseDelayMs * 2 ** attempt;
      const jitter = delay * 0.2 * (Math.random() * 2 - 1); // ±20% jitter
      await sleep(delay + jitter);
    }
  }

  throw new Error(
    `fetchWithRetry failed for ${url} after ${retries + 1} attempts: ${lastError.message}`,
    { cause: lastError }
  );
}
```

