 * (plus random jitter to avoid thundering-herd effects) before retrying.
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options] - Standard fetch options (method, headers, body, etc.).
 * @param {number} [retries=3] - Maximum number of retry attempts after the
 *   initial request fails. 0 means "try once, no retries".
 * @param {Object} [retryOptions] - Optional tuning parameters.
 * @param {number} [retryOptions.baseDelay=300] - Delay (ms) before the first retry.
 * @param {number} [retryOptions.maxDelay=10000] - Upper cap (ms) on any single delay.
 * @param {number[]} [retryOptions.retryOn=[429, 500, 502, 503, 504]] - HTTP status
 *   codes that should trigger a retry. Network errors always retry.
 *
 * @returns {Promise<Response>} The successful fetch Response.
 * @throws {Error} If all attempts fail, or the response has a non-retryable
 *   error status. The thrown error includes a `lastResponse` property when
 *   the final failure was an HTTP error.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {
 *   headers: { Authorization: 'Bearer token' }
 * }, 5);
 */
async function fetchWithRetry(url, options = {}, retries = 3, retryOptions = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    retryOn = [429, 500, 502, 503, 504],
  } = retryOptions;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success or a non-retryable HTTP error — return/handle immediately.
      if (response.ok || !retryOn.includes(response.status)) {
        if (response.ok) return response;

          const err = new Error(`Request failed with status ${response.status}`);
          err.lastResponse = response;
          throw err;
      }

      // Retryable HTTP error (e.g., 503): treat like a failure.
      lastError = new Error(`Retryable status ${response.status}`);
      lastError.lastResponse = response;
    } catch (err) {
      // Non-retryable HTTP errors rethrow immediately.
      if (err.lastResponse && !retryOn.includes(err.lastResponse.status)) {
        throw err;
      }
      lastError = err;
    }

    // Don't sleep if this was the final attempt.
    if (attempt < retries) {
      // Exponential backoff with jitter: delay = min(base * 2^attempt, max) * (0.5–1.5)
      const backoff = Math.min(baseDelay * 2 ** attempt, maxDelay);
      const jittered = backoff * (0.5 + Math.random());
      await sleep(jittered);
    }
  }

  // All attempts exhausted.
  const message = lastError?.lastResponse
    ? `Request failed after ${retries + 1} attempts (status ${lastError.lastResponse.status})`
    : `Request failed after ${retries + 1} attempts: ${lastError?.message ?? 'unknown error'}`;
  const finalError = new Error(message);
  if (lastError?.lastResponse) finalError.lastResponse = lastError.lastResponse;
  throw finalError;
}
