    } = {},
    ...fetchOptions // everything else goes to fetch
  } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('retries must be a non-negative integer');
  }

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      if (
        Array.isArray(retryOnStatus) &&
        retryOnStatus.includes(response.status) &&
        attempt < retries
      ) {
        const delayMs = computeDelay(attempt, baseDelayMs, maxDelayMs);
        onRetry?.({
          attempt: attempt + 1,
          delayMs,
          reason: `HTTP ${response.status}`,
        });
        await sleep(delayMs);
        continue;
      }

      return response;
    } catch (error) {
      // Don't retry user-initiated aborts.
      if (fetchOptions.signal?.aborted) throw error;
      lastError = error;

      if (attempt < retries) {
        const delayMs = computeDelay(attempt, baseDelayMs, maxDelayMs);
        onRetry?.({ attempt: attempt + 1, delayMs, reason: error.message });
        await sleep(delayMs);
      }
    }
  }

  const message =
    `fetchWithRetry: all ${retries + 1} attempts failed for ${url}` +
    (lastError ? ` — last error: ${lastError.message}` : '');
  const error = new Error(message);
  error.attempts = retries + 1;
  if (lastError) error.cause = lastError;
  throw error;
}

/** Exponential backoff with full jitter, clamped to maxDelayMs. */
function computeDelay(attempt, baseDelayMs, maxDelayMs) {
  const exponential = baseDelayMs * 2 ** attempt;
  const clamped = Math.min(exponential, maxDelayMs);
  return Math.random() * clamped; // jitter avoids thundering-herd
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default fetchWithRetry;
```

## Usage

```javascript
// Simple
const res = await fetchWithRetry('https://api.example.com/users');
const data = await res.json();

// Customized
try {
  const res = await fetchWithRetry('/api/flaky', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ok: true }),
    retry: {
      retries: 5,
      baseDelayMs: 200,
      maxDelayMs: 10_000,
      onRetry: ({ attempt, delayMs, reason }) =>
        console.warn(`Attempt ${attempt} failed (${reason}); retrying in ${delayMs}ms`),
    },
  });
} catch (err) {
  console.error(`Failed after ${err.attempts} attempts`);
}
```

## Design notes

- **Jitter** randomizes each delay to prevent many clients from hammering a recovering server simultaneously ("thundering herd").
- **Status-aware**: retries only on transient HTTP errors (429, 5xx) by default — never on 404 or 401, where retrying is pointless.
- **Abort-safe**: passes your `AbortSignal` through to `fetch` and never retries after an intentional abort.
- **Non-2xx handling**: returns the response as-is; callers should still check `res.ok` for non-retryable statuses like 404.

# fetchWithRetry

A utility that wraps the native `fetch` API with automatic retries and exponential backoff on failure.

```javascript
/**
 * Fetches a URL with automatic retry and exponential backoff.
 *
 * Retries the request when it fails (network error) or when the
 * response status indicates a retryable failure (5xx server errors
 * and 429 Too Many Requests). Waits between attempts, doubling the
 * delay each time (with optional jitter to avoid thundering herds).
 *
 * @param {string} url - The URL to fetch.
 * @param {Object} [options] - Standard fetch options (method, headers,
 *   body, signal, etc.).
 * @param {number} [retries=3] - Maximum number of retry attempts after
 *   the initial request. The total number of requests will be
 *   `retries + 1`.
 * @returns {Promise<Response>} The successful fetch Response object.
 * @throws {Error} The last error if all attempts fail, or the last
 *   non-retryable Response if the final attempt returns an error status.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry('https://api.example.com/data');
 *
 * @example
 * // With fetch options and 5 retries
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ hello: 'world' }),
 *   },
 *   5
 * );
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const MAX_RETRIES = Math.max(0, Math.floor(retries));
  const BASE_DELAY_MS = 500;   // delay before the first retry
  const MAX_DELAY_MS = 30_000; // cap the backoff so it doesn't grow forever

  /**
   * Returns true if the given HTTP status is worth retrying.
   * @param {number} status
   * @returns {boolean}
   */
  const isRetryableStatus = (status) =>
    status === 408 || // Request Timeout
    status === 429 || // Too Many Requests
    (status >= 500 && status <= 599); // Server errors

  /**
   * Sleeps for `ms` milliseconds, aborting early if the signal fires.
   * @param {number} ms
   * @param {AbortSignal} [signal]
   * @returns {Promise<void>}
   */
  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      if (signal) {
        signal.addEventListener('abort', () => {
          clearTimeout(timer);
          reject(signal.reason ?? new Error('Aborted'));
        }, { once: true });
      }
    });

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success — return the response for the caller to consume.
      if (response.ok || !isRetryableStatus(response.status)) {
        return response;
      }

      // Retryable HTTP status (e.g., 500, 503, 429).
      lastResponse = response;
      lastError = new Error(
        `Request failed with status ${response.status} (attempt ${attempt + 1})`
      );
    } catch (error) {
      // Network error, CORS issue, aborted request, etc.
      lastError = error;
      lastResponse = undefined;

      // Never retry explicit user aborts.
      if (error.name === 'AbortError') throw error;
    }

    // No attempts left — bail out.
    if (attempt === MAX_RETRIES) break;

    // Exponential backoff: base * 2^attempt, capped, with ±25% jitter.
    const delay = Math.min(BASE_DELAY_MS * 2 ** attempt, MAX_DELAY_MS);
    const jitteredDelay = delay * (0.75 + Math.random() * 0.5);

    await sleep(jitteredDelay, options.signal);
  }

  // All attempts exhausted.
  if (lastResponse && !lastResponse.ok) {
    throw new Error(
      `fetchWithRetry: failed after ${MAX_RETRIES + 1} attempts — ` +
      `last status ${lastResponse.status} from ${url}`
    );
  }
  throw lastError ?? new Error(`fetchWithRetry: failed to fetch ${url}`);
}
```

## Key design decisions

- **What counts as "failure":** Network errors (thrown by `fetch`) and retryable HTTP statuses (`408`, `429`, `5xx`). Non-retryable statuses like `404` are returned to the caller rather than retried, since retrying won't change the outcome.
- **Exponential backoff:** Waits `500ms × 2^attempt` between retries (500ms, 1s, 2s, 4s…), capped at 30s.
- **Jitter:** Each delay is randomized ±25% so many clients retrying simultaneously don't synchronize ("thundering herd" protection).
- **Abort support:** If you pass an `AbortSignal` in `options`, aborting cancels both the request and the backoff wait.
- **Total attempts:** `retries + 1` — the initial request plus `retries` retries.

## Caveats

- Only retries when the body can be safely re-sent (GET/PUT/DELETE, or idempotent POSTs). Non-idempotent requests may cause duplicate side effects if the first attempt actually succeeded server-side.
- Check for a `Retry-After` header on `429`/`503` responses if you need server-directed delays.

# fetchWithRetry

A utility that retries failed `fetch` requests with **exponential backoff** and optional **jitter** to avoid thundering-herd issues.

```js
/**
 * Fetch a resource, retrying with exponential backoff on failure.
 *
 * Retries occur when:
 *   - A network error is thrown (connection refused, DNS failure, etc.)
 *   - The response status is in `retryStatuses` (default: 429, 500, 502, 503, 504)
 *
 * Note: 4xx errors other than those listed are NOT retried — they indicate
 * client mistakes that retrying won't fix (e.g., 401, 404).
 *
 * The delay before each retry is calculated as:
 *   delay = min(baseDelay * 2^attempt, maxDelay) ± jitter
 * where jitter is a random factor (default ±30%) to prevent many clients
 * from retrying in perfect sync.
 *
 * @param {string} url                          - The URL to fetch.
 * @param {Object} [options={}]                  - Standard fetch options
 *                                                (method, headers, body, etc.).
 * @param {Object} [opts]                       - Retry configuration.
 * @param {number} [opts.retries=3]             - Max number of retry attempts
 *                                                AFTER the initial request.
 * @param {number} [opts.baseDelay=300]          - Delay in ms before the first
 *                                                retry. Doubles each attempt.
 * @param {number} [opts.maxDelay=10000]         - Upper cap on the delay (ms).
 * @param {number[]}[opts.retryStatuses=[429,500,502,503,504]]
 *                                              - HTTP status codes that
 *                                                trigger a retry.
 * @param {number} [opts.jitter=0.3]             - Random variation factor
 *                                                (0 = none, 0.3 = ±30%).
 *
 * @returns {Promise<Response>} The final fetch Response object.
 *
 * @throws {Error} If all attempts fail. The error includes the last response
 *                 (if any) and the total number of attempts made.
 */
async function fetchWithRetry(
  url,
  options = {},
  { retries = 3, baseDelay = 300, maxDelay = 10000, retryStatuses = [429, 500, 502, 503, 504], jitter = 0.3 } = {}
) {
  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success or a non-retryable status — return immediately.
      if (response.ok || !retryStatuses.includes(response.status)) {
        return response;
      }

      lastResponse = response;
      lastError = new Error(`HTTP ${response.status}: ${response.statusText}`);

      // Honor `Retry-After` header if the server provides one.
      const retryAfter = Number(response.headers.get("Retry-After"));
      if (!Number.isNaN(retryAfter) && retryAfter > 0) {
        await sleep(retryAfter * 1000);
        continue;
      }
    } catch (err) {
      // Network-level failure (fetch threw).
      lastError = err;
    }

    // Don't sleep if this was the final attempt.
    if (attempt === retries) break;

    const rawDelay = Math.min(baseDelay * 2 ** attempt, maxDelay);
    const jittered = rawDelay * (1 + (Math.random() * 2 - 1) * jitter);
    await sleep(jittered);
  }

  const error = new Error(
    `fetchWithRetry failed after ${retries + 1} attempt(s): ${lastError?.message}`
  );
  error.lastResponse = lastResponse;
  error.cause = lastError;
  throw error;
}

/** Promise-based sleep helper. */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
```

## Usage

```js
// Simple: up to 3 retries with default delays
