```javascript
/**
 * Fetch a resource with automatic retries and exponential backoff.
 *
 * On failure (network error or retryable HTTP status), the request is
 * retried up to `retries` times. The delay between attempts grows
 * exponentially and includes random jitter:
 *
 *     delay = min(maxDelay, baseDelay * 2^attempt) * (0.5 + random())
 *
 * @param {string}  url               The URL to fetch.
 * @param {Object}  [options={}]      Standard fetch options (method, headers,
 *                                    body, signal, etc.).
 * @param {number}  [retries=3]       Maximum number of retry attempts.
 * @param {Object}  [retryConfig]     Optional retry tuning.
 * @param {number}  [retryConfig.baseDelay=300]   Base delay in ms.
 * @param {number}  [retryConfig.maxDelay=5000]   Cap on delay in ms.
 * @param {number[]}[retryConfig.retryOn=[429,500,502,503,504]]
 *                                    HTTP status codes that trigger a retry.
 *
 * @returns {Promise<Response>} The fetch Response object.
 *
 * @throws {Error} If all attempts fail. The thrown error has:
 *                 - `message`: reason for the final failure
 *                 - `attempts`: number of attempts made
 *                 - `status`:   last HTTP status code (if applicable)
 *                 - `cause`:    the underlying error (if applicable)
 *
 * @example
 * try {
 *   const res = await fetchWithRetry('/api/data', { method: 'GET' }, 3);
 *   const data = await res.json();
 * } catch (err) {
 *   console.error(`Failed after ${err.attempts} attempts:`, err.message);
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3, retryConfig = {}) {
  const {
    baseDelay = 300,
    maxDelay = 5000,
    retryOn = [429, 500, 502, 503, 504],
  } = retryConfig;

  const sleep = (ms) =>
    new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      // Support aborting during a backoff wait.
      if (options.signal) {
        options.signal.addEventListener('abort', () => {
          clearTimeout(timer);
          reject(new DOMException('Aborted', 'AbortError'));
        }, { once: true });
      }
    });

  const attempt = async (remaining) => {
    try {
      const response = await fetch(url, options);

      if (response.ok) return response;

      // Retry only on whitelisted, retryable status codes.
      if (!retryOn.includes(response.status) || remaining <= 0) {
        const err = new Error(`Request failed with status ${response.status}`);
        err.status = response.status;
        throw err;
      }

      throw Object.assign(new Error(`Retryable status ${response.status}`), {
        status: response.status,
        retryable: true,
      });
    } catch (error) {
      const isAbort = error.name === 'AbortError';
      const canRetry =
        !isAbort &&
        remaining > 0 &&
        (error.retryable || error instanceof TypeError); // TypeError = network failure

      if (!canRetry) {
        error.attempts = retries - remaining + 1;
        throw error;
      }

      // Exponential backoff with jitter: 0.5x–1.5x of 2^n * baseDelay.
      const delay = Math.min(
        maxDelay,
        baseDelay * 2 ** (retries - remaining)
      ) * (0.5 + Math.random());

      await sleep(delay);
      return attempt(remaining - 1);
    }
  };

  return attempt(retries);
}
```

## Usage Examples

```javascript
// Basic usage: 3 retries, default backoff (300ms → 600ms → 1200ms, with jitter)
const res = await fetchWithRetry('https://api.example.com/users');

// Custom options and more retries
const res2 = await fetchWithRetry('/api/orders', {
  method: 'POST',
