    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ item: 'widget' }),
    retryBaseDelay: 1000,
  },
  5
);

// 3. With an AbortController
const controller = new AbortController();
setTimeout(() => controller.abort(), 8000); // give up after 8s total
try {
  const res = await fetchWithRetry('/slow-endpoint', { signal: controller.signal });
} catch (err) {
  if (err.name === 'AbortError') console.log('Cancelled by caller');
}
```

## Key design decisions

| Decision | Rationale |
|---|---|
| **Jitter** (±50% randomization) | Prevents synchronized retries from many clients ("thundering herd"). |
| **Only retry 408/429/5xx** | Retrying 403/404/422 wastes time — the server won't change its answer. |
| **Max delay cap** | Exponential growth (500 → 1s → 2s → 4s...) can otherwise spiral unreasonably. |
| **AbortSignal respected** | Cancellation must propagate immediately, even mid-backoff. |
| **Returns `Response`, not parsed body** | Keeps it a drop-in replacement for `fetch`; parsing is the caller's job. |

**Caveat:** For requests with a body, be aware that a `ReadableStream` body can only be consumed once — use a string or `Blob`/`ArrayBuffer` body if you need retries to re-send it.

```js
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * The returned value is a `Map` (not a plain object) so that:
 *   - keys of any type are supported (string, number, symbol, object, …),
 *   - there is no risk of prototype pollution (e.g. a key of `"__proto__"`),
 *   - insertion order of first-seen keys is preserved.
 *
 * @template T
 * @template K
 *
 * @param {Iterable<T>} arr
 *   Any iterable of items to group. Passing `null` or `undefined` yields an
 *   empty `Map` rather than throwing.
 *
 * @param {(item: T, index: number) => K} keyFn
 *   Called once per item with the item and its index. The returned value is
 *   used as the group key. Keys are compared with `SameValueZero` semantics
 *   (i.e. `NaN` equals `NaN`, and `+0` equals `-0`), matching `Map` behavior.
 *
 * @returns {Map<K, T[]>}
 *   A `Map` from each distinct key to the array of items that produced it,
 *   in the order the items appeared in the input.
 *
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 *   groupBy([1, 2, 3, 4, 5], n => (n % 2 ? 'odd' : 'even'));
 *   // Map { 'odd' => [1, 3, 5], 'even' => [2, 4] }
 *
 * @example
 *   const people = [
 *     { name: 'Ada',   team: 'eng' },
 *     { name: 'Grace', team: 'eng' },
 *     { name: 'Linus', team: 'ops' },
 *   ];
 *   groupBy(people, p => p.team);
 *   // Map { 'eng' => [Ada, Grace], 'ops' => [Linus] }
 *
 * @example
 *   // Non-string keys work too:
 *   groupBy([1, 2, 3, 4], n => n % 2);
 *   // Map { 1 => [1, 3], 0 => [2, 4] }
 */
export function groupBy(arr, keyFn) {
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: keyFn must be a function');
  }

  const groups = new Map();
  if (arr == null) return groups;

  let index = 0;
  for (const item of arr) {
    const key = keyFn(item, index++);
    const bucket = groups.get(key);
    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  return groups;
}
```

A few notes on the design choices:

- **`Map` over plain object.** A plain object would coerce every key to a string (`1` and `"1"` would collide), and a key of `"__proto__"` or `"constructor"` would be a footgun. `Map` sidesteps both.
- **`Iterable<T>` instead of `T[]`.** Costs nothing and lets callers pass a `Set`, a generator, or a `NodeList`.
- **`arr == null` guard.** `for…of` on `null` throws; returning an empty `Map` is friendlier for callers that pipe optional data through.
- **`bucket === undefined` check.** Using `groups.has(key)` would also work, but `get` + `undefined` check is one lookup instead of two. It's safe here because we never store `undefined` as a value.
- **Index passed to `keyFn`.** Matches the signature of `Array.prototype.map` and is occasionally handy (e.g. grouping into fixed-size chunks).

If you'd rather have a plain object back, wrap it:

```js
const asObject = (m) => Object.fromEntries(m);
```

```js
/**
 * Groups the elements of an array into buckets, keyed by a value derived
 * from each element.
 *
 * The returned object has one own property per distinct key. Each property's
 * value is an array containing every element (in original order) for which
 * `keyFn` returned that key.
 *
 * Keys are coerced to strings, matching normal JavaScript object-key
 * semantics. This means `1`, `'1'`, and `true` would all collide into the
 * same bucket. If you need to preserve key types (e.g. objects, symbols,
 * numbers vs. strings), use a `Map` instead — see the note below.
 *
 * @template T
 * @param {T[]} arr
 *   The array to group. Must be an array; other iterables are not accepted
 *   so that the function fails loudly rather than silently doing the wrong
 *   thing with, say, a string.
 * @param {(item: T, index: number, arr: T[]) => string | number | symbol | boolean | null | undefined} keyFn
 *   Called once per element with `(item, index, arr)`. Its return value is
 *   used as the group key (after string coercion).
 * @returns {Record<string, T[]>}
 *   A null-prototype object mapping each key to an array of matching items.
 *   The prototype is `null` so that keys like `"__proto__"` or `"constructor"`
 *   cannot pollute or shadow anything.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * const people = [
 *   { name: 'Ada',   dept: 'eng' },
 *   { name: 'Grace', dept: 'eng' },
 *   { name: 'Linus', dept: 'ops' },
 * ];
 * groupBy(people, p => p.dept);
 * // => { eng: [{name:'Ada',...}, {name:'Grace',...}], ops: [{name:'Linus',...}] }
 *
 * @example
 * // Empty input yields an empty object.
 * groupBy([], x => x); // => {}
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: first argument must be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: second argument must be a function');
  }

  // Null prototype avoids surprises with keys like "__proto__".
  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = String(keyFn(item, i, arr));

    // `in` check is unnecessary here because the prototype is null, but
    // using a direct lookup keeps the hot path fast.
    const bucket = result[key];
    if (bucket === undefined) {
      result[key] = [item];
    } else {
      bucket.push(item);
    }
  }

  return result;
}
```

### Notes on design choices

- **Null prototype.** Using `Object.create(null)` means `groupBy(items, x => '__proto__')` produces a plain data property instead of silently mutating the object's prototype. It also means `result.hasOwnProperty` is unavailable — use `Object.hasOwn(result, key)` or `key in result` if you need to test membership.
- **String coercion.** This mirrors how object keys work everywhere else in JS. If you need to distinguish `1` from `'1'`, or use object/symbol keys, swap the accumulator for a `Map`:

  ```js
  function groupByMap(arr, keyFn) {
    const m = new Map();
    for (let i = 0; i < arr.length; i++) {
      const k = keyFn(arr[i], i, arr);
      const bucket = m.get(k);
      if (bucket) bucket.push(arr[i]);
      else m.set(k, [arr[i]]);
    }
    return m;
  }
  ```

- **Relationship to `Object.groupBy`.** ES2024 added a built-in `Object.groupBy(items, keyFn)` with nearly identical semantics. This utility is useful when you need to support older runtimes, want the null-prototype guarantee, or want to extend the behavior (e.g. returning a `Map`, sorting buckets, or limiting bucket size).

```js
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * @template T
 * @template {PropertyKey} K
 * @param {readonly T[]} arr - The array to group.
 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 *   Function that returns the group key for an item. It receives the item,
 *   its index, and the original array.
 * @returns {Record<K, T[]>} An object mapping each derived key to an array of items.
 *
 * @remarks
 * - The returned object has no prototype (`Object.create(null)`), so keys like
 *   `"__proto__"`, `"constructor"`, or `"toString"` are safe.
 * - Object keys are coerced to strings or symbols. For example, `1` and `"1"`
 *   are the same key. Use a `Map` if you need to preserve key types/identity.
 * - The input array is not mutated.
 *
 * @example
 * const people = [
 *   { name: 'Alice', age: 30 },
 *   { name: 'Bob', age: 30 },
 *   { name: 'Carol', age: 25 },
 * ];
 *
 * groupBy(people, p => p.age);
 * // {
 * //   '25': [{ name: 'Carol', age: 25 }],
 * //   '30': [{ name: 'Alice', age: 30 }, { name: 'Bob', age: 30 }]
 * // }
 *
 * @example
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4] }
 */
function groupBy(arr, keyFn) {
  const groups = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }

    groups[key].push(item);
  }

  return groups;
}
```

If you need to preserve non-string keys exactly, such as object keys or numbers without string coercion, use a `Map`-based variant instead of a plain object.

