 * const people = [
 *   { name: 'Ada',   role: 'eng' },
 *   { name: 'Grace', role: 'eng' },
 *   { name: 'Linus', role: 'ops' },
 * ];
 * groupBy(people, p => p.role);
 * // => {
 * //      eng: [{ name: 'Ada', ... }, { name: 'Grace', ... }],
 * //      ops: [{ name: 'Linus', ... }],
 * //    }
 *
 * @example
 * // Empty input yields an empty object.
 * groupBy([], x => x); // => {}
 *
 * @see {@link https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/groupBy Object.groupBy} (ES2024)
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: first argument must be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: second argument must be a function');
  }

  // Null-prototype object avoids collisions with inherited keys like
  // `__proto__`, `constructor`, or `toString`.
  const groups = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);

    if (groups[key] === undefined) {
      groups[key] = [];
    }
    groups[key].push(item);
  }

  return groups;
