groupBy(input, n => n % 2);
assert.deepEqual(input, [1, 2, 3]);

// Prototype keys are safe
const r = groupBy([1, 2], () => '__proto__');
assert.equal(Object.getPrototypeOf(r), null);
assert.deepEqual(r['__proto__'], [1, 2]);
```

# `groupBy(arr, keyFn)`

```js
/**
 * Groups the items of an iterable into an object, keyed by the value
 * returned from `keyFn` for each item.
 *
 * Items are pushed into their group in the order they appear in `arr`,
 * so the array for each key preserves the original ordering. Group keys
 * appear in the result in first-seen order.
 *
 * The returned object has a **null prototype** (`Object.create(null)`),
 * which means:
 *   - keys like `"__proto__"`, `"constructor"`, or `"hasOwnProperty"`
 *     are stored as ordinary properties and cannot pollute or collide
 *     with `Object.prototype`;
 *   - the object does not inherit methods such as `toString` or
 *     `hasOwnProperty`. Use `Object.hasOwn(result, key)` if you need
 *     to test for a key.
 *
 * Non-string keys (numbers, symbols, etc.) are stored as object keys,
 * which means numbers are coerced to strings — exactly like any other
 * object property. If you need to preserve the original key type,
 * return a `Map` from your own wrapper instead.
 *
 * @template T
 * @param {Iterable<T>} arr
 *   Any iterable of items to group (array, Set, generator, …).
 * @param {(item: T, index: number) => PropertyKey} keyFn
 *   Called once per item with the item and its zero-based index.
 *   Its return value is used as the group key.
 * @returns {Record<PropertyKey, T[]>}
 *   An object mapping each derived key to the array of items that
 *   produced it. Missing keys are simply absent (never `undefined`
 *   unless `keyFn` itself returned `undefined`).
 *
 * @example
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 ? 'odd' : 'even'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * const people = [
 *   { name: 'Ada',  dept: 'eng' },
 *   { name: 'Bob',  dept: 'eng' },
 *   { name: 'Cara', dept: 'sales' },
 * ];
 * groupBy(people, p => p.dept);
 * // => { eng: [{name:'Ada',…}, {name:'Bob',…}], sales: [{name:'Cara',…}] }
 *
 * @example
 * // Empty input produces an empty object.
 * groupBy([], x => x);
 * // => {}
 */
function groupBy(arr, keyFn) {
  // Use a Map internally so that any key type (including symbols and
  // objects-as-keys) works correctly during accumulation.
  const groups = new Map();
  let index = 0;

  for (const item of arr) {
    const key = keyFn(item, index++);
    const bucket = groups.get(key);
    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  // Convert to a null-prototype object so arbitrary keys are safe.
  const result = Object.create(null);
  for (const [key, items] of groups) {
    result[key] = items;
  }
  return result;
}
```

## Design notes

- **`Iterable<T>` instead of `T[]`** — the implementation only needs `for…of`, so it happily accepts `Set`, generators, typed arrays, etc., at no extra cost.
- **`keyFn` receives an index** — mirrors `Array.prototype.map` and lets callers key by position when useful.
- **`Map` internally, object externally** — the `Map` avoids the `"__proto__"` trap and keeps insertion order, and the final `Object.create(null)` gives callers the familiar plain-object shape without prototype pollution.
- **No `hasOwnProperty` guard needed** — because the accumulator is a `Map`, we don't have to defend against inherited properties the way a naive `{}`-based implementation would.
- **Single pass, O(n)** — no re-scanning, no `reduce` overhead, no closures per item beyond the user's `keyFn`.

## Usage

```js
const words = ['apple', 'avocado', 'banana', 'blueberry', 'cherry'];
groupBy(words, w => w[0]);
// => { a: ['apple', 'avocado'], b: ['banana', 'blueberry'], c: ['cherry'] }

// Beware: object keys are strings, so numeric keys are coerced.
groupBy([1.1, 2.2, 1.3], Math.floor);
// => { '1': [1.1, 1.3], '2': [2.2] }
```

Here’s a small TypeScript `Cache` class backed by a `Map`, with JSDoc for the public API.

```ts
/**
 * A small in-memory key-value cache.
 *
 * @template K The key type.
 * @template V The value type.
 */
export class Cache<K, V> {
  private readonly store = new Map<K, V>();

  /**
   * Creates a new Cache.
   *
   * @param entries Optional iterable of `[key, value]` pairs used to initialize the cache.
   */
  constructor(entries?: Iterable<readonly [K, V]>) {
    if (entries) {
      for (const [key, value] of entries) {
        this.store.set(key, value);
      }
    }
  }

  /**
   * Returns the value associated with `key`, or `undefined` if the key is not present.
   *
   * @param key The key to look up.
   * @returns The cached value, or `undefined`.
   */
  get(key: K): V | undefined {
    return this.store.get(key);
  }

  /**
   * Stores `value` under `key`. Overwrites any existing value.
   *
   * @param key The key to set.
   * @param value The value to cache.
   * @returns This cache instance, for chaining.
   */
  set(key: K, value: V): this {
    this.store.set(key, value);
    return this;
  }

  /**
   * Checks whether `key` exists in the cache.
   *
   * @param key The key to check.
   * @returns `true` if the key exists, otherwise `false`.
   */
  has(key: K): boolean {
    return this.store.has(key);
  }

  /**
   * Removes `key` and its value from the cache.
   *
   * @param key The key to remove.
   * @returns `true` if the key existed and was removed, otherwise `false`.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }
}
```

Example usage:

```ts
const cache = new Cache<string, number>();

cache.set("a", 1);
cache.get("a");    // 1
cache.has("a");    // true
cache.delete("a"); // true
cache.get("a");    // undefined
```

