# Cache

A small in-memory cache with optional TTL and LRU eviction. Written in TypeScript; the JSDoc describes the public API.

```ts
/** A stored value plus its expiry metadata. */
type Entry<V> = {
  value: V;
  /** Epoch ms at which the entry expires, or `null` if it never expires. */
  expiresAt: number | null;
};

export interface CacheOptions {
  /**
   * Maximum number of entries to retain. When exceeded, the
   * least-recently-used entry is evicted. Defaults to `Infinity`.
   */
  maxSize?: number;
  /**
   * Default time-to-live in milliseconds for entries that don't
   * pass an explicit TTL to `set`. Defaults to no expiry.
   */
  defaultTtlMs?: number;
  /**
   * Clock function, injectable for testing. Defaults to `Date.now`.
   */
  now?: () => number;
}

/**
 * A small in-memory key/value cache with optional per-entry TTL and
 * least-recently-used eviction.
 *
 * @example
 * const cache = new Cache<string, number>({ maxSize: 100, defaultTtlMs: 60_000 });
 * cache.set('answer', 42);
 * cache.get('answer'); // 42
 * cache.has('answer'); // true
 * cache.delete('answer'); // true
 */
export class Cache<K, V> {
  private readonly store = new Map<K, Entry<V>>();
  private readonly maxSize: number;
  private readonly defaultTtlMs: number | undefined;
  private readonly now: () => number;

  constructor(options: CacheOptions = {}) {
    this.maxSize = options.maxSize ?? Infinity;
    this.defaultTtlMs = options.defaultTtlMs;
    this.now = options.now ?? Date.now;
  }

  /** Number of entries currently stored (including any that have expired but not yet been pruned). */
  get size(): number {
    return this.store.size;
  }

  /**
   * Retrieve the value for `key`.
   *
   * Expired entries are removed and treated as missing. A successful
   * lookup marks the entry as most-recently-used.
   *
   * @returns The stored value, or `undefined` if the key is absent or expired.
   */
  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (entry === undefined) return undefined;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    // Re-insert to move this key to the most-recently-used position.
    this.store.delete(key);
    this.store.set(key, entry);
    return entry.value;
  }

  /**
   * Store `value` under `key`, overwriting any existing entry.
   *
   * @param ttlMs Time-to-live in milliseconds. Overrides the cache's
   *   `defaultTtlMs`. Pass `Infinity` for no expiry.
   * @returns `this`, for chaining.
   */
  set(key: K, value: V, ttlMs?: number): this {
    const ttl = ttlMs ?? this.defaultTtlMs;
    const expiresAt = ttl === undefined || ttl === Infinity ? null : this.now() + ttl;
    // Delete first so re-inserting moves the key to the most-recent position.
    this.store.delete(key);
    this.store.set(key, { value, expiresAt });
    this.evictIfNeeded();
    return this;
  }

  /**
   * Check whether a non-expired entry exists for `key`.
   *
   * Unlike `get`, this does **not** update the entry's LRU position.
   * Expired entries are removed as a side effect.
   */
  has(key: K): boolean {
    const entry = this.store.get(key);
    if (entry === undefined) return false;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Remove the entry for `key`, if present.
   *
   * @returns `true` if an entry was removed, `false` otherwise.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }

  /** Remove all entries. */
  clear(): void {
    this.store.clear();
  }

  private isExpired(entry: Entry<V>): boolean {
    return entry.expiresAt !== null && entry.expiresAt <= this.now();
  }

  private evictIfNeeded(): void {
    while (this.store.size > this.maxSize) {
      const oldest = this.store.keys().next().value as K | undefined;
      if (oldest === undefined) break;
      this.store.delete(oldest);
    }
  }
}
```

## Design notes

- **LRU via `Map` ordering.** `Map` preserves insertion order, so the first key is always the least-recently-used. `get` and `set` re-insert to bump a key to the end; eviction drops the first key.
- **Lazy expiry.** Expired entries are pruned on access rather than by a timer, so the cache never holds a live `setInterval` and stays cheap when idle.
- **`has` doesn't touch LRU.** Read-only existence checks shouldn't influence eviction order — a common source of surprising cache behavior.
- **Injectable clock.** Passing `now` in tests lets you advance time without `sleep`.

```ts
/**
 * A minimal in-memory key-value cache.
 *
 * Keys use `Map` equality (SameValueZero), so `NaN` matches `NaN` and
 * object keys are compared by reference.
 *
 * @typeParam K - The key type.
 * @typeParam V - The value type.
 */
export class Cache<K, V> {
  private readonly store = new Map<K, V>();

  /**
   * Retrieves the value associated with `key`.
   *
   * @param key - The key to look up.
   * @returns The stored value, or `undefined` if the key is absent.
   */
  get(key: K): V | undefined {
    return this.store.get(key);
  }

  /**
   * Stores `value` under `key`, overwriting any existing value.
   *
   * @param key - The key to set.
   * @param value - The value to cache.
   * @returns This cache instance, allowing method chaining.
   */
  set(key: K, value: V): this {
    this.store.set(key, value);
    return this;
  }

  /**
   * Checks whether `key` exists in the cache.
   *
   * @param key - The key to check.
   * @returns `true` if the key exists, otherwise `false`.
   */
  has(key: K): boolean {
    return this.store.has(key);
  }

  /**
   * Removes `key` and its associated value from the cache.
   *
   * @param key - The key to remove.
   * @returns `true` if the key existed and was removed, otherwise `false`.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }
}
