```typescript
/**
 * A small in-memory key/value cache with optional time-to-live (TTL)
 * and a maximum number of entries.
 *
 * Entries expire lazily: an expired entry is treated as missing the next
 * time it is accessed, and is removed at that point.
 *
 * @example
 * const cache = new Cache<string>({ ttlMs: 5_000, maxSize: 100 });
 * cache.set('user:1', 'alice');
 * cache.get('user:1'); // 'alice'
 * cache.has('user:1'); // true
 * cache.delete('user:1');
 */
export class Cache<V> {
  private readonly store = new Map<string, { value: V; expiresAt: number | null }>();
  private readonly ttlMs: number | null;
  private readonly maxSize: number | null;

  /**
   * @param options.ttlMs   Default time-to-live in milliseconds for entries.
   *                        `null` (default) means entries never expire.
   * @param options.maxSize Maximum number of entries. When exceeded, the
   *                        oldest inserted entry is evicted (FIFO).
   *                        `null` (default) means unbounded.
   */
  constructor(options: { ttlMs?: number | null; maxSize?: number | null } = {}) {
    this.ttlMs = options.ttlMs ?? null;
    this.maxSize = options.maxSize ?? null;
  }

  /**
   * Retrieve the value for `key`.
   * @returns The stored value, or `undefined` if the key is missing or expired.
   */
  get(key: string): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt !== null && entry.expiresAt <= Date.now()) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Store `value` under `key`.
   * @param key   The cache key.
   * @param value The value to store.
   * @param ttlMs Optional per-entry TTL, overriding the cache default.
   *              Pass `null` to store without expiry.
   */
  set(key: string, value: V, ttlMs?: number | null): void {
    const ttl = ttlMs === undefined ? this.ttlMs : ttlMs;
    const expiresAt = ttl === null ? null : Date.now() + ttl;

    // Re-insert to refresh insertion order for FIFO eviction.
    this.store.delete(key);
    this.store.set(key, { value, expiresAt });

    if (this.maxSize !== null && this.store.size > this.maxSize) {
      const oldest = this.store.keys().next().value;
      if (oldest !== undefined) this.store.delete(oldest);
    }
  }

  /**
   * Check whether a non-expired entry exists for `key`.
   */
  has(key: string): boolean {
    return this.get(key) !== undefined;
  }

  /**
   * Remove the entry for `key`.
   * @returns `true` if an entry was removed, `false` if the key was absent.
   */
  delete(key: string): boolean {
    return this.store.delete(key);
  }
}
