/** Options accepted by the {@link Cache} constructor. */
export interface CacheOptions {
  /**
   * Default lifetime of an entry, in milliseconds.
   * `Infinity` (the default) means entries never expire.
   */
  ttl?: number;
  /**
   * Maximum number of entries to keep. When the limit is exceeded the oldest
   * entry is evicted (FIFO). `Infinity` (the default) means no limit.
   */
  maxSize?: number;
}

/**
 * A small in-memory key/value cache with optional TTL and size limits.
 *
 * @typeParam K - Key type. Defaults to `string`.
 * @typeParam V - Value type. Defaults to `unknown`.
 *
 * @example
 * const cache = new Cache<string, number>({ ttl: 5_000, maxSize: 100 });
 * cache.set('answer', 42);
 * cache.get('answer'); // 42
 * cache.has('answer'); // true
 * cache.delete('answer'); // true
 */
export class Cache<K = string, V = unknown> {
  readonly #entries = new Map<K, { value: V; expiresAt: number }>();
  readonly #ttl: number;
  readonly #maxSize: number;

  constructor({ ttl = Infinity, maxSize = Infinity }: CacheOptions = {}) {
    this.#ttl = ttl;
    this.#maxSize = maxSize;
  }

  /**
   * Returns the value stored under `key`, or `undefined` if it is missing or
   * expired. Expired entries are removed as a side effect.
   *
   * Note: a stored `undefined` value is indistinguishable from a miss.
   */
  get(key: K): V | undefined {
    const entry = this.#entries.get(key);
    if (entry === undefined) return undefined;
    if (entry.expiresAt <= Date.now()) {
      this.#entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Stores `value` under `key`.
   *
   * @param ttl - Optional per-entry lifetime in milliseconds, overriding the
   *              cache default. `Infinity` means the entry never expires.
   * @returns `this`, so calls can be chained.
   */
  set(key: K, value: V, ttl: number = this.#ttl): this {
    // Re-insert so the key becomes the most recently added (FIFO eviction order).
    this.#entries.delete(key);
    this.#entries.set(key, { value, expiresAt: Date.now() + ttl });

    if (this.#entries.size > this.#maxSize) {
      const oldest = this.#entries.keys().next();
      if (!oldest.done) this.#entries.delete(oldest.value);
    }
    return this;
  }

  /** Returns `true` if a non-expired entry exists for `key`. */
  has(key: K): boolean {
    const entry = this.#entries.get(key);
    if (entry === undefined) return false;
    if (entry.expiresAt <= Date.now()) {
      this.#entries.delete(key);
      return false;
    }
    return true;
  }

  /** Removes `key`. Returns `true` if an entry was actually removed. */
  delete(key: K): boolean {
    return this.#entries.delete(key);
  }

  /**
   * Number of stored entries, including any that have expired but have not yet
   * been purged by a `get`/`has` call.
   */
  get size(): number {
    return this.#entries.size;
  }

  /** Removes every entry. */
  clear(): void {
    this.#entries.clear();
  }
}
