/**
 * A small in-memory key/value cache.
 *
 * Entries may expire (TTL) and the cache may be capped at a maximum size.
 * Eviction is insertion-ordered (FIFO), not LRU.
 *
 * @example
 * const cache = new Cache({ defaultTtl: 60_000, maxSize: 500 });
 * cache.set('user:1', { name: 'Ada' });
 * cache.get('user:1'); // => { name: 'Ada' }
 * cache.set('token', 'abc', 5_000); // expires in 5s
 */
class Cache {
  #store = new Map();
  #defaultTtl;
  #maxSize;

  /**
   * @param {object} [options]
   * @param {number} [options.defaultTtl=0] Default entry lifetime in ms. `0` means "never expires".
   * @param {number} [options.maxSize=Infinity] Max entries kept; oldest inserted are evicted first.
   */
  constructor({ defaultTtl = 0, maxSize = Infinity } = {}) {
    if (!(defaultTtl >= 0)) throw new RangeError('defaultTtl must be >= 0');
    if (!(maxSize > 0)) throw new RangeError('maxSize must be > 0');
    this.#defaultTtl = defaultTtl;
    this.#maxSize = maxSize;
  }

  /** Number of entries currently stored (expired entries are only purged on access). */
  get size() {
    return this.#store.size;
  }

  /**
   * Read a value.
   * Expired entries are removed and reported as missing.
   *
   * @param {*} key
   * @returns {*} The stored value, or `undefined` if absent or expired.
   */
  get(key) {
    const entry = this.#store.get(key);
    if (entry === undefined) return undefined;
    if (this.#isExpired(entry)) {
      this.#store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Store a value, overwriting any existing entry for `key`.
   *
   * @param {*} key
   * @param {*} value
   * @param {number} [ttl] Lifetime in ms for this entry. Defaults to the cache's `defaultTtl`.
   *   `0` means "never expires".
   * @returns {this} The cache, for chaining.
   */
  set(key, value, ttl = this.#defaultTtl) {
    // Delete first so re-setting a key refreshes its insertion order.
    this.#store.delete(key);
    this.#store.set(key, {
      value,
      expiresAt: ttl > 0 ? Date.now() + ttl : 0,
    });
    this.#evictOverflow();
    return this;
  }

  /**
   * Check whether a live (non-expired) entry exists, without reading its value.
   *
   * @param {*} key
   * @returns {boolean}
   */
  has(key) {
    const entry = this.#store.get(key);
    if (entry === undefined) return false;
    if (this.#isExpired(entry)) {
      this.#store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Remove an entry.
   *
   * @param {*} key
   * @returns {boolean} `true` if an entry was removed, `false` if the key was absent.
   */
  delete(key) {
    return this.#store.delete(key);
  }

  /** Remove every entry. */
  clear() {
    this.#store.clear();
  }

  #isExpired(entry) {
    return entry.expiresAt !== 0 && entry.expiresAt <= Date.now();
  }

  #evictOverflow() {
    while (this.#store.size > this.#maxSize) {
      this.#store.delete(this.#store.keys().next().value);
    }
  }
}
