 * Keys are compared using SameValueZero semantics (like Map), so object
 * keys are matched by reference, not by structural equality.
 *
 * @typeParam K - Type of the cache keys.
 * @typeParam V - Type of the cached values.
 */
export class Cache<K, V> {
  readonly #store = new Map<K, V>();

