/**
 * A small in-memory key/value cache with optional per-entry TTL.
 *
 * @example
 * const cache = new Cache<string>({ defaultTtlMs: 60_000 });
 * cache.set("user:1", "ada");
 * cache.get("user:1"); // "ada"
 * cache.has("user:1"); // true
 * cache.delete("user:1");
 */
export class Cache<V = unknown> {
  private store = new Map<string, { value: V; expiresAt: number | null }>();
  private readonly defaultTtlMs: number | null;

  /**
   * @param options.defaultTtlMs Default time-to-live in milliseconds for entries
   *   that don't specify their own. `null` means entries never expire.
   */
  constructor(options: { defaultTtlMs?: number | null } = {}) {
    this.defaultTtlMs = options.defaultTtlMs ?? null;
  }

  /**
   * Retrieve the value for a key.
   *
   * @param key The cache key.
   * @returns The cached value, or `undefined` if missing or expired.
   */
  get(key: string): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;

    if (entry.expiresAt !== null && entry.expiresAt <= Date.now()) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Store a value under a key, overwriting any existing entry.
   *
   * @param key The cache key.
   * @param value The value to store.
   * @param ttlMs Optional time-to-live in milliseconds. Overrides the
   *   instance default. Use `null` to store without expiration.
   */
  set(key: string, value: V, ttlMs?: number | null): void {
    const ttl = ttlMs === undefined ? this.defaultTtlMs : ttlMs;
    const expiresAt = ttl === null ? null : Date.now() + ttl;
    this.store.set(key, { value, expiresAt });
  }

  /**
   * Check whether a non-expired entry exists for a key.
   *
   * @param key The cache key.
   * @returns `true` if a live entry exists, otherwise `false`.
   */
  has(key: string): boolean {
    return this.get(key) !== undefined;
  }

  /**
   * Remove an entry from the cache.
   *
   * @param key The cache key.
   * @returns `true` if an entry was removed, `false` if the key was absent.
   */
  delete(key: string): boolean {
    return this.store.delete(key);
  }
}
```

A few notes on the design:

- **TTL is optional.** Without it the class is a trivial wrapper around `Map`, but expiry is the one feature almost every cache ends up needing, so it's included. `null` disables it per-entry or instance-wide.
- **Lazy expiration.** Expired entries are only evicted when touched by `get`/`has`. This avoids a background timer; if you want proactive cleanup, add a `prune()` method that iterates the map.
- **`has` reuses `get`.** This keeps the expiry logic in one place. The tradeoff is that `has` treats a stored `undefined` value as "absent" — if you need to distinguish those, store a sentinel or track presence separately.
- **Generic value type.** `new Cache<User>()` gives you typed reads; `new Cache()` defaults to `unknown`.

