 *
 * Entries are removed lazily: an expired entry is treated as absent by
 * `get` and `has`, and is physically removed the next time it is touched.
 *
 * @example
 * const cache = new Cache({ ttl: 60_000 }); // 1 minute default
 * cache.set('user:1', { name: 'Ada' });
 * cache.get('user:1'); // => { name: 'Ada' }
 */
