    /** @type {Map<string, { value: unknown, expiresAt: number }>} */
    this._store = new Map();
    this._defaultTtl = ttl;
  }

  /**
   * Retrieve a value.
   *
   * @param {string} key
   * @param {unknown} [fallback] Value returned if the key is missing or expired.
   * @returns {unknown} The stored value, or `fallback`.
   */
  get(key, fallback = undefined) {
    const entry = this._store.get(key);
    if (!entry) return fallback;
    if (this._isExpired(entry)) {
      this._store.delete(key);
      return fallback;
    }
    return entry.value;
  }

  /**
   * Store a value.
   *
   * @param {string} key
   * @param {unknown} value
   * @param {object} [options]
   * @param {number} [options.ttl] TTL in milliseconds for this entry.
   *   Defaults to the cache's `ttl`. Pass `Infinity` to never expire.
   * @returns {this} The cache, for chaining.
   */
  set(key, value, { ttl = this._defaultTtl } = {}) {
    this._store.set(key, {
      value,
      expiresAt: ttl === Infinity ? Infinity : Date.now() + ttl,
    });
    return this;
  }

  /**
   * Check whether a live (non-expired) entry exists.
   *
   * @param {string} key
   * @returns {boolean}
   */
  has(key) {
    const entry = this._store.get(key);
    if (!entry) return false;
    if (this._isExpired(entry)) {
      this._store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Remove an entry.
   *
   * @param {string} key
   * @returns {boolean} `true` if an entry was removed, `false` if none existed.
   */
  delete(key) {
    return this._store.delete(key);
  }

  /**
   * @private
   * @param {{ expiresAt: number }} entry
   * @returns {boolean}
   */
  _isExpired(entry) {
    return entry.expiresAt <= Date.now();
