 * cache.set('answer', 42);
 * cache.get('answer');    // 42
 * cache.has('answer');    // true
 * cache.delete('answer'); // true
 * cache.get('answer');    // undefined
 */
export class Cache<K, V> {
  private readonly store = new Map<K, { value: V; expiresAt: number | null }>();
  private readonly defaultTtl: number | null;

  /**
   * @param options.ttl - Default lifetime in milliseconds for entries that do
   *   not specify their own. `null` (the default) means entries never expire.
   */
  constructor(options: { ttl?: number | null } = {}) {
    this.defaultTtl = options.ttl ?? null;
  }

  /**
   * Returns the value stored under `key`, or `undefined` if the key is absent
   * or its entry has expired.
   *
   * Expired entries are deleted as a side effect.
   *
   * @param key - The key to look up.
   * @returns The stored value, or `undefined`.
   */
  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (entry === undefined) return undefined;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Stores `value` under `key`, overwriting any existing entry.
   *
   * @param key - The key to store under.
   * @param value - The value to store.
   * @param ttl - Optional lifetime in milliseconds for this entry only,
   *   overriding the cache's default TTL. Pass `null` to make this entry
   *   never expire. Omit to use the default TTL.
   * @returns This cache instance, for chaining.
   */
  set(key: K, value: V, ttl?: number | null): this {
    const lifetime = ttl === undefined ? this.defaultTtl : ttl;
    this.store.set(key, {
      value,
      expiresAt: lifetime === null ? null : Date.now() + lifetime,
    });
    return this;
  }

  /**
   * Returns `true` if a non-expired entry exists for `key`.
   *
   * Expired entries are deleted as a side effect.
   *
   * @param key - The key to check.
   * @returns Whether a live entry exists.
   */
  has(key: K): boolean {
    const entry = this.store.get(key);
    if (entry === undefined) return false;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry for `key`, if any. Works on expired entries too.
   *
   * @param key - The key to remove.
   * @returns `true` if an entry was removed, `false` if the key was absent.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }

  /** Removes all entries. */
  clear(): void {
    this.store.clear();
  }

  /**
   * Number of entries currently stored, including expired entries that have
   * not yet been lazily evicted.
   */
  get size(): number {
    return this.store.size;
  }

  private isExpired(entry: { expiresAt: number | null }): boolean {
    return entry.expiresAt !== null && entry.expiresAt <= Date.now();
  }
}
