```js
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries are attempted for:
 * - Network errors (e.g. DNS, connection reset, etc.)
 * - HTTP statuses: 408, 425, 429, and 5xx
 *
 * It does NOT retry:
 * - AbortError (when `options.signal` is aborted)
 * - Other 4xx responses (they are returned immediately)
 *
 * Backoff:
 *   delay = min(MAX_DELAY_MS, BASE_DELAY_MS * 2^attempt) + jitter
 * where `attempt` is 0 for the first retry. Jitter is 0-20% of the
 * exponential delay to avoid thundering herd.
 *
 * @param {RequestInfo | URL} url - The resource to fetch.
 * @param {RequestInit} [options={}] - Fetch options. `options.signal` is respected.
 * @param {number} [retries=3] - Number of retries after the initial attempt. Must be >= 0.
 * @returns {Promise<Response>} The final Response. If the final response is retryable and retries are exhausted, an Error is thrown with a `response` property.
 * @throws {TypeError} If `retries` is not a non-negative integer.
 * @throws {Error} If all attempts fail due to network errors or retryable HTTP statuses.
 *
 * @example
 * const res = await fetchWithRetry('/api/data', { headers: { Accept: 'application/json' } }, 3);
 * if (!res.ok) {
 *   // handle non-retryable HTTP error (e.g. 404)
 * }
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError('`retries` must be a non-negative integer');
  }

  options = options || {};

  const BASE_DELAY_MS = 300;
  const MAX_DELAY_MS = 10_000;
  const JITTER_RATIO = 0.2; // 0-20% random jitter

  const maxAttempts = retries + 1;
  let lastError;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success or non-retryable HTTP status: return immediately.
      if (response.ok || !isRetryableStatus(response.status)) {
        return response;
      }

      // Retryable HTTP status.
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      lastError.response = response;
    } catch (error) {
      // Do not retry aborts.
      if (error.name === 'AbortError') {
        throw error;
      }

      lastError = error;
    }

    // If this was the last attempt, throw the last error.
    if (attempt === maxAttempts - 1) {
      throw lastError;
    }

    // Wait before the next attempt.
    const exponentialDelay = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * 2 ** attempt);
    const jitter = Math.random() * exponentialDelay * JITTER_RATIO;
    const delay = Math.min(MAX_DELAY_MS, exponentialDelay + jitter);
    await sleep(delay, options.signal);
  }

  // Unreachable, but keeps TypeScript/Flow happy.
  throw lastError;
}

/**
 * Returns true if the HTTP status code is considered retryable.
 * @param {number} status
 * @returns {boolean}
 */
function isRetryableStatus(status) {
  return (
    status === 408 || // Request Timeout
    status === 425 || // Too Early
    status === 429 || // Too Many Requests
    (status >= 500 && status <= 599) // Server errors
  );
}

/**
 * Sleep for `ms` milliseconds, but reject early if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createAbortError());
      return;
    }

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(createAbortError());
    }

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Create an AbortError in a cross-environment way.
 * @returns {Error}
 */
function createAbortError() {
  if (typeof DOMException !== 'undefined') {
    return new DOMException('Aborted', 'AbortError');
  }
  const error = new Error('Aborted');
  error.name = 'AbortError';
  return error;
}
```

**How it works**

- `retries` is the number of retries *after* the initial attempt.  
  `retries = 3` means up to 4 total attempts.
- Retries happen on network errors and retryable HTTP statuses (`408`, `425`, `429`, `5xx`).
- Non-retryable HTTP errors (e.g. `404`, `401`) are returned immediately so the caller can inspect `response.ok` / `response.status`.
- Backoff uses `300ms * 2^attempt` with a `10s` cap and up to 20% random jitter.
- If `options.signal` is aborted, the function stops immediately and throws an `AbortError`.
- If all attempts fail, the last error is thrown. For retryable HTTP statuses, the thrown error has a `response` property attached.

# `fetchWithRetry`

A resilient wrapper around `fetch` that retries failed requests using exponential backoff with jitter. It handles transient network failures and retryable HTTP status codes (5xx, 408, 429) while respecting `Retry-After` headers when present.

```js
/**
 * Fetch a URL with automatic retries on failure using exponential backoff.
 *
 * Retries are triggered by:
 *   - Network errors (e.g. DNS failure, connection reset, timeout)
 *   - HTTP 408 (Request Timeout), 429 (Too Many Requests), and 5xx responses
 *
 * Backoff delay for attempt `n` (0-indexed) is:
 *   delay = min(baseDelay * 2^n, maxDelay) + random jitter
 *
 * If the server sends a `Retry-After` header on a 429/503, that value is
 * used instead of the computed backoff.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. A `signal` may be supplied to cancel the
 *   entire operation (including in-flight retries); the internal timeout
 *   signal is combined with it.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first failure.
 *   Total attempts = retries + 1.
 *
 * @param {object} [config]
 *   Optional tuning parameters.
 * @param {number} [config.baseDelay=300]
 *   Initial backoff delay in milliseconds.
 * @param {number} [config.maxDelay=10000]
 *   Upper bound on any single backoff delay, in milliseconds.
 * @param {number} [config.timeout=10000]
 *   Per-attempt timeout in milliseconds. Set to 0 to disable.
 * @param {number[]} [config.retryOnStatus]
 *   Additional HTTP status codes to treat as retryable.
 * @param {(attempt: number, error: Error, delayMs: number) => void} [config.onRetry]
 *   Callback invoked before each retry sleep. Useful for logging/metrics.
 *
 * @returns {Promise<Response>}
 *   Resolves with the first successful (or non-retryable) `Response`.
 *   Rejects with the last error if all attempts fail.
 *
 * @throws {Error}
 *   Re-throws the final network error or a descriptive error for a
 *   non-ok response that survived all retries.
 *
 * @example
 * const res = await fetchWithRetry('/api/data', { headers: { ... } }, 5);
 * const json = await res.json();
 *
 * @example
 * // With cancellation
 * const controller = new AbortController();
 * fetchWithRetry('/api/slow', { signal: controller.signal }, 3);
 * setTimeout(() => controller.abort(), 5000);
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    timeout = 10_000,
    retryOnStatus = [],
    onRetry = () => {},
  } = config;

  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504, ...retryOnStatus]);
  const callerSignal = options.signal;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Per-attempt timeout signal, chained to the caller's signal.
    const attemptController = new AbortController();
    const timeoutId =
      timeout > 0
        ? setTimeout(() => attemptController.abort(new Error('Request timed out')), timeout)
        : null;

    const onAbort = () => attemptController.abort(callerSignal.reason);
    if (callerSignal) {
      if (callerSignal.aborted) onAbort();
      else callerSignal.addEventListener('abort', onAbort, { once: true });
    }

    try {
      const response = await fetch(url, { ...options, signal: attemptController.signal });

      // Non-retryable status — return as-is (including 4xx).
      if (!retryableStatuses.has(response.status)) return response;

      // Retryable status and no attempts left — return the response so the
      // caller can inspect the body / headers themselves.
      if (attempt === retries) return response;

      const retryAfter = parseRetryAfter(response.headers.get('Retry-After'));
      const delay =
        retryAfter ?? computeBackoff(attempt, baseDelay, maxDelay);

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      onRetry(attempt + 1, lastError, delay);
      await sleep(delay, callerSignal);
    } catch (err) {
      // Caller-initiated abort — do not retry.
      if (callerSignal?.aborted) throw err;

      lastError = err;

      // Out of attempts — surface the underlying error.
      if (attempt === retries) throw err;

      const delay = computeBackoff(attempt, baseDelay, maxDelay);
      onRetry(attempt + 1, err, delay);
      await sleep(delay, callerSignal);
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
      if (callerSignal) callerSignal.removeEventListener('abort', onAbort);
    }
  }

  // Unreachable, but keeps linters happy.
  throw lastError ?? new Error('fetchWithRetry failed');
}

/** Full-jitter exponential backoff, capped at `maxDelay`. */
function computeBackoff(attempt, baseDelay, maxDelay) {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  // Jitter in [0, exponential] to avoid thundering-herd sync.
  return Math.random() * exponential;
}

/** Parse a `Retry-After` header (seconds or HTTP date) into milliseconds. */
function parseRetryAfter(header) {
  if (!header) return null;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(header);
  if (Number.isNaN(date)) return null;
  return Math.max(0, date - Date.now());
}

/** Sleep that resolves early (and rejects) if the caller aborts. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const id = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(id);
      reject(signal.reason);
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Usage

```js
// Basic
const res = await fetchWithRetry('https://api.example.com/items', {}, 5);

// With logging
const res = await fetchWithRetry('/api/data', {}, 4, {
  baseDelay: 500,
  maxDelay: 8000,
  timeout: 5000,
  onRetry: (attempt, err, delay) =>
    console.warn(`Retry ${attempt} in ${delay | 0}ms — ${err.message}`),
});

// Cancel everything with an AbortController
const ac = new AbortController();
fetchWithRetry('/api/slow', { signal: ac.signal }, 3);
ac.abort();
```

## Design notes

- **Full-jitter backoff** (`random() * min(base * 2^n, max)`) is preferred over plain exponential backoff because it substantially reduces the chance of many clients retrying in lockstep after a service recovers.
- **`Retry-After` is honoured** for 429/503 responses, which is what well-behaved clients are expected to do.
- **Timeouts are per-attempt**, not per-call. A request that times out on attempt 1 gets a fresh timeout on attempt 2.
- **The caller's `AbortSignal` is never overwritten** — it's chained into a per-attempt controller, so cancellation propagates to `fetch` and to the backoff sleep.
- **Non-retryable responses (e.g. 400, 404) are returned, not thrown**, so the caller can handle them like a normal `fetch` response.

# `fetchWithRetry`

A robust wrapper around `fetch` that retries transient failures using **exponential backoff with jitter**. It retries on network errors and on HTTP status codes that are typically transient (`408`, `425`, `429`, `5xx`), and gives up immediately on other `4xx` responses.

```js
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries are attempted when:
 *   - The fetch itself throws (network error, DNS failure, CORS, etc.)
 *   - The response status is 408, 425, 429, or any 5xx
 *
 * Non-retryable responses (e.g. 400, 401, 403, 404) are returned as-is so
 * the caller can inspect `response.ok` / `response.status`.
 *
 * Backoff uses "full jitter": delay = random(0, base * 2^attempt), capped at
 * `maxDelay`. Jitter prevents the thundering-herd problem when many clients
 * retry at once.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. May include a custom `signal` for cancellation.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one.
 *   `retries = 0` means a single attempt with no retry.
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelay=300]
 *   Base delay in milliseconds. The first retry waits up to this long.
 * @param {number} [config.maxDelay=10_000]
 *   Upper bound on any single backoff delay, in milliseconds.
 * @param {(attempt: number, error: Error|Response) => void} [config.onRetry]
 *   Called before each retry with the 1-based attempt number and the
 *   error/response that triggered the retry. Useful for logging/metrics.
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (which may be non-OK if the status
 *   was non-retryable). Rejects if all retries are exhausted or the request
 *   is aborted.
 *
 * @throws {Error} If every attempt fails, the last error is thrown with a
 *   `.attempts` property indicating how many tries were made.
 * @throws {DOMException} If the caller's `AbortSignal` fires.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Authorization: `Bearer ${token}` } },
 *   5,
 *   { baseDelay: 500, onRetry: (n, err) => console.warn(`retry #${n}`, err) }
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    onRetry = null,
  } = config;

  const RETRYABLE_STATUS = new Set([408, 425, 429]);

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (options.signal?.aborted) {
      throw options.signal.reason ?? new DOMException("Aborted", "AbortError");
    }

    try {
      const response = await fetch(url, options);

      // Success or a non-retryable HTTP error → return to caller.
      const isRetryable =
        RETRYABLE_STATUS.has(response.status) || response.status >= 500;

      if (!isRetryable || attempt === retries) {
        return response;
      }

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      lastError.response = response;
    } catch (err) {
      // Abort errors should never be retried.
      if (err?.name === "AbortError") throw err;

      lastError = err;
      if (attempt === retries) break;
    }

    // Exponential backoff with full jitter, capped at maxDelay.
    const ceiling = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay = Math.random() * ceiling;

    if (onRetry) {
      try { onRetry(attempt + 1, lastError); } catch { /* ignore logger errors */ }
    }

    await sleep(delay, options.signal);
  }

  // All attempts exhausted.
  lastError.attempts = retries + 1;
  throw lastError;
}

/**
 * Sleep for `ms` milliseconds, but resolve early if `signal` aborts.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

## Design notes

**Why full jitter?** A fixed exponential delay (`base * 2^n`) causes every client that failed at the same moment to retry at the same moment. Randomizing the delay in `[0, ceiling]` spreads the load. If you prefer a gentler spread, use `delay = ceiling / 2 + Math.random() * ceiling / 2` (equal jitter).

**Which statuses are retried?**
- `408 Request Timeout`, `425 Too Early`, `429 Too Many Requests` — transient by spec.
- `5xx` — server-side failures that are often momentary.
- Everything else (including `4xx` like `401`, `404`) is returned to the caller, because retrying won't help and may waste quota.

**Abort handling.** The caller's `AbortSignal` is honored both during the fetch and during the backoff sleep, so `controller.abort()` cancels the whole operation immediately.

**Returning vs. throwing on non-OK.** The function returns the `Response` for non-retryable HTTP errors so the caller can decide what to do (e.g. parse an error body). It only throws for network errors or when retries are exhausted.

**`Retry-After` header.** For production use against rate-limited APIs, you may want to honor the `Retry-After` header on `429`/`503` responses instead of the computed backoff. That's a one-line addition inside the loop:

```js
const retryAfter = Number(response.headers.get("Retry-After"));
const delay = Number.isFinite(retryAfter) ? retryAfter * 1000 : /* jittered */;
```

```js
/**
 * Fetches a URL with automatic retries on transient failures using
 * exponential backoff (with jitter).
 *
 * A "failure" is either:
 *   1. A network-level error (DNS, connection reset, timeout, etc.)
 *   2. An HTTP response with status 408, 429, or 5xx.
 *
 * Non-retryable client errors (e.g. 400, 401, 403, 404) are returned
 * immediately so the caller can inspect `response.ok` / `response.status`.
 *
 * The backoff delay for attempt `n` (0-indexed) is:
 *
 *     delay = min(baseDelay * 2^n, maxDelay)   // exponential cap
 *     delay = delay * (0.5 + Math.random())    // full jitter in [0.5x, 1.5x]
 *
 * Jitter avoids the "thundering herd" problem when many clients retry
 * simultaneously after a shared outage.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard fetch options. The following extra fields are recognised:
 *     - `signal`      : AbortSignal — aborting cancels pending retries too.
 *     - `retryStatuses`: number[]   — override the default retryable statuses
 *                                     ([408, 429, 500, 502, 503, 504]).
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one.
 *   `retries = 0` means "try once, never retry".
 *
 * @param {object} [backoff={}]
 *   Backoff tuning:
 *     - `baseDelay` {number} — initial delay in ms (default: 300).
 *     - `maxDelay`  {number} — upper bound on delay in ms (default: 10_000).
 *
 * @returns {Promise<Response>}
 *   Resolves with the final Response. The Response may be a non-ok
 *   status (e.g. 404) if the status was not retryable.
 *
 * @throws {Error}
 *   Throws the last underlying error (network error or a `RetryError`
 *   wrapping a persistently-failing status) if every attempt fails.
 *   Throws `AbortError` immediately if the signal aborts.
 *
 * @example
 *   const res = await fetchWithRetry('/api/data', { signal }, 5);
 *   if (!res.ok) throw new Error(`HTTP ${res.status}`);
 *   const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, backoff = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
  } = backoff;

  const retryStatuses = new Set(
    options.retryStatuses ?? [408, 429, 500, 502, 503, 504]
  );

  // Strip our custom field so it isn't passed to fetch().
  const { retryStatuses: _ignored, ...fetchOptions } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (fetchOptions.signal?.aborted) {
      throw fetchOptions.signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      const response = await fetch(url, fetchOptions);

      if (!retryStatuses.has(response.status)) {
        return response; // success OR non-retryable error — hand it back
      }

      // Retryable status. Consume the body so the connection can be reused.
      // (Not strictly required in browsers, but polite and avoids leaks.)
      try { await response.body?.cancel(); } catch { /* ignore */ }

      lastError = new RetryError(
        `HTTP ${response.status} ${response.statusText} for ${url}`,
        response.status
      );
    } catch (err) {
      if (err.name === 'AbortError') throw err;
      lastError = err;
    }

    if (attempt === retries) break;

    const delay = computeDelay(attempt, baseDelay, maxDelay);
    await sleep(delay, fetchOptions.signal);
  }

  throw lastError;
}

/* ------------------------------------------------------------------ */

/** Computes the jittered exponential backoff for a given attempt. */
function computeDelay(attempt, baseDelay, maxDelay) {
  const exp = Math.min(baseDelay * 2 ** attempt, maxDelay);
  const jitter = 0.5 + Math.random(); // 0.5 .. 1.5
  return Math.min(exp * jitter, maxDelay);
}

/** Promise-based sleep that can be interrupted by an AbortSignal. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/** Error type used when all attempts returned a retryable HTTP status. */
export class RetryError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'RetryError';
    this.status = status;
  }
}
```

A few design notes worth highlighting:

- **What gets retried.** Network errors and the statuses in `retryStatuses` (default `408, 429, 5xx`). Real client errors like 401/404 are returned to the caller instead of being retried — retrying them wastes time and can lock accounts (e.g. auth throttling).
- **Jitter.** `0.5 + Math.random()` gives ±50% noise on top of the exponential delay, which is the "full jitter" strategy recommended by AWS. It's what keeps retries from synchronizing across clients.
- **AbortSignal.** If the caller aborts, both the in-flight `fetch` and any pending backoff timer reject immediately with an `AbortError` — no orphan timers.
- **`retries` semantics.** It's *additional* attempts, so `retries = 3` means at most 4 fetches total. This is the common convention, but make sure it's documented (it is).
- **Body draining.** When discarding a retryable response, we cancel the body stream so the underlying connection can be reused — this matters at high request volumes.
- **Return value.** The function returns the `Response` even for non-retryable failures. That keeps the caller in control of error handling (`if (!res.ok) …`) rather than forcing exceptions for expected HTTP statuses.

```js
/**
 * Fetch a URL, retrying transient failures with exponential backoff and jitter.
 *
 * Retries when:
 * - `fetch` rejects with a network error
 * - the response status is one of: 408, 425, 429, 500, 502, 503, 504
 *
 * Does not retry when:
 * - the request is aborted (`AbortError`)
 * - the response is a non-retryable HTTP error, e.g. 400, 401, 404
 *
 * Backoff:
 * - Uses exponential backoff: 300ms, 600ms, 1200ms, ...
 * - Applies full jitter: random delay between 0 and the exponential delay
 * - Respects the `Retry-After` header when present
 *
 * @param {string} url - URL to fetch.
 * @param {RequestInit} [options={}] - Standard `fetch` options.
 * @param {number} [retries=3] - Maximum retries after the initial attempt.
 * @returns {Promise<Response>} The final `Response`. If retries are exhausted
 *   on a retryable HTTP status, the last `Response` is returned.
 * @throws {Error} If all attempts fail with a network/abort error, or if aborted.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const maxRetries = Number.isFinite(retries)
    ? Math.max(0, Math.floor(retries))
    : 3;

  const retryableStatuses = new Set([
    408, // Request Timeout
    425, // Too Early
    429, // Too Many Requests
    500, // Internal Server Error
    502, // Bad Gateway
    503, // Service Unavailable
    504, // Gateway Timeout
  ]);

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (response.ok || !retryableStatuses.has(response.status)) {
        return response;
      }

      if (attempt === maxRetries) {
        return response;
      }

      // Free the body so the connection can be reused before retrying.
      try {
        await response.body?.cancel();
      } catch {
        // Ignore body cancellation errors.
      }

      await sleep(getBackoffDelay(attempt, response), options.signal);
    } catch (error) {
      if (error?.name === 'AbortError') {
        throw error;
      }

      if (attempt === maxRetries) {
        throw error;
      }

      await sleep(getBackoffDelay(attempt), options.signal);
    }
  }

  // Unreachable, but keeps linters/type-checkers happy.
  throw new Error('fetchWithRetry: exhausted retries');
}

/**
 * Calculates the delay before the next retry.
 *
 * @param {number} attempt - Zero-based retry attempt index.
 * @param {Response} [response] - Optional response, used for `Retry-After`.
 * @returns {number} Delay in milliseconds.
 */
function getBackoffDelay(attempt, response) {
  const baseDelayMs = 300;
  const maxDelayMs = 10_000;

  // Exponential backoff: 300ms, 600ms, 1200ms, ...
  const exponential = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);

  // Full jitter: randomize between 0 and the exponential delay.
  let delay = Math.random() * exponential;

  // Respect Retry-After when present.
  const retryAfter = response?.headers?.get('Retry-After');

  if (retryAfter) {
    const seconds = Number(retryAfter);

    if (Number.isFinite(seconds)) {
      delay = Math.max(delay, seconds * 1000);
    } else {
      const dateMs = Date.parse(retryAfter);

      if (Number.isFinite(dateMs)) {
        delay = Math.max(delay, dateMs - Date.now());
      }
    }
  }

  return Math.min(maxDelayMs, Math.max(0, delay));
}

/**
 * Sleeps for the given number of milliseconds.
 * Rejects with an `AbortError` if the provided signal is aborted.
 *
 * @param {number} ms - Milliseconds to sleep.
 * @param {AbortSignal} [signal] - Optional abort signal.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createAbortError());
      return;
    }

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(createAbortError());
    }

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Creates an AbortError-compatible error.
 *
 * @returns {Error}
 */
function createAbortError() {
  const error = new Error('Aborted');
  error.name = 'AbortError';
  return error;
}
```

Example usage:

```js
const response = await fetchWithRetry(
  'https://api.example.com/data',
  {
    method: 'GET',
    headers: { Accept: 'application/json' },
  },
  3
);

const data = await response.json();
```

If you want the function to throw when retries are exhausted on a retryable HTTP status, replace:

```js
if (attempt === maxRetries) {
  return response;
}
```

with something like:

```js
if (attempt === maxRetries) {
  throw new Error(`Request failed with status ${response.status}`);
}
```

# `fetchWithRetry`

A small utility that wraps `fetch` with retry-on-failure using exponential backoff and jitter. It retries on network errors and on server-side / rate-limit HTTP statuses (5xx and 429), but **not** on client errors like 404 or 400 — those are returned immediately since retrying won't help.

```js
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries on:
 *   - Network errors (DNS failure, connection refused, CORS, etc.)
 *   - HTTP 429 (Too Many Requests)
 *   - HTTP 5xx (Server errors)
 *
 * Does NOT retry on 4xx client errors other than 429, since those
 * represent a problem with the request itself, not a transient failure.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options (method, headers, body, signal, etc.).
 *   Note: if you pass a `signal` and it aborts, the retry loop will
 *   stop immediately and re-throw the abort error.
 *
 * @param {number} [retries=3]
 *   Maximum number of retry attempts AFTER the initial try.
 *   `retries = 0` means "try once, no retries".
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelayMs=300]
 *   Initial backoff delay. Doubles on each subsequent attempt.
 * @param {number} [config.maxDelayMs=10000]
 *   Upper bound on the backoff delay (before jitter).
 * @param {number} [config.jitter=0.3]
 *   Fraction of the delay to randomize, in [0, 1]. Helps avoid a
 *   thundering herd of synchronized clients. `0` disables jitter.
 * @param {(err: Error|Response, attempt: number) => boolean} [config.shouldRetry]
 *   Optional override deciding whether a given failure is retryable.
 *   Receives either the thrown Error or the non-OK Response, plus the
 *   current attempt number (0-indexed). Return `true` to retry.
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (which may be non-OK if retries
 *   were exhausted on a retryable status). Rejects if a network error
 *   persists after all retries, or if the request was aborted.
 *
 * @throws {Error}
 *   Throws the last encountered network error, or an AbortError if the
 *   provided signal was aborted.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Authorization: `Bearer ${token}` } },
 *   3,
 * );
 * if (!res.ok) console.error("gave up:", res.status);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelayMs = 300,
    maxDelayMs = 10_000,
    jitter = 0.3,
    shouldRetry = defaultShouldRetry,
  } = config;

  // Track the most recent failure so we can re-throw it if we run out of retries.
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success — return immediately, even if it's a 4xx we won't retry.
      if (response.ok || !shouldRetry(response, attempt)) {
        return response;
      }

      // Retryable HTTP status. Remember it and fall through to backoff.
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      lastError.response = response;
    } catch (err) {
      // Abort: don't retry, propagate immediately.
      if (err?.name === "AbortError") throw err;

      if (!shouldRetry(err, attempt)) throw err;
      lastError = err;
    }

    // If this was the last attempt, stop.
    if (attempt === retries) break;

    // Exponential backoff: base * 2^attempt, capped, then jittered.
    const expDelay = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
    const delay = applyJitter(expDelay, jitter);

    await sleep(delay, options.signal);
  }

  // Out of retries — surface the last failure.
  throw lastError ?? new Error("fetchWithRetry: unknown failure");
}

/**
 * Default retry predicate: retry 429 and 5xx responses.
 * @private
 */
function defaultShouldRetry(result) {
  if (result instanceof Response) {
    return result.status === 429 || (result.status >= 500 && result.status <= 599);
  }
  // Network / unknown errors are retryable by default.
  return true;
}

/**
 * Scale a delay by a random amount within +/- `jitter`.
 * @private
 */
function applyJitter(delayMs, jitter) {
  if (jitter <= 0) return delayMs;
  const delta = delayMs * jitter;
  return delayMs + (Math.random() * 2 - 1) * delta;
}

/**
 * Sleep for `ms`, but abort early if the given signal fires.
 * @private
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    };

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

## Design notes

**Backoff schedule** — with defaults (`baseDelayMs: 300`), attempts are spaced roughly `300ms → 600ms → 1200ms → …` capped at 10s, each perturbed by ±30% jitter. After `retries + 1` total attempts the function gives up.

**Jitter** — without it, many clients failing at the same moment retry in lockstep and hammer the server. The ±30% spread decorrelates them.

**Non-OK responses** — a 500 that exhausts retries resolves with the `Response` rather than rejecting, so callers can inspect `res.status` / `res.headers` if needed. If you'd rather reject on any non-OK result, wrap the call:

```js
const res = await fetchWithRetry(url, {}, 3);
if (!res.ok) throw new Error(`Request failed: ${res.status}`);
```

**Abort handling** — the `signal` is respected both during the request *and* during the backoff sleep, so cancelling is immediate rather than waiting out a multi-second delay.

**Customizing retry policy** — pass `shouldRetry` to retry on 404s (sometimes useful for eventually-consistent resources), or to bail early on specific network error codes:

```js
await fetchWithRetry(url, {}, 5, {
  shouldRetry: (result) =>
    result instanceof Response ? result.status === 503 : true,
});
```

**Idempotency warning** — retries are safe for `GET`/`HEAD`/`PUT`/`DELETE` but **not** for `POST` unless the server treats the request idempotently (e.g. via an idempotency key). A retried `POST` can create duplicate records if the first attempt actually succeeded but the response was lost.

# `fetchWithRetry`

A small utility that wraps `fetch` with automatic retries and exponential backoff. It's useful for flaky networks, rate-limited APIs, or transient server errors.

```js
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries are attempted when:
 *   - The network request throws (DNS failure, connection reset, timeout, etc.)
 *   - The response has a retryable HTTP status (408, 425, 429, or 5xx)
 *
 * Non-retryable responses (e.g. 400, 401, 404) are returned immediately so
 * the caller can inspect `response.ok` / `response.status` as usual.
 *
 * Backoff schedule (with default options):
 *   attempt 1 → immediate
 *   attempt 2 → ~200ms
 *   attempt 3 → ~400ms
 *   attempt 4 → ~800ms
 *   ...
 * Each delay is jittered by ±20% to avoid thundering-herd effects.
 *
 * If the server sends a `Retry-After` header (seconds or HTTP date), that
 * value is honored instead of the computed backoff.
 *
 * @param {string} url
 *   The URL to fetch. Passed straight to `fetch`.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. A `signal` is respected: if the caller aborts,
 *   the function stops retrying and rejects with the abort reason.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one.
 *   `retries = 0` means "try once, no retries".
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelayMs=200]
 *   Base delay in milliseconds. Delay for attempt `n` is
 *   `baseDelayMs * 2^(n-1)`, jittered by ±20%.
 * @param {number} [config.maxDelayMs=30_000]
 *   Upper bound on any single backoff delay.
 * @param {(err: Error|Response, attempt: number) => void} [config.onRetry]
 *   Called just before each retry. `err` is the thrown error or the
 *   retryable `Response`. `attempt` is 1-based (the attempt that just failed).
 *
 * @returns {Promise<Response>}
 *   Resolves with the first successful (or non-retryable) `Response`.
 *   Rejects with the last error if all attempts fail, or with the abort
 *   reason if the caller's `signal` fires.
 *
 * @throws {TypeError} If `url` is not a string.
 * @throws {RangeError} If `retries` is negative.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Authorization: `Bearer ${token}` } },
 *   5,
 *   { onRetry: (err, n) => console.warn(`retry #${n}`, err) }
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  if (typeof url !== "string") {
    throw new TypeError("fetchWithRetry: `url` must be a string");
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError("fetchWithRetry: `retries` must be a non-negative integer");
  }

  const {
    baseDelayMs = 200,
    maxDelayMs = 30_000,
    onRetry = null,
  } = config;

  const signal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException("Aborted", "AbortError");
    }

    try {
      const response = await fetch(url, options);

      // Success or a non-retryable status: hand it back to the caller.
      if (!isRetryableStatus(response.status)) {
        return response;
      }

      // Retryable status. If we're out of attempts, return the response
      // so the caller can decide what to do with it.
      if (attempt === retries) {
        return response;
      }

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      const delay = retryAfterMs(response) ?? backoffMs(attempt, baseDelayMs, maxDelayMs);
      onRetry?.(response, attempt + 1);
      await sleep(delay, signal);
    } catch (err) {
      // Abort errors should propagate immediately, not be retried.
      if (err?.name === "AbortError") throw err;

      lastError = err;
      if (attempt === retries) break;

      const delay = backoffMs(attempt, baseDelayMs, maxDelayMs);
      onRetry?.(err, attempt + 1);
      await sleep(delay, signal);
    }
  }

  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/** HTTP statuses that are worth retrying. */
function isRetryableStatus(status) {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

/**
 * Exponential backoff with ±20% jitter, capped at `maxDelayMs`.
 * `attempt` is 0-based: attempt 0 → baseDelay, attempt 1 → 2×base, etc.
 */
function backoffMs(attempt, baseDelayMs, maxDelayMs) {
  const raw = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
  const jitter = raw * 0.2 * (Math.random() * 2 - 1); // ±20%
  return Math.max(0, Math.round(raw + jitter));
}

/**
 * Parse a `Retry-After` header. Returns milliseconds, or `null` if absent
 * or unparseable. Supports both the delta-seconds and HTTP-date forms.
 */
function retryAfterMs(response) {
  const header = response.headers?.get?.("Retry-After");
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/** Promise-based sleep that rejects if the caller's signal aborts. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener?.("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener?.("abort", onAbort, { once: true });
  });
}
```

## Design notes

- **What gets retried.** Only transient failures: thrown network errors, `408`, `425`, `429`, and `5xx`. A `404` or `401` is returned to the caller immediately — retrying those just wastes time.
- **Backoff.** Doubling delay with ±20% jitter prevents many clients from retrying in lockstep after an outage. `Retry-After` from the server always wins when present.
- **Abort support.** If you pass a `signal`, aborting it stops the loop and rejects with the abort reason — including while sleeping between attempts.
- **Return vs. throw.** On the final attempt, a retryable HTTP response is *returned* (not thrown) so the caller can inspect `res.status` and `res.headers`. Only thrown errors (network failures) cause a rejection.
- **No dependencies.** Works in browsers, Node 18+, Deno, Bun, and edge runtimes.

## Quick usage

```js
// Simple
const res = await fetchWithRetry("https://api.example.com/items", {}, 4);

// With abort + progress logging
const ctrl = new AbortController();
setTimeout(() => ctrl.abort(), 10_000);

const res = await fetchWithRetry(
  "https://api.example.com/items",
  { signal: ctrl.signal },
  5,
  { baseDelayMs: 300, onRetry: (err, n) => console.log(`retry ${n}:`, err) }
);
```

