 *   after the first one. `retries = 0` means a single attempt.
 * @param {object} [config]
 * @param {number} [config.baseDelay=300] - Base delay in ms for backoff.
 * @param {number} [config.maxDelay=10_000] - Cap on the backoff delay.
 * @param {(attempt: number, error: Error|Response) => void} [config.onRetry]
 *   - Optional hook called before each retry. `attempt` is 1-indexed.
 * @returns {Promise<Response>} The successful `Response`.
 * @throws {Error} If all attempts fail, or if the request is aborted.
 *
 * @example
 * const res = await fetchWithRetry('/api/data', { method: 'GET' }, 5);
 * const json = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    onRetry = null,
  } = config;

  const signal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      const response = await fetch(url, options);

      // Success or non-retryable client error → return as-is.
      if (!isRetryableStatus(response.status)) {
        return response;
      }

      // Retryable HTTP status. If this was the last attempt, return it
      // so the caller can inspect the status/body themselves.
      if (attempt === retries) {
        return response;
      }

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      const retryAfter = parseRetryAfter(response.headers.get('Retry-After'));
      const delay = retryAfter ?? computeBackoff(attempt, baseDelay, maxDelay);

      onRetry?.(attempt + 1, response);
      await sleep(delay, signal);
    } catch (err) {
      // Abort errors should propagate immediately, not be retried.
      if (err?.name === 'AbortError') throw err;

      lastError = err;
      if (attempt === retries) break;

      const delay = computeBackoff(attempt, baseDelay, maxDelay);
      onRetry?.(attempt + 1, err);
      await sleep(delay, signal);
    }
