/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/** Statuses worth retrying: request timeout, rate limit, server errors. */
function isRetryableStatus(status) {
  return status === 408 || status === 429 || (status >= 500 && status <= 599);
}

/**
 * Exponential backoff with full jitter.
 * attempt 0 → ~[0, baseDelay)
 * attempt 1 → ~[0, 2*baseDelay)
 * attempt 2 → ~[0, 4*baseDelay) ... capped at maxDelay.
 */
function computeBackoff(attempt, baseDelay, maxDelay) {
  const exp = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return Math.random() * exp;
}

/** Parse a `Retry-After` header (seconds or HTTP date) into milliseconds. */
function parseRetryAfter(header) {
  if (!header) return null;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(header);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

/** Promise-based sleep that rejects if the signal aborts mid-wait. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Design notes

**Why full jitter?** A pure exponential backoff (`base * 2^n`) causes every client that failed at the same moment to retry at the same moment, hammering the server in synchronized waves. Randomizing the delay between `0` and the exponential cap spreads retries out.

**Why return the last retryable `Response` instead of throwing?** A 5xx response is still a valid HTTP response with a body and headers. Returning it lets the caller decide how to handle it (log, parse error body, etc.) rather than forcing them to catch an exception and lose the response.

**Why honor `Retry-After`?** When a server explicitly tells you how long to wait (common with 429 and 503), ignoring it is rude and can get you rate-limited harder.

**Abort handling.** The `AbortSignal` is threaded through both the `fetch` call and the backoff `sleep`, so a single `controller.abort()` cancels the entire retry loop — including any in-flight wait.

## Usage

```js
const controller = new AbortController();
setTimeout(() => controller.abort(), 30_000);

try {
  const res = await fetchWithRetry(
    'https://api.example.com/data',
    { signal: controller.signal },
    5,
    {
      baseDelay: 500,
      maxDelay: 8_000,
      onRetry: (attempt, errOrRes) =>
        console.warn(`Retry #${attempt}:`, errOrRes),
    }
  );
  if (!res.ok) throw new Error(`Gave up: HTTP ${res.status}`);
  return await res.json();
} catch (err) {
  console.error('Request failed permanently:', err);
}
```

