 *   const res = await fetchWithRetry(
 *     'https://api.example.com/data',
 *     { headers: { Authorization: `Bearer ${token}` } },
 *     5,
 *     { baseDelay: 500, onRetry: ({ attempt, delay }) =>
 *         console.warn(`retry #${attempt} in ${delay}ms`) }
 *   );
 *   if (!res.ok) throw new Error(`HTTP ${res.status}`);
 *   const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 30_000,
    onRetry = () => {},
  } = config;

  const signal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      const response = await fetch(url, options);

      // Success or non-retryable status: return as-is.
      if (!isRetryableStatus(response.status) || attempt === retries) {
        return response;
      }

      // Retryable status: fall through to backoff.
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      const delay = computeDelay(attempt, baseDelay, maxDelay);
      onRetry({ attempt: attempt + 1, response, delay });
      await sleep(delay, signal);
    } catch (err) {
      // Abort errors should propagate immediately, not be retried.
      if (err?.name === 'AbortError') throw err;

      lastError = err;

      if (attempt === retries) break;

      const delay = computeDelay(attempt, baseDelay, maxDelay);
      onRetry({ attempt: attempt + 1, error: err, delay });
      await sleep(delay, signal);
    }
  }

  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/** Status codes worth retrying: transient server / rate-limit errors. */
function isRetryableStatus(status) {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

/**
 * Exponential backoff with full jitter.
 * delay = min(maxDelay, baseDelay * 2^attempt) * random(0.5, 1.5)
 */
function computeDelay(attempt, baseDelay, maxDelay) {
  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  const jitter = 0.5 + Math.random(); // [0.5, 1.5)
  return Math.round(exponential * jitter);
}

/** Promise-based sleep that can be cancelled by an AbortSignal. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Design notes

- **What gets retried.** Only *transient* failures: network exceptions and the status codes `408`, `425`, `429`, and `5xx`. A `404` or `401` is returned to the caller immediately — retrying those just wastes time and can hammer a server that's already telling you "no".
- **Exponential backoff with jitter.** The delay doubles each attempt (`baseDelay * 2^attempt`) and is capped at `maxDelay`. A random multiplier in `[0.5, 1.5)` is applied so that many clients failing at the same moment don't all retry in lockstep.
- **Abort-aware.** If the caller passes an `AbortSignal`, both the fetch and the backoff sleep are cancelled immediately, and the abort reason is propagated rather than swallowed.
- **Observability.** The `onRetry` hook receives the attempt number, the error or response that triggered the retry, and the delay about to be applied — handy for logging or emitting metrics.
- **Return value.** On success (or a non-retryable status) you get the raw `Response`, so you can still inspect `res.ok`, `res.status`, and read the body yourself. On total failure you get the last error thrown.

## Usage

```js
try {
  const res = await fetchWithRetry(
    'https://api.example.com/items',
    { headers: { Accept: 'application/json' } },
    4, // up to 5 total attempts
    {
      baseDelay: 500,
      maxDelay: 10_000,
      onRetry: ({ attempt, delay, error, response }) =>
        console.warn(
          `retry ${attempt} in ${delay}ms`,
          error?.message ?? `HTTP ${response.status}`
        ),
    }
  );

  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  const data = await res.json();
  console.log(data);
} catch (err) {
  console.error('All attempts failed:', err);
}
```

> **Note:** `fetch` in Node.js 18+ and all modern browsers supports `AbortSignal`. If you need a per-attempt timeout, pass a signal created with `AbortSignal.timeout(ms)` — but be aware that once it fires, the whole retry loop will abort, so for per-attempt timeouts you'd want to create a fresh signal inside the loop.

# `fetchWithRetry`

A robust wrapper around `fetch` that retries transient failures using **exponential backoff with jitter**. It distinguishes between retryable errors (network failures, 5xx, 429) and non-retryable ones (4xx), and respects an optional `AbortSignal`.

```js
/**
 * Fetch a URL with automatic retries on transient failures.
 *
 * Retries are performed with exponential backoff plus full jitter:
 *
 *     delay = random(0, min(maxDelay, baseDelay * 2 ** attempt))
 *
 * Jitter is important: without it, many clients that fail at the same time
 * will retry in lockstep and hammer the server (the "thundering herd" problem).
 *
 * A failure is considered retryable when:
 *   - `fetch` itself rejects (DNS failure, connection reset, timeout, etc.)
 *   - The response status is 408 (Request Timeout)
 *   - The response status is 429 (Too Many Requests)
 *   - The response status is >= 500 (server error)
 *
 * Non-retryable responses (e.g. 400, 401, 404) are returned immediately so
 * the caller can inspect them.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. An optional `signal` is honored: if it aborts,
 *   the function stops retrying and rejects with the abort reason.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one. So
 *   `retries = 3` means up to 4 total requests.
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelay=300]
 *   Base delay in milliseconds for the first retry.
 * @param {number} [config.maxDelay=10_000]
 *   Upper bound on the computed backoff delay.
 * @param {(attempt: number, error: Error|Response) => void} [config.onRetry]
 *   Called before each retry with the 1-based attempt number and the
 *   error/response that triggered it. Useful for logging/metrics.
 *
 * @returns {Promise<Response>}
 *   Resolves with the first successful (or non-retryable) `Response`.
 *   Rejects if all attempts fail, or if the request is aborted.
 *
 * @throws {Error} If `retries` is negative or not a finite number.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Authorization: `Bearer ${token}` } },
 *   5,
 *   { baseDelay: 500, onRetry: (n, err) => console.warn("retry", n, err) }
 * );
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  if (!Number.isFinite(retries) || retries < 0) {
    throw new Error(`retries must be a non-negative finite number, got ${retries}`);
  }

  const {
    baseDelay = 300,
    maxDelay = 10_000,
    onRetry = () => {},
  } = config;

  const { signal } = options;

  /** Sleep that rejects immediately if the signal aborts. */
  const sleep = (ms) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);
      const id = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(id);
        reject(signal.reason);
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  /** Decide whether a response status warrants a retry. */
  const isRetryableStatus = (status) =>
    status === 408 || status === 429 || status >= 500;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (signal?.aborted) throw signal.reason;

    try {
      const response = await fetch(url, options);

      if (!isRetryableStatus(response.status)) {
        return response; // success or a client error we shouldn't retry
      }

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);

      // If this was the last attempt, return the response so the caller
      // can inspect the body/status themselves.
      if (attempt === retries) return response;
    } catch (err) {
      // Abort errors should propagate immediately, not be retried.
      if (err?.name === "AbortError") throw err;
      lastError = err;
      if (attempt === retries) throw err;
    }

    // Exponential backoff with full jitter.
    const cap = Math.min(maxDelay, baseDelay * 2 ** attempt);
    const delay = Math.random() * cap;

    onRetry(attempt + 1, lastError);
    await sleep(delay);
  }

  // Unreachable in practice, but keeps the type checker happy.
  throw lastError ?? new Error("fetchWithRetry: exhausted retries");
}
```

## Design notes

**Why full jitter?** `random(0, cap)` spreads retries uniformly across the window. Alternatives like `cap/2 + random(0, cap/2)` ("equal jitter") are also fine; full jitter tends to minimize contention.

**Why return the last 5xx response instead of throwing?** The caller usually wants to inspect the status and body (e.g. to log a server error). Throwing would hide that information. Network-level failures still throw, since there's no response to return.

**Abort handling.** The `sleep` helper listens for `abort` so a long backoff doesn't delay cancellation. `AbortError` is re-thrown immediately rather than retried — the caller asked us to stop.

**`retries` semantics.** It's the number of *additional* attempts, so `retries = 0` means "try once, no retries." This matches the intuition of most HTTP client libraries.

**What's not handled here.** This function doesn't parse `Retry-After` headers, doesn't cap total elapsed time, and doesn't deduplicate concurrent requests. If you need those, layer them on top or reach out to a library like `p-retry` or `got`.

# `fetchWithRetry`

A small utility that wraps `fetch` with automatic retries using **exponential backoff** and jitter. Useful for flaky networks, rate-limited APIs, and transient 5xx errors.

```js
/**
 * Fetch a URL, retrying on failure with exponential backoff and jitter.
 *
 * @param {string} url
 *   The URL to fetch. Passed straight to `fetch`.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options (method, headers, body, signal, ...).
 *
 * @param {number} [retries=3]
 *   Maximum number of *retry attempts* after the initial try.
 *   Total attempts = retries + 1.
 *
 * @param {object} [config]
 *   Optional tuning knobs (non-standard, stripped before calling `fetch`).
 * @param {number} [config.baseDelay=300]
 *   Base backoff delay in milliseconds. Attempt `n` waits
 *   `baseDelay * 2^n` ms (plus jitter), capped by `maxDelay`.
 * @param {number} [config.maxDelay=10_000]
 *   Upper bound on the delay between attempts, in milliseconds.
 * @param {(response: Response) => boolean} [config.shouldRetry]
 *   Predicate deciding whether an HTTP response should be retried.
 *   Defaults to retrying on 408, 425, 429, and 5xx.
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (which may itself be a non-ok
 *   response if `shouldRetry` said not to retry it). Rejects if all
 *   attempts fail or if a non-retryable error is thrown.
 *
 * @throws {Error}
 *   The last error encountered, augmented with `.attempts` (number of
 *   tries made) and, if applicable, the last `.response`.
 *
 * @example
 *   const res = await fetchWithRetry(
 *     "https://api.example.com/data",
 *     { headers: { Authorization: `Bearer ${token}` } },
 *     3,
 *   );
 *   const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    shouldRetry = defaultShouldRetry,
  } = config;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (!shouldRetry(response) || attempt === retries) {
        return response;
      }

      // Drain the body so the connection can be reused.
      try { await response.body?.cancel(); } catch { /* ignore */ }

      lastError = new Error(
        `Retryable HTTP ${response.status} ${response.statusText}`,
      );
      lastError.response = response;
    } catch (err) {
      // Network error, DNS failure, abort, etc.
      lastError = err;

      // Don't retry if the caller explicitly aborted.
      if (err?.name === "AbortError") throw err;
      if (attempt === retries) break;
    }

    await sleep(backoffDelay(attempt, baseDelay, maxDelay));
  }

  lastError ??= new Error("fetchWithRetry failed with no captured error");
  lastError.attempts = retries + 1;
  throw lastError;
}

/**
 * Default retry predicate: retry transient HTTP statuses.
 * @param {Response} response
 * @returns {boolean}
 */
function defaultShouldRetry(response) {
  // 408 Request Timeout, 425 Too Early, 429 Too Many Requests, 5xx Server Error.
  return (
    response.status === 408 ||
    response.status === 425 ||
    response.status === 429 ||
    (response.status >= 500 && response.status <= 599)
  );
}

/**
 * Compute the delay for a given attempt using exponential backoff
 * with "full jitter": a random value in [0, base * 2^attempt].
 *
 * @param {number} attempt Zero-based attempt index.
 * @param {number} base Base delay in ms.
 * @param {number} max Upper bound in ms.
 * @returns {number} Delay in milliseconds.
 */
function backoffDelay(attempt, base, max) {
  const exponential = Math.min(max, base * 2 ** attempt);
  return Math.random() * exponential;
}

/** @param {number} ms */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
```

## Design notes

- **Exponential backoff with full jitter.** The delay is `random(0, min(max, base * 2^attempt))`. This is the "full jitter" strategy from AWS's *Exponential Backoff and Jitter* — it prevents the thundering-herd problem when many clients retry at once.
- **Retry decision is pluggable.** `shouldRetry(response)` lets callers retry on custom statuses (e.g. treat `404` as retryable in some apps) or not retry at all.
- **Aborts are not retried.** An `AbortError` (typically a user-initiated cancellation via `AbortController`) is re-thrown immediately — retrying it would ignore the caller's intent.
- **Response body is cancelled** before retrying so the underlying HTTP connection can be released back to the pool.
- **Errors carry context.** The thrown error includes `.attempts` and, for HTTP failures, `.response` so callers can inspect the final status.

## Usage

```js
try {
  const res = await fetchWithRetry("/api/orders", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ sku: "abc", qty: 1 }),
  }, 4, { baseDelay: 500, maxDelay: 8_000 });

  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  console.log(await res.json());
} catch (err) {
  console.error(`Failed after ${err.attempts} attempts:`, err.message);
}
```

## Common pitfalls

- **Retrying non-idempotent requests.** POST/PATCH may create duplicate resources. Only enable retries on endpoints that are safe to repeat, or use an idempotency key.
- **Ignoring `Retry-After`.** For 429/503 responses, the server may send a `Retry-After` header. You can honor it inside a custom `shouldRetry`/delay policy if desired.
- **Unbounded backoff.** `maxDelay` caps the wait; without it, delays grow astronomically and the caller appears hung.

# `fetchWithRetry`

A robust wrapper around `fetch` that retries transient failures using exponential backoff with jitter.

## Design decisions

- **Retry only on transient errors.** Network errors, `5xx`, `408`, and `429` are retried. Other `4xx` responses (auth, validation, not-found) are returned immediately — retrying them is pointless and wastes time.
- **Exponential backoff with full jitter.** Delay is `base * 2^attempt`, then multiplied by a random `[0,1)` factor. Jitter prevents thundering-herd retries when many clients fail at once.
- **Respect `Retry-After`.** If the server tells us how long to wait, we honor it (capped at `maxDelay`).
- **Abort-aware.** An external `AbortSignal` cancels both the in-flight request and any pending backoff timer.
- **Non-2xx is not thrown** by default — you get the `Response` back (matching `fetch` semantics). Only network/abort errors throw.

## Implementation

```js
/**
 * Fetch a URL with automatic retries on transient failures.
 *
 * Retries are performed for:
 *   - Network errors (DNS failure, connection reset, etc.)
 *   - HTTP 408 (Request Timeout)
 *   - HTTP 425 (Too Early)
 *   - HTTP 429 (Too Many Requests)
 *   - HTTP 5xx (Server Error)
 *
 * All other 4xx responses are returned immediately without retrying.
 *
 * @param {string} url - The URL to fetch.
 * @param {RequestInit} [options={}] - Standard `fetch` options.
 *   May include an `AbortSignal` via `options.signal`.
 * @param {number} [retries=3] - Maximum number of *retries* (i.e. total
 *   attempts = retries + 1). Must be >= 0.
 * @param {object} [config] - Optional tuning knobs.
 * @param {number} [config.baseDelay=300] - Base delay in ms for backoff.
 * @param {number} [config.maxDelay=10000] - Max delay between attempts, ms.
 * @param {number} [config.factor=2] - Exponential growth factor.
 * @param {(attempt: number, err: unknown) => void} [config.onRetry]
 *   Called before each retry with the 1-based attempt number and the
 *   reason (an Error or a Response) that triggered the retry.
 * @param {typeof fetch} [config.fetchImpl=fetch] - Injectable fetch
 *   implementation (useful for testing / older Node versions).
 *
 * @returns {Promise<Response>} The final `Response` object. Non-2xx
 *   responses are returned, not thrown — matching `fetch` semantics.
 *
 * @throws {Error} If all retries are exhausted due to network errors, or
 *   if the request is aborted via the provided signal.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/things",
 *   { headers: { Authorization: `Bearer ${token}` } },
 *   5,
 *   { onRetry: (n, err) => console.warn(`retry #${n}`, err) },
 * );
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    factor = 2,
    onRetry = null,
    fetchImpl = fetch,
  } = config;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError("retries must be a non-negative integer");
  }

  const signal = options.signal;
  const throwIfAborted = () => {
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException("Aborted", "AbortError");
    }
  };

  /** Sleep that resolves early if the signal aborts. */
  const sleep = (ms) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason ?? new Error("Aborted"));
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason ?? new Error("Aborted"));
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  /** Compute the delay before the next attempt. */
  const backoff = (attempt, response) => {
    // Honor Retry-After if the server sent one (seconds or HTTP-date).
    const retryAfter = response?.headers?.get("retry-after");
    if (retryAfter) {
      const seconds = Number(retryAfter);
      const ms = Number.isFinite(seconds)
        ? seconds * 1000
        : Date.parse(retryAfter) - Date.now();
      if (Number.isFinite(ms) && ms > 0) return Math.min(ms, maxDelay);
    }
    // Exponential backoff with full jitter.
    const ceiling = Math.min(baseDelay * factor ** attempt, maxDelay);
    return Math.random() * ceiling;
  };

  /** Should we retry this response? */
  const isRetryableStatus = (status) =>
    status === 408 || status === 425 || status === 429 || status >= 500;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    throwIfAborted();

    try {
      const response = await fetchImpl(url, options);

      if (!isRetryableStatus(response.status)) {
        return response; // Success or non-retryable failure.
      }

      // Retryable HTTP status. If we're out of retries, return it.
      if (attempt === retries) return response;

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      onRetry?.(attempt + 1, response);
      await sleep(backoff(attempt, response));
    } catch (err) {
      // Abort should propagate immediately — never retry.
      if (err?.name === "AbortError" || signal?.aborted) throw err;

      lastError = err;
      if (attempt === retries) throw err;

      onRetry?.(attempt + 1, err);
      await sleep(backoff(attempt));
    }
  }

  // Unreachable, but keeps linters happy.
  throw lastError ?? new Error("fetchWithRetry: exhausted retries");
}
```

## Usage

```js
// Basic
const res = await fetchWithRetry("/api/data", {}, 3);

// With auth + jitter logging
const res = await fetchWithRetry(
  "https://api.example.com/orders",
  { method: "POST", headers: { "Content-Type": "application/json" }, body },
  5,
  {
    baseDelay: 500,
    maxDelay: 15_000,
    onRetry: (n, err) => console.warn(`[retry ${n}]`, err),
  },
);

// Cancellable
const ac = new AbortController();
setTimeout(() => ac.abort(), 5_000);
const res = await fetchWithRetry(url, { signal: ac.signal }, 3);
```

## Notes & trade-offs

- **No retry on `POST` by default?** The function retries any method. If your POST is not idempotent, pass a wrapper or check `options.method` before calling. A common pattern is to add an `Idempotency-Key` header and retry safely.
- **Full jitter** (uniform in `[0, ceiling]`) is used rather than "equal jitter" — it minimizes collisions under load and is the recommendation in AWS's *Exponential Backoff and Jitter* article.
- **`retry-after` is capped** at `maxDelay` so a misbehaving server can't stall you for an hour.
- **Non-2xx responses are returned**, not thrown, so callers can inspect `res.ok`/`res.status` — this matches `fetch` and avoids surprising control flow.

```js
/**
 * Fetch a URL and retry transient failures with exponential backoff + jitter.
 *
 * Retries when:
 *   - fetch rejects (network error, DNS failure, connection reset, etc.)
 *   - the response has a retryable HTTP status: 408, 425, 429, 500, 502, 503, 504
 *
 * Does not retry when:
 *   - the caller aborts via `options.signal` (AbortError is rethrown immediately)
 *   - the response has a non-retryable HTTP status (the error is thrown immediately)
 *
 * Note: If `options.body` is a stream, it may not be reusable across retries.
 *
 * @param {string | URL | Request} url
 *   Resource to fetch.
 * @param {RequestInit} [options={}]
 *   Standard fetch options. If `options.signal` aborts, retries stop.
 * @param {number} [retries=3]
 *   Number of retries after the initial attempt. Total attempts = retries + 1.
 * @returns {Promise<Response>}
 *   A successful (2xx) Response.
 * @throws {Error | DOMException}
 *   The last retryable error if all attempts fail, a non-retryable HTTP error,
 *   or an AbortError if aborted.
 *
 * @example
 * const res = await fetchWithRetry("/api/data", { headers: { Accept: "application/json" } }, 5);
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  options = options || {};

  const maxRetries = Number.isFinite(retries)
    ? Math.max(0, Math.floor(retries))
    : 3;

  const baseDelayMs = 300;
  const maxDelayMs = 10_000;

  let lastError;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (!response.ok) {
        const error = new Error(
          `HTTP ${response.status} ${response.statusText || ""}`.trim()
        );
        error.name = "HTTPError";
        error.response = response;
        error.retryable = isRetryableStatus(response.status);
        error.retryAfterMs = getRetryAfterMs(response);
        throw error;
      }

      return response;
    } catch (error) {
      lastError = error;

      // Caller aborted: do not retry.
      if (error?.name === "AbortError") {
        throw error;
      }

      // Non-retryable HTTP error: fail immediately.
      if (error?.retryable === false) {
        throw error;
      }

      const isLastAttempt = attempt === maxRetries;
      if (isLastAttempt) {
        break;
      }

      const backoffMs = getBackoffDelay(attempt, baseDelayMs, maxDelayMs);
      const retryAfterMs =
        typeof error?.retryAfterMs === "number" ? error.retryAfterMs : 0;

      await sleep(Math.max(backoffMs, retryAfterMs), options.signal);
    }
  }

  throw lastError;
}

/**
 * HTTP statuses that are usually safe/meaningful to retry.
 * @param {number} status
 * @returns {boolean}
 */
function isRetryableStatus(status) {
  return (
    status === 408 || // Request Timeout
    status === 425 || // Too Early
    status === 429 || // Too Many Requests
    status === 500 || // Internal Server Error
    status === 502 || // Bad Gateway
    status === 503 || // Service Unavailable
    status === 504    // Gateway Timeout
  );
}

/**
 * Parse a Retry-After header into milliseconds.
 * @param {Response} response
 * @returns {number} Milliseconds to wait, or 0 if not present/invalid.
 */
function getRetryAfterMs(response) {
  const header = response.headers.get("Retry-After");
  if (!header) return 0;

  const seconds = Number(header);
  if (Number.isFinite(seconds)) {
    return Math.max(0, seconds * 1000);
  }

  const date = Date.parse(header);
  if (!Number.isNaN(date)) {
    return Math.max(0, date - Date.now());
  }

  return 0;
}

/**
 * Exponential backoff with equal jitter.
 * attempt 0: 150–300ms, attempt 1: 300–600ms, attempt 2: 600–1200ms, ...
 * @param {number} attempt Zero-based retry attempt.
 * @param {number} baseDelayMs
 * @param {number} maxDelayMs
 * @returns {number} Delay in milliseconds.
 */
function getBackoffDelay(attempt, baseDelayMs, maxDelayMs) {
  const exponential = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
  const half = exponential / 2;
  return Math.floor(half + Math.random() * half);
}

/**
 * Sleep for `ms` milliseconds, but reject early if `signal` aborts.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createAbortError());
      return;
    }

    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(createAbortError());
    }

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * Create an AbortError in environments that lack DOMException.
 * @returns {Error}
 */
function createAbortError() {
  const error = new Error("Aborted");
  error.name = "AbortError";
  return error;
}
```

# `fetchWithRetry`

A robust wrapper around `fetch` that retries failed requests using **exponential backoff with jitter**. It handles both network errors and retryable HTTP status codes (408, 429, 5xx), and respects `Retry-After` headers when present.

```javascript
/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries are attempted on:
 *   - Network errors (fetch rejects)
 *   - HTTP 408 (Request Timeout)
 *   - HTTP 429 (Too Many Requests)
 *   - HTTP 5xx (Server Errors)
 *
 * Non-retryable responses (e.g. 4xx other than 408/429) are returned
 * immediately so callers can inspect the status themselves.
 *
 * Backoff delay for attempt `n` (0-indexed) is:
 *     baseDelay * 2^n  +  random jitter in [0, jitterMs)
 * capped at `maxDelay`. If the server sends a `Retry-After` header,
 * that value is honored instead (capped at `maxDelay`).
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options (method, headers, body, signal, ...).
 *   The `signal` is respected: aborting it stops retries immediately.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the initial one.
 *   `retries = 0` means a single attempt (no retry).
 *
 * @param {object} [config]
 *   Optional tuning parameters.
 * @param {number} [config.baseDelay=300]
 *   Base delay in milliseconds for the first retry.
 * @param {number} [config.maxDelay=30_000]
 *   Upper bound for any single backoff delay, in milliseconds.
 * @param {number} [config.jitterMs=100]
 *   Max random jitter added to each delay to avoid thundering herd.
 * @param {(attempt: number, error: Error) => void} [config.onRetry]
 *   Callback invoked before each retry. `attempt` is 1-based for the
 *   upcoming retry, `error` describes the previous failure.
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (either success or a non-retryable
 *   failure). Rejects only if all retries are exhausted or the request is
 *   aborted.
 *
 * @throws {Error} When retries are exhausted. The error carries:
 *   - `error.cause`  – the last underlying error or a synthetic HTTP error
 *   - `error.attempts` – total number of attempts made
 *
 * @example
 * const res = await fetchWithRetry('/api/data', { method: 'GET' }, 5);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 *
 * @example
 * // Abort from outside
 * const ctrl = new AbortController();
 * fetchWithRetry(url, { signal: ctrl.signal }, 3).catch(console.error);
 * setTimeout(() => ctrl.abort(), 5000);
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 30_000,
    jitterMs = 100,
    onRetry,
  } = config;

  const RETRYABLE_STATUSES = new Set([408, 429]);

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Respect external abort between attempts.
    if (options.signal?.aborted) {
      throw options.signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      const response = await fetch(url, options);

      const retryable =
        RETRYABLE_STATUSES.has(response.status) || response.status >= 500;

      if (!retryable || attempt === retries) {
        return response;
      }

      // Drain the body so the connection can be reused.
      try { await response.body?.cancel(); } catch { /* ignore */ }

      const delay = computeDelay(
        attempt,
        response.headers.get('Retry-After'),
        baseDelay,
        maxDelay,
        jitterMs,
      );

      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      onRetry?.(attempt + 1, lastError);
      await sleep(delay, options.signal);
    } catch (err) {
      // Abort errors should never be retried.
      if (err?.name === 'AbortError') throw err;

      lastError = err;

      if (attempt === retries) break;

      const delay = computeDelay(attempt, null, baseDelay, maxDelay, jitterMs);
      onRetry?.(attempt + 1, err);
      await sleep(delay, options.signal);
    }
  }

  const error = new Error(
    `fetchWithRetry failed after ${retries + 1} attempt(s): ${lastError?.message}`,
    { cause: lastError },
  );
  error.attempts = retries + 1;
  throw error;
}

/* ------------------------------------------------------------------ */

/**
 * Compute the backoff delay for a given attempt.
 * @private
 */
function computeDelay(attempt, retryAfterHeader, baseDelay, maxDelay, jitterMs) {
  // Prefer an explicit Retry-After (seconds or HTTP date).
  if (retryAfterHeader) {
    const seconds = Number(retryAfterHeader);
    if (Number.isFinite(seconds)) {
      return Math.min(seconds * 1000, maxDelay);
    }
    const date = Date.parse(retryAfterHeader);
    if (!Number.isNaN(date)) {
      return Math.min(Math.max(date - Date.now(), 0), maxDelay);
    }
  }

  const exponential = baseDelay * 2 ** attempt;
  const jitter = Math.random() * jitterMs;
  return Math.min(exponential + jitter, maxDelay);
}

/**
 * Promise-based sleep that can be cancelled via an AbortSignal.
 * @private
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Design notes

**What gets retried**
- Network-level failures (DNS, connection reset, TLS errors) — `fetch` throws.
- HTTP `408`, `429`, and any `5xx`.
- Everything else (e.g. `404`, `401`) is returned as-is, so callers can branch on `response.ok` without surprises.

**Backoff shape**

| Attempt | Base delay | With jitter (0–100 ms) |
|--------:|-----------:|-----------------------:|
| 1       | 300 ms     | 300–400 ms             |
| 2       | 600 ms     | 600–700 ms             |
| 3       | 1200 ms    | 1200–1300 ms           |
| 4       | 2400 ms    | 2400–2500 ms           |

Jitter prevents many clients from retrying in lockstep ("thundering herd"). `Retry-After` from the server always wins when present, clamped to `maxDelay` so a hostile header can't stall you for hours.

**Abort safety**
- If the caller's `signal` aborts mid-request, `fetch` rejects and we re-throw immediately (no retry).
- If it aborts during a backoff sleep, `sleep` rejects and we propagate the abort.
- Aborted requests never count as a "retryable" failure.

**Body draining**
When a retryable response comes back, we `cancel()` its body before retrying so the underlying socket can be reused instead of being held open until GC.

**Error contract**
On exhaustion you get a single `Error` whose `cause` is the last underlying failure and whose `attempts` property tells you how many tries were made — useful for telemetry or for distinguishing "server is down" from "URL is wrong".

**Not included (intentionally)**
- No request-body replay logic. If you pass a `ReadableStream` as `body`, it will be consumed by the first attempt and cannot be retried — pass a `string`, `Blob`, or `FormData` instead.
- No global concurrency limiting. Layer a semaphore on top if you need it.

# `fetchWithRetry`

A robust wrapper around `fetch` that retries failed requests using **exponential backoff with jitter**. It handles both network errors and retryable HTTP status codes (408, 429, 5xx), and respects the `Retry-After` header when present.

```js
/**
 * Fetch a URL, retrying on failure with exponential backoff.
 *
 * Retries are attempted when:
 *   - The fetch promise rejects (network error, DNS failure, CORS, etc.)
 *   - The response status is 408 (Timeout), 429 (Too Many Requests),
 *     or any 5xx (Server Error)
 *
 * Backoff schedule (base 300ms, capped at 10s, with ±30% jitter):
 *   attempt 1 (initial): immediate
 *   attempt 2: ~300ms
 *   attempt 3: ~600ms
 *   attempt 4: ~1200ms
 *   ...
 *
 * If the server sends a `Retry-After` header (seconds or HTTP date),
 * that value is honored instead of the computed backoff.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard fetch options (method, headers, body, signal, etc.).
 *   The `signal` is respected — an aborted request stops retrying.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the initial one.
 *   `retries = 0` means "try once, no retries".
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (which may be a non-ok status
 *   if all retries were exhausted on a retryable status code).
 *
 * @throws {Error}
 *   - The last network error, if all attempts rejected.
 *   - An `AbortError` if the caller's signal was aborted.
 *
 * @example
 * const res = await fetchWithRetry("/api/data", { method: "GET" }, 5);
 * if (!res.ok) console.error("Gave up with status", res.status);
 *
 * @example
 * // Cancellable
 * const ctrl = new AbortController();
 * fetchWithRetry("/slow", { signal: ctrl.signal }, 3).catch(console.error);
 * ctrl.abort();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const BASE_DELAY_MS = 300;
  const MAX_DELAY_MS  = 10_000;
  const RETRYABLE_STATUS = new Set([408, 429]);

  for (let attempt = 0; ; attempt++) {
    try {
      const response = await fetch(url, options);

      const shouldRetry =
        RETRYABLE_STATUS.has(response.status) || response.status >= 500;

      // Success (or non-retryable error) — return as-is.
      if (!shouldRetry || attempt >= retries) {
        return response;
      }

      const delay = getRetryDelay(response, attempt, BASE_DELAY_MS, MAX_DELAY_MS);
      await sleep(delay, options.signal);
    } catch (err) {
      // Never retry an explicit abort.
      if (err?.name === "AbortError") throw err;

      // Out of retries — propagate the last error.
      if (attempt >= retries) throw err;

      const delay = backoff(attempt, BASE_DELAY_MS, MAX_DELAY_MS);
      await sleep(delay, options.signal);
    }
  }
}

/**
 * Compute the delay before the next attempt.
 * Prefers the server's `Retry-After` header when present.
 *
 * @param {Response} response
 * @param {number} attempt     Zero-based attempt index (0 = initial).
 * @param {number} baseMs
 * @param {number} maxMs
 * @returns {number} Delay in milliseconds.
 */
function getRetryDelay(response, attempt, baseMs, maxMs) {
  const header = response.headers.get("Retry-After");
  if (header) {
    // Retry-After can be either a number of seconds or an HTTP date.
    const seconds = Number(header);
    if (Number.isFinite(seconds)) {
      return Math.min(seconds * 1000, maxMs);
    }
    const dateMs = Date.parse(header);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, Math.min(dateMs - Date.now(), maxMs));
    }
  }
  return backoff(attempt, baseMs, maxMs);
}

/**
 * Exponential backoff with full jitter, capped at `maxMs`.
 *
 * @param {number} attempt  Zero-based attempt index.
 * @param {number} baseMs
 * @param {number} maxMs
 * @returns {number} Delay in milliseconds.
 */
function backoff(attempt, baseMs, maxMs) {
  const exponential = Math.min(baseMs * 2 ** attempt, maxMs);
  // Full jitter: random value in [0.7 * exponential, 1.3 * exponential].
  const jitter = 0.7 + Math.random() * 0.6;
  return Math.round(exponential * jitter);
}

/**
 * Sleep for `ms` milliseconds, aborting early if `signal` fires.
 *
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(new DOMException("Aborted", "AbortError"));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
```

## Design notes

- **What gets retried.** Only failures that are *likely transient*: network rejections, `408`, `429`, and `5xx`. A `404` or `400` is returned immediately — retrying won't help.
- **Jitter.** The ±30% randomization prevents a "thundering herd" when many clients fail at once and would otherwise retry in lockstep.
- **`Retry-After` respect.** Servers under load often tell you exactly how long to wait. Honoring the header is both polite and more effective than guessing.
- **Abort-aware sleeps.** If the caller aborts mid-backoff, the promise rejects immediately instead of waiting out the timer.
- **Return vs. throw.** On a retryable HTTP status that survives all attempts, the final `Response` is returned (not thrown) so the caller can inspect `status`, headers, and body. Only network-level failures throw.
- **Tunable constants.** `BASE_DELAY_MS`, `MAX_DELAY_MS`, and `RETRYABLE_STATUS` are local to the function; promote them to parameters or a config object if you need per-call tuning.

# `fetchWithRetry`

A robust `fetch` wrapper that retries failed requests using **exponential backoff with jitter**. It only retries on network errors and retryable HTTP status codes (408, 429, 5xx), and respects the `Retry-After` header when present.

```javascript
/**
 * Fetches a URL with automatic retries on failure, using exponential backoff
 * with jitter between attempts.
 *
 * Retries are triggered by:
 *   - Network errors (e.g. DNS failure, connection reset, timeout)
 *   - HTTP 408 (Request Timeout)
 *   - HTTP 429 (Too Many Requests)
 *   - HTTP 5xx (Server errors)
 *
 * Non-retryable responses (e.g. 4xx other than 408/429) are returned as-is
 * so the caller can inspect them normally.
 *
 * @param {string} url
 *   The URL to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. Passed through unchanged to each attempt.
 *
 * @param {number} [retries=3]
 *   Maximum number of *retry* attempts after the initial request.
 *   Total attempts = retries + 1. Must be >= 0.
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelayMs=300]
 *   Base delay for the first retry. Subsequent delays grow exponentially:
 *   `baseDelayMs * 2^attempt`.
 * @param {number} [config.maxDelayMs=30000]
 *   Upper bound for any single backoff delay.
 * @param {number} [config.jitterMs=100]
 *   Random jitter (0..jitterMs) added to each delay to avoid thundering herd.
 * @param {(err: Error, attempt: number) => void} [config.onRetry]
 *   Called before each retry with the error/response that triggered it.
 *   `attempt` is the 1-based retry number.
 * @param {AbortSignal} [config.signal]
 *   Optional AbortSignal to cancel the entire operation (including backoff).
 *
 * @returns {Promise<Response>}
 *   Resolves with the final `Response` (successful or a non-retryable error
 *   response). Rejects if all retries are exhausted, if the network keeps
 *   failing, or if the operation is aborted.
 *
 * @throws {TypeError} If `url` is not a string or `retries` is negative.
 * @throws {Error} If all retry attempts fail.
 * @throws {DOMException} If the operation is aborted via `signal`.
 *
 * @example
 * const res = await fetchWithRetry(
 *   "https://api.example.com/data",
 *   { headers: { Authorization: "Bearer ..." } },
 *   3
 * );
 * const data = await res.json();
 *
 * @example
 * // With a timeout and custom backoff
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 10_000);
 * const res = await fetchWithRetry(url, { signal: controller.signal }, 5, {
 *   baseDelayMs: 500,
 *   maxDelayMs: 10_000,
 *   onRetry: (err, n) => console.warn(`Retry #${n}:`, err.message),
 * });
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  if (typeof url !== "string") {
    throw new TypeError("fetchWithRetry: 'url' must be a string");
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError("fetchWithRetry: 'retries' must be a non-negative integer");
  }

  const {
    baseDelayMs = 300,
    maxDelayMs = 30_000,
    jitterMs = 100,
    onRetry,
    signal,
  } = config;

  /** Sleep that respects the abort signal. */
  const sleep = (ms) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) {
        return reject(new DOMException("Aborted", "AbortError"));
      }
      const timer = setTimeout(() => {
        signal?.removeEventListener("abort", onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(new DOMException("Aborted", "AbortError"));
      };
      signal?.addEventListener("abort", onAbort, { once: true });
    });

  /** Decide whether a response should be retried. */
  const isRetryableStatus = (status) =>
    status === 408 || status === 429 || (status >= 500 && status <= 599);

  /**
   * Parse a `Retry-After` header (seconds or HTTP-date) into milliseconds.
   * Returns `null` if the header is absent or unparseable.
   */
  const parseRetryAfter = (response) => {
    const header = response.headers.get("Retry-After");
    if (!header) return null;
    const seconds = Number(header);
    if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
    const date = Date.parse(header);
    if (Number.isFinite(date)) return Math.max(0, date - Date.now());
    return null;
  };

  /** Compute the delay for a given retry attempt (0-based). */
  const computeDelay = (attempt, retryAfterMs) => {
    if (retryAfterMs != null) return Math.min(retryAfterMs, maxDelayMs);
    const exponential = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
    const jitter = Math.random() * jitterMs;
    return exponential + jitter;
  };

  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, { ...options, signal });

      if (!isRetryableStatus(response.status) || attempt === retries) {
        return response;
      }

      // Retryable HTTP error — decide how long to wait.
      const retryAfter = parseRetryAfter(response);
      const delay = computeDelay(attempt, retryAfter);
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      onRetry?.(lastError, attempt + 1);

      // Drain the body so the connection can be reused.
      await response.body?.cancel().catch(() => {});
      await sleep(delay);
    } catch (err) {
      // Abort should propagate immediately — no retry.
      if (err?.name === "AbortError") throw err;

      lastError = err;
      if (attempt === retries) break;

      const delay = computeDelay(attempt, null);
      onRetry?.(err, attempt + 1);
      await sleep(delay);
    }
  }

  throw lastError ?? new Error("fetchWithRetry: unknown failure");
}
```

## Design notes

**Why exponential backoff?** Each retry waits roughly twice as long as the previous one, giving a struggling server time to recover instead of hammering it. The delay is capped at `maxDelayMs` so it never grows unbounded.

**Why jitter?** If many clients fail at the same instant, they'd all retry at the same instant too (a "thundering herd"). Adding `Math.random() * jitterMs` spreads them out.

**Why honor `Retry-After`?** For 429/503, servers often tell you exactly how long to wait. Trusting that header is more polite than guessing.

**What gets retried?**
- ✅ Network errors (fetch rejects)
- ✅ `408`, `429`, `5xx`
- ❌ `4xx` (client errors — retrying won't help)
- ❌ `AbortError` (caller asked us to stop)

**Cancellation.** The `signal` is passed to both `fetch` and the internal `sleep`, so an abort interrupts an in-flight request *or* an in-progress backoff.

**Body draining.** When a retryable response is discarded, we cancel its body to free the underlying connection back to the pool.

## Usage

```js
// Basic
const res = await fetchWithRetry("/api/items", {}, 3);

// With a 10-second overall timeout and observability
const controller = new AbortController();
const timer = setTimeout(() => controller.abort(), 10_000);

try {
  const res = await fetchWithRetry(
    "/api/items",
    { method: "POST", body: JSON.stringify(payload) },
    5,
    {
      baseDelayMs: 500,
      maxDelayMs: 15_000,
      signal: controller.signal,
      onRetry: (err, n) => console.warn(`retry ${n}: ${err.message}`),
    }
  );
  console.log(await res.json());
} finally {
  clearTimeout(timer);
}
```

> ⚠️ **Idempotency warning:** only retry non-idempotent requests (POST/PATCH) if the server is idempotent or you're passing an idempotency key. Otherwise a retry can create duplicate resources.

