  for (let attempt = 0; attempt <= retries; attempt++) {
    throwIfAborted(signal);

    try {
      const response = await fetch(url, options);

      // Success, or a client error we shouldn't retry.
      if (!shouldRetryResponse(response)) {
        return response;
      }

      // Out of retries — hand the last response back to the caller.
      if (attempt === retries) return response;

      const delayMs = computeDelay(attempt, response, baseDelayMs, maxDelayMs);
      onRetry({ attempt, error: response, delayMs });
      await sleep(delayMs, signal);
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
    } catch (error) {
      // Abort must propagate immediately — never retry an aborted request.
      if (isAbortError(error)) throw error;

      if (attempt === retries) throw error;

      const delayMs = computeDelay(attempt, null, baseDelayMs, maxDelayMs);
      onRetry({ attempt, error, delayMs });
      await sleep(delayMs, signal);
      lastError = error;
    }
  }

  // Unreachable, but keeps the type-checker happy.
  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/**
 * Whether a `Response` represents a transient failure worth retrying.
 * 408 Request Timeout, 425 Too Early, 429 Too Many Requests, and any 5xx.
 */
function shouldRetryResponse(response) {
  if (response.status === 408 || response.status === 425 || response.status === 429) {
    return true;
  }
  return response.status >= 500 && response.status <= 599;
}

/**
 * Compute the backoff delay for the given attempt.
 *
 * Full-jitter exponential backoff:
 *   ceiling = min(maxDelayMs, baseDelayMs * 2^attempt)
 *   delay   = random integer in [0, ceiling]
 *
 * If the server sent a `Retry-After` header (seconds or HTTP date), that
 * value wins, capped at `maxDelayMs`.
 */
function computeDelay(attempt, response, baseDelayMs, maxDelayMs) {
  if (response) {
    const retryAfter = parseRetryAfter(response.headers.get("retry-after"));
    if (retryAfter != null) return Math.min(retryAfter, maxDelayMs);
  }
  const ceiling = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
  return Math.floor(Math.random() * ceiling);
}

/**
 * Parse a `Retry-After` header value into milliseconds.
 * Accepts either delta-seconds (`"120"`) or an HTTP-date.
 * Returns `null` if the header is missing or unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());
  return null;
}

/**
 * Sleep for `ms`, rejecting immediately if `signal` aborts.
 * Always clears the timer so we don't leak handles.
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? abortError());
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? abortError());
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

function throwIfAborted(signal) {
  if (signal?.aborted) throw signal.reason ?? abortError();
}

function abortError() {
  return new DOMException("The operation was aborted.", "AbortError");
}

function isAbortError(error) {
  return error?.name === "AbortError";
}
```

## Design notes

**Why full jitter instead of pure exponential backoff?**
If a backend goes down and 10,000 clients all start retrying on the same schedule, they will synchronize and hammer the server in waves. Randomizing each delay over `[0, ceiling]` spreads the load and dramatically reduces contention.

**Why not retry 4xx?**
A 400 or 404 will not become a 200 on the second attempt — retrying just wastes time and quota. The only 4xx we do retry are the ones that explicitly mean "try again later": 408, 425, and 429.

**Why return the final failing `Response` rather than throw?**
It matches `fetch`'s contract: the caller decides whether a 500 body is meaningful. We only throw when the *transport* failed (network error, abort) — never because of a status code.

**Abort handling.**
Both the in-flight `fetch` and the backoff `sleep` are wired to the caller's `AbortSignal`. An abort during either phase rejects immediately with the signal's reason, so a user-initiated cancel never has to wait out a 30-second backoff timer.

## Usage

```js
const controller = new AbortController();
document.querySelector("#cancel").onclick = () => controller.abort();

try {
  const res = await fetchWithRetry(
    "/api/orders",
    {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ sku: "ABC-123", qty: 2 }),
      signal: controller.signal,
    },
    5, // up to 5 retries
    {
      baseDelayMs: 250,
      maxDelayMs: 10_000,
      onRetry: ({ attempt, error, delayMs }) =>
        console.warn(`retry #${attempt} in ${delayMs}ms`, error),
    },
  );

  if (!res.ok) {
    // Non-retryable client error — inspect the body.
    throw new Error(`Request failed: ${res.status}`);
  }
  return await res.json();
} catch (err) {
  if (err.name === "AbortError") return; // user cancelled
  throw err;
}
```

```js
/**
 * Fetches a URL with automatic retries and exponential backoff.
 *
 * On failure (network error, non-2xx response, or timeout), the function
 * waits before retrying, doubling the delay each attempt:
 *
 *   attempt 1 → immediate
 *   attempt 2 → ~100ms
 *   attempt 3 → ~200ms
 *   attempt 4 → ~400ms
 *   ...
 *
 * A small random jitter is added to each delay to avoid thundering-herd
 * problems when many clients retry at once.
 *
 * @param {string} url
 *   The resource to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options (method, headers, body, etc.).
 *   Two extra keys are supported:
 *     - `timeout` {number}  Per-attempt timeout in ms (default: 10_000).
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one fails.
 *   `retries = 0` means "try once, no retry".
 *
 * @param {object} [config={}]
 *   Optional tuning knobs.
 *     - `baseDelay` {number}  Initial backoff in ms (default: 100).
 *     - `maxDelay`  {number}  Cap on backoff delay in ms (default: 30_000).
 *     - `factor`    {number}  Backoff multiplier (default: 2).
 *     - `jitter`    {boolean} Add random jitter to delays (default: true).
 *     - `signal`    {AbortSignal} External abort signal.
 *     - `onRetry`   {(info: { attempt: number, error: Error, delay: number }) => void}
 *                 Called before each retry — useful for logging/metrics.
 *     - `shouldRetry` {(error: Error, response?: Response) => boolean}
 *                 Decide whether a given failure is retryable.
 *                 By default: retries on network errors, timeouts, 429, and 5xx.
 *
 * @returns {Promise<Response>}
 *   Resolves with the successful `Response`. Rejects with the last error
 *   (or `AbortError`) if all attempts fail.
 *
 * @example
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   { method: 'GET', timeout: 5000 },
 *   4,
 *   { onRetry: ({ attempt, delay }) => console.log(`retry #${attempt} in ${delay}ms`) }
 * );
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 100,
    maxDelay = 30_000,
    factor = 2,
    jitter = true,
    signal: externalSignal,
    onRetry,
    shouldRetry = defaultShouldRetry,
  } = config;

  const { timeout = 10_000, ...fetchOptions } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Combine external abort signal with per-attempt timeout.
    const controller = new AbortController();
    const onExternalAbort = () => controller.abort(externalSignal?.reason);
    if (externalSignal) {
      if (externalSignal.aborted) throw abortError(externalSignal.reason);
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
    const timeoutId = setTimeout(
      () => controller.abort(new DOMException('Timeout', 'TimeoutError')),
      timeout,
    );

    try {
      const response = await fetch(url, {
        ...fetchOptions,
        signal: controller.signal,
      });

      // Treat non-2xx as failure (except when caller opts out).
      if (!response.ok && shouldRetry(responseError(response), response)) {
        throw responseError(response);
      }

      return response;
    } catch (err) {
      lastError = err;

      // Never retry if the caller aborted.
      if (externalSignal?.aborted) throw err;

      const isLastAttempt = attempt === retries;
      if (isLastAttempt || !shouldRetry(err)) throw err;

      // Exponential backoff with optional jitter.
      const exp = Math.min(maxDelay, baseDelay * factor ** attempt);
      const delay = jitter ? Math.random() * exp : exp;

      onRetry?.({ attempt: attempt + 1, error: err, delay });

      await sleep(delay, externalSignal);
    } finally {
      clearTimeout(timeoutId);
      if (externalSignal) {
        externalSignal.removeEventListener('abort', onExternalAbort);
      }
    }
  }

  // Unreachable, but keeps the type checker happy.
  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

function defaultShouldRetry(error, response) {
  // Network / timeout errors → retry.
  if (error?.name === 'TimeoutError') return true;
  if (error instanceof TypeError) return true; // fetch network failure

  // HTTP status based retry.
  if (response) {
    if (response.status === 429) return true;       // rate limited
    if (response.status >= 500 && response.status < 600) return true; // server error
  }
  return false;
}

function responseError(response) {
  const err = new Error(`HTTP ${response.status} ${response.statusText}`);
  err.name = 'HTTPError';
  err.status = response.status;
  err.response = response;
  return err;
}

function abortError(reason) {
  return reason instanceof Error
    ? reason
    : new DOMException('Aborted', 'AbortError');
}

/**
 * Sleep that can be cancelled by an AbortSignal.
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortError(signal.reason));
    const id = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(id);
      reject(abortError(signal.reason));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

### Key design decisions

- **Exponential backoff with jitter.** Delay is `min(maxDelay, baseDelay * factor^attempt)`, then randomized. Jitter prevents synchronized retries from hammering a recovering server.
- **Per-attempt timeout.** Each attempt gets its own `AbortController`, so a slow request doesn't eat into the retry budget of the next one.
- **Composable cancellation.** An external `signal` can abort the whole operation, including the wait between retries.
- **Retry policy is pluggable.** `shouldRetry` defaults to "network errors, timeouts, 429, and 5xx" — override it if your API needs different rules.
- **Non-2xx responses throw.** The function returns only successful responses, so callers don't have to remember to check `response.ok`. (If you'd rather return the failing response instead, drop the `throw responseError(...)` line and just `return response`.)
- **`onRetry` hook.** Makes it trivial to wire in logging, metrics, or UI feedback without touching the retry logic.

### Usage

```js
try {
  const res = await fetchWithRetry(
    'https://api.example.com/data',
    { method: 'GET', timeout: 5000 },
    4, // up to 5 total attempts
    {
      baseDelay: 200,
      maxDelay: 10_000,
      onRetry: ({ attempt, delay }) =>
        console.warn(`retry #${attempt} in ${Math.round(delay)}ms`),
    },
  );
  const data = await res.json();
} catch (err) {
  console.error('Gave up:', err);
}
```

# `fetchWithRetry`

A small, dependency-free helper that wraps `fetch` with automatic retries and exponential backoff (plus jitter) for transient failures.

```js
/**
 * Fetch a URL with automatic retries on transient failures.
 *
 * Retries are attempted when:
 *   - The network request itself rejects (DNS failure, connection reset, etc.)
 *   - The server responds with a retryable status code (408, 425, 429, or any 5xx)
 *
 * Non-retryable responses (e.g. 4xx other than the ones above) are returned
 * immediately so the caller can inspect `response.ok` / `response.status`.
 *
 * Backoff uses exponential growth with full jitter:
 *   delay = random(0, min(maxDelay, baseDelay * 2 ** attempt))
 * Jitter helps avoid the "thundering herd" problem when many clients retry
 * at the same time.
 *
 * @param {string|URL} url
 *   The resource to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. May include a `signal` for cancellation; if the
 *   signal aborts, the function throws immediately without further retries.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the initial one. `retries: 0`
 *   means a single attempt (no retries).
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelay=300]
 *   Base delay in milliseconds for the first backoff.
 * @param {number} [config.maxDelay=10_000]
 *   Upper bound on any single backoff delay, in milliseconds.
 * @param {number[]} [config.retryStatuses=[408, 425, 429]]
 *   Additional non-5xx status codes that should trigger a retry.
 * @param {(info: {attempt: number, error: Error, delay: number}) => void} [config.onRetry]
 *   Callback invoked before each retry. Useful for logging/metrics.
 *
 * @returns {Promise<Response>}
 *   The final `Response`. Note that a retryable status code may still be
 *   returned if all attempts are exhausted — check `response.ok`.
 *
 * @throws {Error}
 *   If the final attempt fails at the network level, or if the request is
 *   aborted via `options.signal`.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {
 *   method: 'GET',
 *   headers: { Accept: 'application/json' },
 * }, 4);
 *
 * if (!res.ok) throw new Error(`Request failed: ${res.status}`);
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    retryStatuses = [408, 425, 429],
    onRetry = () => {},
  } = config;

  const isRetryableStatus = (status) =>
    status >= 500 || retryStatuses.includes(status);

  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      if (signal?.aborted) {
        return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      }
      const timer = setTimeout(() => {
        signal?.removeEventListener('abort', onAbort);
        resolve();
      }, ms);
      const onAbort = () => {
        clearTimeout(timer);
        reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      };
      signal?.addEventListener('abort', onAbort, { once: true });
    });

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    // Bail out early if the caller already aborted.
    if (options.signal?.aborted) {
      throw options.signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      const response = await fetch(url, options);

      if (!isRetryableStatus(response.status) || attempt === retries) {
        return response;
      }

      // Retryable status — decide when to try again.
      lastError = new Error(`Retryable HTTP status: ${response.status}`);

      // Honour `Retry-After` if the server provided one (seconds or HTTP date).
      const retryAfter = parseRetryAfter(response.headers.get('retry-after'));
      const backoff = jitteredBackoff(attempt, baseDelay, maxDelay);
      const delay = retryAfter != null ? Math.min(retryAfter, maxDelay) : backoff;

      onRetry({ attempt: attempt + 1, error: lastError, delay });
      await sleep(delay, options.signal);
    } catch (err) {
      // Aborts should not be retried.
      if (err?.name === 'AbortError') throw err;

      lastError = err;

      if (attempt === retries) break;

      const delay = jitteredBackoff(attempt, baseDelay, maxDelay);
      onRetry({ attempt: attempt + 1, error: err, delay });
      await sleep(delay, options.signal);
    }
  }

  throw lastError ?? new Error('fetchWithRetry: exhausted retries');
}

/**
 * Full-jitter exponential backoff:
 *   random(0, min(maxDelay, baseDelay * 2 ** attempt))
 *
 * @param {number} attempt  Zero-based attempt index.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @returns {number} Delay in milliseconds.
 */
function jitteredBackoff(attempt, baseDelay, maxDelay) {
  const ceiling = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return Math.random() * ceiling;
}

/**
 * Parse the `Retry-After` header. Supports both the delay-seconds form
 * (`Retry-After: 120`) and the HTTP-date form (`Retry-After: Wed, 21 Oct ...`).
 *
 * @param {string|null} header
 * @returns {number|null} Delay in milliseconds, or `null` if absent/invalid.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;

  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}
```

## Design notes

**What gets retried.** Only *transient* failures: network errors, `408/425/429`, and all `5xx`. A `404` or `401` is returned to the caller on the first attempt — retrying those would just waste time.

**Backoff shape.** `baseDelay * 2 ** attempt` gives the classic 300 ms → 600 ms → 1.2 s → 2.4 s curve. Full jitter (multiplying by `Math.random()`) spreads retries across the interval, which matters when many clients fail simultaneously.

**`Retry-After` support.** If the server tells us how long to wait (common with `429`), we respect it, capped at `maxDelay` so a hostile/buggy server can't stall us indefinitely.

**Cancellation.** The caller's `AbortSignal` is threaded through both the `fetch` call and the backoff sleep, so aborting cancels an in-flight request *or* a pending retry immediately, and aborts are never retried.

**Return value.** A `Response` is always returned on a successful round-trip, even if the final status is retryable — the caller decides what to do with it. Network-level failures throw after retries are exhausted.

## Usage examples

```js
// Basic
const res = await fetchWithRetry('/api/items');

// With a custom abort controller and logging
const controller = new AbortController();
const res = await fetchWithRetry(
  '/api/items',
  { signal: controller.signal },
  5,
  {
    baseDelay: 500,
    maxDelay: 15_000,
    onRetry: ({ attempt, error, delay }) =>
      console.warn(`Retry ${attempt} in ${Math.round(delay)}ms:`, error.message),
  },
);
```

## Tests worth writing

- Succeeds on the first try → no retries, no delay.
- Fails twice then succeeds → exactly two retries, delays grow.
- `500` on every attempt → throws after `retries + 1` calls.
- `404` → returned immediately, no retries.
- `429` with `Retry-After: 1` → waits ~1 s, not the exponential value.
- Aborting mid-backoff → rejects with `AbortError` and stops retrying.

# `fetchWithRetry`

A robust wrapper around `fetch` that retries transient failures using **exponential backoff with jitter**, while respecting `Retry-After` headers and abort signals.

```js
/**
 * Fetch a URL with automatic retries on transient failures.
 *
 * Retries use exponential backoff with full jitter:
 *   delay = random(0, min(maxDelay, baseDelay * 2^attempt))
 *
 * A response is considered retryable when:
 *   - The network request throws (DNS failure, connection reset, etc.)
 *   - The response status is 408, 425, 429, or >= 500
 *
 * Non-retryable responses (e.g. 400, 401, 404) are returned immediately so
 * the caller can handle them like a normal `fetch` response. If all retries
 * are exhausted, the last error or response is thrown/returned.
 *
 * @param {string|URL} url
 *   The resource to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard `fetch` options. Pass an `AbortSignal` via `options.signal` to
 *   cancel the operation; the signal is respected during backoff sleeps too.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first failure.
 *   `retries = 0` means "try once, no retries".
 *
 * @param {object} [config]
 *   Optional tuning knobs.
 * @param {number} [config.baseDelay=300]
 *   Initial backoff in milliseconds.
 * @param {number} [config.maxDelay=10_000]
 *   Upper bound for any single backoff delay, in milliseconds.
 * @param {number} [config.factor=2]
 *   Multiplier applied to the delay after each failed attempt.
 * @param {(attempt: number, errorOrResponse: Error|Response) => boolean} [config.shouldRetry]
 *   Custom predicate. Return `true` to retry, `false` to give up and return
 *   the response / throw the error.
 * @param {(info: {attempt: number, delay: number, error?: Error, response?: Response}) => void} [config.onRetry]
 *   Callback invoked before each backoff sleep. Useful for logging/metrics.
 *
 * @returns {Promise<Response>}
 *   The first non-retryable `Response`, or the final response after retries
 *   are exhausted. Throws if the last attempt produced a network error.
 *
 * @throws {Error} If the request ultimately fails after all retries.
 * @throws {DOMException} If the request is aborted via `options.signal`.
 *
 * @example
 * // Simple usage
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 *
 * @example
 * // With cancellation and custom logging
 * const controller = new AbortController();
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   { signal: controller.signal, headers: { Authorization: 'Bearer …' } },
 *   5,
 *   {
 *     baseDelay: 500,
 *     onRetry: ({ attempt, delay, response }) =>
 *       console.warn(`Retry ${attempt} in ${delay}ms (status ${response?.status})`),
 *   }
 * );
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const {
    baseDelay = 300,
    maxDelay = 10_000,
    factor = 2,
    shouldRetry = defaultShouldRetry,
    onRetry,
  } = config;

  let lastError;
  let lastResponse;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success or a non-retryable status — return it as-is.
      if (!shouldRetry(attempt, response)) {
        return response;
      }

      lastResponse = response;

      // Last attempt: no point sleeping, just return the response.
      if (attempt === retries) return response;

      const delay = computeDelay({ attempt, baseDelay, maxDelay, factor, response });
      onRetry?.({ attempt: attempt + 1, delay, response });
      await sleep(delay, options.signal);
    } catch (err) {
      // Abort errors should propagate immediately — do not retry.
      if (err?.name === 'AbortError') throw err;

      lastError = err;

      if (attempt === retries || !shouldRetry(attempt, err)) {
        throw err;
      }

      const delay = computeDelay({ attempt, baseDelay, maxDelay, factor });
      onRetry?.({ attempt: attempt + 1, delay, error: err });
      await sleep(delay, options.signal);
    }
  }

  // Unreachable in practice, but keeps the type checker happy.
  if (lastError) throw lastError;
  return lastResponse;
}

/* ------------------------------------------------------------------ */
/* Internal helpers                                                    */
/* ------------------------------------------------------------------ */

/** Statuses that are worth retrying. */
const RETRYABLE_STATUS = new Set([408, 425, 429]);

/**
 * Default retry policy: retry on network errors and transient HTTP statuses.
 * @param {number} _attempt
 * @param {Error|Response} errorOrResponse
 * @returns {boolean}
 */
function defaultShouldRetry(_attempt, errorOrResponse) {
  if (errorOrResponse instanceof Response) {
    return (
      RETRYABLE_STATUS.has(errorOrResponse.status) ||
      errorOrResponse.status >= 500
    );
  }
  return true; // network error
}

/**
 * Compute the next backoff delay, honoring `Retry-After` when present.
 * Uses full jitter to avoid thundering-herd effects.
 * @returns {number} milliseconds
 */
function computeDelay({ attempt, baseDelay, maxDelay, factor, response }) {
  const retryAfter = response?.headers?.get?.('Retry-After');
  if (retryAfter) {
    const seconds = Number(retryAfter);
    if (Number.isFinite(seconds)) {
      return Math.min(seconds * 1000, maxDelay);
    }
    const date = Date.parse(retryAfter);
    if (!Number.isNaN(date)) {
      return Math.max(0, Math.min(date - Date.now(), maxDelay));
    }
  }

  const exponential = baseDelay * Math.pow(factor, attempt);
  const capped = Math.min(exponential, maxDelay);
  return Math.floor(Math.random() * capped); // full jitter
}

/**
 * Promise-based sleep that can be interrupted by an AbortSignal.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Design notes

**Why full jitter?** A naïve exponential backoff makes every client retry in lockstep, which can DDoS a recovering service. `random(0, cappedDelay)` spreads retries out and is the strategy recommended by AWS's *Exponential Backoff and Jitter* paper.

**Retryable statuses.** `408` (timeout), `425` (too early), `429` (rate-limited), and all `5xx` are transient by convention. Everything else — including `404`, `401`, `422` — is returned to the caller immediately, since retrying won't help.

**`Retry-After` support.** When a server sends `Retry-After` (either seconds or an HTTP date), we honor it instead of our own backoff. This is what well-behaved clients do for `429`/`503`.

**Abort safety.** The `sleep` helper listens for the abort event and rejects immediately, so an `AbortController` can cancel a request even mid-backoff.

**Return vs. throw.** Network errors throw; HTTP errors return a `Response`. This mirrors `fetch`'s own contract, so callers can keep using `res.ok` / `res.status` checks.

## Implementation

```js
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * The returned object maps each distinct key to an array of the elements
 * that produced it. Keys are normalized to strings (or kept as symbols),
 * so `1` and `"1"` land in the same group.
 *
 * @template T
 * @param {readonly T[]} arr        The array to group. Not mutated.
 * @param {(item: T, index: number, array: readonly T[]) => unknown} keyFn
 *        Derives the group key for an element. Receives the element, its
 *        index, and the source array.
 * @returns {Record<string, T[]> & { [key: symbol]: T[] }}
 *          A null-prototype object mapping key -> array of matching elements.
 *          Groups appear in the order their keys were first encountered, and
 *          elements within a group keep their original relative order.
 *
 * @throws {TypeError} If `arr` is not an array, `keyFn` is not a function, or
 *         `keyFn` returns a value that cannot be used as an object key
 *         (e.g. a plain object).
 *
 * @example
 * groupBy([1, 2, 3, 4], n => n % 2 === 0 ? "even" : "odd");
 * // { odd: [1, 3], even: [2, 4] }
 *
 * @example
 * groupBy(users, u => u.department);
 * // { Engineering: [...], Sales: [...] }
 */
export function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError("groupBy: expected an array");
  }
  if (typeof keyFn !== "function") {
    throw new TypeError("groupBy: expected keyFn to be a function");
  }

  // A null prototype keeps inherited names ("toString", "constructor", ...)
  // out of the result and makes "__proto__" a safe, ordinary key.
  const groups = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = normalizeKey(keyFn(item, i, arr), i);

    const bucket = groups[key];
    if (bucket === undefined) {
      groups[key] = [item];
    } else {
      bucket.push(item);
    }
  }

  return groups;
}

/**
 * Converts a derived key into a valid property key.
 * Symbols are preserved; other primitives are stringified.
 *
 * @param {unknown} key
 * @param {number} index Index of the source element, used for error messages.
 * @returns {string | symbol}
 */
function normalizeKey(key, index) {
  if (typeof key === "symbol") return key;

  const type = typeof key;
  if (key === null || type === "undefined" || type === "string" ||
      type === "number" || type === "boolean" || type === "bigint") {
    return String(key);
  }

  throw new TypeError(
    `groupBy: keyFn must return a primitive (string, number, boolean, ` +
    `bigint, symbol, null or undefined); received ${type} at index ${index}. ` +
    `Use groupByMap() if you need object keys.`
  );
}
```

### Variant: preserve key identity with a `Map`

Use this when keys are objects, or when you need to distinguish `1` from `"1"`.

```js
/**
 * Like {@link groupBy}, but returns a `Map` so keys keep their original type
 * and identity (no string coercion).
 *
 * @template T, K
 * @param {readonly T[]} arr
 * @param {(item: T, index: number, array: readonly T[]) => K} keyFn
 * @returns {Map<K, T[]>}
 */
export function groupByMap(arr, keyFn) {
  if (!Array.isArray(arr)) throw new TypeError("groupByMap: expected an array");
  if (typeof keyFn !== "function") throw new TypeError("groupByMap: expected keyFn to be a function");

  const groups = new Map();
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const bucket = groups.get(key);
    if (bucket === undefined) groups.set(key, [item]);
    else bucket.push(item);
  }
  return groups;
}
```

## Usage

```js
const orders = [
  { id: 1, status: "paid",    total: 20 },
  { id: 2, status: "pending", total: 35 },
  { id: 3, status: "paid",    total: 10 },
];

const byStatus = groupBy(orders, o => o.status);
// byStatus.paid    -> [{ id: 1, ... }, { id: 3, ... }]
// byStatus.pending -> [{ id: 2, ... }]

// The result has no prototype, so use Object.hasOwn / Object.keys:
Object.hasOwn(byStatus, "toString"); // false
Object.keys(byStatus);                // ["paid", "pending"]

// Missing keys are simply absent:
byStatus.refunded;                    // undefined

// Symbols work as keys too:
const tagged = groupBy([1, 2, 3], n => Symbol.for(n % 2 ? "odd" : "even"));
tagged[Symbol.for("odd")];            // [1, 3]
```

## Behavior notes

| Situation | Behavior |
|---|---|
| `arr` is empty | Returns an empty object |
| `keyFn` returns `undefined` / `null` | Grouped under the string `"undefined"` / `"null"` |
| `keyFn` returns `1` vs `"1"` | Same group (both become `"1"`) |
| `keyFn` returns an object | Throws `TypeError` — use `groupByMap` instead |
| Key is `"__proto__"` | Treated as a normal key; no prototype pollution |
| Sparse array | Holes are visited as `undefined` elements |
| `arr` is mutated during the call | Not supported; snapshot the array first |

**Complexity:** O(n) time and O(n) space, with one pass over the input. Each `keyFn` call is made exactly once per element.

**Native alternative:** ES2024's `Object.groupBy(arr, keyFn)` does the same thing for string-coerced keys, but it silently stringifies object keys (`"[object Object]"`) instead of throwing, and it isn't available in older runtimes.

## `groupBy`

```js
/**
 * Groups the elements of an array by a key derived from each element.
 *
 * The returned `Map` preserves insertion order: keys appear in the order they
 * were first encountered, and items within each group keep their original
 * relative order.
 *
 * A `Map` is used (rather than a plain object) so that any key type is
 * supported — including objects, symbols, and `undefined` — without keys
 * being coerced to strings.
 *
 * @param {T[]} arr                 The array to group. Must be an array.
 * @param {(item: T, index: number) => K} keyFn
 *        Derives the group key for an item. Called once per element with the
 *        element and its index. May return any value usable as a `Map` key.
 * @returns {Map<K, T[]>} A map from derived key to the array of items with
 *          that key. Items are not cloned; the original references are kept.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @template T The element type.
 * @template K The key type.
 *
 * @example
 * const people = [
 *   { name: 'Ada',   role: 'engineer' },
 *   { name: 'Grace', role: 'engineer' },
 *   { name: 'Alan',  role: 'scientist' },
 * ];
 *
 * const byRole = groupBy(people, (p) => p.role);
 *
 * byRole.get('engineer');
 * // => [{ name: 'Ada', role: 'engineer' }, { name: 'Grace', role: 'engineer' }]
 *
 * byRole.get('scientist');
 * // => [{ name: 'Alan', role: 'scientist' }]
 *
 * @example
 * // Grouping by an object key uses reference identity.
 * const byUser = groupBy(posts, (post) => post.user);
 * byUser.get(userObject); // only posts belonging to that exact object
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: expected an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: expected keyFn to be a function');
  }

  /** @type {Map<K, T[]>} */
  const groups = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);

    let bucket = groups.get(key);
    if (bucket === undefined) {
      bucket = [];
      groups.set(key, bucket);
    }
    bucket.push(item);
  }

  return groups;
}
```

### Notes

- **Complexity:** O(n) time and O(n) space, assuming `keyFn` is O(1).
- **Empty input:** Returns an empty `Map`.
- **Errors from `keyFn`:** If the key function throws, the exception propagates and no partial result is returned.
- **Need a plain object?** Convert explicitly, e.g. `Object.fromEntries(groupBy(arr, keyFn))` — but remember that object keys are stringified, so prefer the `Map` when keys may be objects or symbols.

## `groupBy`

```js
/**
 * Groups the items of an array by a key derived from each item.
 *
 * The returned `Map` maps each derived key to the list of items that
 * produced it. Items keep their original relative order inside a group,
 * and groups appear in the order their key was first encountered.
 *
 * Keys are **not** coerced to strings: a numeric key stays a number, and
 * object keys are compared by reference. This makes `Map` the right
 * container here — a plain object would mangle keys like `1` vs `"1"`,
 * and would misbehave for keys such as `"__proto__"`.
 *
 * @template T
 * @param {readonly T[]} arr        The array to group. Must be an array.
 * @param {(item: T, index: number) => unknown} keyFn
 *        Derives the group key for an item. Called exactly once per item,
 *        in array order, with the item and its index.
 * @returns {Map<unknown, T[]>} A map from derived key to the items with
 *        that key. Empty if `arr` is empty.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * groupBy([1, 2, 3, 4], n => n % 2 ? 'odd' : 'even');
 * // Map { 'odd' => [1, 3], 'even' => [2, 4] }
 *
 * @example
 * const users = [
 *   { name: 'Ada',  role: 'admin' },
 *   { name: 'Alan', role: 'user'  },
 *   { name: 'Grace', role: 'admin' },
 * ];
 * const byRole = groupBy(users, u => u.role);
 * byRole.get('admin'); // [{ name: 'Ada', ... }, { name: 'Grace', ... }]
 * byRole.get('admin').map(u => u.name); // ['Ada', 'Grace']
 */
export function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: expected `arr` to be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: expected `keyFn` to be a function');
  }

  /** @type {Map<unknown, T[]>} */
  const groups = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);

    const bucket = groups.get(key);
    if (bucket === undefined) {
      // First item with this key: start a new group.
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  return groups;
}
```

### Notes on the implementation

- **`Map` over a plain object.** Keys keep their type and identity, so `groupBy(xs, x => x.id)` works correctly even when ids are numbers, and `__proto__` is just an ordinary key.
- **Single pass.** `keyFn` is invoked exactly once per element, so it can be an expensive computation (e.g. `x => x.date.toISOString()`) without being called twice.
- **Order guarantees.** Group order follows first appearance of the key; item order within a group follows the original array.
- **Complexity.** O(n) time and O(n) space, excluding the cost of `keyFn` itself.

### Companion: plain-object variant

If you specifically need a JSON-friendly object (e.g. to serialize the result), use a null-prototype object so special keys stay safe:

```js
/**
 * Like {@link groupBy}, but returns a plain object keyed by the derived key.
 * Keys are coerced to strings, so use only when that is acceptable.
 *
 * @template T
 * @param {readonly T[]} arr
 * @param {(item: T, index: number) => unknown} keyFn
 * @returns {Record<string, T[]>}
 */
export function groupByToObject(arr, keyFn) {
  const groups = Object.create(null); // no prototype: "__proto__" is a normal key
  for (const [key, items] of groupBy(arr, keyFn)) {
    groups[String(key)] = items;
  }
  return groups;
}
```

### Quick usage

```js
groupBy(['apple', 'fig', 'banana'], s => s[0]);   // Map { a => ['apple'], f => ['fig'], b => ['banana'] }
groupBy([1.5, 2.5, 3.5], n => Math.floor(n));      // Map { 1 => [1.5], 2 => [2.5], 3 => [3.5] }
groupBy([], x => x);                              // Map {}
groupBy(users, (u, i) => i % 2 === 0);            // keyFn receives the index too
```

## `groupBy`

```js
/**
 * Groups the items of an array by a key derived from each item.
 *
 * The returned `Map` preserves the type of the keys (so numbers stay numbers,
 * and object/symbol keys are not coerced to strings) and iterates in the order
 * the keys were first encountered.
 *
 * @template T
 * @param {readonly T[]} arr        The array to group. `null`/`undefined` are treated as empty.
 * @param {(item: T, index: number) => unknown} keyFn
 *        Derives the group key for an item. Receives the item and its index.
 * @returns {Map<unknown, T[]>}
 *        A map of key -> array of items sharing that key. Each group is a new array.
 *
 * @example
 * groupBy([1, 2, 3, 4], n => n % 2);
 * // Map { 1 => [1, 3], 0 => [2, 4] }
 *
 * @example
 * groupBy(users, u => u.department);
 * // Map { 'eng' => [...], 'sales' => [...] }
 */
export function groupBy(arr, keyFn) {
  const groups = new Map();

  if (arr == null) return groups;
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: keyFn must be a function');
  }

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);

    const bucket = groups.get(key);
    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  return groups;
}
```

### Why a `Map` and not a plain object?

| | `Map` (this impl) | Plain object |
|---|---|---|
| Key types | any value: numbers, objects, symbols | coerced to strings (`1` → `"1"`) |
| Lookup | `O(1)` | `O(1)` but string coercion |
| Order | insertion order | insertion order (string keys only) |
| Prototype safety | no `"__proto__"`/`"constructor"` collisions | real hazard |

If you specifically want a plain object (e.g. for JSON serialization), use the variant below — but be aware of the `__proto__` pitfall.

### Object-returning variant

```js
/**
 * Like {@link groupBy}, but returns a plain object.
 * Keys are coerced to strings, so only use this when keys are strings/numbers.
 *
 * @template T
 * @param {readonly T[]} arr
 * @param {(item: T, index: number) => string | number} keyFn
 * @returns {Record<string, T[]>}
 */
export function groupByObject(arr, keyFn) {
  const groups = Object.create(null); // avoids prototype pollution
  for (let i = 0; i < (arr?.length ?? 0); i++) {
    const key = String(keyFn(arr[i], i));
    (groups[key] ??= []).push(arr[i]);
  }
  return groups;
}
```

### Usage examples

```js
const orders = [
  { id: 1, customer: 'ada',  total: 10 },
  { id: 2, customer: 'bob',  total: 25 },
  { id: 3, customer: 'ada',  total: 7  },
];

// Group by a field
const byCustomer = groupBy(orders, o => o.customer);
// byCustomer.get('ada') // => [{ id: 1, ... }, { id: 3, ... }]

// Group by a computed key, using the index
const byParity = groupBy([1, 2, 3, 4, 5], (n, i) => (i % 2 ? 'odd-index' : 'even-index'));

// Group by an object key (only possible with Map)
const byDate = groupBy(events, e => e.day); // e.day is a Date instance

// Iterate the result
for (const [key, items] of byCustomer) {
  console.log(key, items.length);
}

// Transform each group
const totals = new Map(
  [...byCustomer].map(([k, items]) => [k, items.reduce((s, o) => s + o.total, 0)])
);
```

### Notes

- **Non-mutating**: the input array is never modified; each group is a fresh array.
- **Complexity**: `O(n)` time, `O(n)` space.
- **Duplicate keys**: items with the same key keep their relative order within the group.
- **`NaN` keys**: `Map` uses SameValueZero, so `NaN` correctly groups with `NaN` (unlike `===`).
- **Standard alternative**: ES2024 ships `Object.groupBy(arr, keyFn)`, which returns a plain object with the same string-key caveats. Use it if you don't need non-string keys and your target runtime supports it.

