### TypeScript version

```ts
function groupBy<T, K>(
  arr: readonly T[],
  keyFn: (item: T, index: number) => K,
): Map<K, T[]> {
  const groups = new Map<K, T[]>();
  arr.forEach((item, i) => {
    const key = keyFn(item, i);
    const bucket = groups.get(key);
    if (bucket) bucket.push(item);
    else groups.set(key, [item]);
  });
  return groups;
}
```

## `groupBy` — group array items by a derived key

```js
/**
 * Groups the elements of an array according to a key derived from each element.
 *
 * The key function is called once per element, in array order, and its return
 * value determines which group the element belongs to. Keys are compared with
 * SameValueZero semantics (the same rules used by `Map`/`Set`), so `NaN` is a
 * valid key and `0` and `-0` are treated as the same key.
 *
 * A `Map` is returned rather than a plain object so that any key type is
 * supported — including objects, symbols, and `__proto__` — without the risk
 * of prototype collisions. Group order follows first-appearance order of keys,
 * and items within a group keep their original relative order.
 *
 * @template T - The element type of the input array.
 * @template K - The type of the derived key.
 * @param {readonly T[]} arr - The array to group. `null`/`undefined` yields an empty `Map`.
 * @param {(item: T, index: number) => K} keyFn - Derives the group key for an element.
 *        Receives the element and its index.
 * @returns {Map<K, T[]>} A map from key to the array of elements with that key.
 * @throws {TypeError} If `arr` is not an array (and not nullish) or `keyFn` is not a function.
 *
 * @example
 * const people = [
 *   { name: 'Ada',   role: 'engineer' },
 *   { name: 'Grace', role: 'engineer' },
 *   { name: 'Alan',  role: 'scientist' },
 * ];
 *
 * const byRole = groupBy(people, (p) => p.role);
 * byRole.get('engineer'); // [{ name: 'Ada', ... }, { name: 'Grace', ... }]
 * byRole.get('scientist'); // [{ name: 'Alan', ... }]
 *
 * @example
 * // Keys don't have to be strings — objects work too.
 * const byUser = groupBy(posts, (post) => post.author); // Map<User, Post[]>
 *
 * @example
 * // The index is available as the second argument.
 * groupBy(['a', 'b', 'c'], (ch, i) => i % 2);
 * // Map { 0 => ['a', 'c'], 1 => ['b'] }
 */
export function groupBy(arr, keyFn) {
  if (arr == null) return new Map();
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: expected an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: keyFn must be a function');
  }

  /** @type {Map<K, T[]>} */
  const groups = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);
    const bucket = groups.get(key);

    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  return groups;
}
```

### Usage

```js
const words = ['apple', 'avocado', 'banana', 'blueberry', 'cherry'];

const byFirstLetter = groupBy(words, (w) => w[0]);

for (const [letter, group] of byFirstLetter) {
  console.log(letter, group);
}
// a ['apple', 'avocado']
// b ['banana', 'blueberry']
// c ['cherry']

// Convert to a plain object if you prefer:
