- **Space:** `O(n)` — every item is stored exactly once, plus one array per distinct key.

### Native alternative

Modern engines ship `Object.groupBy` (ES2024, Node 21+, current browsers):

```js
Object.groupBy([1.3, 2.1, 2.4], (n) => Math.floor(n)); // { '1': [1.3], '2': [2.1, 2.4] }
```

It behaves like `groupBy` but returns an object with the normal `Object.prototype` (so `"__proto__"` as a key is a hazard) and always coerces keys to strings. The hand-rolled version above is worth keeping when you need the null-prototype safety, the `Map` variant, or consistent behavior across older runtimes.

## `groupBy` — group array items by a derived key

```js
/**
 * Groups the items of an array by the key derived for each item.
 *
 * Every item is passed to `keyFn` exactly once. Items whose derived key is
 * equal end up in the same group, and the original relative order of items
 * is preserved inside each group. The input array is never mutated.
 *
 * Keys are coerced to strings, so `1` and `'1'` land in the same group.
 * If you need to preserve key types (numbers, objects, `NaN`, …), use
 * {@link groupByMap} instead.
 *
 * @template T
 * @param {readonly T[]} arr The array to group. Must be an array.
 * @param {(item: T, index: number) => unknown} keyFn Derives the group key
 *   for an item. Receives the item and its index in `arr`.
 * @returns {Record<string, T[]>} A plain object mapping each distinct key to
 *   the array of items that produced it. Groups appear in the order their
 *   key was first encountered.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * groupBy([1, 2, 3, 4], n => (n % 2 ? 'odd' : 'even'));
 * // => { odd: [1, 3], even: [2, 4] }
 *
 * @example
 * const users = [
 *   { name: 'Ada',  role: 'admin' },
 *   { name: 'Linus', role: 'user' },
 *   { name: 'Grace', role: 'admin' },
 * ];
 * groupBy(users, u => u.role);
 * // => {
 * //   admin: [{ name: 'Ada', role: 'admin' }, { name: 'Grace', role: 'admin' }],
 * //   user:  [{ name: 'Linus', role: 'user' }]
 * // }
 *
 * @example
 * // Keys are stringified:
 * groupBy([1, '1', 2], x => x);
 * // => { '1': [1, '1'], '2': [2] }
 */
export function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: expected `arr` to be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: expected `keyFn` to be a function');
  }

  const groups = new Map();
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = String(keyFn(item, i));
    const bucket = groups.get(key);
    if (bucket) bucket.push(item);
    else groups.set(key, [item]);
  }

  // Materialise the Map into a plain object. `defineProperty` is used so
  // that a key of "__proto__" becomes a normal own property instead of
  // silently mutating the object's prototype.
  const result = {};
  for (const [key, bucket] of groups) {
    Object.defineProperty(result, key, {
      value: bucket,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return result;
}
```

