 * @example
 * groupBy([1, 2, 3, 4], n => n % 2 ? 'odd' : 'even');
 * // => { odd: [1, 3], even: [2, 4] }
 *
 * @example
 * groupBy(users, u => u.role);
 * // => { admin: [...], editor: [...], viewer: [...] }
 *
 * @remarks
 * - Groups appear in the order their key was first encountered.
 * - Items within a group keep their relative order from `arr`.
 * - Keys are stringified, so `1` and `'1'` land in the same group.
 *   Use {@link groupByMap} if you need non-string keys (symbols, objects).
 * - The returned object has a normal prototype, but group keys are defined
 *   with `Object.defineProperty`, so a key such as `"__proto__"` cannot
 *   pollute `Object.prototype`.
 * - Time: O(n). Space: O(n).
 */
export function groupBy(arr, keyFn) {
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: keyFn must be a function');
  }

  // A Map is used internally so that keys are compared with SameValueZero
  // (NaN === NaN) and so that object/symbol keys never collide before
  // stringification.
  const groups = new Map();

  if (arr == null) return {};

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);
    const bucket = groups.get(key);
    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }

  const result = {};
  for (const [key, bucket] of groups) {
    // defineProperty (rather than `result[key] = bucket`) so that a key of
    // "__proto__" creates a plain own property instead of mutating the
    // prototype chain.
    Object.defineProperty(result, String(key), {
      value: bucket,
      enumerable: true,
      writable: true,
      configurable: true,
    });
  }
  return result;
}
