 * @param {readonly T[]} arr The array to group. Must be an array.
 * @param {(item: T, index: number) => unknown} keyFn
 *   Function that derives the group key for an item. Receives the item and
 *   its index in `arr`.
 * @returns {Map<unknown, T[]>}
 *   A map from derived key to the array of items with that key. Keys appear
 *   in first-encountered order; items within a group keep their original
 *   relative order.
 * @throws {TypeError} If `arr` is not an array or `keyFn` is not a function.
 *
 * @example
 * const words = ['apple', 'avocado', 'banana', 'blueberry', 'cherry'];
 *
 * groupBy(words, (word) => word[0]);
 * // Map(3) {
 * //   'a' => ['apple', 'avocado'],
 * //   'b' => ['banana', 'blueberry'],
 * //   'c' => ['cherry'],
 * // }
 *
 * @example
 * // Grouping objects by a computed property
 * const users = [
 *   { name: 'Ada',  role: 'admin' },
 *   { name: 'Alan', role: 'user' },
 *   { name: 'Grace', role: 'admin' },
 * ];
 *
 * const byRole = groupBy(users, (user) => user.role);
 * byRole.get('admin'); // [{ name: 'Ada', ... }, { name: 'Grace', ... }]
 * byRole.get('missing'); // undefined
 *
 * @example
 * // The index is available as the second argument
 * groupBy(['a', 'b', 'c'], (letter, i) => i % 2);
 * // Map(2) { 0 => ['a', 'c'], 1 => ['b'] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError('groupBy: expected `arr` to be an array');
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError('groupBy: expected `keyFn` to be a function');
  }

  /** @type {Map<unknown, T[]>} */
  const groups = new Map();

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i);

    const group = groups.get(key);
    if (group === undefined) {
      groups.set(key, [item]);
    } else {
      group.push(item);
    }
  }

  return groups;
}
