## `Cache` — a small in-memory key/value cache

```js
/**
 * A small in-memory key/value cache with optional TTL expiry and LRU eviction.
 *
 * Keys are compared with SameValueZero (like `Map`), so `NaN` works as a key.
 * Values may be anything, including `undefined` — use `has()` to distinguish
 * "missing" from "stored as undefined".
 */
export class Cache {
  /**
   * @param {object} [options]
   * @param {number} [options.maxSize=Infinity] Maximum number of live entries.
   *   When exceeded, the least-recently-used entry is evicted.
   * @param {number} [options.ttl=Infinity] Default lifetime of an entry, in
   *   milliseconds. `Infinity` means entries never expire.
   */
  constructor({ maxSize = Infinity, ttl = Infinity } = {}) {
    /** @type {Map<string|number|symbol, {value: any, expiresAt: number}>} */
    this._entries = new Map();
    this._maxSize = maxSize;
    this._ttl = ttl;
  }

  /**
   * Number of live (non-expired) entries currently held.
   * @returns {number}
   */
  get size() {
    this._purge();
    return this._entries.size;
  }

  /**
   * Read a value.
   *
   * @param {string|number|symbol} key
   * @returns {any} The stored value, or `undefined` if the key is absent or expired.
   */
  get(key) {
    const entry = this._entries.get(key);
    if (!entry) return undefined;
    if (this._isExpired(entry)) {
      this._entries.delete(key);
      return undefined;
    }
    // Refresh recency for LRU eviction.
    this._entries.delete(key);
    this._entries.set(key, entry);
    return entry.value;
  }

  /**
   * Store a value.
   *
   * @param {string|number|symbol} key
   * @param {any} value
   * @param {number} [ttl] Override the cache's default TTL for this entry, in ms.
   * @returns {this} The cache, for chaining.
   */
  set(key, value, ttl = this._ttl) {
    this._entries.delete(key);
    this._entries.set(key, { value, expiresAt: Date.now() + ttl });
    this._evictIfNeeded();
    return this;
  }

  /**
   * Test whether a key is present and unexpired.
   *
   * @param {string|number|symbol} key
   * @returns {boolean}
   */
  has(key) {
    const entry = this._entries.get(key);
    if (!entry) return false;
    if (this._isExpired(entry)) {
      this._entries.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Remove a key.
   *
   * @param {string|number|symbol} key
   * @returns {boolean} `true` if an entry was removed, `false` if there was nothing to remove.
   */
  delete(key) {
    return this._entries.delete(key);
  }

  /**
   * Remove every entry.
   *
   * @returns {void}
   */
  clear() {
    this._entries.clear();
  }

  // --- internals ---

  /** @param {{expiresAt: number}} entry */
  _isExpired(entry) {
    return entry.expiresAt <= Date.now();
  }

  /** Drop expired entries so `size` and eviction stay accurate. */
  _purge() {
    for (const [key, entry] of this._entries) {
      if (this._isExpired(entry)) this._entries.delete(key);
    }
  }

  /** Evict least-recently-used entries until within `maxSize`. */
  _evictIfNeeded() {
    while (this._entries.size > this._maxSize) {
      const oldest = this._entries.keys().next().value;
      this._entries.delete(oldest);
    }
  }
}
```

### Usage

```js
const cache = new Cache({ maxSize: 100, ttl: 60_000 });

cache.set('user:1', { name: 'Ada' });
cache.get('user:1');        // { name: 'Ada' }
cache.has('user:1');        // true
cache.delete('user:1');     // true
cache.get('user:1');        // undefined
```

### API summary

| Member | Description |
| --- | --- |
| `new Cache(options?)` | `options.maxSize` (LRU cap), `options.ttl` (default lifetime in ms). |
| `get(key)` | Value for `key`, or `undefined` if missing/expired. Marks the entry as recently used. |
| `set(key, value, ttl?)` | Stores `value`; optional per-entry TTL override. Returns `this`. |
| `has(key)` | `true` if `key` exists and has not expired. |
| `delete(key)` | Removes `key`; returns whether anything was removed. |
| `clear()` | Removes all entries. |
| `size` | Count of live entries. |

Two notes on behaviour worth knowing: expiry is lazy (checked on access, plus a sweep in `size`), so an expired entry can linger in memory until touched; and `get()` returning `undefined` is ambiguous if you legitimately store `undefined` — use `has()` in that case.

## `cache.js`

```js
/**
 * A small in-memory key/value cache with optional TTL expiry and LRU eviction.
 *
 * Keys are compared using SameValueZero semantics (as with `Map`), so any
 * value can be used as a key.
 */
export class Cache {
  #store = new Map();
  #maxSize;
  #ttl;

  /**
   * Creates a new cache.
   *
   * @param {object}  [options]
   * @param {number}  [options.maxSize=Infinity] Maximum number of live entries.
   *   When exceeded, the least recently used entry is evicted.
   * @param {number|null} [options.ttl=null] Default time-to-live in
   *   milliseconds. `null` means entries never expire.
   * @throws {RangeError} If `maxSize` or `ttl` is not a positive number
   *   (`ttl` may be `null`).
   */
  constructor({ maxSize = Infinity, ttl = null } = {}) {
    if (!(maxSize > 0)) throw new RangeError('maxSize must be a positive number');
    if (ttl !== null && !(ttl > 0)) throw new RangeError('ttl must be a positive number or null');
    this.#maxSize = maxSize;
    this.#ttl = ttl;
  }

  /**
   * The number of entries currently held, including any that have expired
   * but not yet been reaped.
   *
   * @returns {number}
   */
  get size() {
    return this.#store.size;
  }

  /**
   * Returns the value stored for `key`, or `undefined` if the key is absent
   * or its entry has expired. Expired entries are removed as a side effect.
   *
   * Reading an entry marks it as most recently used.
   *
   * @param {*} key
   * @returns {*} The stored value, or `undefined`.
   */
  get(key) {
    const entry = this.#store.get(key);
    if (entry === undefined) return undefined;

    if (this.#isExpired(entry)) {
      this.#store.delete(key);
      return undefined;
    }

    // Refresh recency: re-inserting moves the key to the end of the Map.
    this.#store.delete(key);
    this.#store.set(key, entry);
    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any previous value.
   *
   * @param {*} key
   * @param {*} value
   * @param {object}  [options]
   * @param {number|null} [options.ttl] Per-entry time-to-live in milliseconds,
   *   overriding the cache default. `null` disables expiry for this entry.
   * @returns {Cache} This cache, for chaining.
   */
  set(key, value, { ttl = this.#ttl } = {}) {
    const expiresAt = ttl === null ? null : Date.now() + ttl;

    if (this.#store.has(key)) this.#store.delete(key);
    this.#store.set(key, { value, expiresAt });

    // Evict least recently used entries until we are within the size limit.
    while (this.#store.size > this.#maxSize) {
      const oldest = this.#store.keys().next().value;
      this.#store.delete(oldest);
    }

    return this;
  }

  /**
   * Reports whether a live (non-expired) value exists for `key`.
   * Does not affect recency.
   *
   * @param {*} key
   * @returns {boolean}
   */
  has(key) {
    const entry = this.#store.get(key);
    if (entry === undefined) return false;

    if (this.#isExpired(entry)) {
      this.#store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry for `key`.
   *
   * @param {*} key
   * @returns {boolean} `true` if an entry was removed, `false` if none existed.
   */
  delete(key) {
    return this.#store.delete(key);
  }

  /**
   * Removes every entry from the cache.
   *
   * @returns {void}
   */
  clear() {
    this.#store.clear();
  }

  /**
   * @param {{expiresAt: number|null}} entry
   * @returns {boolean}
   */
  #isExpired({ expiresAt }) {
    return expiresAt !== null && Date.now() >= expiresAt;
  }
}
