cache.set('token', 'abc', { ttl: 5_000 }); // per-entry TTL
```

**Notes on behavior**
- `get` returns `undefined` for a miss, so a stored `undefined` is indistinguishable from an absent key — store a sentinel if that matters.
- Expiry is lazy: an entry past its TTL is only removed when `get`/`has` touches it, so `size` may briefly overcount.
- `set` returns the cache itself, so calls can be chained: `cache.set('a', 1).set('b', 2)`.

Here's a small, dependency-free cache in TypeScript (a Map-backed cache with optional TTL and LRU-style eviction):

```ts
/** Options controlling cache behavior. */
export interface CacheOptions {
  /**
   * Maximum number of live entries. When exceeded, the least recently
   * used entry is evicted. Defaults to `Infinity` (unbounded).
   */
  maxSize?: number;
  /**
   * Default time-to-live in milliseconds for entries created by `set()`.
   * `undefined` (default) means entries never expire.
   */
  ttl?: number;
}

interface CacheEntry<T> {
  value: T;
  /** Epoch ms after which the entry is expired, or `null` if it never expires. */
  expiresAt: number | null;
}

/**
 * A simple in-memory key/value cache.
 *
 * Keys are strings; values are of type `T`. Expired entries are removed
 * lazily, when they are accessed via `get()` or `has()`.
 */
export class Cache<T = unknown> {
  private readonly store = new Map<string, CacheEntry<T>>();
  private readonly maxSize: number;
  private readonly defaultTtl: number | undefined;

  constructor(options: CacheOptions = {}) {
    this.maxSize = options.maxSize ?? Infinity;
    this.defaultTtl = options.ttl;
    if (this.maxSize <= 0) {
      throw new RangeError("maxSize must be greater than 0");
    }
  }

  /**
   * Returns the value stored under `key`, or `undefined` if the key is
   * missing or its entry has expired. Reading an entry marks it as
   * most recently used.
   */
  get(key: string): T | undefined {
    const entry = this.store.get(key);
    if (entry === undefined) return undefined;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return undefined;
    }
    // Refresh recency (Map preserves insertion order).
    this.store.delete(key);
    this.store.set(key, entry);
    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any previous value.
   *
   * @param ttlMs Optional per-entry time-to-live in milliseconds; overrides
   *              the cache-wide default. A value of `0` or less expires
   *              the entry immediately.
   * @returns `this`, for chaining.
   */
  set(key: string, value: T, ttlMs?: number): this {
    const ttl = ttlMs ?? this.defaultTtl;
    const expiresAt = ttl === undefined ? null : Date.now() + ttl;
    this.store.delete(key);
    this.store.set(key, { value, expiresAt });
    this.evictIfNeeded();
    return this;
  }

  /**
   * Returns `true` if a non-expired entry exists for `key`.
   * Does not affect the entry's recency.
   */
  has(key: string): boolean {
    const entry = this.store.get(key);
    if (entry === undefined) return false;
    if (this.isExpired(entry)) {
      this.store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry for `key`.
   *
   * @returns `true` if an entry was removed, `false` if the key was absent.
   */
  delete(key: string): boolean {
    return this.store.delete(key);
  }

  /** Removes all entries. */
  clear(): void {
    this.store.clear();
  }

  /** Number of entries currently stored, including any not-yet-reaped expired ones. */
  get size(): number {
    return this.store.size;
  }

  private isExpired(entry: CacheEntry<T>): boolean {
    return entry.expiresAt !== null && entry.expiresAt <= Date.now();
  }

  private evictIfNeeded(): void {
    while (this.store.size > this.maxSize) {
      const oldest = this.store.keys().next().value;
      if (oldest === undefined) break;
      this.store.delete(oldest);
    }
  }
}
```

Example:

```ts
const cache = new Cache<string>({ maxSize: 100, ttl: 60_000 });

cache.set("user:1", "Ada");
cache.get("user:1");   // "Ada"
cache.has("user:1");   // true
cache.delete("user:1"); // true
cache.get("user:1");   // undefined
```

Notes on semantics:
- `get` returns `undefined` for both missing and expired keys; use `has` to distinguish presence (though `has` also reports `false` for expired entries).
- `set` overwrites and refreshes the TTL; it returns `this` so calls can be chained.
- Eviction is least-recently-used, based on `get`/`set` order.

