/**
 * A small, dependency-free in-memory cache backed by a `Map`.
 *
 * Features:
 *  - Optional per-cache time-to-live (TTL), in milliseconds.
 *  - Optional maximum size with least-recently-used (LRU) eviction.
 *  - Expired entries are treated as absent and are lazily removed.
 *
 * @example
 * const cache = new Cache({ maxSize: 100, ttl: 60_000 });
 * cache.set("user:1", { name: "Ada" });
 * cache.get("user:1");      // => { name: "Ada" }
 * cache.has("user:1");      // => true
 * cache.delete("user:1");   // => true
 */
export class Cache {
  /**
   * @typedef {object} CacheOptions
   * @property {number} [maxSize=Infinity] Maximum number of live entries.
   *   When exceeded, the least recently used entry is evicted.
   * @property {number} [ttl=Infinity] Default lifetime of an entry in
   *   milliseconds. `Infinity` means entries never expire.
   */

  /**
   * Creates an empty cache.
   *
   * @param {CacheOptions} [options] Cache configuration.
   */
  constructor({ maxSize = Infinity, ttl = Infinity } = {}) {
    /** @type {Map<string, {value: unknown, expiresAt: number}>} */
    this._entries = new Map();
    this._maxSize = maxSize;
    this._ttl = ttl;
  }

  /**
   * Returns the value stored under `key`, or `undefined` if the key is
   * missing or its entry has expired. Reading an entry marks it as
   * recently used.
   *
   * @param {string} key Lookup key.
   * @returns {unknown} The cached value, or `undefined` when not cached.
   */
  get(key) {
    const entry = this._entries.get(key);
    if (entry === undefined) return undefined;

    if (this._isExpired(entry)) {
      this._entries.delete(key);
      return undefined;
    }

    // Refresh recency: re-inserting moves the key to the end of the Map's
    // insertion order, which is what LRU eviction relies on.
    this._entries.delete(key);
    this._entries.set(key, entry);

    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any previous value. The entry's
   * TTL is reset to the cache's default. If the cache is full, the least
   * recently used entry is evicted to make room.
   *
   * @param {string} key Key to store the value under.
   * @param {unknown} value Value to store. May be `undefined`.
   * @returns {this} The cache, for chaining.
   */
  set(key, value) {
    // Delete first so the key moves to the end of the insertion order.
    this._entries.delete(key);
    this._entries.set(key, {
      value,
      expiresAt: this._ttl === Infinity ? Infinity : Date.now() + this._ttl,
    });

    while (this._entries.size > this._maxSize) {
      const oldestKey = this._entries.keys().next().value;
      this._entries.delete(oldestKey);
    }

    return this;
  }

  /**
   * Reports whether a live (non-expired) value is stored under `key`.
   * Does not affect the entry's recency.
   *
   * @param {string} key Key to check.
   * @returns {boolean} `true` if a non-expired entry exists.
   */
  has(key) {
    const entry = this._entries.get(key);
    if (entry === undefined) return false;

    if (this._isExpired(entry)) {
      this._entries.delete(key);
      return false;
    }

    return true;
  }

  /**
   * Removes the entry stored under `key`.
   *
   * @param {string} key Key to remove.
   * @returns {boolean} `true` if an entry was removed, `false` if the key
   *   was absent or already expired.
   */
  delete(key) {
    const existed = this.has(key); // also purges expired entries
    return this._entries.delete(key) && existed;
  }

  /**
   * Removes every entry from the cache.
   *
   * @returns {this} The cache, for chaining.
   */
  clear() {
    this._entries.clear();
    return this;
  }

  /**
   * The number of live entries currently held.
   *
   * @returns {number} Entry count.
   */
  get size() {
    let count = 0;
    for (const entry of this._entries.values()) {
      if (!this._isExpired(entry)) count++;
    }
    return count;
  }

  /**
   * @param {{expiresAt: number}} entry
   * @returns {boolean} `true` if the entry's TTL has elapsed.
   * @private
   */
  _isExpired(entry) {
    return entry.expiresAt !== Infinity && Date.now() >= entry.expiresAt;
  }
}
```

### Notes on behaviour

- **Missing keys and expired keys are indistinguishable** through `get` — both yield `undefined`. Use `has` if you need to tell them apart.
- **`has` does not refresh recency**, but `get` and `set` do; this keeps `has` cheap and side-effect free apart from purging expired entries.
- **`delete` returns `false`** for keys that were absent or already expired.
- **Eviction is LRU**: when `maxSize` is reached, the entry that was least recently read or written is dropped.
- Keys are compared with `Map` semantics (SameValueZero), so `1` and `"1"` are distinct keys.

Here's a small, dependency-free cache with an optional size cap (LRU eviction) and optional per-entry TTL.

```js
/**
 * A simple in-memory key/value cache.
 *
 * @example
 * const cache = new Cache({ maxSize: 100 });
 * cache.set('user:1', { name: 'Ada' });
 * cache.get('user:1');        // { name: 'Ada' }
 * cache.has('user:1');        // true
 * cache.delete('user:1');     // true
 */
export class Cache {
  /**
   * @param {object} [options]
   * @param {number} [options.maxSize=Infinity] Maximum number of entries. When
   *   exceeded, the least-recently-used entry is evicted.
   * @param {number|null} [options.ttl=null] Default time-to-live in
   *   milliseconds for every entry. `null` means entries never expire.
   */
  constructor({ maxSize = Infinity, ttl = null } = {}) {
    /** @private @type {Map<string, {value: any, expiresAt: number|null}>} */
    this._store = new Map();
    this._maxSize = maxSize;
    this._ttl = ttl;
  }

  /**
   * Returns the value stored for `key`, or `undefined` if the key is missing
   * or its entry has expired. Reading an entry refreshes its recency.
   *
   * @param {string} key
   * @returns {any} The cached value, or `undefined`.
   */
  get(key) {
    const entry = this._store.get(key);
    if (!entry) return undefined;

    if (this._isExpired(entry)) {
      this._store.delete(key);
      return undefined;
    }

    // Refresh recency (Map preserves insertion order).
    this._store.delete(key);
    this._store.set(key, entry);
    return entry.value;
  }

  /**
   * Stores `value` under `key`, replacing any previous value.
   *
   * @param {string} key
   * @param {any} value
   * @returns {this} The cache, for chaining.
   */
  set(key, value) {
    if (this._store.has(key)) this._store.delete(key);
    this._store.set(key, { value, expiresAt: this._ttl === null ? null : Date.now() + this._ttl });
    this._evictIfNeeded();
    return this;
  }

  /**
   * Reports whether a live (non-expired) entry exists for `key`. Does not
   * affect recency.
   *
   * @param {string} key
   * @returns {boolean}
   */
  has(key) {
    const entry = this._store.get(key);
    if (!entry) return false;
    if (this._isExpired(entry)) {
      this._store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes the entry for `key`.
   *
   * @param {string} key
   * @returns {boolean} `true` if an entry was removed, `false` if the key was
   *   not present (or had already expired).
   */
  delete(key) {
    return this._store.delete(key);
  }

  /**
   * Removes every entry.
   *
   * @returns {void}
   */
  clear() {
    this._store.clear();
  }

  /**
   * The number of live entries currently held.
   *
   * @returns {number}
   */
  get size() {
    return this._store.size;
  }

  /** @private */
  _isExpired(entry) {
    return entry.expiresAt !== null && Date.now() >= entry.expiresAt;
  }

  /** @private */
  _evictIfNeeded() {
    while (this._store.size > this._maxSize) {
      const oldestKey = this._store.keys().next().value;
      this._store.delete(oldestKey);
    }
  }
}
```

### Public API summary

| Member | Signature | Returns |
| --- | --- | --- |
| `constructor` | `new Cache({ maxSize?, ttl? })` | — |
| `get` | `get(key)` | cached value or `undefined` |
| `set` | `set(key, value)` | `this` (chainable) |
| `has` | `has(key)` | `boolean` |
| `delete` | `delete(key)` | `boolean` (whether something was removed) |
| `clear` | `clear()` | `void` |
| `size` | `size` (getter) | `number` of live entries |

Notes on behavior worth knowing:
- `get` and `has` both treat expired entries as absent and purge them lazily.
- `get` counts as a use for LRU purposes; `has` does not.
- `maxSize: Infinity` (the default) means unbounded growth — set a limit if memory matters.
- Eviction is strict LRU, not LFU; ties break by insertion order.

Here's a small, well-documented cache. I used TypeScript since the types document the API contract; the same code works as plain JS with the types stripped.

```ts
/**
 * A simple in-memory key/value cache.
 *
 * Backed by a `Map`, so lookups are O(1) and insertion order is preserved.
 * Keys are compared by identity (SameValueZero), exactly like `Map`.
 *
 * @typeParam K - Type of the cache keys.
 * @typeParam V - Type of the cached values.
 *
 * @example
 * const cache = new Cache<string, number>();
 * cache.set("hits", 0).set("misses", 0);
 *
 * cache.get("hits");    // 0
 * cache.has("hits");    // true
 * cache.delete("hits"); // true
 * cache.has("hits");    // false
 */
export class Cache<K = string, V = unknown> {
  /** @internal Backing store. Never mutated from outside the class. */
  private readonly store = new Map<K, V>();

  /**
   * Returns the value stored under `key`.
   *
   * @param key - The key to look up.
   * @returns The cached value, or `undefined` if `key` is not present.
   *
   * @remarks
   * A key that was explicitly `set` to `undefined` is indistinguishable from a
   * missing key here. Use {@link Cache.has} to test for presence.
   */
  get(key: K): V | undefined {
    return this.store.get(key);
  }

  /**
   * Stores `value` under `key`, replacing any existing entry.
   *
   * @param key - The key to write.
   * @param value - The value to cache.
   * @returns `this`, so calls can be chained.
   */
  set(key: K, value: V): this {
    this.store.set(key, value);
    return this;
  }

  /**
   * Reports whether an entry exists for `key`.
   *
   * @param key - The key to test.
   * @returns `true` if the key is present, `false` otherwise.
   */
  has(key: K): boolean {
    return this.store.has(key);
  }

  /**
   * Removes the entry stored under `key`.
   *
   * @param key - The key to remove.
   * @returns `true` if an entry was removed, `false` if `key` was not present.
   */
  delete(key: K): boolean {
    return this.store.delete(key);
  }

  /**
   * The number of entries currently held.
   */
  get size(): number {
    return this.store.size;
  }

  /**
   * Returns the keys of all entries, in insertion order.
   *
   * @returns A new array of keys; mutating it does not affect the cache.
   */
  keys(): K[] {
    return [...this.store.keys()];
  }

  /**
   * Removes every entry from the cache.
   */
  clear(): void {
    this.store.clear();
  }
}
```

**API summary**

| Member | Signature | Returns |
| --- | --- | --- |
| `get` | `get(key: K): V \| undefined` | The value, or `undefined` if absent |
| `set` | `set(key: K, value: V): this` | `this` (chainable) |
| `has` | `has(key: K): boolean` | Whether the key exists |
| `delete` | `delete(key: K): boolean` | Whether an entry was removed |
| `size` | `get size(): number` | Entry count |
| `keys` | `keys(): K[]` | Copy of the keys, in insertion order |
| `clear` | `clear(): void` | — |

**Usage**

```ts
const cache = new Cache<string, string>();

cache.set("a", "1").set("b", "2");

cache.get("a");       // "1"
cache.get("missing"); // undefined
cache.has("b");       // true
cache.delete("b");    // true
cache.delete("b");    // false — already gone
cache.size;           // 1
```

Two notes on deliberate choices:

- **`delete` returns a boolean** (matching `Map.delete`) so callers can tell a successful removal from a no-op — useful when you're invalidating something and want to log or count it.
- **`get` and `has` are separate** because `undefined` is a legal value to cache. `has` is the only reliable presence check.

If you want this to grow into a real cache, the natural next steps are an optional TTL per entry (store `{ value, expiresAt }` and check expiry in `get`/`has`), a max-size limit with an eviction policy (LRU via `Map` re-insertion order), and a `getOrSet(key, factory)` helper. Happy to add any of those.

## `fetchWithRetry`

```js
/**
 * HTTP status codes that represent transient server-side problems and are
 * therefore safe to retry.
 * @type {Set<number>}
 */
const RETRYABLE_STATUS_CODES = new Set([
  408, // Request Timeout
  425, // Too Early
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

const DEFAULT_RETRIES = 3;
const DEFAULT_BASE_DELAY_MS = 300;
const DEFAULT_MAX_DELAY_MS = 30_000;

/**
 * Error thrown when the server responds with a non-2xx status.
 *
 * The offending {@link Response} is attached as `.response` so callers can
 * inspect the status, headers, or read the body themselves.
 */
export class HttpError extends Error {
  /**
   * @param {string} message
   * @param {Response} response
   */
  constructor(message, response) {
    super(message);
    this.name = 'HttpError';
    this.status = response.status;
    this.statusText = response.statusText;
    this.response = response;
  }
}

/**
 * Fetches a URL, retrying failed requests with exponential backoff.
 *
 * ## Behaviour
 *
 * - **Attempts:** `retries + 1` total (the initial request plus `retries`
 *   retries). `retries = 0` performs a single attempt.
 * - **Retried failures:** network/transport errors (DNS failure, connection
 *   reset, socket hang-up) and HTTP responses with a retryable status
 *   (see {@link RETRYABLE_STATUS_CODES}).
 * - **Not retried:** non-retryable statuses (e.g. `404`, `401`) fail fast, and
 *   requests aborted by the caller's `AbortSignal` are never retried.
 * - **Backoff:** `baseDelay * 2^attempt`, capped at `maxDelay`, with *equal
 *   jitter* (half fixed, half random) to avoid thundering-herd retries.
 *   A `Retry-After` response header (seconds or HTTP-date) takes precedence
 *   over the computed delay, still capped at `maxDelay`.
 * - **Timeouts:** `options.timeout` sets a per-attempt timeout in
 *   milliseconds. A timed-out attempt is treated as a transient failure and
 *   is retried.
 *
 * ## Options
 *
 * All standard `fetch` options (`method`, `headers`, `body`, `signal`, …) are
 * forwarded untouched. Three extra options are understood:
 *
 * | Option      | Type     | Default | Description                                  |
 * | ----------- | -------- | ------- | -------------------------------------------- |
 * | `timeout`   | `number` | –       | Per-attempt timeout in ms.                   |
 * | `baseDelay` | `number` | `300`   | Base backoff delay in ms.                    |
 * | `maxDelay`  | `number` | `30000` | Upper bound for any single backoff delay.    |
 *
 * ## Caveats
 *
 * - The request body is reused across attempts, so pass a rewindable body
 *   (e.g. a string or `Buffer`) rather than a consumed stream.
 * - Retrying non-idempotent requests (`POST`, `PATCH`, …) can duplicate
 *   side effects. Use `retries = 0`, or make the endpoint idempotent, if that
 *   is a concern.
 *
 * @param {string | URL} url                 The resource to fetch.
 * @param {RequestInit & {timeout?: number, baseDelay?: number, maxDelay?: number}} [options]
 *        Fetch options plus the retry-specific options described above.
 * @param {number} [retries=3]              Number of retries after the first attempt.
 * @returns {Promise<Response>}             The first successful (2xx) response.
 * @throws {HttpError}                       If the final attempt returns a non-2xx status.
 * @throws {Error}                           If the final attempt fails with a network error,
 *                                           or if the caller's signal aborts.
 *
 * @example
 * try {
 *   const res = await fetchWithRetry('https://api.example.com/data', {
 *     headers: { Accept: 'application/json' },
 *     timeout: 5_000,
 *   }, 3);
 *   const data = await res.json();
 *   console.log(data);
 * } catch (err) {
 *   if (err instanceof HttpError) {
 *     console.error(`HTTP ${err.status}: ${err.statusText}`);
 *   } else {
 *     console.error('Request failed:', err.message);
 *   }
 * }
 */
export async function fetchWithRetry(url, options = {}, retries = DEFAULT_RETRIES) {
  if (typeof url !== 'string' && !(url instanceof URL)) {
    throw new TypeError('fetchWithRetry: `url` must be a string or URL.');
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('fetchWithRetry: `retries` must be a non-negative integer.');
  }

  const {
    timeout,
    baseDelay = DEFAULT_BASE_DELAY_MS,
    maxDelay = DEFAULT_MAX_DELAY_MS,
    ...fetchOptions
  } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const isLastAttempt = attempt === retries;

    // ---- Attempt -----------------------------------------------------------
    let response;
    try {
      response = await performFetch(url, fetchOptions, timeout);
    } catch (error) {
      // A caller-initiated abort is a deliberate cancellation, not a failure.
      if (fetchOptions.signal?.aborted) throw error;

      lastError = error;
      if (isLastAttempt) break;

      await sleep(computeDelay(attempt, null, baseDelay, maxDelay), fetchOptions.signal);
      continue;
    }

    // ---- Success -----------------------------------------------------------
    if (response.ok) return response;

    // ---- HTTP error --------------------------------------------------------
    const error = new HttpError(
      `fetchWithRetry: ${url} responded with ${response.status} ${response.statusText}`,
      response,
    );
    lastError = error;

    // Fail fast on statuses that will not change on a retry.
    if (!RETRYABLE_STATUS_CODES.has(response.status) || isLastAttempt) throw error;

    // Discard the error body so the connection can be reused.
    try {
      await response.body?.cancel();
    } catch {
      /* ignore */
    }

    await sleep(computeDelay(attempt, response, baseDelay, maxDelay), fetchOptions.signal);
  }

  throw lastError;
}

/**
 * Performs a single fetch, optionally applying a per-attempt timeout that is
 * combined with the caller's own AbortSignal.
 *
 * @param {string | URL} url
 * @param {RequestInit} fetchOptions
 * @param {number | undefined} timeoutMs
 * @returns {Promise<Response>}
 */
async function performFetch(url, fetchOptions, timeoutMs) {
  if (!timeoutMs) return fetch(url, fetchOptions);

  const controller = new AbortController();
  const timer = setTimeout(() => {
    const error = new Error(`Request timed out after ${timeoutMs}ms`);
    error.name = 'TimeoutError';
    controller.abort(error);
  }, timeoutMs);

  try {
    const signal = combineSignals([fetchOptions.signal, controller.signal]);
    return await fetch(url, { ...fetchOptions, signal });
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Computes the delay before the next attempt.
 *
 * `Retry-After` wins when present; otherwise exponential backoff with equal
 * jitter is used: `delay = cap/2 + random(0, cap/2)`.
 *
 * @param {number} attempt      Zero-based index of the attempt that just failed.
 * @param {Response | null} response
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @returns {number} Delay in milliseconds.
 */
function computeDelay(attempt, response, baseDelay, maxDelay) {
  const retryAfter = response ? parseRetryAfter(response.headers.get('retry-after')) : null;
  if (retryAfter !== null) return Math.min(retryAfter, maxDelay);

  const capped = Math.min(baseDelay * 2 ** attempt, maxDelay);
  return capped / 2 + Math.random() * (capped / 2);
}

/**
 * Parses a `Retry-After` header value (delta-seconds or HTTP-date).
 *
 * @param {string | null | undefined} value
 * @returns {number | null} Delay in milliseconds, or `null` if unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const timestamp = Date.parse(value);
  if (!Number.isNaN(timestamp)) return Math.max(0, timestamp - Date.now());

  return null;
}

/**
 * Sleeps for `ms`, rejecting immediately if the signal is aborted.
 *
 * @param {number} ms
 * @param {AbortSignal | undefined} signal
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortReason(signal));
      return;
    }

    let timer;
    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };

    timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Combines several AbortSignals into one.
 *
 * @param {Array<AbortSignal | undefined | null>} signals
 * @returns {AbortSignal | undefined}
 */
function combineSignals(signals) {
  const active = signals.filter(Boolean);
  if (active.length === 0) return undefined;
  if (active.length === 1) return active[0];
  if (typeof AbortSignal.any === 'function') return AbortSignal.any(active);

  // Fallback for runtimes without `AbortSignal.any`.
  const controller = new AbortController();
  for (const signal of active) {
    if (signal.aborted) {
      controller.abort(signal.reason);
      break;
    }
    signal.addEventListener('abort', () => controller.abort(signal.reason), { once: true });
  }
  return controller.signal;
}

/**
 * Returns the abort reason, falling back to a generic AbortError.
 *
 * @param {AbortSignal} signal
 * @returns {Error}
 */
function abortReason(signal) {
  if (signal.reason) return signal.reason;
  const error = new Error('The operation was aborted.');
  error.name = 'AbortError';
  return error;
}
```

### Usage

```js
// Basic: 3 retries (4 attempts total) with default backoff.
const res = await fetchWithRetry('https://api.example.com/users');

// Custom timeout, backoff, and retry count.
const res = await fetchWithRetry(
  'https://api.example.com/users',
  { timeout: 5_000, baseDelay: 500, maxDelay: 10_000 },
  5,
);

// Cancellation: aborting the signal stops the retry loop immediately.
const controller = new AbortController();
setTimeout(() => controller.abort(), 2_000);
await fetchWithRetry('https://api.example.com/slow', { signal: controller.signal });
```

**Notes**
- Requires a runtime with global `fetch` (Node 18+, Deno, Bun, or modern browsers).
- `HttpError` is exported so callers can distinguish HTTP failures from transport failures via `instanceof` or `error.status`.
- The `Retry-After` header is honoured for `429`/`503` responses, which is important for rate-limited APIs.

## `fetchWithRetry`

```js
/**
 * @typedef {Object} RetryConfig
 * @property {number}  [baseDelayMs=300]        Base delay for the exponential backoff.
 * @property {number}  [maxDelayMs=30000]       Upper bound for any single backoff delay.
 * @property {number}  [timeoutMs=30000]        Per-attempt timeout (time to response headers). `0` disables it.
 * @property {number[]} [retryableStatuses=[408,425,429,500,502,503,504]] HTTP statuses worth retrying.
 * @property {boolean} [retryOnNetworkError=true] Retry when the request fails before a response arrives.
 * @property {boolean} [respectRetryAfter=true]  Honour a `Retry-After` header when the server sends one.
 * @property {boolean} [retryNonIdempotent=false] Allow retrying POST/PATCH (may duplicate side effects).
 * @property {(info: {attempt:number, delay:number, error?:Error, response?:Response}) => void} [onRetry]
 *           Called before each backoff wait — handy for logging/metrics.
 */

/** HTTP methods that are safe to replay without changing server state. */
const IDEMPOTENT_METHODS = new Set(['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE', 'TRACE']);

/** @type {RetryConfig} */
const DEFAULT_RETRY_CONFIG = {
  baseDelayMs: 300,
  maxDelayMs: 30_000,
  timeoutMs: 30_000,
  retryableStatuses: [408, 425, 429, 500, 502, 503, 504],
  retryOnNetworkError: true,
  respectRetryAfter: true,
  retryNonIdempotent: false,
  onRetry: undefined,
};

/**
 * Perform an HTTP request, retrying transient failures with exponential backoff + jitter.
 *
 * ## Contract
 * - **Resolves** with the final `Response`, *even if its status is an error status*.
 *   Check `response.ok` / `response.status` yourself. This mirrors `fetch` semantics and
 *   keeps the response body readable for the caller.
 * - **Rejects** only when the request could not be completed at all: a network error that
 *   survived all retries, an abort, or a per-attempt timeout.
 *
 * ## What is retried
 * - Network-level failures (DNS, connection reset, TLS errors) — `fetch` rejects with a `TypeError`.
 * - Transient HTTP statuses: `408, 425, 429, 500, 502, 503, 504` by default.
 * - `4xx` statuses other than the ones above are treated as permanent and returned immediately.
 *
 * ## What is *not* retried
 * - Non-idempotent methods (`POST`, `PATCH`) unless `retryNonIdempotent` is enabled, because a
 *   replay can duplicate side effects. Use an idempotency key if you need to retry them.
 * - Aborted requests and per-attempt timeouts (these throw).
 *
 * ## Backoff
 * `delay = min(maxDelayMs, baseDelayMs * 2^attempt)`, then "equal jitter" is applied:
 * the final wait is `50%` of that value plus a random `0–50%`. This keeps a guaranteed
 * minimum spacing while still spreading retries out to avoid a thundering herd.
 * A `Retry-After` header (seconds or HTTP-date) overrides the computed delay, capped at `maxDelayMs`.
 *
 * @param {string|URL} url                 The resource to request.
 * @param {RequestInit & {retry?: RetryConfig}} [options={}]
 *        Standard `fetch` init object. `options.signal` is honoured and aborts the whole
 *        operation (including pending backoff waits). `options.retry` may carry a {@link RetryConfig}.
 * @param {number} [retries=3]             Number of *additional* attempts after the first one.
 *                                        `0` means "try once, never retry".
 * @param {RetryConfig} [config={}]        Overrides for {@link RetryConfig} (highest precedence).
 * @returns {Promise<Response>}            The final response.
 * @throws {Error}                         On network failure, abort, or timeout.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 5);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  const { retry: inlineConfig, ...fetchOptions } = options ?? {};
  const cfg = { ...DEFAULT_RETRY_CONFIG, ...(inlineConfig ?? {}), ...config };
  const maxRetries = Math.max(0, Math.floor(Number(retries) || 0));

  const externalSignal = fetchOptions.signal ?? null;
  const method = (fetchOptions.method ?? 'GET').toUpperCase();
  const methodIsReplayable = cfg.retryNonIdempotent || IDEMPOTENT_METHODS.has(method);

  let lastError = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    // Bail out early if the caller already aborted.
    if (externalSignal?.aborted) throw abortReason(externalSignal);

    const { signal, cleanup } = createAttemptSignal(cfg.timeoutMs, externalSignal);

    let response;
    try {
      response = await fetch(url, { ...fetchOptions, signal });
    } catch (error) {
      cleanup();
      lastError = error;

      const aborted = error?.name === 'AbortError' || error?.name === 'TimeoutError';
      if (aborted || !cfg.retryOnNetworkError || !methodIsReplayable || attempt === maxRetries) {
        throw error;
      }

      const wait = computeBackoff(attempt, cfg);
      cfg.onRetry?.({ attempt, delay: wait, error });
      await sleep(wait, externalSignal);
      continue;
    }
    cleanup();

    // Success, a permanent error status, or no retries left -> hand the response to the caller.
    if (!cfg.retryableStatuses.includes(response.status) || attempt === maxRetries || !methodIsReplayable) {
      return response;
    }

    // We're going to retry: release the body so the socket can be reused.
    try {
      await response.body?.cancel();
    } catch {
      /* ignore — best effort cleanup */
    }

    const retryAfterMs = cfg.respectRetryAfter
      ? parseRetryAfter(response.headers.get('retry-after'))
      : null;
    const wait = retryAfterMs != null
      ? Math.min(retryAfterMs, cfg.maxDelayMs)
      : computeBackoff(attempt, cfg);

    lastError = new Error(`Request failed with HTTP ${response.status} ${response.statusText}`);
    cfg.onRetry?.({ attempt, delay: wait, response, error: lastError });
    await sleep(wait, externalSignal);
  }

  /* istanbul ignore next — the loop always returns or throws before reaching here */
  throw lastError ?? new Error('fetchWithRetry: request failed');
}

/* ------------------------------------------------------------------ helpers */

/**
 * Compute the backoff delay for a given 0-based attempt.
 * @param {number} attempt
 * @param {RetryConfig} cfg
 * @returns {number} milliseconds to wait
 */
function computeBackoff(attempt, cfg) {
  const capped = Math.min(cfg.baseDelayMs * 2 ** attempt, cfg.maxDelayMs);
  return Math.round(capped * (0.5 + Math.random() * 0.5)); // equal jitter
}

/**
 * Parse a `Retry-After` header value (delta-seconds or HTTP-date) into milliseconds.
 * @param {string|null} value
 * @returns {number|null} milliseconds to wait, or `null` if the header is absent/unparseable
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const timestamp = Date.parse(value);
  if (!Number.isNaN(timestamp)) return Math.max(0, timestamp - Date.now());

  return null;
}

/**
 * Create an AbortSignal that fires when either the caller's signal aborts or the
 * per-attempt timeout elapses.
 * @param {number} timeoutMs
 * @param {AbortSignal|null} externalSignal
 */
function createAttemptSignal(timeoutMs, externalSignal) {
  const controller = new AbortController();

  const onExternalAbort = () => controller.abort(abortReason(externalSignal));
  if (externalSignal) {
    if (externalSignal.aborted) controller.abort(abortReason(externalSignal));
    else externalSignal.addEventListener('abort', onExternalAbort, { once: true });
  }

  const timer =
    timeoutMs > 0
      ? setTimeout(() => {
          controller.abort(new DOMException(`Timed out after ${timeoutMs}ms`, 'TimeoutError'));
        }, timeoutMs)
      : null;

  return {
    signal: controller.signal,
    cleanup() {
      if (timer) clearTimeout(timer);
      externalSignal?.removeEventListener('abort', onExternalAbort);
    },
  };
}

/**
 * Sleep, rejecting immediately if the signal aborts.
 * @param {number} ms
 * @param {AbortSignal|null} signal
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortReason(signal));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * @param {AbortSignal} signal
 * @returns {Error} the signal's abort reason, or a generic AbortError
 */
function abortReason(signal) {
  return signal.reason ?? new DOMException('The operation was aborted.', 'AbortError');
}
```

## Usage

```js
// Simple: 3 retries (4 total attempts) with default backoff.
const res = await fetchWithRetry('https://api.example.com/users', {}, 3);
if (!res.ok) throw new Error(`HTTP ${res.status}`);
console.log(await res.json());

// With a timeout, custom backoff, and retry logging.
const res = await fetchWithRetry(
  'https://api.example.com/users',
  { method: 'GET', headers: { Accept: 'application/json' } },
  5,
  {
    baseDelayMs: 500,
    maxDelayMs: 10_000,
    timeoutMs: 5_000,
    onRetry: ({ attempt, delay, error, response }) =>
      console.warn(`retry #${attempt + 1} in ${delay}ms`, error?.message ?? response?.status),
  },
);

// Cancellable.
const controller = new AbortController();
setTimeout(() => controller.abort(), 2_000);
await fetchWithRetry(url, { signal: controller.signal }, 3);

// POST is not retried by default (avoids duplicate writes).
await fetchWithRetry(url, { method: 'POST', body: payload }, 3);
// ...unless you opt in and your API supports idempotency keys:
await fetchWithRetry(url, { method: 'POST', body: payload }, 3, { retryNonIdempotent: true });
```

## Design notes

- **Resolve vs. reject:** the function returns the last `Response` even for `500`s, so you can inspect the body; it only throws when there is no response at all. This avoids the common bug of losing the server's error payload.
- **Jitter:** without it, every client that failed at the same moment retries at the same moment, re-creating the overload that caused the failure.
- **`Retry-After`:** servers often tell you exactly how long to wait (especially on `429`); honouring it is more polite than your own backoff.
- **Method safety:** replaying a `POST` can create duplicate records, so non-idempotent methods are not retried unless you opt in.
- **Timeouts:** the per-attempt timeout covers time-to-response-headers. Once headers arrive the timer is cleared, so streaming a large body isn't cut off — pass your own `AbortSignal` if you need to bound the whole operation.
- **Portability:** uses the global `fetch` (Node 18+, Deno, Bun, modern browsers). On older Node versions, install `undici` or pass a custom `fetch` implementation via `options.fetch` (add `const { fetch: fetchImpl = globalThis.fetch } = options` if you need it).

