```js
/**
 * @module fetch-retry
 */

/**
 * HTTP status codes that are considered *transient* and therefore safe to retry.
 * All other 4xx responses (e.g. 400, 401, 403, 404) fail fast — retrying them
 * would only waste time and hammer the server.
 *
 * @type {Set<number>}
 */
const RETRYABLE_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

const DEFAULT_BASE_DELAY_MS = 300;
const DEFAULT_MAX_DELAY_MS = 30_000;

/**
 * Error thrown when the server returns a non-OK HTTP status.
 *
 * The original {@link Response} is attached so the caller can still inspect the
 * status, headers and body (the body is *not* consumed for you).
 */
export class HttpError extends Error {
  /**
   * @param {Response} response The failed response.
   * @param {string} message    Human-readable description.
   */
  constructor(response, message) {
    super(message);
    this.name = 'HttpError';
    this.status = response.status;
    this.statusText = response.statusText;
    this.headers = response.headers;
    this.response = response;
  }
}

/**
 * Fetch a URL, retrying transient failures with exponential backoff.
 *
 * ## What is retried
 * - Network errors (DNS failure, connection reset, TLS errors, ...).
 * - Per-attempt timeouts (see `options.timeout`).
 * - Transient HTTP statuses: `408`, `425`, `429`, `500`, `502`, `503`, `504`.
 *
 * ## What is *not* retried
 * - Non-transient HTTP statuses (e.g. `400`, `401`, `403`, `404`) — an
 *   {@link HttpError} is thrown immediately.
 * - Calls aborted through `options.signal` — the abort reason is rethrown as-is.
 *
 * ## Backoff
 * The delay before retry *n* (1-based) is `baseDelay * 2 ** (n - 1)`, capped at
 * `maxDelay`. By default "full jitter" is applied (`random()` in `[0, delay]`)
 * to avoid a thundering herd of clients retrying in lockstep. If the response
 * carries a `Retry-After` header (seconds or HTTP-date), that value takes
 * precedence over the computed backoff.
 *
 * @param {string} url                 Absolute URL to request.
 * @param {object} [options]           Options; everything except the keys listed
 *                                     below is forwarded verbatim to `fetch()`.
 * @param {number} [options.timeout=0] Per-attempt timeout in milliseconds.
 *                                     `0` (default) disables the timeout.
 * @param {number} [options.baseDelay=300]   Base backoff delay in milliseconds.
 * @param {number} [options.maxDelay=30000]  Maximum backoff delay in milliseconds.
 * @param {boolean} [options.jitter=true]    Apply random jitter to the backoff.
 *                                     Set to `false` for deterministic delays.
 * @param {AbortSignal} [options.signal]     Signal used to cancel the whole
 *                                     operation, including pending backoff waits.
 * @param {number} [retries=3]         Number of *retries* after the initial
 *                                     attempt. `retries = 3` means up to
 *                                     4 requests in total. `0` disables retries.
 *
 * @returns {Promise<Response>} The first successful (2xx) response.
 *
 * @throws {TypeError}  If `url` or `retries` are invalid.
 * @throws {HttpError}  If the server returns a non-OK status that is not
 *                      retried, or is still failing after the last attempt.
 *                      `error.status` and `error.response` are available.
 * @throws {Error}      The underlying network/timeout error if every attempt
 *                      failed. `error.attempts` holds the number of attempts.
 *
 * @example
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   { method: 'POST', body: JSON.stringify({ a: 1 }), timeout: 5_000 },
 *   3,
 * );
 * console.log(await res.json());
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  if (typeof url !== 'string' || url.length === 0) {
    throw new TypeError('fetchWithRetry: `url` must be a non-empty string.');
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError('fetchWithRetry: `retries` must be a non-negative integer.');
  }
  if (typeof fetch !== 'function') {
    throw new Error(
      'fetchWithRetry: global `fetch` is unavailable (requires Node.js 18+ or a browser).',
    );
  }

  const {
    timeout = 0,
    baseDelay = DEFAULT_BASE_DELAY_MS,
    maxDelay = DEFAULT_MAX_DELAY_MS,
    jitter = true,
    signal,
    ...fetchOptions
  } = options ?? {};

  let attempt = 0;

  for (;;) {
    attempt += 1;

    // ---- Attempt -----------------------------------------------------------
    let response;
    try {
      response = await performFetch(url, fetchOptions, timeout, signal);
    } catch (error) {
      // The caller cancelled: propagate immediately, never retry.
      if (signal?.aborted) throw error;

      if (attempt > retries) {
        if (error && typeof error === 'object') error.attempts = attempt;
        throw error;
      }

      await sleep(backoffDelay(attempt, baseDelay, maxDelay, jitter), signal);
      continue;
    }

    // ---- Success -----------------------------------------------------------
    if (response.ok) return response;

    // ---- Non-OK response ---------------------------------------------------
    const isRetryable = RETRYABLE_STATUS_CODES.has(response.status);
    if (!isRetryable || attempt > retries) {
      const error = new HttpError(
        response,
        `fetchWithRetry: ${url} responded with ${response.status} ${response.statusText}`,
      );
      error.attempts = attempt;
      throw error;
    }

    // Release the connection before retrying.
    await discardBody(response);

    const retryAfterMs = parseRetryAfter(response.headers.get('retry-after'));
    const delay =
      retryAfterMs !== null
        ? retryAfterMs
        : backoffDelay(attempt, baseDelay, maxDelay, jitter);

    await sleep(delay, signal);
  }
}

/**
 * Perform a single `fetch`, honouring the caller's abort signal and an
 * optional per-attempt timeout.
 *
 * @param {string} url
 * @param {object} fetchOptions
 * @param {number} timeout
 * @param {AbortSignal} [signal]
 * @returns {Promise<Response>}
 */
async function performFetch(url, fetchOptions, timeout, signal) {
  const controller = new AbortController();

  const onExternalAbort = () => controller.abort(abortReason(signal));
  if (signal) {
    if (signal.aborted) throw abortReason(signal);
    signal.addEventListener('abort', onExternalAbort, { once: true });
  }

  let timer = null;
  if (timeout > 0) {
    timer = setTimeout(() => {
      controller.abort(
        new DOMException(`fetchWithRetry: request timed out after ${timeout}ms`, 'TimeoutError'),
      );
    }, timeout);
    if (typeof timer.unref === 'function') timer.unref();
  }

  try {
    return await fetch(url, { ...fetchOptions, signal: controller.signal });
  } finally {
    if (timer) clearTimeout(timer);
    signal?.removeEventListener('abort', onExternalAbort);
  }
}

/**
 * Exponential backoff with optional full jitter.
 *
 * @param {number} attempt   1-based attempt number that just failed.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @param {boolean} jitter
 * @returns {number} Delay in milliseconds.
 */
function backoffDelay(attempt, baseDelay, maxDelay, jitter) {
  const exponential = Math.min(maxDelay, baseDelay * 2 ** (attempt - 1));
  return jitter ? Math.random() * exponential : exponential;
}

/**
 * Parse a `Retry-After` header (delta-seconds or HTTP-date).
 *
 * @param {string|null} value
 * @returns {number|null} Delay in milliseconds, or `null` if not parseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Sleep, rejecting early if the signal is aborted.
 *
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortReason(signal));
      return;
    }

    let timer;
    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };

    timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    if (typeof timer.unref === 'function') timer.unref();

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Cancel/drain a response body so the connection can be reused.
 *
 * @param {Response} response
 * @returns {Promise<void>}
 */
async function discardBody(response) {
  try {
    if (response.body && typeof response.body.cancel === 'function') {
      await response.body.cancel();
    } else if (typeof response.arrayBuffer === 'function') {
      await response.arrayBuffer();
    }
  } catch {
    // Ignore: the body is being thrown away anyway.
  }
}

/**
 * @param {AbortSignal} signal
 * @returns {Error} The abort reason, or a generic `AbortError`.
 */
function abortReason(signal) {
  return signal?.reason ?? new DOMException('The operation was aborted.', 'AbortError');
}
