### Behaviour summary

| Situation | Result |
|---|---|
| 2xx response | Resolved with the `Response` |
| Network error / timeout | Retried with exponential backoff |
| `408, 425, 429, 500, 502, 503, 504` | Retried with exponential backoff (honours `Retry-After`) |
| Other non-2xx (`400, 401, 404`, …) | Throws `HttpError` immediately (`error.status`, `error.response`) |
| `options.signal` aborted | Abort reason rethrown, no further attempts |
| All attempts exhausted | Throws the last `HttpError` / network error (`error.attempts`) |

Requires a global `fetch` (Node.js 18+, Deno, Bun, or a browser).

## `fetchWithRetry`

```js
/**
 * Default HTTP status codes that are considered transient and therefore
 * worth retrying. All other 4xx responses are treated as permanent errors.
 * @type {ReadonlySet<number>}
 */
const DEFAULT_RETRYABLE_STATUS = new Set([
  408, // Request Timeout
  425, // Too Early
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

/**
 * Creates an error describing an HTTP response that had a retryable status.
 * @param {Response} response
 * @param {number} status
 * @returns {Error}
 */
function httpError(response, status) {
  const err = new Error(`Request failed with status ${status} (${response.statusText || 'Unknown'})`);
  err.name = 'HttpError';
  err.status = status;
  err.response = response;
  return err;
}

/**
 * True if the error represents an explicit cancellation (AbortController).
 * These are never retried — the caller asked to stop.
 * @param {unknown} err
 * @returns {boolean}
 */
function isAbortError(err) {
  return (
    err instanceof Error &&
    (err.name === 'AbortError' || err.name === 'TimeoutError')
  );
}

/**
 * Parses a `Retry-After` header (delta-seconds or HTTP-date) into milliseconds.
 * @param {string | null} header
 * @returns {number | null} Delay in ms, or null if the header is absent/invalid.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Sleeps for `ms` milliseconds, rejecting early if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Computes the backoff delay for a given attempt (0-based).
 *
 * delay = min(maxDelay, baseDelay * 2^attempt), optionally randomized with
 * "full jitter" (uniformly distributed in [0, delay]) to avoid a thundering
 * herd when many clients fail at the same moment.
 *
 * @param {number} attempt Zero-based attempt index.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @param {boolean} jitter
 * @returns {number} Delay in milliseconds.
 */
function backoffDelay(attempt, baseDelay, maxDelay, jitter) {
  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return jitter ? Math.random() * exponential : exponential;
}

/**
 * Fetches a URL, retrying transient failures with exponential backoff.
 *
 * ## Retry policy
 * - **Network errors** (DNS failure, connection reset, TLS error, ...) are retried.
 * - **Retryable HTTP statuses** (408, 425, 429, 500, 502, 503, 504 by default) are retried.
 * - **Other 4xx statuses** are permanent and are returned immediately without retrying.
 * - **Aborted requests** are never retried; the abort error is rethrown.
 * - A `Retry-After` header on a 429/503 response takes precedence over the
 *   computed backoff delay.
 *
 * ## Semantics
 * - `retries` is the number of *additional* attempts after the first one, so
 *   the maximum number of requests is `retries + 1`.
 * - If every attempt fails with a network error, the last error is thrown.
 * - If every attempt returns a retryable HTTP status, the **final response is
 *   returned** (not thrown) so the caller can inspect `response.status` and
 *   the response body.
 *
 * @param {string | URL} url The resource to fetch.
 * @param {RequestInit} [options] Standard `fetch` options (method, headers,
 *   body, signal, ...). `options.signal` is honoured during backoff waits.
 * @param {number} [retries=3] Number of retries after the initial attempt.
 *   Must be a non-negative integer.
 * @param {object} [config] Optional tuning parameters.
 * @param {number} [config.baseDelay=300] Base backoff delay in milliseconds.
 * @param {number} [config.maxDelay=30000] Maximum single backoff delay in ms.
 * @param {boolean} [config.jitter=true] Whether to randomize delays (full jitter).
 * @param {(response: Response) => boolean} [config.shouldRetry] Custom predicate
 *   deciding whether a response should be retried. Defaults to the status set above.
 * @param {(info: {attempt: number, delay: number, error?: Error, response?: Response}) => void} [config.onRetry]
 *   Callback invoked before each backoff wait; useful for logging/metrics.
 * @returns {Promise<Response>} The successful response, or the last response if
 *   all attempts returned a retryable status.
 * @throws {Error} The last network error if all attempts fail, or an `AbortError`
 *   if the request is cancelled.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 5);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3, config = {}) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError('`retries` must be a non-negative integer.');
  }

  const {
    baseDelay = 300,
    maxDelay = 30_000,
    jitter = true,
    shouldRetry = (response) => DEFAULT_RETRYABLE_STATUS.has(response.status),
    onRetry,
  } = config;

  const signal = options.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const isLastAttempt = attempt === retries;

    try {
      const response = await fetch(url, options);

      // Success, a permanent failure, or no retries left: hand it back to the caller.
      if (!shouldRetry(response) || isLastAttempt) {
        return response;
      }

      // Release the connection before retrying.
      try {
        await response.body?.cancel();
      } catch {
        /* ignore: body may already be consumed or locked */
      }

      lastError = httpError(response, response.status);

      const retryAfter = parseRetryAfter(response.headers.get('retry-after'));
      const delay = retryAfter ?? backoffDelay(attempt, baseDelay, maxDelay, jitter);

      onRetry?.({ attempt: attempt + 1, delay, response, error: lastError });
      await sleep(delay, signal);
    } catch (err) {
      // Never retry cancellations.
      if (isAbortError(err) || signal?.aborted) throw err;

      lastError = err;
      if (isLastAttempt) throw err;

      const delay = backoffDelay(attempt, baseDelay, maxDelay, jitter);
      onRetry?.({ attempt: attempt + 1, delay, error: err });
      await sleep(delay, signal);
    }
  }

  /* istanbul ignore next — unreachable, but keeps the contract explicit. */
  throw lastError;
}
