 * Perform a `fetch()` request, retrying transient failures with exponential backoff.
 *
 * A request is retried when:
 *  - the network call rejects (DNS failure, connection reset, per-attempt timeout, …), or
 *  - the server responds with a retryable status (see `retryableStatuses`, default
 *    408/425/429/500/502/503/504).
 *
 * A non-retryable status (e.g. 400, 401, 404) fails fast with an {@link HttpError}.
 *
 * Backoff is exponential: `baseDelay * 2^attempt`, capped at `maxDelay`, with
 * "equal jitter" (50 % fixed + 50 % random) to avoid thundering herds. If the
 * response carries a `Retry-After` header (seconds or HTTP-date), that value is
 * honoured instead (still capped by `maxDelay`).
 *
 * @param {string | URL} url                 The resource to request.
 * @param {RequestInit & {
 *   signal?: AbortSignal,
 *   timeout?: number,
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   retryableStatuses?: readonly number[],
 *   onRetry?: (info: { attempt: number, delay: number, error: Error, response?: Response }) => void
 * }} [options]                              Standard `fetch` options plus the extras above.
 * @param {number} [retries=3]               Number of *retries* after the initial attempt
 *                                           (i.e. `retries = 3` ⇒ up to 4 requests total).
 * @returns {Promise<Response>}              The first successful (2xx) response.
 * @throws {HttpError}                       On a non-2xx response that is not retryable, or
 *                                           on the final failed attempt.
 * @throws {Error}                           On a network error / timeout after the last attempt.
 * @throws {Error | DOMException}            Immediately, if `options.signal` is aborted.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 5);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = DEFAULT_RETRIES) {
  if (typeof url !== 'string' && !(url instanceof URL)) {
    throw new TypeError('fetchWithRetry: `url` must be a string or URL.');
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('fetchWithRetry: `retries` must be a non-negative integer.');
  }

  const {
    signal: userSignal,
    timeout,
    baseDelay = DEFAULT_BASE_DELAY_MS,
    maxDelay = DEFAULT_MAX_DELAY_MS,
    retryableStatuses = DEFAULT_RETRYABLE_STATUSES,
    onRetry,
    ...fetchOptions
  } = options;

  const retryable = new Set(retryableStatuses);
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const isLastAttempt = attempt === retries;

    // ---- one attempt -------------------------------------------------
    const attemptCtl = createAttemptSignal(timeout, userSignal);
    let response;
    try {
      response = await fetch(url, { ...fetchOptions, signal: attemptCtl.signal });
    } catch (err) {
      attemptCtl.cleanup();
      // The caller cancelled → stop immediately, do not retry.
      if (userSignal?.aborted) throw err;

      lastError = err;
      if (isLastAttempt) break;

      const delay = backoffDelay(attempt, baseDelay, maxDelay);
      onRetry?.({ attempt: attempt + 1, delay, error: err });
      await wait(delay, userSignal);
      continue;
    }
    attemptCtl.cleanup();

    // ---- success -----------------------------------------------------
    if (response.ok) return response;

    // ---- HTTP error --------------------------------------------------
    const error = new HttpError(
      `fetchWithRetry: ${url} responded with ${response.status} ${response.statusText}`,
      response,
    );
    lastError = error;

    // Fail fast on client errors, or when no attempts remain.
    if (isLastAttempt || !retryable.has(response.status)) throw error;

    // Release the connection so the retry is not blocked by the unread body.
    try {
      await response.body?.cancel();
    } catch {
      /* ignore */
    }

    const delay = retryAfterDelay(response, attempt, baseDelay, maxDelay);
    onRetry?.({ attempt: attempt + 1, delay, error, response });
    await wait(delay, userSignal);
  }

  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/**
 * Exponential backoff with equal jitter, capped at `maxDelay`.
 * @param {number} attempt 0-based index of the attempt that just failed.
 */
function backoffDelay(attempt, baseDelay, maxDelay) {
  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return Math.round(exponential * (0.5 + Math.random() * 0.5));
}

/**
 * Use the server's `Retry-After` hint when present, otherwise fall back to backoff.
 * @param {Response} response
 */
function retryAfterDelay(response, attempt, baseDelay, maxDelay) {
  const header = response.headers?.get?.('retry-after');
  const parsed = parseRetryAfter(header);
  if (parsed !== null) return Math.min(parsed, maxDelay);
  return backoffDelay(attempt, baseDelay, maxDelay);
}

/**
 * Parse a `Retry-After` header (delta-seconds or HTTP-date) into milliseconds.
 * @returns {number | null} `null` when the header is absent or unparsable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Combine the caller's `AbortSignal` with an optional per-attempt timeout.
 * The returned signal aborts when either the user cancels or the timeout fires.
 */
function createAttemptSignal(timeout, userSignal) {
  const controller = new AbortController();
  let timer = null;

  const onUserAbort = () => controller.abort(userSignal.reason);
  if (userSignal) {
    if (userSignal.aborted) controller.abort(userSignal.reason);
    else userSignal.addEventListener('abort', onUserAbort, { once: true });
  }

  if (typeof timeout === 'number' && timeout > 0) {
    timer = setTimeout(() => {
      const err = new Error(`fetchWithRetry: request timed out after ${timeout}ms`);
      err.name = 'TimeoutError';
      controller.abort(err);
    }, timeout);
  }

  return {
    signal: controller.signal,
    cleanup() {
      if (timer) clearTimeout(timer);
      userSignal?.removeEventListener('abort', onUserAbort);
    },
  };
}

/**
 * Promise-based sleep that rejects immediately if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 */
function wait(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortReason(signal));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/** @returns {Error} The abort reason, or a generic `AbortError`. */
function abortReason(signal) {
  if (signal?.reason) return signal.reason;
  const err = new Error('The operation was aborted.');
  err.name = 'AbortError';
  return err;
}
```

### Usage

```js
import { fetchWithRetry, HttpError } from './fetchWithRetry.js';

// Simple: up to 4 total attempts (1 + 3 retries).
const res = await fetchWithRetry('https://api.example.com/users');

// Custom options: POST body, per-attempt timeout, logging, cancellation.
const controller = new AbortController();
setTimeout(() => controller.abort(), 10_000);

try {
  const res = await fetchWithRetry(
    'https://api.example.com/users',
    {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name: 'Ada' }),
      timeout: 5_000,          // aborts a single attempt after 5s
      baseDelay: 500,          // 500ms, 1s, 2s, 4s …
      maxDelay: 10_000,
      onRetry: ({ attempt, delay, error }) =>
        console.warn(`retry #${attempt} in ${delay}ms:`, error.message),
    },
    5,                        // up to 6 total attempts
  );
  console.log(await res.json());
} catch (err) {
  if (err instanceof HttpError) {
    console.error(`HTTP ${err.status}`, await err.response.text());
  } else {
    console.error('Request failed:', err);
  }
}
```

### Behaviour notes

- **Retry triggers:** network errors (including per-attempt timeouts) and retryable HTTP statuses. Other 4xx responses fail immediately with `HttpError`.
- **Backoff:** `baseDelay * 2^attempt`, capped at `maxDelay`, with equal jitter; a `Retry-After` header takes precedence.
- **Cancellation:** an aborted `options.signal` stops everything immediately (including the backoff wait) and rethrows the abort reason.
- **Timeout scope:** `options.timeout` limits each individual attempt up to the response headers; it does not cover streaming the response body.
- **Errors:** the last failure is thrown — `HttpError` for HTTP failures, the original error for network failures.

# `fetchWithRetry`

A dependency-free wrapper around `fetch` that retries transient failures using exponential backoff with jitter.

```js
/**
 * @file fetch-retry.js
 */

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * HTTP status codes that are considered *transient* — i.e. the same request
 * has a reasonable chance of succeeding if sent again.
 *
 * - 408 Request Timeout        — server gave up waiting
 * - 425 Too Early               — server is not ready to process the request
 * - 429 Too Many Requests       — rate limited (honour `Retry-After`)
 * - 500 Internal Server Error   — generic server-side fault
 * - 502 Bad Gateway             — upstream server failed
 * - 503 Service Unavailable     — overloaded or in maintenance
 * - 504 Gateway Timeout         — upstream server timed out
 *
 * @type {ReadonlySet<number>}
 */
const DEFAULT_RETRY_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

/** Delay before the first retry, in milliseconds. */
const DEFAULT_BASE_DELAY_MS = 300;

/** Upper bound for a single backoff delay, in milliseconds. */
const DEFAULT_MAX_DELAY_MS = 30_000;

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

/**
 * Error thrown (or attached to a retry) when a request ends with a retryable
 * HTTP error status.
 */
export class HttpError extends Error {
  /**
   * @param {Response} response The failing response.
   * @param {string} url        The requested URL.
   */
  constructor(response, url) {
    super(`Request to ${url} failed with status ${response.status} ${response.statusText}`);
    this.name = 'HttpError';
    this.status = response.status;
    this.statusText = response.statusText;
    this.url = url;
    /** @type {Response} */
    this.response = response;
  }
}

/**
 * Create an `AbortError`-style error.
 *
 * @param {*} [reason] Optional underlying reason.
 * @returns {Error} An error whose `name` is `"AbortError"`.
 */
function createAbortError(reason) {
  if (reason instanceof Error) return reason;
  const err = new Error(typeof reason === 'string' ? reason : 'The operation was aborted');
  err.name = 'AbortError';
  return err;
}

/**
 * Create a `TimeoutError`-style error.
 *
 * @param {number} ms The timeout that elapsed, in milliseconds.
 * @returns {Error} An error whose `name` is `"TimeoutError"`.
 */
function createTimeoutError(ms) {
  const err = new Error(`Request timed out after ${ms}ms`);
  err.name = 'TimeoutError';
  return err;
}

/**
 * Resolve after `ms` milliseconds, or reject immediately if `signal` aborts.
 *
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createAbortError(signal.reason));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(createAbortError(signal.reason));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Compute the backoff delay for a given attempt using *equal jitter*.
 *
 * The raw exponential delay is `base * 2^attempt`, capped at `maxDelayMs`.
 * Half of that value is fixed and half is random, which keeps a minimum
 * spacing between retries while still spreading a fleet of clients out over
 * time (avoiding the "thundering herd" problem).
 *
 * @param {number} attempt      Zero-based index of the attempt that just failed.
 * @param {number} baseDelayMs  Base delay in milliseconds.
 * @param {number} maxDelayMs   Maximum delay in milliseconds.
 * @returns {number} Delay in milliseconds.
 */
function computeBackoff(attempt, baseDelayMs, maxDelayMs) {
  const exponential = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
  return Math.round(exponential / 2 + Math.random() * (exponential / 2));
}

/**
 * Parse a `Retry-After` header into milliseconds.
 *
 * Supports both forms defined by RFC 9110:
 * - `Retry-After: 120`        → delay in seconds
 * - `Retry-After: Wed, 21 Oct 2015 07:28:00 GMT` → an HTTP date
 *
 * @param {string|null} header Raw header value.
 * @param {number} [now]       Current epoch time (ms), injectable for testing.
 * @returns {number|null} Delay in milliseconds, or `null` if not parseable.
 */
function parseRetryAfter(header, now = Date.now()) {
  if (!header) return null;

  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(header);
  if (Number.isNaN(date)) return null;
  return Math.max(0, date - now);
}

/**
 * Release the resources held by a response we are about to discard.
 *
 * Without this, an unread body keeps the connection open and can exhaust the
 * HTTP agent's socket pool under load.
 *
 * @param {Response} response
 * @returns {Promise<void>}
 */
async function discardBody(response) {
  try {
    if (response.body && typeof response.body.cancel === 'function') {
      await response.body.cancel();
    } else if (typeof response.arrayBuffer === 'function') {
      await response.arrayBuffer();
    }
  } catch {
    /* The body was already consumed or the connection is gone — ignore. */
  }
}

/**
 * Build a per-attempt `AbortSignal` that combines the caller's signal with an
 * optional per-attempt timeout.
 *
 * @param {AbortSignal} [userSignal]
 * @param {number} [timeoutMs]
 * @returns {{ signal: AbortSignal|undefined, cleanup: () => void }}
 */
function createAttemptSignal(userSignal, timeoutMs) {
  if (!userSignal && !timeoutMs) {
    return { signal: undefined, cleanup: () => {} };
  }

  const controller = new AbortController();
  let timer;

  const onUserAbort = () => controller.abort(userSignal?.reason);
  if (userSignal) {
    if (userSignal.aborted) {
      controller.abort(userSignal.reason);
    } else {
      userSignal.addEventListener('abort', onUserAbort, { once: true });
    }
  }

  if (timeoutMs > 0) {
    timer = setTimeout(() => controller.abort(createTimeoutError(timeoutMs)), timeoutMs);
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      if (timer) clearTimeout(timer);
      userSignal?.removeEventListener('abort', onUserAbort);
    },
  };
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Perform an HTTP request, retrying transient failures with exponential
 * backoff and jitter.
 *
 * ## Behaviour
 *
 * - **Attempts:** the request is sent at most `retries + 1` times
 *   (`retries = 0` means a single attempt, no retry).
 * - **Retryable failures:** network/transport errors (e.g. `TypeError:
 *   fetch failed`, DNS failures, connection resets) and responses whose status
 *   is in `retry.retryOnStatus` (default: 408, 425, 429, 500, 502, 503, 504).
 * - **Non-retryable failures:** 4xx client errors (other than the ones above)
 *   are returned immediately — resending them will not help.
 * - **Backoff:** `min(maxDelayMs, baseDelayMs * 2^attempt)`, split 50/50 into a
 *   fixed and a random component ("equal jitter"). A `Retry-After` header on a
 *   429/503 response takes precedence over the computed delay.
 * - **Cancellation:** if `options.signal` aborts, the pending request and any
 *   pending backoff delay are aborted immediately and the abort reason is
 *   thrown. Aborts are never retried.
 * - **Result:** the function resolves with the last `Response`, *even if* that
 *   response has an error status. Check `response.ok` / `response.status`.
 *   Transport errors that survive every attempt are thrown.
 *
 * ## ⚠️ Idempotency
 *
 * Retrying is only safe for idempotent requests. By default every HTTP method
 * is retried, which can duplicate side effects for `POST`. Either restrict
 * `retry.retryMethods`, or send an `Idempotency-Key` header so the server can
 * de-duplicate the replay.
 *
 * @param {string|URL} url
 *   The URL to request.
 * @param {RequestInit & {
 *   timeoutMs?: number,
 *   retry?: {
 *     baseDelayMs?: number,
 *     maxDelayMs?: number,
 *     retryOnStatus?: Iterable<number>,
 *     retryOnNetworkError?: boolean,
 *     respectRetryAfter?: boolean,
 *     retryMethods?: Iterable<string>,
 *     fetchImpl?: typeof fetch,
 *     onRetry?: (info: { attempt: number, delayMs: number, error?: Error, response?: Response }) => void,
 *   },
 * }} [options]
 *   Standard `fetch` options, plus:
 *   - `timeoutMs` — per-attempt timeout in milliseconds (`0`/omitted = no timeout).
 *   - `retry` — tuning knobs for the retry behaviour (see above).
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one.
 * @returns {Promise<Response>} The final response.
 * @throws {Error} If the caller aborts, or if every attempt failed with a
 *   transport-level error.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 *
 * @example
 * // With a timeout, a custom backoff and retry logging
 * const res = await fetchWithRetry(
 *   'https://api.example.com/data',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json', 'Idempotency-Key': key },
 *     body: JSON.stringify(payload),
 *     timeoutMs: 5_000,
 *     retry: {
 *       baseDelayMs: 500,
 *       maxDelayMs: 10_000,
 *       onRetry: ({ attempt, delayMs, error }) =>
 *         console.warn(`attempt ${attempt} failed (${error?.message}); retrying in ${delayMs}ms`),
 *     },
 *   },
 *   5,
 * );
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`"retries" must be a non-negative integer, received ${retries}`);
  }

  const {
    timeoutMs = 0,
    retry: retryOptions = {},
    signal: userSignal,
    ...init
  } = options;

  const {
    baseDelayMs = DEFAULT_BASE_DELAY_MS,
    maxDelayMs = DEFAULT_MAX_DELAY_MS,
    retryOnStatus = DEFAULT_RETRY_STATUS_CODES,
    retryOnNetworkError = true,
    respectRetryAfter = true,
    retryMethods = null, // null → retry every method
    fetchImpl = globalThis.fetch?.bind(globalThis),
    onRetry = null,
  } = retryOptions;

  if (typeof fetchImpl !== 'function') {
    throw new TypeError('No fetch implementation available; pass `retry.fetchImpl`.');
  }

  const retryableStatuses = retryOnStatus instanceof Set ? retryOnStatus : new Set(retryOnStatus);
  const allowedMethods = retryMethods
    ? new Set([...retryMethods].map((m) => m.toUpperCase()))
    : null;

  const method = (init.method ?? 'GET').toUpperCase();
  const methodIsRetryable = !allowedMethods || allowedMethods.has(method);

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    const isLastAttempt = attempt === retries;
    const { signal, cleanup } = createAttemptSignal(userSignal, timeoutMs);

    try {
      const response = await fetchImpl(url, { ...init, signal });

      const statusIsRetryable = retryableStatuses.has(response.status);

      // Success, a non-retryable status, or no attempts left → hand it back.
      if (!statusIsRetryable || isLastAttempt || !methodIsRetryable) {
        return response;
      }

      // Retryable status: capture the context, release the body, then back off.
      const error = new HttpError(response, String(url));
      lastError = error;

      const retryAfterMs = respectRetryAfter
        ? parseRetryAfter(response.headers.get('retry-after'))
        : null;
      const delayMs = retryAfterMs ?? computeBackoff(attempt, baseDelayMs, maxDelayMs);

      onRetry?.({ attempt: attempt + 1, delayMs, error, response });

      await discardBody(response);
      await sleep(delayMs, userSignal);
    } catch (error) {
      // A user-initiated abort must never be retried.
      if (userSignal?.aborted) throw error;

      const isTimeout = error?.name === 'TimeoutError';
      const isTransportError = !(error instanceof HttpError);

      if (!isTransportError || (!isTimeout && !retryOnNetworkError) || isLastAttempt) {
        throw error;
      }

      lastError = error;
      const delayMs = computeBackoff(attempt, baseDelayMs, maxDelayMs);
      onRetry?.({ attempt: attempt + 1, delayMs, error });
      await sleep(delayMs, userSignal);
    } finally {
      cleanup();
    }
  }

  /* istanbul ignore next — the loop always returns or throws. */
  throw lastError ?? new Error(`Request to ${url} failed`);
}
