## Usage

```js
// Simple: 3 retries (4 attempts total) with the default backoff.
const res = await fetchWithRetry('https://api.example.com/users');

// Custom backoff + logging + per-attempt timeout.
const res = await fetchWithRetry(
  'https://api.example.com/orders',
  {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Idempotency-Key': crypto.randomUUID() },
    body: JSON.stringify(order),
    timeoutMs: 5_000,
    retry: {
      baseDelayMs: 500,
      maxDelayMs: 15_000,
      onRetry: ({ attempt, delayMs, error }) =>
        console.warn(`#${attempt} failed: ${error?.message} — retrying in ${delayMs}ms`),
    },
  },
  5,
);

// Only retry safe methods.
await fetchWithRetry(url, { retry: { retryMethods: ['GET', 'HEAD'] } }, 3);

// Cancel in-flight work.
const controller = new AbortController();
setTimeout(() => controller.abort(), 1_000);
await fetchWithRetry(url, { signal: controller.signal }, 5);
```

## Design notes

| Concern | Decision |
|---|---|
| **Which failures retry?** | Transport errors + a configurable set of transient statuses. 4xx client errors are returned immediately. |
| **Backoff shape** | Exponential (`base * 2^attempt`), capped, with *equal jitter* (50 % fixed / 50 % random) to avoid thundering herds. |
| **`Retry-After`** | Honoured for `429`/`503` when present and parseable (seconds or HTTP-date). |
| **Result vs. throw** | Resolves with the last `Response` (check `response.ok`); throws only on transport failure or abort. This keeps `fetch`-like semantics. |
| **Body leaks** | Bodies of discarded responses are cancelled so sockets are released. |
| **Timeouts** | Per attempt, via an internal `AbortController`; a timeout is treated as a transient failure and is retried. |
| **Cancellation** | The caller's `signal` aborts both the request and the pending backoff sleep; aborts are never retried. |
| **Idempotency** | Documented, with `retry.retryMethods` and `Idempotency-Key` guidance for `POST`. |

If you need this in a different runtime (e.g. `node-fetch` v2, or a `fetch` that lacks `AbortSignal` support), pass a compatible implementation via `retry.fetchImpl`.

## `fetchWithRetry`

```js
/**
 * @file Retry-aware wrapper around the global `fetch` API (Node 18+, Deno, Bun, browsers).
 */

/** HTTP status codes treated as transient failures that are worth retrying. */
const DEFAULT_RETRIABLE_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

const DEFAULT_TIMEOUT_MS = 10_000;   // per attempt
const DEFAULT_BASE_DELAY_MS = 300;   // first backoff delay
const DEFAULT_MAX_DELAY_MS = 30_000; // backoff ceiling

/**
 * Parses a `Retry-After` header (delta-seconds or HTTP-date) into milliseconds.
 * @param {string | null} header
 * @returns {number | null} Milliseconds to wait, or `null` if the header is absent/invalid.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(header);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Computes the delay before the next attempt: exponential backoff with
 * "equal jitter" (half fixed, half random) to avoid thundering herds.
 *
 * @param {number} attempt Zero-based index of the attempt that just failed.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @param {number | null} retryAfterMs Server-requested delay, if any.
 * @returns {number} Delay in milliseconds.
 */
function computeDelay(attempt, baseDelay, maxDelay, retryAfterMs) {
  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  const jittered = exponential / 2 + Math.random() * (exponential / 2);

  if (retryAfterMs != null) {
    // Honour the server's instruction, but never wait longer than `maxDelay`.
    return Math.min(maxDelay, Math.max(jittered, retryAfterMs));
  }
  return jittered;
}

/**
 * Promise-based sleep that rejects immediately if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal | undefined} signal
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Creates a signal that aborts after `ms` milliseconds.
 * @param {number} ms `0`/negative disables the timeout.
 * @returns {AbortSignal | undefined}
 */
function createTimeoutSignal(ms) {
  if (!ms || ms <= 0) return undefined;

  if (typeof AbortSignal?.timeout === 'function') return AbortSignal.timeout(ms);

  // Fallback for older runtimes.
  const controller = new AbortController();
  const timer = setTimeout(
    () => controller.abort(new DOMException('The operation timed out.', 'TimeoutError')),
    ms,
  );
  timer.unref?.();
  return controller.signal;
}

/**
 * Combines several signals into one that aborts as soon as any of them does.
 * @param {Array<AbortSignal | undefined>} signals
 * @returns {AbortSignal | undefined}
 */
function combineSignals(signals) {
  const active = signals.filter(Boolean);
  if (active.length === 0) return undefined;
  if (active.length === 1) return active[0];

  const controller = new AbortController();
  for (const signal of active) {
    if (signal.aborted) {
      controller.abort(signal.reason);
      break;
    }
    signal.addEventListener('abort', () => controller.abort(signal.reason), { once: true });
  }
  return controller.signal;
}

/**
 * Fetches a URL, retrying transient failures with exponential backoff.
 *
 * ## What is retried
 * - **Network errors** (DNS failure, connection reset, socket hang up, …).
 * - **Timeouts** of a single attempt.
 * - **Transient HTTP statuses**: `408`, `425`, `429`, `500`, `502`, `503`, `504`
 *   (override with `options.retriableStatusCodes`).
 *
 * ## What is *not* retried
 * - Other `4xx` statuses (e.g. `404`, `401`) — they are returned as-is.
 * - Aborts triggered by the caller's `options.signal` — the error is rethrown immediately.
 *
 * ## Return value
 * Resolves with the `Response` of the first attempt that is either successful or
 * non-retriable (including the final failed attempt). It does **not** throw on
 * HTTP error statuses; check `response.ok` / `response.status` yourself.
 * It throws only when every attempt failed at the network/timeout level.
 *
 * ## Backoff
 * Delay before attempt *n* is `baseDelay * 2 ** n`, capped at `maxDelay`, with
 * equal jitter applied. A `Retry-After` header (on `429`/`503`) takes precedence
 * over the computed delay, but is still capped at `maxDelay`.
 *
 * ## Body replayability
 * The request body must be replayable across attempts (string, `Buffer`,
 * `Blob`, `FormData`, `URLSearchParams`, …). A one-shot stream body cannot be
 * re-sent and will fail on the second attempt.
 *
 * @param {string | URL} url The resource to fetch.
 * @param {RequestInit & {
 *   timeout?: number,
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   retriableStatusCodes?: Iterable<number>,
 *   onRetry?: (info: { attempt: number, delay: number, url: string | URL,
 *                       error?: unknown, response?: Response }) => void | Promise<void>
 * }} [options] Standard `fetch` options plus the retry-specific extras below.
 *   All non-reserved keys are forwarded to `fetch` untouched.
 * @param {number} [retries=3] Number of *additional* attempts after the first
 *   (i.e. `retries: 3` means up to 4 requests in total). Negative/fractional
 *   values are clamped to `0`.
 * @returns {Promise<Response>} The response of the first usable attempt.
 * @throws {Error} The last network/timeout error if all attempts fail, or the
 *   abort reason if the caller aborts.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {
 *   method: 'POST',
 *   headers: { 'content-type': 'application/json' },
 *   body: JSON.stringify({ hello: 'world' }),
 *   timeout: 5_000,
 *   onRetry: ({ attempt, delay, error }) =>
 *     console.warn(`Attempt ${attempt} failed (${error?.message}); retrying in ${delay}ms`),
 * }, 5);
 *
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    timeout = DEFAULT_TIMEOUT_MS,
    baseDelay = DEFAULT_BASE_DELAY_MS,
    maxDelay = DEFAULT_MAX_DELAY_MS,
    retriableStatusCodes = DEFAULT_RETRIABLE_STATUS_CODES,
    onRetry,
    ...fetchOptions
  } = options ?? {};

  const maxRetries = Number.isFinite(retries) ? Math.max(0, Math.floor(retries)) : 0;
  const totalAttempts = maxRetries + 1;
  const retriable = retriableStatusCodes instanceof Set
    ? retriableStatusCodes
    : new Set(retriableStatusCodes);
  const callerSignal = fetchOptions.signal;

  let lastError;

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    const isLastAttempt = attempt === totalAttempts - 1;

    // Per-attempt timeout combined with the caller's cancellation signal.
    const signal = combineSignals([callerSignal, createTimeoutSignal(timeout)]);

    let response;
    let error;

    try {
      response = await fetch(url, { ...fetchOptions, signal });
    } catch (err) {
      error = err;
    }

    // --- Network error / timeout -------------------------------------------
    if (error) {
      // The caller cancelled: stop immediately, do not retry.
      if (callerSignal?.aborted) throw error;
      if (isLastAttempt) throw error;

      lastError = error;
      const delay = computeDelay(attempt, baseDelay, maxDelay, null);
      await onRetry?.({ attempt: attempt + 1, delay, url, error });
      await sleep(delay, callerSignal);
      continue;
    }

    // --- HTTP response ------------------------------------------------------
    if (response.ok || !retriable.has(response.status) || isLastAttempt) {
      return response;
    }

    // Transient status: release the connection, then back off and retry.
    const retryAfterMs = parseRetryAfter(response.headers.get('retry-after'));
    const delay = computeDelay(attempt, baseDelay, maxDelay, retryAfterMs);

    try {
      await response.body?.cancel();
    } catch {
      /* ignore: best-effort connection cleanup */
    }

    await onRetry?.({ attempt: attempt + 1, delay, url, response });
    await sleep(delay, callerSignal);
  }

  /* istanbul ignore next — unreachable in practice */
  throw lastError ?? new Error(`Failed to fetch ${url}`);
}
```

### Behaviour summary

| Situation | Action |
|---|---|
| Network error / attempt timeout | Retry with exponential backoff + jitter |
| `408, 425, 429, 500, 502, 503, 504` | Retry (honouring `Retry-After`) |
| Other `4xx`/`5xx` | Return the response immediately |
| Caller's `AbortSignal` fires | Abort immediately, no further retries |
| All attempts exhausted | Throw the last network/timeout error |

### Usage

```js
// Simple GET with 3 retries (4 attempts total)
const res = await fetchWithRetry('https://api.example.com/users', {}, 3);

// POST with a custom timeout and logging
const created = await fetchWithRetry('https://api.example.com/users', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ name: 'Ada' }),
  timeout: 5_000,
  baseDelay: 500,
  maxDelay: 10_000,
  onRetry: ({ attempt, delay, error }) =>
    console.warn(`Attempt ${attempt} failed: ${error?.message ?? 'HTTP error'}; retry in ${delay}ms`),
}, 5);

// Cancellable request
const controller = new AbortController();
setTimeout(() => controller.abort(), 2_000);
await fetchWithRetry('https://slow.example.com', { signal: controller.signal }, 3);
```

## `fetchWithRetry`

```js
/**
 * Retryable HTTP status codes: transient server/rate-limit conditions.
 * 4xx codes not listed here (400, 401, 403, 404, ...) are treated as
 * permanent failures and are returned to the caller immediately.
 */
const RETRYABLE_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

/**
 * Error thrown when a request fails with a network/transport error
 * (DNS failure, connection reset, TLS error, timeout, ...).
 */
export class NetworkError extends Error {
  constructor(message, { cause, attempts } = {}) {
    super(message, { cause });
    this.name = 'NetworkError';
    this.attempts = attempts;
  }
}

/**
 * Fetch a URL, retrying transient failures with exponential backoff + jitter.
 *
 * ## Behaviour
 * - A request is *retried* when the transport fails (network error / timeout)
 *   or when the server answers with a retryable status (see above).
 * - The delay before attempt *n* is `baseDelay * 2 ** n`, capped at `maxDelay`,
 *   then randomised ("equal jitter") so that many clients retrying at once
 *   do not stampede the server.
 * - A `Retry-After` response header (seconds or HTTP-date) takes precedence
 *   over the computed backoff, honouring server-side rate limits.
 * - The caller's `AbortSignal` always wins: if it aborts, the promise rejects
 *   immediately and no further attempts are made.
 * - Each attempt gets its own timeout (`options.timeout`).
 *
 * ## Return value
 * Resolves with the `Response` of the **last** attempt. HTTP error statuses
 * are *not* thrown — inspect `response.ok` / `response.status` yourself.
 * Only transport failures reject (after the retries are exhausted).
 *
 * @param {string | URL} url                 The resource to fetch.
 * @param {object}  [options]                Standard `fetch` options plus:
 * @param {number}  [options.timeout=10000]   Per-attempt timeout in ms (0 = no timeout).
 * @param {number}  [options.baseDelay=300]   Base backoff delay in ms.
 * @param {number}  [options.maxDelay=30000]  Upper bound for any single delay in ms.
 * @param {Function} [options.retryOn]        `(error, response) => boolean`.
 *                                           Called after each failed attempt to decide
 *                                           whether to retry. Defaults to
 *                                           "retry network errors and retryable statuses".
 * @param {RequestInit} [options...]          `method`, `headers`, `body`, `signal`, ...
 *                                           `body` may be a **function** returning a fresh
 *                                           body, so it can be replayed on every attempt.
 * @param {number}  [retries=3]               Number of *additional* attempts after the
 *                                           first one (total attempts = `retries + 1`).
 * @returns {Promise<Response>}
 * @throws {NetworkError} When every attempt failed at the transport level.
 * @throws {Error}         The abort reason, if the caller's signal was aborted.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {
 *   headers: { Authorization: `Bearer ${token}` },
 *   timeout: 5_000,
 * }, 5);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    timeout = 10_000,
    baseDelay = 300,
    maxDelay = 30_000,
    retryOn = defaultShouldRetry,
    ...init
  } = options;

  const callerSignal = init.signal;
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const isLastAttempt = attempt === retries;

    try {
      const response = await performFetch(url, init, timeout, callerSignal);

      // A retryable status, and we still have attempts left -> back off and retry.
      if (!isLastAttempt && retryOn(null, response)) {
        await discardBody(response); // free the socket before the next attempt
        await sleep(computeDelay(attempt, response, baseDelay, maxDelay), callerSignal);
        continue;
      }

      return response; // success, or a permanent/final failure the caller must handle
    } catch (error) {
      // The caller cancelled: propagate immediately, never retry.
      if (callerSignal?.aborted) throw error;

      lastError = error;

      if (isLastAttempt || !retryOn(error, null)) {
        throw new NetworkError(
          `fetch failed after ${attempt + 1} attempt(s): ${error?.message ?? error}`,
          { cause: error, attempts: attempt + 1 },
        );
      }

      await sleep(computeDelay(attempt, null, baseDelay, maxDelay), callerSignal);
    }
  }

  /* istanbul ignore next — unreachable, the loop always returns or throws */
  throw lastError;
}

/* ------------------------------------------------------------------ */
/* Internals                                                           */
/* ------------------------------------------------------------------ */

/**
 * Default retry policy: retry transport errors and transient HTTP statuses.
 * @param {Error|null} error
 * @param {Response|null} response
 * @returns {boolean}
 */
function defaultShouldRetry(error, response) {
  if (response) return RETRYABLE_STATUS_CODES.has(response.status);
  if (!error) return false;
  // Timeouts and network errors (TypeError in browsers/undici) are transient.
  return true;
}

/**
 * Perform a single fetch attempt with its own timeout and abort handling.
 * @returns {Promise<Response>}
 */
async function performFetch(url, init, timeout, callerSignal) {
  const controller = new AbortController();
  const timer =
    timeout > 0
      ? setTimeout(
          () => controller.abort(new DOMException(`Timed out after ${timeout}ms`, 'TimeoutError')),
          timeout,
        )
      : null;

  const signal = combineSignals([controller.signal, callerSignal]);
  // A body factory lets non-replayable payloads (streams) be re-created per attempt.
  const body = typeof init.body === 'function' ? init.body() : init.body;

  try {
    return await fetch(url, { ...init, body, signal });
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * Combine several AbortSignals into one.
 * @param {Array<AbortSignal|undefined|null>} signals
 * @returns {AbortSignal|undefined}
 */
function combineSignals(signals) {
  const list = signals.filter(Boolean);
  if (list.length === 0) return undefined;
  if (list.length === 1) return list[0];
  if (typeof AbortSignal.any === 'function') return AbortSignal.any(list);

  // Fallback for older runtimes.
  const controller = new AbortController();
  for (const signal of list) {
    if (signal.aborted) {
      controller.abort(signal.reason);
      break;
    }
    signal.addEventListener('abort', () => controller.abort(signal.reason), { once: true });
  }
  return controller.signal;
}

/**
 * Compute the delay before the next attempt.
 * @param {number} attempt  Zero-based index of the attempt that just failed.
 * @param {Response|null} response
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @returns {number} Milliseconds to wait.
 */
function computeDelay(attempt, response, baseDelay, maxDelay) {
  const retryAfter = response ? parseRetryAfter(response.headers?.get?.('retry-after')) : null;
  if (retryAfter != null) return Math.min(retryAfter, maxDelay);

  const backoff = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return backoff / 2 + Math.random() * (backoff / 2); // equal jitter
}

/**
 * Parse a `Retry-After` header (delta-seconds or HTTP-date).
 * @param {string|null} value
 * @returns {number|null} Milliseconds, or null if absent/unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const timestamp = Date.parse(value);
  if (Number.isNaN(timestamp)) return null;
  return Math.max(0, timestamp - Date.now());
}

/**
 * Cancel a response body so the connection can be reused.
 * @param {Response} response
 */
async function discardBody(response) {
  try {
    await response.body?.cancel();
  } catch {
    /* the body may already be closed — nothing to do */
  }
}

/**
 * Promise-based sleep that can be interrupted by an AbortSignal.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
