```js
// Simple: 3 retries (4 attempts total) on 5xx / 429 / network errors.
const res = await fetchWithRetry('https://api.example.com/users', {}, 3);
if (!res.ok) throw new Error(`HTTP ${res.status}`);
console.log(await res.json());

// With a timeout, custom headers and a caller-controlled abort.
const controller = new AbortController();
setTimeout(() => controller.abort(), 30_000);

const res = await fetchWithRetry(
  'https://api.example.com/orders',
  {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ sku: 'A-1' }),   // string bodies are replayed automatically
    timeout: 5_000,                          // per attempt
    signal: controller.signal,
  },
  5,
);

// Non-replayable body: pass a factory so each attempt gets a fresh stream.
await fetchWithRetry(url, { method: 'POST', body: () => fs.createReadStream('big.csv') }, 3);

// Custom policy: also retry 409 (conflict).
await fetchWithRetry(
  url,
  { retryOn: (err, res) => !!res && [409, 429, 503].includes(res.status) },
  4,
);
```

### Design notes

- **What is retried:** transport errors (DNS, connection reset, TLS, timeouts) and transient statuses `408, 425, 429, 500, 502, 503, 504`. Permanent `4xx` responses are returned immediately — retrying them just wastes time.
- **Backoff:** `baseDelay * 2^attempt`, capped at `maxDelay`, with equal jitter (`delay/2 + random*delay/2`). Jitter is what prevents a fleet of clients from retrying in lockstep after a server outage.
- **`Retry-After`:** honoured when present, so a `429` with `Retry-After: 30` waits 30 s instead of the computed backoff.
- **Timeouts vs. cancellation:** the per-attempt timeout is implemented with an internal `AbortController` combined with the caller's signal, so a caller abort aborts the in-flight request *and* the backoff sleep.
- **Bodies:** a plain string/`Buffer` body is replayed as-is; pass a function for streams so each attempt gets a fresh one.
- **Errors:** HTTP failures resolve with the `Response` (fetch-like semantics — check `res.ok`); only transport failures reject, wrapped in `NetworkError` with `cause` and `attempts` attached.

Below is a production‑grade implementation. It handles the things people usually forget: **which** failures are worth retrying, **jitter** (so you don't get a thundering herd), **`Retry-After`** headers, **per‑attempt timeouts**, **cancellation**, and **draining the body** of failed responses so sockets aren't leaked.

```js
/**
 * @file fetch-retry
 * @module fetch-retry
 */

/**
 * HTTP status codes that are considered *transient* by default.
 * 4xx codes other than these are almost always a client bug and are NOT retried.
 * @type {ReadonlySet<number>}
 */
const DEFAULT_RETRYABLE_STATUS_CODES = new Set([
  408, // Request Timeout
  425, // Too Early
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

/** @type {Readonly<Required<Pick<RetryOptions, 'retries'|'baseDelay'|'maxDelay'|'factor'|'jitter'|'timeout'|'respectRetryAfter'>>>} */
const DEFAULTS = {
  retries: 3,
  baseDelay: 300,   // ms before the *first* retry
  maxDelay: 30_000, // ms ceiling for a single backoff wait
  factor: 2,        // exponential growth factor
  jitter: true,     // full jitter: random(0, delay)
  timeout: 0,       // per-attempt timeout in ms (0 = no timeout)
  respectRetryAfter: true,
};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

/**
 * Create an `AbortError`-shaped error.
 * @param {string} message
 * @returns {Error}
 */
function abortError(message = 'The operation was aborted.') {
  if (typeof DOMException === 'function') {
    return new DOMException(message, 'AbortError');
  }
  const err = new Error(message);
  err.name = 'AbortError';
  return err;
}

/**
 * Resolve after `ms` milliseconds, rejecting early if `signal` is aborted.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? abortError());
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      signal?.removeEventListener('abort', onAbort);
      reject(signal.reason ?? abortError());
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Build the signal used for a single attempt: the caller's signal, optionally
 * combined with a per-attempt timeout.
 * @param {number} timeoutMs
 * @param {AbortSignal} [parentSignal]
 * @returns {{ signal: AbortSignal|undefined, cleanup: () => void }}
 */
function createAttemptSignal(timeoutMs, parentSignal) {
  if (!timeoutMs || timeoutMs <= 0) {
    return { signal: parentSignal, cleanup: () => {} };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => {
    controller.abort(
      typeof DOMException === 'function'
        ? new DOMException(`Request timed out after ${timeoutMs}ms`, 'TimeoutError')
        : Object.assign(new Error(`Request timed out after ${timeoutMs}ms`), { name: 'TimeoutError' }),
    );
  }, timeoutMs);

  const onParentAbort = () => controller.abort(parentSignal?.reason);
  if (parentSignal) {
    if (parentSignal.aborted) controller.abort(parentSignal.reason);
    else parentSignal.addEventListener('abort', onParentAbort, { once: true });
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timer);
      parentSignal?.removeEventListener('abort', onParentAbort);
    },
  };
}

/**
 * Compute an exponential backoff delay with optional full jitter.
 * @param {number} attempt Zero-based index of the attempt that just failed.
 * @param {{ baseDelay: number, maxDelay: number, factor: number, jitter: boolean }} cfg
 * @returns {number} Delay in milliseconds.
 */
function computeBackoff(attempt, { baseDelay, maxDelay, factor, jitter }) {
  const exponential = baseDelay * factor ** attempt;
  const capped = Math.min(exponential, maxDelay);
  return Math.round(jitter ? Math.random() * capped : capped);
}

/**
 * Parse a `Retry-After` header (delta-seconds or HTTP-date) into milliseconds.
 * @param {string|null} value
 * @returns {number|null} Milliseconds to wait, or `null` if unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (Number.isNaN(date)) return null;

  return Math.max(0, date - Date.now());
}

/**
 * Release the connection held by a response we are about to discard.
 * @param {Response} response
 * @returns {Promise<void>}
 */
async function discardBody(response) {
  try {
    if (response.body && !response.bodyUsed) {
      await response.body.cancel();
    }
  } catch {
    /* best effort — the body may already be closed */
  }
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Error thrown when every attempt failed at the network level.
 */
export class RetryError extends Error {
  /**
   * @param {string} url
   * @param {number} attempts
   * @param {Error} cause
   */
  constructor(url, attempts, cause) {
    super(`fetchWithRetry: ${url} failed after ${attempts} attempt(s): ${cause?.message ?? cause}`, {
      cause,
    });
    this.name = 'RetryError';
    this.url = url;
    this.attempts = attempts;
  }
}

/**
 * Fetch a URL, retrying transient failures with exponential backoff.
 *
 * ### What gets retried
 * - **Network errors** (`TypeError: fetch failed`, DNS failures, connection resets).
 * - **Per-attempt timeouts** (see `timeout`).
 * - **Transient HTTP statuses** — by default `408, 425, 429, 500, 502, 503, 504`.
 *
 * ### What does NOT get retried
 * - `4xx` client errors other than the ones listed above (a `400` will never
 *   succeed on a second try).
 * - Aborts caused by the caller's `AbortSignal` — cancellation is final.
 *
 * ### Backoff
 * The wait before retry *n* (0-based) is `baseDelay * factor ** n`, capped at
 * `maxDelay`. With `jitter: true` (the default) the actual wait is
 * `random(0, delay)` — "full jitter", which is the best-known way to avoid
 * synchronised retry storms across many clients. If the server sends a
 * `Retry-After` header it takes precedence (still capped at `maxDelay`).
 *
 * ### Return value
 * - On success (or a non-retryable status) the `Response` is returned as-is.
 * - If all attempts are exhausted and the last attempt produced an HTTP error
 *   response, that response is returned so the caller can inspect
 *   `status`/`body`. **Check `response.ok`.**
 * - If all attempts are exhausted and the last attempt failed at the network
 *   level, a {@link RetryError} is thrown.
 *
 * @param {string|URL} url The resource to fetch.
 * @param {RetryOptions & RequestInit} [options] Standard `fetch` init plus retry options.
 * @param {number} [retries=3] Number of *additional* attempts after the first.
 *   Total attempts = `retries + 1`. `options.retries` takes precedence.
 * @returns {Promise<Response>} The response of the first successful (or final) attempt.
 * @throws {RetryError} When every attempt failed at the network level.
 * @throws {Error} The abort reason when the caller's `AbortSignal` fires.
 *
 * @example
 * // Basic usage — up to 4 total attempts.
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 *
 * @example
 * // POST with an idempotency key, a 5s per-attempt timeout, and logging.
 * const res = await fetchWithRetry('https://api.example.com/pay', {
 *   method: 'POST',
 *   headers: { 'content-type': 'application/json', 'idempotency-key': key },
 *   body: JSON.stringify(payload),
 *   timeout: 5_000,
 *   retries: 5,
 *   onRetry: ({ attempt, delay, error, response }) =>
 *     console.warn(`retry #${attempt + 1} in ${delay}ms`, error ?? response?.status),
 * });
 */
export async function fetchWithRetry(url, options = {}, retries = DEFAULTS.retries) {
  const {
    retries: retriesOption,
    baseDelay = DEFAULTS.baseDelay,
    maxDelay = DEFAULTS.maxDelay,
    factor = DEFAULTS.factor,
    jitter = DEFAULTS.jitter,
    timeout = DEFAULTS.timeout,
    respectRetryAfter = DEFAULTS.respectRetryAfter,
    retryableStatusCodes = DEFAULT_RETRYABLE_STATUS_CODES,
    shouldRetry,
    onRetry,
    ...init
  } = options ?? {};

  const maxRetries = Math.max(0, Number(retriesOption ?? retries) || 0);
  const retryable =
    retryableStatusCodes instanceof Set
      ? retryableStatusCodes
      : new Set(retryableStatusCodes ?? DEFAULT_RETRYABLE_STATUS_CODES);

  const parentSignal = init.signal;

  /** Default policy: retry network errors and transient statuses. */
  const defaultShouldRetry = ({ error, response }) => {
    if (error) return true;
    if (!response) return false;
    return retryable.has(response.status);
  };

  const policy = shouldRetry ?? defaultShouldRetry;

  let lastError = null;

  for (let attempt = 0; attempt <= maxRetries; attempt += 1) {
    const isLastAttempt = attempt === maxRetries;
    const { signal, cleanup } = createAttemptSignal(timeout, parentSignal);

    let response = null;
    let error = null;

    try {
      // A function body is re-evaluated per attempt so streams can be replayed.
      const body = typeof init.body === 'function' ? init.body() : init.body;
      response = await fetch(url, { ...init, body, signal });
    } catch (err) {
      error = err;
    } finally {
      cleanup();
    }

    /* ---- Network-level failure ------------------------------------------ */
    if (error) {
      // The caller cancelled: never retry, surface the reason immediately.
      if (parentSignal?.aborted) throw error;
      // An abort we didn't cause (e.g. a proxy-level abort) is not retryable.
      if (error.name === 'AbortError') throw error;

      lastError = error;

      if (isLastAttempt || !policy({ attempt, error, response: null, url })) {
        throw new RetryError(String(url), attempt + 1, error);
      }

      const delay = computeBackoff(attempt, { baseDelay, maxDelay, factor, jitter });
      await waitBeforeRetry({ onRetry, delay, attempt, maxRetries, error, response: null, url, signal: parentSignal });
      continue;
    }

    /* ---- HTTP-level result ---------------------------------------------- */
    const wantsRetry = !isLastAttempt && policy({ attempt, error: null, response, url });

    if (!wantsRetry) {
      // Success, a non-retryable status, or the final attempt: hand it back.
      return response;
    }

    const retryAfterMs = respectRetryAfter
      ? parseRetryAfter(response.headers.get('retry-after'))
      : null;
    const delay =
      retryAfterMs != null
        ? Math.min(retryAfterMs, maxDelay)
        : computeBackoff(attempt, { baseDelay, maxDelay, factor, jitter });

    await discardBody(response);
    await waitBeforeRetry({ onRetry, delay, attempt, maxRetries, error: null, response, url, signal: parentSignal });
  }

  /* istanbul ignore next — the loop always returns or throws. */
  throw new RetryError(String(url), maxRetries + 1, lastError);
}

/**
 * Notify the caller and wait out the backoff period.
 * @param {{
 *   onRetry?: (info: RetryInfo) => void|Promise<void>,
 *   delay: number, attempt: number, maxRetries: number,
 *   error: Error|null, response: Response|null,
 *   url: string|URL, signal?: AbortSignal
 * }} params
 * @returns {Promise<void>}
 */
async function waitBeforeRetry({ onRetry, delay, attempt, maxRetries, error, response, url, signal }) {
  if (typeof onRetry === 'function') {
    try {
      await onRetry({
        attempt,          // zero-based index of the attempt that just failed
        nextAttempt: attempt + 1,
        maxRetries,
        delay,            // milliseconds we are about to wait
        error,            // network error, or null for an HTTP-status failure
        response,         // the failed response (body already discarded), or null
        url,
      });
    } catch {
      /* a broken logger must never break the retry loop */
    }
  }
  await sleep(delay, signal);
}

/**
 * @typedef {Object} RetryInfo
 * @property {number} attempt Zero-based index of the attempt that just failed.
 * @property {number} nextAttempt One-based index of the upcoming attempt.
 * @property {number} maxRetries Total number of retries allowed.
 * @property {number} delay Milliseconds until the next attempt.
 * @property {Error|null} error Network error, or `null` if the failure was an HTTP status.
 * @property {Response|null} response The failed response, or `null` for a network error.
 * @property {string|URL} url The requested URL.
 */

/**
 * @typedef {Object} RetryOptions
 * @property {number} [retries=3] Retries after the first attempt (overrides the 3rd argument).
 * @property {number} [baseDelay=300] Base backoff delay in milliseconds.
 * @property {number} [maxDelay=30000] Maximum backoff delay in milliseconds.
 * @property {number} [factor=2] Exponential growth factor.
 * @property {boolean} [jitter=true] Apply full jitter to the computed delay.
 * @property {number} [timeout=0] Per-attempt timeout in milliseconds; `0` disables it.
 * @property {boolean} [respectRetryAfter=true] Honour the `Retry-After` response header.
 * @property {Set<number>|number[]} [retryableStatusCodes] Status codes considered transient.
 * @property {(ctx: { attempt: number, error: Error|null, response: Response|null, url: string|URL }) => boolean} [shouldRetry]
 *   Custom retry predicate. Return `false` to stop retrying immediately.
 * @property {(info: RetryInfo) => void|Promise<void>} [onRetry] Called before each backoff wait.
 */
```

### Usage examples

```js
// 1. Simple GET, 3 retries (4 attempts total).
const res = await fetchWithRetry('https://api.example.com/users', {}, 3);
if (!res.ok) throw new Error(`HTTP ${res.status}`);

// 2. POST that must be safe to replay — use an idempotency key.
await fetchWithRetry('https://api.example.com/charges', {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'idempotency-key': crypto.randomUUID() },
  body: JSON.stringify({ amount: 1000 }),
  retries: 5,
  timeout: 5_000,
});

// 3. Only retry idempotent methods.
await fetchWithRetry(url, {
  method: 'POST',
  shouldRetry: ({ error, response }) =>
    !!error || ['429', '503'].includes(String(response?.status)),
});

// 4. Cancel everything after 30s (covers attempts *and* backoff waits).
const ac = new AbortController();
setTimeout(() => ac.abort(), 30_000);
await fetchWithRetry(url, { signal: ac.signal, retries: 10 });

// 5. Replayable streaming body (a function is called once per attempt).
await fetchWithRetry(url, {
  method: 'PUT',
  body: () => fs.createReadStream('./big-file.bin'),
  duplex: 'half', // required by Node's undici for stream bodies
});
```

### Things to keep in mind

- **`retries` means *extra* attempts.** `retries: 3` → up to 4 requests. Worst-case wall time is roughly `baseDelay * (factor^n - 1) / (factor - 1)`, so with the defaults that's ~2.1s of sleeping plus request time.
- **Non-idempotent requests.** Retrying a `POST` can duplicate side effects. Either send an idempotency key (as above) or restrict retries with `shouldRetry`.
- **The final HTTP failure is returned, not thrown.** `fetch` doesn't throw on 4xx/5xx, so always check `response.ok` — this keeps the "last response" available for logging and error bodies.
- **Jitter matters.** Without it, every client that failed at the same moment retries at the same moment. Keep `jitter: true`.
- **Timeouts are per attempt**, not for the whole operation. Combine with an `AbortSignal` if you need a total deadline.
- **Requires a global `fetch`** (Node 18+, Deno, Bun, or any modern browser). In older Node, install `undici` and assign `globalThis.fetch`.

## `fetchWithRetry`

```js
/**
 * fetchWithRetry(url, options, retries)
 * -------------------------------------
 * Performs an HTTP request with `fetch`, retrying transient failures using
 * exponential backoff with jitter.
 *
 * WHAT IS RETRIED
 *   • Network-level failures (DNS failure, connection reset/refused, socket
 *     hang-up, TLS handshake errors) — surfaced by `fetch` as a `TypeError`.
 *   • Requests that exceed the per-attempt timeout.
 *   • HTTP responses whose status is in `retryableStatusCodes`
 *     (default: 408, 425, 429, 500, 502, 503, 504).
 *
 * WHAT IS NOT RETRIED
 *   • 4xx client errors other than 408/425/429 (e.g. 400, 401, 404) — these
 *     are returned to the caller immediately.
 *   • Aborts caused by the caller's own `AbortSignal`.
 *   • Any error thrown by `fetch` that is not a recognised network failure.
 *
 * BACKOFF
 *   delay = min(maxDelayMs, baseDelayMs * 2^attempt), then randomised with
 *   "full jitter" (delay = random() * exponential) so that many clients
 *   retrying the same failing service do not stampede it.
 *   If the server sends a `Retry-After` header (429/503), that value is
 *   honoured instead (capped at `maxDelayMs`).
 *
 * RETURN VALUE
 *   Resolves with the standard `Response` object. HTTP error statuses are NOT
 *   thrown — check `response.ok` / `response.status` yourself. The number of
 *   attempts made is available as the non-enumerable `response.attempts`.
 *   Rejects only when the request could not be completed at all (network
 *   error, timeout, or abort) or when all attempts were exhausted.
 *
 * @param {string|URL} url                 The resource to request.
 * @param {object}  [options={}]           Standard `fetch` init options
 *        (`method`, `headers`, `body`, `signal`, …) plus the extra keys below.
 *        Extra keys are stripped before the options are passed to `fetch`.
 * @param {number}  [options.retries=3]    Overrides the `retries` argument.
 * @param {number}  [options.baseDelayMs=300]   Delay before the first retry.
 * @param {number}  [options.maxDelayMs=30000]  Upper bound for any single wait.
 * @param {number}  [options.timeoutMs=10000]   Per-attempt timeout (0 = none).
 * @param {Set<number>|number[]} [options.retryableStatusCodes]
 *        Status codes considered transient and therefore retryable.
 * @param {boolean} [options.respectRetryAfter=true] Honour `Retry-After`.
 * @param {(info: {url: string, attempt: number, delayMs: number,
 *                 status?: number, error?: Error, reason: string}) => void}
 *        [options.onRetry] Called before each retry — useful for logging.
 * @param {number}  [retries=3]            Number of *additional* attempts
 *        after the first one. `0` means "try once, never retry".
 *
 * @returns {Promise<Response>} The response of the first successful attempt
 *          (or of the final attempt if every attempt failed).
 *
 * @throws {Error} The last network/timeout error if all attempts fail, or the
 *         caller's abort reason if the request was cancelled.
 *
 * @example
 *   const res = await fetchWithRetry('https://api.example.com/items', {
 *     method: 'POST',
 *     headers: { 'content-type': 'application/json' },
 *     body: JSON.stringify({ name: 'widget' }),
 *     timeoutMs: 5_000,
 *     onRetry: ({ attempt, delayMs, reason }) =>
 *       console.warn(`retry #${attempt} in ${delayMs}ms (${reason})`),
 *   }, 5);
 *
 * @example  // With cancellation
 *   const ac = new AbortController();
 *   setTimeout(() => ac.abort(), 1_000);
 *   await fetchWithRetry(url, { signal: ac.signal });
 *
 * @requires A runtime with global `fetch` (Node.js >= 18, Deno, Bun, modern
 *           browsers) and `AbortController.abort(reason)` support.
 */

const DEFAULTS = {
  retries: 3,
  baseDelayMs: 300,
  maxDelayMs: 30_000,
  timeoutMs: 10_000,
  retryableStatusCodes: new Set([408, 425, 429, 500, 502, 503, 504]),
  respectRetryAfter: true,
};

/** Error codes that indicate a transient, likely-recoverable network fault. */
const RETRYABLE_ERROR_CODES = new Set([
  'ECONNRESET', 'ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'EPIPE',
  'EAI_AGAIN', 'ENETDOWN', 'ENETUNREACH', 'EHOSTUNREACH', 'ENOTFOUND',
  'UND_ERR_SOCKET', 'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_HEADERS_TIMEOUT',
  'UND_ERR_BODY_TIMEOUT',
]);

export async function fetchWithRetry(url, options = {}, retries = DEFAULTS.retries) {
  const {
    // Strip our own options so only real `fetch` init options remain.
    retries: _ignoredRetries,
    baseDelayMs = DEFAULTS.baseDelayMs,
    maxDelayMs = DEFAULTS.maxDelayMs,
    timeoutMs = DEFAULTS.timeoutMs,
    retryableStatusCodes = DEFAULTS.retryableStatusCodes,
    respectRetryAfter = DEFAULTS.respectRetryAfter,
    onRetry,
    ...init
  } = options ?? {};

  const retryableStatuses =
    retryableStatusCodes instanceof Set
      ? retryableStatusCodes
      : new Set(retryableStatusCodes ?? DEFAULTS.retryableStatusCodes);

  const maxAttempts = Math.max(1, Math.floor(Number(retries) || 0) + 1);
  const externalSignal = init.signal ?? null;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const attemptNumber = attempt + 1;
    const isLastAttempt = attemptNumber === maxAttempts;

    // ---- 1. Make the attempt -------------------------------------------
    let response;
    let error;
    try {
      response = await fetchWithTimeout(url, init, timeoutMs);
    } catch (err) {
      error = err;
    }

    // ---- 2a. Network / timeout failure ---------------------------------
    if (error) {
      if (isLastAttempt || !isRetryableError(error, externalSignal)) throw error;

      const delayMs = computeDelay(attempt, baseDelayMs, maxDelayMs, null);
      await notify(onRetry, {
        url: String(url), attempt: attemptNumber, delayMs, error,
        reason: error?.name === 'TimeoutError' ? 'timeout' : 'network-error',
      });
      await sleep(delayMs, externalSignal);
      continue;
    }

    // ---- 2b. Transient HTTP status -------------------------------------
    if (!isLastAttempt && response.status >= 400 && retryableStatuses.has(response.status)) {
      const retryAfterMs = respectRetryAfter
        ? parseRetryAfter(response.headers.get('retry-after'))
        : null;

      // Release the connection: an unread body keeps the socket open.
      await discardBody(response);

      const delayMs = computeDelay(attempt, baseDelayMs, maxDelayMs, retryAfterMs);
      await notify(onRetry, {
        url: String(url), attempt: attemptNumber, delayMs,
        status: response.status, reason: 'http-status',
      });
      await sleep(delayMs, externalSignal);
      continue;
    }

    // ---- 3. Success (or a non-retryable status) ------------------------
    Object.defineProperty(response, 'attempts', {
      value: attemptNumber, enumerable: false, configurable: true,
    });
    return response;
  }

  /* istanbul ignore next — the loop always returns or throws. */
  throw new Error('fetchWithRetry: exhausted all attempts');
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/**
 * `fetch` with a per-attempt timeout, composed with any caller-supplied
 * signal. The caller's abort always wins; the timeout abort is reported as a
 * `TimeoutError` so it can be distinguished from a user cancellation.
 */
async function fetchWithTimeout(url, init, timeoutMs) {
  if (!timeoutMs || timeoutMs <= 0) return fetch(url, init);

  const controller = new AbortController();
  const external = init.signal;

  const onExternalAbort = () => controller.abort(external.reason);
  if (external) {
    if (external.aborted) controller.abort(external.reason);
    else external.addEventListener('abort', onExternalAbort, { once: true });
  }

  const timer = setTimeout(
    () => controller.abort(new DOMException('Request timed out', 'TimeoutError')),
    timeoutMs,
  );

  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
    external?.removeEventListener('abort', onExternalAbort);
  }
}

/** Decides whether a thrown error is worth another attempt. */
function isRetryableError(error, externalSignal) {
  // The caller cancelled — never retry.
  if (externalSignal?.aborted) return false;
  if (error?.name === 'TimeoutError') return true;
  if (error?.name === 'AbortError') return false;

  const code = error?.code ?? error?.cause?.code;
  if (code && RETRYABLE_ERROR_CODES.has(code)) return true;

  // `fetch` reports network failures as a TypeError ("fetch failed").
  if (error instanceof TypeError) return true;

  return false;
}

/**
 * Exponential backoff with full jitter.
 * `Retry-After` (milliseconds) takes precedence when present.
 */
function computeDelay(attempt, baseDelayMs, maxDelayMs, retryAfterMs) {
  if (retryAfterMs != null) return Math.min(retryAfterMs, maxDelayMs);
  const exponential = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
  return Math.round(Math.random() * exponential);
}

/**
 * Parses a `Retry-After` header, which may be a delay in seconds or an
 * HTTP-date. Returns milliseconds, or `null` if the header is absent/invalid.
 */
function parseRetryAfter(header) {
  if (!header) return null;

  const seconds = Number(header);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const timestamp = Date.parse(header);
  if (!Number.isNaN(timestamp)) return Math.max(0, timestamp - Date.now());

  return null;
}

/** Cancels an unread response body so the socket can be reused. */
async function discardBody(response) {
  try {
    await response.body?.cancel();
  } catch {
    /* the body may already be closed — nothing to do */
  }
}

/** Invokes the `onRetry` hook; hook failures must not break the request. */
async function notify(onRetry, info) {
  if (typeof onRetry !== 'function') return;
  try {
    await onRetry(info);
  } catch {
    /* ignore */
  }
}

/** Promise-based `setTimeout` that can be interrupted by an abort signal. */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

### Design notes

**Why jitter?** Pure exponential backoff synchronises all clients that failed at the same instant, producing a thundering herd when the service recovers. Full jitter (`random() * delay`) spreads the retries out and is the variant recommended by the AWS Architecture Blog.

**Why not retry 4xx?** A `400`/`401`/`404` will fail identically on the next attempt — retrying only wastes time and load. `408` (request timeout), `425` (too early) and `429` (rate limited) are the exceptions, since the server is explicitly telling you to come back.

**Why `Retry-After`?** When a server rate-limits you, it usually tells you exactly how long to wait. Ignoring it and using your own backoff is both slower to recover and impolite.

**Why a per-attempt timeout?** Without one, a hung TCP connection blocks the whole retry loop indefinitely. The timeout is per attempt, so the total worst-case time is roughly `attempts × (timeoutMs + maxDelayMs)`.

**Idempotency caveat:** the function retries *any* method, including `POST`. If your endpoint is not idempotent, pass an idempotency key in the headers so the server can deduplicate the replayed request — otherwise you may create duplicate records.

**Cancellation:** pass `options.signal` and the function aborts promptly, including during the backoff wait, and never retries a caller-initiated abort.

## `fetchWithRetry`

```js
/**
 * HTTP status codes that indicate a *transient* server-side condition and are
 * therefore worth retrying. Client errors (4xx) other than these are returned
 * to the caller immediately, because retrying them would not help.
 * @type {ReadonlySet<number>}
 */
const RETRYABLE_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

/** Low-level error codes that indicate a temporary network problem. */
const TRANSIENT_ERROR_CODES = new Set([
  'ECONNRESET', 'ECONNREFUSED', 'ETIMEDOUT', 'EPIPE', 'EAI_AGAIN',
  'ENETDOWN', 'ENETUNREACH', 'EHOSTUNREACH',
  'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_HEADERS_TIMEOUT', 'UND_ERR_SOCKET',
]);

const DEFAULT_RETRIES = 3;
const DEFAULT_BASE_DELAY_MS = 300;
const DEFAULT_MAX_DELAY_MS = 30_000;

/**
 * Error thrown when the server keeps answering with a retryable status code
 * (e.g. 503) until the retry budget is exhausted.
 *
 * The last `Response` is attached as {@link HttpError#response} so the caller
 * can still inspect its body (e.g. `await err.response.text()`).
 */
export class HttpError extends Error {
  /**
   * @param {Response} response The final (unsuccessful) response.
   * @param {string} url        The requested URL.
   * @param {number} attempts   Total number of attempts that were made.
   */
  constructor(response, url, attempts) {
    super(`HTTP ${response.status} ${response.statusText} for ${url}`);
    this.name = 'HttpError';
    this.status = response.status;
    this.statusText = response.statusText;
    this.response = response;
    this.url = url;
    this.attempts = attempts;
  }
}

/** @returns {Error} The reason an AbortSignal was aborted. */
function abortReason(signal) {
  return signal?.reason ?? new DOMException('The operation was aborted.', 'AbortError');
}

/**
 * Resolves after `ms` milliseconds, or rejects immediately if `signal` aborts.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortReason(signal));
    const onAbort = () => { clearTimeout(timer); reject(abortReason(signal)); };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Computes the delay before the next attempt: `baseDelay * 2^attempt`,
 * capped at `maxDelay`. With jitter enabled the delay is picked uniformly at
 * random from `[0, delay]` ("full jitter"), which avoids a thundering herd
 * when many clients fail at the same moment.
 * @param {number} attempt   Zero-based index of the attempt that just failed.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @param {boolean} jitter
 * @returns {number} Delay in milliseconds.
 */
function backoffDelay(attempt, baseDelay, maxDelay, jitter) {
  const delay = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return jitter ? Math.random() * delay : delay;
}

/**
 * Parses a `Retry-After` header (delta-seconds or HTTP-date) into milliseconds.
 * @param {string|null} value
 * @returns {number|null} Milliseconds to wait, or `null` if not parseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;
  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

/**
 * Decides whether a thrown error is worth retrying. Aborts are never retried;
 * network-level failures (`TypeError: fetch failed` / `Failed to fetch`) and
 * known transient socket errors are.
 * @param {unknown} error
 * @param {AbortSignal} [signal]
 * @returns {boolean}
 */
function isRetryableError(error, signal) {
  if (signal?.aborted) return false;
  if (error?.name === 'AbortError' || error?.name === 'TimeoutError') return false;
  const code = error?.cause?.code ?? error?.code;
  if (TRANSIENT_ERROR_CODES.has(code)) return true;
  return error instanceof TypeError &&
    /failed to fetch|fetch failed|network (error|request failed)/i.test(error.message ?? '');
}

/**
 * Fetches a URL, retrying transient failures with exponential backoff.
 *
 * ## What is retried
 * - Network-level failures (connection reset, DNS blip, socket timeout, …).
 * - Responses with a transient status code: 408, 425, 429, 500, 502, 503, 504.
 *
 * ## What is *not* retried
 * - Successful responses (2xx/3xx) and non-transient client errors (e.g. 404):
 *   the response is returned as-is so the caller can inspect it.
 * - Aborts: an aborted `signal` rejects immediately with the abort reason.
 *
 * ## Backoff
 * The delay before retry *n* (1-based) is `baseDelay * 2^(n-1)`, capped at
 * `maxDelay` and randomised with full jitter. If the server sends a
 * `Retry-After` header it takes precedence (still capped at `maxDelay`).
 *
 * @param {string} url                       URL to request.
 * @param {object} [options]                 Options forwarded to `fetch`, plus:
 * @param {number} [options.baseDelay=300]    Initial backoff delay in ms.
 * @param {number} [options.maxDelay=30000]  Maximum backoff delay in ms.
 * @param {boolean} [options.jitter=true]     Randomise the backoff delay.
 * @param {(response: Response) => boolean} [options.retryOn]
 *        Custom predicate deciding whether a response should be retried.
 *        Defaults to the built-in list of transient status codes.
 * @param {(info: {attempt: number, delay: number, error?: Error, response?: Response, url: string}) => void}
 *        [options.onRetry] Called before each retry; useful for logging/metrics.
 * @param {AbortSignal} [options.signal]     Cancels the request and any pending backoff.
 * @param {RequestInit|(() => BodyInit)} [options.body]
 *        A function may be supplied to produce a fresh body for every attempt
 *        (a `ReadableStream` can only be consumed once).
 * @param {number} [retries=3]                Number of *retries* after the first
 *        attempt, i.e. up to `retries + 1` requests are made in total.
 * @returns {Promise<Response>} The first non-retryable response.
 * @throws {HttpError} If the last attempt returned a retryable status code.
 * @throws {Error} The underlying error if every attempt failed at the network level.
 * @throws {Error} The abort reason if `options.signal` is aborted.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/users', {}, 3);
 * if (res.ok) console.log(await res.json());
 */
export async function fetchWithRetry(url, options = {}, retries = DEFAULT_RETRIES) {
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`retries must be a non-negative integer, received ${retries}`);
  }

  const {
    baseDelay = DEFAULT_BASE_DELAY_MS,
    maxDelay = DEFAULT_MAX_DELAY_MS,
    jitter = true,
    retryOn,
    onRetry,
    signal,
    ...fetchOptions
  } = options ?? {};

  // A body factory lets us replay a request body on every attempt.
  const bodyFactory = typeof fetchOptions.body === 'function' ? fetchOptions.body : null;

  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) throw abortReason(signal);

    const init = bodyFactory ? { ...fetchOptions, body: bodyFactory() } : fetchOptions;

    // ---- Attempt -------------------------------------------------------
    let response;
    try {
      response = await fetch(url, { ...init, signal });
    } catch (error) {
      if (!isRetryableError(error, signal)) throw error;   // e.g. abort or bad URL
      if (attempt === retries) throw error;                  // budget exhausted

      const delay = backoffDelay(attempt, baseDelay, maxDelay, jitter);
      onRetry?.({ attempt: attempt + 1, delay, error, url });
      await sleep(delay, signal);
      continue;
    }

    // ---- Decide: retry or return? --------------------------------------
    const retryable = typeof retryOn === 'function'
      ? retryOn(response)
      : RETRYABLE_STATUS_CODES.has(response.status);

    if (!retryable) return response;

    if (attempt === retries) {
      throw new HttpError(response, url, attempt + 1);       // budget exhausted
    }

    // ---- Back off and try again ----------------------------------------
    const retryAfterMs = parseRetryAfter(response.headers.get('retry-after'));
    const delay = retryAfterMs !== null
      ? Math.min(retryAfterMs, maxDelay)
      : backoffDelay(attempt, baseDelay, maxDelay, jitter);

    onRetry?.({ attempt: attempt + 1, delay, response, url });

    // Release the connection so the socket can be reused by the next attempt.
    try { await response.body?.cancel(); } catch { /* ignore */ }

    await sleep(delay, signal);
  }
}
```

### Usage

```js
// Simple GET: up to 3 retries (4 attempts total).
const res = await fetchWithRetry('https://api.example.com/data');

// POST with JSON body.
await fetchWithRetry('https://api.example.com/items', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ name: 'Widget' }),
}, 5);

// Cancellation: aborts both the in-flight request and any pending backoff.
const controller = new AbortController();
setTimeout(() => controller.abort(), 5_000);
await fetchWithRetry(url, { signal: controller.signal }, 3);

// Streamed body: supply a factory so each attempt gets a fresh stream.
await fetchWithRetry(url, {
  method: 'POST',
  body: () => createReadStream(),   // called once per attempt
}, 3);

// Observability.
await fetchWithRetry(url, {
  onRetry: ({ attempt, delay, error, response }) =>
    console.warn(`retry #${attempt} in ${Math.round(delay)}ms`, error ?? response?.status),
}, 3);
```

### Notes / caveats

- **Attempt count:** `retries = 3` means up to **4** total requests (1 initial + 3 retries).
- **Non-retryable HTTP errors are returned, not thrown** (e.g. a `404` resolves with `response.ok === false`). Only *transient* statuses that survive the retry budget become an `HttpError`.
- **Idempotency:** retrying a non-idempotent request (e.g. `POST`) can duplicate side effects if the server processed the request but the response was lost. Only retry such requests if your API supports idempotency keys.
- **Request bodies:** a `ReadableStream` body cannot be replayed — pass a factory function instead.
- **Runtime:** requires a platform with `fetch` (browsers, Node.js 18+, Deno, Bun).

## `fetchWithRetry`

```js
/**
 * Performs a `fetch()` request, retrying failed attempts with exponential backoff.
 *
 * ## Behaviour
 *
 * - A request is **retried** when the network call throws (DNS failure, connection
 *   reset, socket hang-up, per-attempt timeout, …) or when the server answers with a
 *   *retryable* status (default: `408`, `429`, and any `5xx`).
 * - A request is **not** retried** for other `4xx` statuses (e.g. `404`, `422`) — those
 *   are deterministic client errors and retrying only wastes time.
 * - The delay between attempts grows exponentially:
 *   `delay = min(baseDelay * 2 ** attempt, maxDelay)`, then jitter is applied.
 * - If the server sends a `Retry-After` header (delay in seconds or an HTTP date),
 *   that value is honoured instead of the computed backoff.
 * - `retries` is the number of **extra** attempts after the first one, so the total
 *   number of requests is `retries + 1`.
 *
 * ## Options
 *
 * `options` is a standard `fetch()` init object (`method`, `headers`, `body`, `signal`,
 * `credentials`, …) plus one extra `retry` key:
 *
 * ```js
 * {
 *   baseDelay: 300,        // ms before the first retry
 *   maxDelay: 30_000,      // upper bound for a single backoff delay
 *   timeout: 10_000,       // ms allowed for a single attempt (0 = no timeout)
 *   jitter: true,          // randomise the delay to avoid thundering herds
 *   retryOnStatus: (s) => s === 408 || s === 429 || s >= 500,
 *   retryOnError: true,    // retry when the request itself throws
 *   throwOnHttpError: true,// throw instead of returning a non-2xx response
 *   onRetry: (info) => {}, // called before each backoff: { attempt, error, delay }
 * }
 * ```
 *
 * ## Caveats
 *
 * - `options.body` must be replayable (string, `Buffer`, `Blob`, `URLSearchParams`).
 *   A consumed `ReadableStream` cannot be re-read, so pass a **function**
 *   (`body: () => stream`) to have a fresh body created for every attempt.
 * - An `AbortSignal` passed via `options.signal` cancels the whole operation
 *   (including pending backoff waits) and is never retried.
 *
 * @param {string|URL} url            The resource to request.
 * @param {object}   [options={}]     `fetch()` init object plus the optional `retry` config.
 * @param {number}   [retries=3]      Number of retries after the initial attempt.
 * @returns {Promise<Response>}       The first successful (2xx) response.
 * @throws  {HttpError}               When the final attempt returns a non-2xx status
 *                                     and `throwOnHttpError` is enabled.
 * @throws  {Error}                   The last network/timeout error when all attempts fail.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/users', {}, 5);
 * console.log(await res.json());
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 300,
    maxDelay = 30_000,
    timeout = 10_000,
    jitter = true,
    retryOnStatus = (status) => status === 408 || status === 429 || status >= 500,
    retryOnError = true,
    throwOnHttpError = true,
    onRetry = null,
    ...init
  } = options;

  const { retry: _ignored, ...fetchInit } = init;
  const maxAttempts = Math.max(0, retries) + 1;
  let lastError;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const isLastAttempt = attempt === maxAttempts - 1;

    // ---- 1. Perform a single attempt -------------------------------------
    const { signal, cleanup } = createAttemptSignal(timeout, fetchInit.signal);
    let response;

    try {
      response = await fetch(url, {
        ...fetchInit,
        signal,
        // Allow a factory so the body can be replayed on every attempt.
        body: typeof fetchInit.body === 'function' ? fetchInit.body() : fetchInit.body,
      });
    } catch (error) {
      cleanup();

      // A user-initiated abort must never be retried.
      if (fetchInit.signal?.aborted) throw error;

      lastError = error;
      if (isLastAttempt || !retryOnError) throw error;

      await wait(computeDelay(attempt), fetchInit.signal, {
        attempt,
        error,
        onRetry,
      });
      continue;
    } finally {
      cleanup();
    }

    // ---- 2. Success -------------------------------------------------------
    if (response.ok) return response;

    // ---- 3. Non-retryable status -----------------------------------------
    if (!retryOnStatus(response.status)) {
      if (throwOnHttpError) throw new HttpError(response, url);
      return response;
    }

    // ---- 4. Retryable status ---------------------------------------------
    if (isLastAttempt) {
      if (throwOnHttpError) throw new HttpError(response, url);
      return response;
    }

    const retryAfter = parseRetryAfter(response.headers.get('retry-after'));
    // Release the socket; we are not going to read this body.
    await response.body?.cancel?.().catch(() => {});

    await wait(retryAfter ?? computeDelay(attempt), fetchInit.signal, {
      attempt,
      error: new HttpError(response, url),
      onRetry,
    });
  }

  /* istanbul ignore next — the loop always returns or throws. */
  throw lastError;
}

/* -------------------------------------------------------------------------- */
/* Helpers                                                                     */
/* -------------------------------------------------------------------------- */

/**
 * Error thrown when the server responds with a non-2xx status.
 * The original `Response` is attached for inspection (e.g. `error.response.status`).
 */
export class HttpError extends Error {
  /**
   * @param {Response} response The failed response.
   * @param {string|URL} url     The requested URL.
   */
  constructor(response, url) {
    super(`Request to ${url} failed with status ${response.status} ${response.statusText}`);
    this.name = 'HttpError';
    this.status = response.status;
    this.response = response;
    this.url = String(url);
  }
}

/**
 * Computes the backoff delay for a given attempt (0-based).
 *
 * @param {number} attempt  Zero-based attempt index.
 * @param {number} baseDelay
 * @param {number} maxDelay
 * @param {boolean} jitter  If true, randomise half of the delay ("equal jitter").
 * @returns {number} Delay in milliseconds.
 */
function computeDelay(attempt, baseDelay = 300, maxDelay = 30_000, jitter = true) {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  if (!jitter) return exponential;
  // Equal jitter: half of the window is fixed, half is random.
  return exponential / 2 + Math.random() * (exponential / 2);
}

/**
 * Parses a `Retry-After` header value.
 *
 * @param {string|null} value
 * @param {number} [now=Date.now()]
 * @returns {number|null} Delay in milliseconds, or `null` if the header is absent/invalid.
 */
function parseRetryAfter(value, now = Date.now()) {
  if (!value) return null;

  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - now);

  return null;
}

/**
 * Creates an `AbortSignal` that fires when the attempt times out or when the
 * caller's signal aborts, whichever happens first.
 *
 * @param {number} timeoutMs   Per-attempt timeout; `0` disables it.
 * @param {AbortSignal} [externalSignal]
 * @returns {{ signal: AbortSignal, cleanup: () => void }}
 */
function createAttemptSignal(timeoutMs, externalSignal) {
  const controller = new AbortController();

  const abortFrom = (signal) => {
    controller.abort(signal.reason ?? new DOMException('Aborted', 'AbortError'));
  };

  if (externalSignal) {
    if (externalSignal.aborted) abortFrom(externalSignal);
    else externalSignal.addEventListener('abort', () => abortFrom(externalSignal), { once: true });
  }

  const timer =
    timeoutMs > 0
      ? setTimeout(
          () =>
            controller.abort(
              new DOMException(`Request timed out after ${timeoutMs}ms`, 'TimeoutError'),
            ),
          timeoutMs,
        )
      : undefined;

  return {
    signal: controller.signal,
    cleanup: () => clearTimeout(timer),
  };
}

/**
 * Sleeps for `ms`, rejecting immediately if `signal` aborts.
 *
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @param {{ attempt: number, error: Error, onRetry: Function|null }} info
 */
function wait(ms, signal, info) {
  info.onRetry?.({ attempt: info.attempt, error: info.error, delay: ms });

  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

### Usage

```js
// Simple: 3 retries with default backoff.
const res = await fetchWithRetry('https://api.example.com/users', {}, 3);

// Tuned: longer base delay, custom retryable statuses, logging.
const res2 = await fetchWithRetry(
  'https://api.example.com/orders',
  {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ sku: 'A1' }),        // replayable body → safe to retry
    signal: AbortSignal.timeout(60_000),        // cancels everything after 60s
    retry: {
      baseDelay: 500,
      maxDelay: 20_000,
      timeout: 5_000,
      retryOnStatus: (s) => s === 429 || s >= 500,
      onRetry: ({ attempt, delay, error }) =>
        console.warn(`attempt ${attempt} failed (${error.message}); retrying in ${delay}ms`),
    },
  },
  5,
);
```

### Notes / trade-offs

- **Why not retry 4xx?** `400`/`401`/`404`/`422` will fail identically every time; only `408` (request timeout) and `429` (rate limited) are worth another attempt.
- **Jitter** is on by default: without it, many clients retrying the same failing endpoint stay in lockstep and keep hammering it.
- **`Retry-After`** takes precedence over the computed backoff, which is the polite thing to do when a server explicitly asks you to slow down.
- **Timeouts are per attempt**, not for the whole operation — otherwise a slow-but-progressing server could never use its retries. Use `options.signal` for an overall deadline.
- **Idempotency**: retrying a `POST` can duplicate side effects. Only retry non-idempotent requests if the server supports an idempotency key (e.g. `Idempotency-Key` header).

## `fetchWithRetry(url, options, retries)`

```js
/**
 * Perform an HTTP request with automatic retries and exponential backoff.
 *
 * ## Behaviour
 *
 * - Makes up to `retries + 1` total attempts (i.e. `retries = 3` means 1 initial
 *   attempt + 3 retries).
 * - Retries when the request fails at the network level (DNS failure, connection
 *   reset, TLS error, ...) or when the server answers with a *retryable* status:
 *   `408, 425, 429, 500, 502, 503, 504`.
 * - Waits between attempts using **exponential backoff**: `baseDelay * 2^attempt`,
 *   capped at `maxDelay`, with optional random jitter to avoid thundering herds.
 * - Honours the `Retry-After` response header (seconds or HTTP-date) when present.
 * - Does **not** retry client errors such as `400`, `401`, `403` or `404`; the
 *   response is returned as-is so the caller can inspect it.
 * - Does **not** retry non-idempotent methods (`POST`, `PATCH`, ...) by default,
 *   because a retry could duplicate a side effect. Enable with
 *   `options.retry.retryNonIdempotent = true`.
 * - Aborts immediately (without further retries) if `options.signal` is aborted.
 *
 * ## Retry configuration
 *
 * Unknown properties are ignored by `fetch`, so `options.retry` can safely carry
 * tuning knobs:
 *
 * ```js
 * {
 *   retry: {
 *     baseDelay: 300,        // ms, delay before the first retry
 *     maxDelay: 30_000,      // ms, upper bound for any single delay
 *     jitter: true,          // randomise the delay by up to ±50%
 *     retryNonIdempotent: false,
 *     shouldRetry: (err, response) => boolean, // custom override
 *   }
 * }
 * ```
 *
 * @param {string|URL} url            The URL to request.
 * @param {RequestInit & {retry?: object}} [options={}]
 *        Standard `fetch` options (`method`, `headers`, `body`, `signal`, ...) plus
 *        the optional `retry` configuration object described above.
 * @param {number} [retries=3]        Maximum number of *retries* after the first attempt.
 * @returns {Promise<Response>}       The first successful response, or the final
 *                                     (still failing) response if all attempts were
 *                                     exhausted with a retryable HTTP status.
 * @throws {Error}                    If every attempt failed at the network level.
 *                                     The last error is rethrown, annotated with
 *                                     `.attempts`.
 * @throws {AbortError}               If the request was aborted via `options.signal`.
 *
 * @example
 * const res = await fetchWithRetry('https://api.example.com/data', {}, 3);
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 * const data = await res.json();
 *
 * @example
 * // With a timeout and custom backoff
 * const res = await fetchWithRetry('https://api.example.com/data', {
 *   signal: AbortSignal.timeout(5_000),
 *   retry: { baseDelay: 500, maxDelay: 10_000 },
 * }, 5);
 */
export async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 300,
    maxDelay = 30_000,
    jitter = true,
    retryNonIdempotent = false,
    shouldRetry,
  } = options.retry ?? {};

  const method = (options.method ?? 'GET').toUpperCase();
  const canRetryMethod = retryNonIdempotent || IDEMPOTENT_METHODS.has(method);
  const signal = options.signal;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    let response;

    try {
      response = await fetch(url, options);
    } catch (error) {
      // Aborts are never retried.
      if (isAbortError(error) || signal?.aborted) throw error;
      lastError = error;
      if (attempt === retries) break;
      await sleep(computeDelay(attempt, null, { baseDelay, maxDelay, jitter }), signal);
      continue;
    }

    const retryable = isRetryableStatus(response.status) && canRetryMethod;
    const custom = shouldRetry ? shouldRetry(null, response) : false;

    // Success, a non-retryable status, or the final attempt: hand it to the caller.
    if (!retryable || (!custom && !retryable) || attempt === retries) {
      if (attempt === retries && retryable) {
        // Final attempt also failed with a retryable status -> return it as-is.
        return response;
      }
      return response;
    }

    // Free the connection before retrying: discard the unread body.
    try {
      await response.body?.cancel();
    } catch {
      /* ignore */
    }

    lastError = new Error(`Request failed with status ${response.status}`);
    lastError.status = response.status;
    lastError.response = response;

    await sleep(computeDelay(attempt, response, { baseDelay, maxDelay, jitter }), signal);
  }

  // All attempts failed at the network level.
  lastError.attempts = retries + 1;
  throw lastError;
}
```

### Helpers

```js
const IDEMPOTENT_METHODS = new Set(['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS', 'TRACE']);
const RETRYABLE_STATUS = new Set([408, 425, 429, 500, 502, 503, 504]);

/** @param {number} status */
function isRetryableStatus(status) {
  return RETRYABLE_STATUS.has(status);
}

/** @param {unknown} err */
function isAbortError(err) {
  return (
    err instanceof Error &&
    (err.name === 'AbortError' || err.name === 'TimeoutError')
  );
}

/**
 * Exponential backoff with an optional jitter of ±50 %.
 * `Retry-After` takes precedence over the computed backoff.
 *
 * @param {number} attempt   Zero-based index of the attempt that just failed.
 * @param {Response|null} response
 * @param {{baseDelay:number,maxDelay:number,jitter:boolean}} config
 * @returns {number} Delay in milliseconds.
 */
function computeDelay(attempt, response, { baseDelay, maxDelay, jitter }) {
  const retryAfter = parseRetryAfter(response?.headers?.get?.('retry-after'));
  if (retryAfter !== null) return Math.min(retryAfter, maxDelay);

  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  return jitter ? exponential * (0.5 + Math.random() * 0.5) : exponential;
}

/**
 * Parse a `Retry-After` header value (delay-seconds or HTTP-date).
 * @param {string|null|undefined} value
 * @returns {number|null} Milliseconds to wait, or `null` if not parseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (!Number.isNaN(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Abortable sleep.
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
      return;
    }

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('The operation was aborted.', 'AbortError'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

### Notes / caveats

- **Requires a `fetch` implementation** — built into browsers, Node.js 18+, Deno, Bun, and Cloudflare Workers.
- **Return value on HTTP failure:** after exhausting retries on a retryable status (e.g. `503`), the final `Response` is returned rather than thrown, so the caller can read the body. Network-level failures (no HTTP response at all) always throw.
- **Timeouts:** pass `signal: AbortSignal.timeout(5000)`; the abort is propagated immediately and no further retries are attempted.
- **Jitter** is on by default ("equal jitter": 50–100 % of the computed delay) to prevent many clients from retrying in lockstep.

# `fetchWithRetry`

A dependency-free wrapper around `fetch` (Node 18+, Deno, Bun, browsers) that retries transient failures with exponential backoff + jitter.

```js
/**
 * @file fetch-retry.js
 * @module fetch-retry
 */

/* -------------------------------------------------------------------------- */
/* Defaults                                                                   */
/* -------------------------------------------------------------------------- */

/** @type {number} Additional attempts made *after* the first one. */
const DEFAULT_RETRIES = 3;

/** @type {number} Per-attempt timeout in milliseconds. `0` disables it. */
const DEFAULT_TIMEOUT_MS = 10_000;

/** @type {number} Base of the exponential backoff curve, in milliseconds. */
const DEFAULT_BASE_DELAY_MS = 300;

/** @type {number} Upper bound for any single backoff delay, in milliseconds. */
const DEFAULT_MAX_DELAY_MS = 30_000;

/**
 * HTTP statuses that are considered transient and therefore worth retrying.
 * 4xx statuses are excluded on purpose: they are deterministic client errors
 * and retrying them just wastes time and hammers the server.
 */
const RETRYABLE_STATUS_CODES = new Set([408, 425, 429, 500, 502, 503, 504]);

/**
 * Methods that are safe to replay. `POST`/`PATCH` are excluded because a
 * replayed `POST` can duplicate side effects (charges, emails, rows...).
 */
const IDEMPOTENT_METHODS = new Set(['GET', 'HEAD', 'OPTIONS', 'TRACE', 'PUT', 'DELETE']);

/** Option keys consumed by this helper; stripped before calling `fetch`. */
const CONTROL_OPTIONS = [
  'timeout', 'baseDelay', 'maxDelay', 'signal', 'retryableStatuses',
  'retryMethods', 'retryNonIdempotent', 'shouldRetry', 'onRetry',
  'fetchImpl', 'retries',
];

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Perform an HTTP request, retrying transient failures with exponential
 * backoff and jitter.
 *
 * ### Behaviour contract
 *
 * - **Resolved value** — a `Response`, exactly as `fetch` would return it.
 *   Non-2xx responses (including `404`, `400`, `401`) are *returned*, not
 *   thrown, so the caller can inspect `response.status` / `response.body`.
 * - **Rejected value** — only when the request could not be completed at all:
 *   a network failure, a per-attempt timeout, or an abort from the caller's
 *   `AbortSignal`. The error from the final attempt is rethrown unchanged.
 *
 * ### What is retried
 *
 * | Failure                          | Retried?                       |
 * | -------------------------------- | ------------------------------ |
 * | Network error (`TypeError`)      | Yes                            |
 * | Per-attempt timeout              | Yes                            |
 * | `408, 425, 429, 500, 502, 503, 504` | Yes                         |
 * | Other `4xx` / `2xx`              | No (response is returned)      |
 * | Caller abort                     | No (rejects immediately)       |
 * | Non-idempotent method (`POST`)   | No, unless `retryNonIdempotent`|
 *
 * ### Backoff
 *
 * `delay = min(maxDelay, baseDelay * 2 ** attempt)`, then randomised to
 * 50–100 % of that value ("equal jitter"). Jitter is essential: without it,
 * every client that failed during an outage retries in lockstep and
 * re-creates the thundering herd that caused it.
 *
 * When the server sends a `Retry-After` header (on `429`/`503`) that value is
 * honoured instead of the computed backoff, clamped to `maxDelay`.
 *
 * @param {string | URL} url
 *   The resource to request.
 *
 * @param {RequestInit & {
 *   timeout?: number,
 *   baseDelay?: number,
 *   maxDelay?: number,
 *   signal?: AbortSignal,
 *   retryableStatuses?: Iterable<number>,
 *   retryMethods?: Iterable<string>,
 *   retryNonIdempotent?: boolean,
 *   shouldRetry?: (ctx: RetryContext) => boolean,
 *   onRetry?: (info: RetryInfo) => void,
 *   fetchImpl?: typeof fetch,
 *   retries?: number,
 * }} [options={}]
 *   Standard `fetch` options plus the tuning knobs above. The tuning knobs
 *   are removed before the options object is handed to `fetch`.
 *
 * @param {number} [retries=3]
 *   Maximum number of *additional* attempts after the first one.
 *   `retries = 3` therefore means up to 4 requests in total.
 *   Falls back to `options.retries`, then to {@link DEFAULT_RETRIES}.
 *
 * @returns {Promise<Response>}
 *   The first response that is either successful or not retryable.
 *
 * @throws {Error}
 *   The underlying error from the last attempt (network error, timeout),
 *   or the caller's abort reason.
 *
 * @example
 * // Basic usage
 * const res = await fetchWithRetry('https://api.example.com/data');
 * if (!res.ok) throw new Error(`HTTP ${res.status}`);
 *
 * @example
 * // With a deadline and custom backoff
 * const res = await fetchWithRetry(url, { timeout: 2_000, baseDelay: 100 }, 5);
 *
 * @example
 * // Cancelling from the outside
 * const controller = new AbortController();
 * const p = fetchWithRetry(url, { signal: controller.signal });
 * controller.abort(); // rejects immediately, no further attempts
 */
export async function fetchWithRetry(url, options = {}, retries = DEFAULT_RETRIES) {
  /* ---- Resolve configuration ------------------------------------------ */

  const opts = { ...options };

  const timeout = opts.timeout ?? DEFAULT_TIMEOUT_MS;
  const baseDelay = opts.baseDelay ?? DEFAULT_BASE_DELAY_MS;
  const maxDelay = opts.maxDelay ?? DEFAULT_MAX_DELAY_MS;
  const retryableStatuses = new Set(opts.retryableStatuses ?? RETRYABLE_STATUS_CODES);
  const retryMethods = new Set(opts.retryMethods ?? IDEMPOTENT_METHODS);
  const retryNonIdempotent = opts.retryNonIdempotent ?? false;
  const shouldRetry = opts.shouldRetry ?? defaultShouldRetry;
  const onRetry = opts.onRetry ?? (() => {});
  const fetchImpl = opts.fetchImpl ?? globalThis.fetch;

  /** @type {AbortSignal | undefined} */
  const userSignal = opts.signal;

  const maxRetries = Math.max(0, Math.trunc(retries ?? opts.retries ?? DEFAULT_RETRIES));
  const method = String(opts.method ?? 'GET').toUpperCase();
  const methodMayBeReplayed = retryNonIdempotent || retryMethods.has(method);

  // Strip our own knobs so `fetch` never sees unknown properties.
  for (const key of CONTROL_OPTIONS) delete opts[key];

  if (typeof fetchImpl !== 'function') {
    throw new TypeError(
      'fetchWithRetry: no `fetch` implementation available. ' +
      'Use Node 18+, Deno, Bun, a browser, or pass `options.fetchImpl`.'
    );
  }

  /* ---- Attempt loop ---------------------------------------------------- */

  let lastError;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    // The caller may have aborted while we were waiting to back off.
    if (userSignal?.aborted) throw abortReason(userSignal);

    const controller = new AbortController();
    let timedOut = false;

    const timer =
      timeout > 0
        ? setTimeout(() => {
            timedOut = true;
            controller.abort(new DOMException(`Timed out after ${timeout}ms`, 'TimeoutError'));
          }, timeout)
        : null;

    const unlink = forwardAbort(userSignal, controller);

    /** @type {Response | undefined} */
    let response;
    /** @type {any} */
    let error;

    try {
      response = await fetchImpl(url, { ...opts, signal: controller.signal });
    } catch (err) {
      error = err;
    } finally {
      if (timer) clearTimeout(timer);
      unlink();
    }

    /* --- Case 1: the request itself failed (network error / timeout) --- */
    if (error) {
      // A user-initiated abort is final: never retry it.
      if (userSignal?.aborted) throw error;

      lastError = error;

      if (attempt >= maxRetries || !methodMayBeReplayed) throw error;

      const retry = shouldRetry({ error, attempt, maxRetries, method, timedOut, url });
      if (!retry) throw error;

      const delay = backoffDelay(attempt, baseDelay, maxDelay);
      onRetry({ url, attempt, maxRetries, delay, error, response: undefined, reason: 'error' });
      await sleep(delay, userSignal);
      continue;
    }

    /* --- Case 2: we got an HTTP response ------------------------------- */
    const status = response.status;
    const retryableStatus = retryableStatuses.has(status);

    // Success, a non-retryable status, or no attempts left: hand it back.
    if (!retryableStatus || attempt >= maxRetries || !methodMayBeReplayed) {
      return response;
    }

    const retry = shouldRetry({
      error: undefined,
      response,
      attempt,
      maxRetries,
      method,
      timedOut: false,
      url,
    });
    if (!retry) return response;

    const delay = backoffDelay(
      attempt,
      baseDelay,
      maxDelay,
      parseRetryAfter(response.headers.get('retry-after'))
    );

    // Release the connection instead of leaving the body dangling.
    try {
      await response.body?.cancel?.();
    } catch {
      /* the body may already be consumed or locked — nothing to do */
    }

    onRetry({ url, attempt, maxRetries, delay, error: undefined, response, reason: 'status' });
    await sleep(delay, userSignal);
  }

  /* istanbul ignore next — the loop always returns or throws */
  throw lastError;
}

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

/**
 * Default retry predicate.
 *
 * @param {{
 *   error?: any,
 *   response?: Response,
 *   attempt: number,
 *   maxRetries: number,
 *   method: string,
 *   timedOut: boolean,
 *   url: string | URL,
 * }} ctx
 * @returns {boolean}
 */
function defaultShouldRetry({ error, response, attempt, maxRetries, method, timedOut }) {
  if (attempt >= maxRetries) return false;

  if (error) {
    if (timedOut) return true;                       // our own deadline
    if (error?.name === 'AbortError') return false;   // someone cancelled
    if (isFatalTypeError(error)) return false;       // e.g. malformed URL
    return true;                                     // network-level failure
  }

  return response ? RETRYABLE_STATUS_CODES.has(response.status) : false;
}

/**
 * Detect errors that will never succeed no matter how often we retry.
 * @param {any} error
 * @returns {boolean}
 */
function isFatalTypeError(error) {
  if (!error || error.name !== 'TypeError') return false;
  return /invalid url|failed to parse url|failed to construct 'url'/i.test(
    error.message ?? ''
  );
}

/**
 * Compute the delay before the next attempt.
 *
 * @param {number} attempt      Zero-based index of the attempt that just failed.
 * @param {number} baseDelay    Base delay in milliseconds.
 * @param {number} maxDelay     Maximum delay in milliseconds.
 * @param {number | null} [retryAfterMs] Server-provided delay, if any.
 * @returns {number} Delay in milliseconds.
 */
function backoffDelay(attempt, baseDelay, maxDelay, retryAfterMs = null) {
  if (retryAfterMs != null) return Math.min(retryAfterMs, maxDelay);

  const exponential = Math.min(maxDelay, baseDelay * 2 ** attempt);
  // Equal jitter: keep at least half the delay, randomise the rest.
  return Math.round(exponential / 2 + Math.random() * (exponential / 2));
}

/**
 * Parse a `Retry-After` header, which may be a delay in seconds or an HTTP date.
 *
 * @param {string | null} value
 * @returns {number | null} Milliseconds to wait, or `null` if unparseable.
 */
function parseRetryAfter(value) {
  if (!value) return null;

  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - Date.now());

  return null;
}

/**
 * Abortable `setTimeout`.
 *
 * @param {number} ms
 * @param {AbortSignal} [signal]
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortReason(signal));

    const onAbort = () => {
      clearTimeout(timer);
      reject(abortReason(signal));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Forward an abort from the caller's signal to our per-attempt controller.
 *
 * @param {AbortSignal | undefined} source
 * @param {AbortController} controller
 * @returns {() => void} Cleanup function that removes the listener.
 */
function forwardAbort(source, controller) {
  if (!source) return () => {};

  if (source.aborted) {
    controller.abort(source.reason);
    return () => {};
  }

  const onAbort = () => controller.abort(source.reason);
  source.addEventListener('abort', onAbort, { once: true });
  return () => source.removeEventListener('abort', onAbort);
}

/**
 * Extract the abort reason, falling back to a standard `AbortError`.
 *
 * @param {AbortSignal} signal
 * @returns {any}
 */
function abortReason(signal) {
  return (
    signal.reason ??
    new DOMException('The operation was aborted.', 'AbortError')
  );
}
