## Usage

```js
import { fetchWithRetry } from './fetch-retry.js';

// 1. Simple: up to 3 retries, 10 s per-attempt timeout.
const res = await fetchWithRetry('https://api.example.com/users');

// 2. Tuning the backoff curve.
await fetchWithRetry(url, { baseDelay: 1_000, maxDelay: 60_000 }, 5);

// 3. Respecting a deadline and cancelling early.
const controller = new AbortController();
setTimeout(() => controller.abort(), 5_000);
await fetchWithRetry(url, { signal: controller.signal });

// 4. Observability: log every retry.
await fetchWithRetry(url, {
  onRetry: ({ attempt, delay, reason, response, error }) => {
    console.warn(`retry #${attempt + 1} in ${delay}ms (${reason})`, response?.status ?? error);
  },
});

// 5. Retrying a POST (opt in explicitly — it can duplicate side effects).
await fetchWithRetry(url, { method: 'POST', body: payload, retryNonIdempotent: true });

// 6. Testing without a network: inject a fake fetch.
await fetchWithRetry(url, { fetchImpl: fakeFetch });
```

